+        event.preventDefault();
+        const lineHeight = parseFloat(getComputedStyle(cafeMap).lineHeight);
+        const xUnit = event.deltaMode === 1 ? lineHeight : event.deltaMode === 2 ? cafeMap.clientWidth : 1;
+        const yUnit = event.deltaMode === 1 ? lineHeight : event.deltaMode === 2 ? cafeMap.clientHeight : 1;
+        cafeMap.scrollLeft += event.deltaX * xUnit;
+        cafeMap.scrollTop += event.deltaY * yUnit;
+      }, { passive: false });
+    }
+
