@@ -0,0 +1,93 @@
+(() => {
+  const coffees = [
+    {
+      name: 'Maple Oat Latte',
+      description: 'Creamy oat milk with a hint of Vermont maple syrup.',
+      temperature: 'hot',
+      flavor: 'sweet',
+      url: '/menu/seasonal',
+    },
+    {
+      name: 'Dark Roast Espresso',
+      description: 'Bold, smokey, and perfect for a morning boost.',
+      temperature: 'hot',
+      flavor: 'bold',
+      url: '/menu/espresso',
+    },
+    {
+      name: 'Cold Brew',
+      description: 'Steeped for 18 hours for maximum smoothness.',
+      temperature: 'iced',
+      flavor: 'smooth',
+      url: '/menu/cold-brew',
+    },
+  ];
+
+  const form = document.getElementById('coffee-finder-form');
+  const heading = document.getElementById('finder-result-heading');
+  const summary = document.getElementById('finder-result-summary');
+  const list = document.getElementById('finder-result-list');
+  const allowed = {
+    temperature: ['any', 'hot', 'iced'],
+    flavor: ['any', 'sweet', 'bold', 'smooth'],
+  };
+
+  function findCoffee() {
+    const data = new FormData(form);
+    const preferences = Object.fromEntries(
+      Object.keys(allowed).map((name) => [name, data.get(name)]),
+    );
+
+    if (Object.entries(preferences).some(([name, value]) => !allowed[name].includes(value))) {
+      heading.textContent = 'Choose your preferences';
+      summary.textContent = 'Please select a temperature and flavor mood, then try again.';
+      list.replaceChildren();
+      return { status: 'error', message: summary.textContent };
+    }
+
+    const matches = coffees.filter((coffee) =>
+      Object.entries(preferences).every(([name, value]) => value === 'any' || coffee[name] === value),
+    );
+    heading.textContent = matches.length ? 'Meet your coffee match' : 'A different mood?';
+    summary.textContent = matches.length
+      ? `${matches.length} seasonal ${matches.length === 1 ? 'favorite matches' : 'favorites match'} your preferences.`
+      : 'No seasonal favorites match that combination. Try “Either” or “Surprise me” to explore more.';
+
+    list.replaceChildren(...matches.map((coffee) => {
+      const item = document.createElement('li');
+      const link = document.createElement('a');
+      link.href = coffee.url;
+      link.textContent = coffee.name;
+      const description = document.createElement('p');
+      description.textContent = coffee.description;
+      const details = document.createElement('small');
+      details.textContent = `${coffee.temperature === 'hot' ? 'Served hot' : 'Served iced'} · ${coffee.flavor}`;
+      item.append(link, description, details);
+      return item;
+    }));
+
+    return { status: 'success', preferences, count: matches.length, matches, message: summary.textContent };
+  }
+
+  form.addEventListener('submit', (event) => {
+    event.preventDefault();
+    const result = findCoffee();
+    // Older browsers ignore the declarative attributes and use the same UI.
+    if (event.agentInvoked && typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(result));
+    }
+  });
+
+  // Restore preferences after a native GET submission or when following a shared URL.
+  const query = new URLSearchParams(window.location.search);
+  let restored = false;
+  for (const [name, values] of Object.entries(allowed)) {
+    const value = query.get(name);
+    if (values.includes(value)) {
+      const control = Array.from(form.elements).find((field) => field.name === name && field.value === value);
+      control.checked = true;
+      restored = true;
+    }
+  }
+  if (restored) findCoffee();
+})();
