+(() => {
+  const form = document.getElementById('coffee-finder-form');
+  const result = document.getElementById('coffee-result');
+  const options = {
+    temperature: ['hot', 'iced'],
+    roast: ['light', 'medium', 'dark'],
+    caffeine: ['regular', 'decaf'],
+  };
+  const drinks = {
+    light: {
+      hot: { name: 'Light Roast Pour-over', description: 'A bright, aromatic cup with a clean finish.' },
+      iced: { name: 'Iced Light Roast Coffee', description: 'Bright and refreshing, brewed coffee served over ice.' },
+    },
+    medium: {
+      hot: { name: 'Maple Oat Latte', description: 'Creamy oat milk with a hint of maple and smooth, balanced espresso.' },
+      iced: { name: 'Iced Maple Oat Latte', description: 'Smooth espresso, oat milk, and a hint of maple, served over ice.' },
+    },
+    dark: {
+      hot: { name: 'Dark Roast Espresso', description: 'A short, bold cup with a rich, roasted finish.' },
+      iced: { name: 'Iced Dark Roast Americano', description: 'Bold espresso lengthened with water and poured over ice.' },
+    },
+  };
+
+  function findCoffee() {
+    const data = new FormData(form);
+    const preferences = Object.fromEntries(Object.keys(options).map(key => [key, data.get(key)]));
+    // Validate here as well as with HTML constraints, including programmatic submissions.
+    for (const [key, allowed] of Object.entries(options)) {
+      if (!allowed.includes(preferences[key])) {
+        const message = `Please select a valid ${key} preference.`;
+        result.textContent = message;
+        return { status: 'error', message };
+      }
+    }
+
+    const drink = drinks[preferences.roast][preferences.temperature];
+    const recommendation = {
+      name: `${preferences.caffeine === 'decaf' ? 'Decaf ' : ''}${drink.name}`,
+      description: drink.description,
+      ...preferences,
+    };
+    const note = 'Suggested cup only. Ask your barista about roast and decaf availability. Decaf contains some caffeine. No order has been placed.';
+    const heading = document.createElement('h3');
+    heading.textContent = `Your match: ${recommendation.name}`;
+    const description = document.createElement('p');
+    description.textContent = recommendation.description;
+    const match = document.createElement('p');
+    match.textContent = `Made for your preferences: ${preferences.temperature}, ${preferences.roast} roast, ${preferences.caffeine === 'decaf' ? 'decaf' : 'regular caffeine'}.`;
+    const availability = document.createElement('p');
+    availability.className = 'finder-note';
+    availability.textContent = note;
+    result.replaceChildren(heading, description, match, availability);
+    return { status: 'success', recommendation, note };
+  }
+
+  form.addEventListener('submit', event => {
+    event.preventDefault();
+    const response = findCoffee();
+    // WebMCP supplies respondWith; ordinary browser submissions use the same result.
+    if (typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(response));
+    }
+  });
+
+  form.addEventListener('input', () => result.replaceChildren());
+  form.addEventListener('change', () => result.replaceChildren());
+})();
