new file mode 100644
index 0000000..84718ad
--- /dev/null
+++ b/src/utils/agentForms.ts
@@ -0,0 +1,24 @@
+import type { FormEvent } from 'react';
+
+// These preview API members are not yet included in TypeScript's DOM types.
+type AgentSubmitEvent = Event & {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<string>) => void;
+};
+
+export function submitAgentForm(
+  event: FormEvent<HTMLFormElement>,
+  submit: (data: FormData) => Promise<string>,
+) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const result = form.reportValidity()
+    // Read the actual controls: agent-filled values need not match React state.
+    ? submit(new FormData(form))
+    : Promise.resolve('Validation failed. Check the required form fields.');
+
+  const nativeEvent = event.nativeEvent as AgentSubmitEvent;
+  if (nativeEvent.agentInvoked && typeof nativeEvent.respondWith === 'function') {
+    nativeEvent.respondWith(result);
+  }
+}

