diff --git a/src/hooks/useAuthForm.ts b/src/hooks/useAuthForm.ts
new file mode 100644
index 0000000..dfdeb76
--- /dev/null
+++ b/src/hooks/useAuthForm.ts
@@ -0,0 +1,115 @@
+import { useEffect, useRef, useState } from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+
+const settings = {
+  signin: {
+    endpoint: 'login',
+    tool: 'sign_in',
+    description: 'Sign in to The DevTools Times with the user’s credentials.',
+    failure: 'Login failed',
+    success: 'Login successful!',
+  },
+  signup: {
+    endpoint: 'register',
+    tool: 'sign_up',
+    description: 'Create a DevTools Times account. Use when the user wants to register.',
+    failure: 'Registration failed',
+    success: 'User registered successfully! You can now sign in.',
+  },
+};
+
+export default function useAuthForm(mode: keyof typeof settings) {
+  const [username, setUsername] = useState('');
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [success, setSuccess] = useState<string | null>(null);
+  const [loading, setLoading] = useState(false);
+  const pending = useRef<AbortController | null>(null);
+  const config = settings[mode];
+
+  useEffect(() => () => pending.current?.abort(), []);
+
+  const submit = async (input: unknown, signal?: AbortSignal) => {
+    const fail = (message: string) => {
+      setError(message);
+      return { content: [{ type: 'text', text: message }], isError: true };
+    };
+    if (pending.current) {
+      return { content: [{ type: 'text', text: 'A submission is already in progress.' }], isError: true };
+    }
+    signal?.throwIfAborted();
+    setError(null);
+    setSuccess(null);
+    if (!input || typeof input !== 'object' ||
+        !('username' in input) || typeof input.username !== 'string' || !input.username ||
+        !('password' in input) || typeof input.password !== 'string' || !input.password) {
+      return fail('Username and password are required.');
+    }
+    if (mode === 'signup' && (input.password.length < 8 || !/[0-9]/.test(input.password))) {
+      return fail('Password must be at least 8 characters and contain a number.');
+    }
+
+    const controller = new AbortController();
+    pending.current = controller;
+    const requestSignal = signal ? AbortSignal.any([signal, controller.signal]) : controller.signal;
+    setUsername(input.username);
+    setPassword(input.password);
+    setLoading(true);
+    try {
+      const response = await fetch(`https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/${config.endpoint}`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ username: input.username, password: input.password }),
+        signal: requestSignal,
+      });
+      const data = await response.json();
+      requestSignal.throwIfAborted();
+      if (!response.ok) return fail(`${config.failure}: ${data?.error || 'Unknown error'}`);
+      setSuccess(config.success);
+      if (mode === 'signup') {
+        setUsername('');
+        setPassword('');
+      }
+      // Do not expose credentials or authentication tokens in tool results.
+      return { content: [{ type: 'text', text: config.success }] };
+    } catch (err) {
+      if (requestSignal.aborted) throw err;
+      return fail('An unexpected error occurred. Please try again later.');
+    } finally {
+      pending.current = null;
+      if (!controller.signal.aborted) setLoading(false);
+    }
+  };
+
+  useWebMCP({
+    name: config.tool,
+    description: config.description,
+    inputSchema: {
+      type: 'object',
+      properties: {
+        username: { type: 'string', minLength: 1, description: 'The account username.' },
+        password: {
+          type: 'string',
+          minLength: mode === 'signup' ? 8 : 1,
+          ...(mode === 'signup' ? { pattern: '[0-9]' } : {}),
+          description: 'The account password.',
+        },
+      },
+      required: ['username', 'password'],
+      additionalProperties: false,
+    },
+    annotations: { readOnlyHint: false },
+    execute: (input, { signal }) => submit(input, signal),
+  });
+
+  const handleSubmit = async (event: React.FormEvent) => {
+    event.preventDefault();
+    try {
+      await submit({ username, password });
+    } catch {
+      // Cancellation on unmount does not need an error message.
+    }
+  };
+
+  return { username, setUsername, password, setPassword, error, success, loading, handleSubmit };
+}
