@@ -0,0 +1,154 @@
+// @vitest-environment jsdom
+import React, { act } from 'react';
+import { createRoot, type Root } from 'react-dom/client';
+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+import SignInForm from '../src/components/SignInForm';
+import SignUpForm from '../src/components/SignUpForm';
+import SearchButton from '../src/components/SearchButton';
+
+type Tool = {
+  name: string;
+  execute: (input: unknown, options: { signal: AbortSignal }) => Promise<any>;
+};
+
+let root: Root;
+let container: HTMLDivElement;
+let tools: Map<string, Tool>;
+let fetchMock: ReturnType<typeof vi.fn>;
+
+beforeEach(() => {
+  (globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
+  tools = new Map();
+  Object.defineProperty(document, 'modelContext', {
+    configurable: true,
+    value: {
+      registerTool(tool: Tool, { signal }: { signal: AbortSignal }) {
+        if (tools.has(tool.name)) throw new Error('Duplicate tool');
+        tools.set(tool.name, tool);
+        signal.addEventListener('abort', () => tools.delete(tool.name), { once: true });
+      },
+    },
+  });
+  fetchMock = vi.fn().mockResolvedValue({ ok: true, json: async () => ({ token: 'private-token' }) });
+  vi.stubGlobal('fetch', fetchMock);
+  container = document.createElement('div');
+  document.body.append(container);
+  root = createRoot(container);
+});
+
+afterEach(async () => {
+  await act(async () => root.unmount());
+  container.remove();
+  delete (document as any).modelContext;
+  vi.unstubAllGlobals();
+});
+
+async function mount(component: React.ReactNode) {
+  await act(async () => root.render(component));
+}
+
+async function invoke(name: string, input: unknown, signal = new AbortController().signal) {
+  let result: any;
+  await act(async () => { result = await tools.get(name)!.execute(input, { signal }); });
+  return result;
+}
+
+describe('authentication tools', () => {
+  it.each([
+    ['sign_in', <SignInForm />, 'login', 'Login successful!'],
+    ['sign_up', <SignUpForm />, 'register', 'User registered successfully!'],
+  ])('executes %s and updates the form without leaking secrets', async (name, component, endpoint, message) => {
+    await mount(component);
+    const result = await invoke(name as string, { username: 'reader', password: 'secret123' });
+    expect(fetchMock).toHaveBeenCalledWith(expect.stringContaining(`/api/${endpoint}`), expect.objectContaining({
+      method: 'POST', body: JSON.stringify({ username: 'reader', password: 'secret123' }), signal: expect.any(AbortSignal),
+    }));
+    expect(container.textContent).toContain(message);
+    expect(result.isError).not.toBe(true);
+    expect(JSON.stringify(result)).not.toMatch(/secret123|private-token/);
+  });
+
+  it('rejects invalid credentials before issuing a request', async () => {
+    await mount(<SignUpForm />);
+    for (const input of [null, {}, { username: 'reader', password: 'short1' }, { username: 'reader', password: 'nonumbers' }]) {
+      expect((await invoke('sign_up', input)).isError).toBe(true);
+    }
+    expect(fetchMock).not.toHaveBeenCalled();
+  });
+
+  it('returns backend and network failures to the agent and UI', async () => {
+    await mount(<SignInForm />);
+    fetchMock.mockResolvedValueOnce({ ok: false, json: async () => ({ error: 'APP_ERR_2001' }) });
+    const result = await invoke('sign_in', { username: 'reader', password: 'bad' });
+    expect(result.isError).toBe(true);
+    expect(container.textContent).toContain('Login failed: APP_ERR_2001');
+    fetchMock.mockRejectedValueOnce(new Error('offline'));
+    expect((await invoke('sign_in', { username: 'reader', password: 'bad' })).isError).toBe(true);
+    expect(container.textContent).toContain('An unexpected error occurred');
+  });
+
+  it('uses the same submission path for a human form submit', async () => {
+    await mount(<SignInForm />);
+    for (const [id, value] of [['username', 'reader'], ['password', 'secret123']]) {
+      await act(async () => {
+        const input = container.querySelector(`#${id}`)!;
+        Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')!.set!.call(input, value);
+        input.dispatchEvent(new Event('input', { bubbles: true }));
+      });
+    }
+    await act(async () => { container.querySelector('form')!.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true })); });
+    expect(fetchMock).toHaveBeenCalledTimes(1);
+    expect(container.textContent).toContain('Login successful!');
+  });
+
+  it('prevents duplicate calls and propagates cancellation to fetch', async () => {
+    await mount(<SignInForm />);
+    fetchMock.mockImplementation((_url, { signal }) => new Promise((_resolve, reject) => {
+      signal.addEventListener('abort', () => reject(signal.reason));
+    }));
+    const controller = new AbortController();
+    let pending: Promise<any>;
+    await act(async () => {
+      pending = tools.get('sign_in')!.execute({ username: 'reader', password: 'secret123' }, { signal: controller.signal });
+    });
+    expect((await invoke('sign_in', { username: 'reader', password: 'secret123' })).isError).toBe(true);
+    expect(fetchMock).toHaveBeenCalledTimes(1);
+    await act(async () => { controller.abort(); await pending!; });
+    expect(fetchMock.mock.calls[0][1].signal.aborted).toBe(true);
+    expect(container.querySelector('button')!.disabled).toBe(false);
+  });
+
+  it('unregisters on unmount and can register again after navigation', async () => {
+    await mount(<SignInForm />);
+    expect(tools.has('sign_in')).toBe(true);
+    await mount(<SignUpForm />);
+    expect([...tools.keys()]).toEqual(['sign_up']);
+    await mount(<SignInForm />);
+    expect([...tools.keys()]).toEqual(['sign_in']);
+  });
+
+  it('keeps forms usable when WebMCP is unavailable', async () => {
+    delete (document as any).modelContext;
+    await mount(<SignInForm />);
+    expect(tools.size).toBe(0);
+    expect(container.querySelector('form')).not.toBeNull();
+  });
+});
+
+it('searches titles and summaries, displays results, and returns article links', async () => {
+  await mount(<SearchButton articles={[
+    { slug: 'coffee', title: 'Coffee Alchemy', summary: 'A morning ritual' },
+    { slug: 'science', title: 'Research', summary: 'The science of COFFEE' },
+  ]} />);
+  expect((await invoke('search_articles', { query: '' })).isError).toBe(true);
+  const result = await invoke('search_articles', { query: 'coffee' });
+  const data = JSON.parse(result.content[0].text);
+  expect(data.articles).toHaveLength(2);
+  expect(data.articles[0].url).toMatch(/articles\/coffee$/);
+  expect(container.querySelector('input')!.value).toBe('coffee');
+  expect(container.textContent).toContain('Coffee Alchemy');
+  const empty = await invoke('search_articles', { query: 'nonexistent' });
+  expect(JSON.parse(empty.content[0].text).articles).toEqual([]);
+  expect(container.textContent).toContain('No results found');
+  expect(fetchMock).not.toHaveBeenCalled();
+});

