+
+  function positionMenu(trigger, menu) {
+    if (hasAnchors && hasPopover) return;
+    const rect = trigger.getBoundingClientRect();
+    const left = Math.max(8, Math.min(rect.left, innerWidth - menu.offsetWidth - 8));
+    const top = rect.bottom + menu.offsetHeight > innerHeight - 8
+      ? Math.max(8, rect.top - menu.offsetHeight) : rect.bottom;
+    menu.style.setProperty('--menu-left', `${left}px`);
+    menu.style.setProperty('--menu-top', `${top}px`);
+  }
+
+  function syncMenu(trigger, menu) {
+    const open = isOpen(menu);
+    trigger.setAttribute('aria-expanded', String(open));
+    if (open) {
+      positionMenu(trigger, menu);
+      if (enterOnOpen.has(menu)) {
+        const items = itemsFor(menu);
+        items[enterOnOpen.get(menu) === 'last' ? items.length - 1 : 0].focus();
+      }
+    }
+    enterOnOpen.delete(menu);
+  }
+
+  function closeAll() {
+    triggers.forEach(trigger => {
+      const menu = menuFor(trigger);
+      enterOnOpen.delete(menu);
+      if (!isOpen(menu)) return;
+      if (hasPopover) menu.hidePopover();
+      else {
+        menu.removeAttribute('data-open');
+        syncMenu(trigger, menu);
+      }
+    });
+  }
+
+  function show(trigger) {
+    const menu = menuFor(trigger);
+    if (isOpen(menu)) return;
+    const enter = enterOnOpen.get(menu);
+    closeAll();
+    if (enter) enterOnOpen.set(menu, enter);
+    if (hasPopover) menu.showPopover({ source: trigger });
+    else {
+      menu.setAttribute('data-open', '');
+      syncMenu(trigger, menu);
+    }
+  }
