+  function focusTrigger(trigger, fromPointer = false) {
+    suppressPreview = true;
+    triggers.forEach(item => { item.tabIndex = item === trigger ? 0 : -1; });
+    trigger.focus({ preventScroll: true, ...(fromPointer ? { focusVisible: false } : {}) });
+    suppressPreview = false;
+  }
