+  <script>
+    (() => {
+      const remainingElement = document.getElementById('promotion-remaining');
+      const elapsedElement = document.getElementById('promotion-elapsed');
+      const hour = 60 * 60 * 1000;
+
+      function formatHours(totalHours) {
+        const days = Math.floor(totalHours / 24);
+        const hours = totalHours % 24;
+        return `${days} ${days === 1 ? 'day' : 'days'} and ${hours} ${hours === 1 ? 'hour' : 'hours'}`;
+      }
+
+      function updatePromotionTimer() {
+        // Component constructors use the visitor's local time zone, including DST.
+        // Assumed promotion start: January 1, 2026 at local midnight.
+        const start = new Date(2026, 0, 1, 0, 0, 0).getTime();
+        const end = new Date(2026, 2, 1, 0, 0, 0).getTime();
+        const now = Date.now();
+        // Round remaining time up so an active offer never displays zero hours.
+        const remainingHours = Math.ceil(Math.max(0, end - now) / hour);
+        const elapsedHours = Math.floor(Math.max(0, now - start) / hour);
+
+        remainingElement.textContent = now >= end
+          ? 'Offer ended — 0 days and 0 hours left'
+          : `${formatHours(remainingHours)} left`;
+        elapsedElement.textContent = now < start
+          ? 'Promotion has not started yet — 0 days and 0 hours elapsed.'
+          : `${formatHours(elapsedHours)} elapsed since the promotion started.`;
+      }
+
+      updatePromotionTimer();
+      setInterval(updatePromotionTimer, 60 * 1000);
+      document.addEventListener('visibilitychange', () => {
+        if (!document.hidden) updatePromotionTimer();
+      });
+    })();
