diff --git a/foreground-time.js b/foreground-time.js
new file mode 100644
--- a/foreground-time.js
+++ b/foreground-time.js
@@ -0,0 +1,27 @@
+/**
+ * Returns total page foreground time in milliseconds, including the current
+ * visible interval. Visibility measures whether the page is shown, not gaze.
+ *
+ * Browsers without visibility-state performance entries return time since
+ * navigation as an upper bound; that fallback includes background time.
+ * @returns {number}
+ */
+function getTotalForegroundTime() {
+  const entries = performance.getEntriesByType('visibility-state');
+  const now = performance.now();
+
+  if (entries.length === 0) {
+    return now;
+  }
+
+  let totalForegroundTime = 0;
+
+  for (let i = 0; i < entries.length; i++) {
+    if (entries[i].name === 'visible') {
+      const end = i + 1 < entries.length ? entries[i + 1].startTime : now;
+      totalForegroundTime += end - entries[i].startTime;
+    }
+  }
+
+  return totalForegroundTime;
+}

