+import { ml_kem768_x25519 } from '@noble/post-quantum/hybrid.js';
+import { ml_kem768 } from '@noble/post-quantum/ml-kem.js';
+
+const encoder = new TextEncoder();
+const kems = { hybrid: ml_kem768_x25519, quantum: ml_kem768 };
+export const suites = {
+  hybrid: 'ML-KEM-768+X25519 / HKDF-SHA256 / AES-256-GCM',
+  quantum: 'ML-KEM-768 / HKDF-SHA256 / AES-256-GCM',
+  classical: 'ECDH-P256 / HKDF-SHA256 / AES-256-GCM',
+};
+const b64 = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes)));
+const unb64 = text => Uint8Array.from(atob(text), char => char.charCodeAt(0));
+const random = size => crypto.getRandomValues(new Uint8Array(size));
+
+// Preview recipient keys stay in memory. Only the public key is passed to encryptNote.
+export async function createRecipient(mode = 'hybrid') {
+  if (!Object.hasOwn(suites, mode)) throw new Error('Unsupported protection mode.');
+  if (!globalThis.crypto?.subtle) throw new Error('Encryption requires HTTPS or localhost and Web Crypto support.');
+  let publicKey, privateKey;
+  if (mode === 'classical') {
+    const keys = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, false, ['deriveBits']);
+    privateKey = keys.privateKey;
+    publicKey = new Uint8Array(await crypto.subtle.exportKey('raw', keys.publicKey));
+  } else {
+    const keys = kems[mode].keygen();
+    publicKey = keys.publicKey;
+    privateKey = keys.secretKey;
+  }
+  const hash = new Uint8Array(await crypto.subtle.digest('SHA-256', publicKey));
+  return { mode, publicKey, privateKey, id: b64(hash) };
+}
+
+async function derive(secret, salt, header) {
+  const material = await crypto.subtle.importKey('raw', secret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey({ name: 'HKDF', hash: 'SHA-256', salt,
+    info: encoder.encode(`daily-grind/delivery-note/v1:${JSON.stringify(header)}`) },
+  material, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
+}
+
+export async function encryptNote(text, recipient) {
+  if (!text.trim() || text.length > 1000) throw new Error('Enter a note between 1 and 1,000 characters.');
+  const { mode, publicKey, id } = recipient;
+  if (!Object.hasOwn(suites, mode)) throw new Error('Unsupported protection mode.');
+  const header = { version: 1, suite: suites[mode], recipient: id, noteId: crypto.randomUUID(), createdAt: new Date().toISOString() };
+  let secret, capsule;
+  if (mode === 'classical') {
+    const peer = await crypto.subtle.importKey('raw', publicKey, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
+    const ephemeral = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, false, ['deriveBits']);
+    secret = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: peer }, ephemeral.privateKey, 256));
+    capsule = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeral.publicKey));
+  } else {
+    const result = kems[mode].encapsulate(publicKey);
+    secret = result.sharedSecret;
+    capsule = result.cipherText;
+  }
+  const salt = random(32), iv = random(12);
+  const bytes = encoder.encode(text);
+  try {
+    const key = await derive(secret, salt, header);
+    const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv, tagLength: 128,
+      additionalData: encoder.encode(JSON.stringify(header)) }, key, bytes);
+    return { header, capsule: b64(capsule), salt: b64(salt), iv: b64(iv), ciphertext: b64(ciphertext) };
+  } finally { secret.fill(0); bytes.fill(0); }
+}
+
+export async function decryptNote(envelope, recipient) {
+  const { header } = envelope;
+  if (header.version !== 1 || header.suite !== suites[recipient.mode] || header.recipient !== recipient.id) {
+    throw new Error('The note does not belong to this recipient or protection mode.');
+  }
+  const capsule = unb64(envelope.capsule), salt = unb64(envelope.salt), iv = unb64(envelope.iv);
+  if (salt.length !== 32 || iv.length !== 12) throw new Error('Invalid encrypted note.');
+  let secret;
+  if (recipient.mode === 'classical') {
+    const peer = await crypto.subtle.importKey('raw', capsule, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
+    secret = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: peer }, recipient.privateKey, 256));
+  } else secret = kems[recipient.mode].decapsulate(capsule, recipient.privateKey);
+  try {
+    const key = await derive(secret, salt, header);
+    const plaintext = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv, tagLength: 128,
+      additionalData: encoder.encode(JSON.stringify(header)) }, key, unb64(envelope.ciphertext)));
+    try { return new TextDecoder().decode(plaintext); } finally { plaintext.fill(0); }
+  } finally { secret.fill(0); }
+}
+
+export function disposeRecipient(recipient) {
+  if (recipient?.privateKey instanceof Uint8Array) recipient.privateKey.fill(0);
+}
