+import { createRecipient, encryptNote, decryptNote, disposeRecipient } from './crypto.js';
+
+const $ = id => document.getElementById(id);
+const form = $('note-form'), note = $('note'), status = $('status');
+const recipients = new Map();
+let saved = null;
+const descriptions = {
+  hybrid: 'Two layers of key protection. One private note.',
+  quantum: 'Post-quantum key protection with ML-KEM-768.',
+  classical: 'Established P-256 key agreement. No post-quantum protection.',
+};
+const selectedMode = () => form.elements.protection.value;
+function announce(message, error = false) {
+  status.textContent = message;
+  status.classList.toggle('error', error);
+}
+function hidePlaintext() {
+  $('revealed-note').textContent = '';
+  $('revealed-note').hidden = true;
+  $('reveal').textContent = 'Reveal note';
+  $('reveal').setAttribute('aria-expanded', 'false');
+}
+function clearResult() {
+  saved = null;
+  hidePlaintext();
+  $('encrypted-result').hidden = true;
+}
+
+note.addEventListener('input', () => {
+  $('character-count').textContent = `${note.value.length.toLocaleString()} / 1,000`;
+  note.setCustomValidity('');
+});
+form.addEventListener('change', event => {
+  if (event.target.name === 'protection') $('mode-description').textContent = descriptions[selectedMode()];
+});
+form.addEventListener('submit', async event => {
+  event.preventDefault();
+  if (!note.value.trim()) {
+    note.setCustomValidity('Please enter your delivery instructions.');
+    note.reportValidity();
+    return;
+  }
+  const mode = selectedMode(), text = note.value;
+  $('note-fields').disabled = true;
+  $('submit-label').textContent = 'Encrypting securely…';
+  announce('Preparing your encrypted note…');
+  try {
+    let recipient = recipients.get(mode);
+    if (!recipient) { recipient = await createRecipient(mode); recipients.set(mode, recipient); }
+    // Encryption receives public material only; the recipient private key is kept separate.
+    const envelope = await encryptNote(text, { mode, publicKey: recipient.publicKey, id: recipient.id });
+    clearResult();
+    saved = { envelope, recipient };
+    note.value = '';
+    $('character-count').textContent = '0 / 1,000';
+    $('encrypted-size').textContent = `${atob(envelope.ciphertext).length.toLocaleString()} encrypted bytes`;
+    $('encrypted-result').hidden = false;
+    announce('Note encrypted successfully. Nothing was sent to a delivery team.');
+  } catch {
+    announce('Your note could not be encrypted. Use HTTPS in a browser with Web Crypto support and try again. Your draft has been kept.', true);
+  } finally {
+    $('note-fields').disabled = false;
+    $('submit-label').textContent = 'Encrypt my note';
+  }
+});
+$('reveal').addEventListener('click', async () => {
+  if (!saved) return;
+  if (!$('revealed-note').hidden) { hidePlaintext(); return; }
+  try {
