new file mode 100644
index 0000000..bd361a5
--- /dev/null
+++ b/tests/crypto.test.js
@@ -0,0 +1,43 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createRecipient, encryptNote, decryptNote, disposeRecipient } from '../src/crypto.js';
+
+for (const mode of ['hybrid', 'quantum', 'classical']) {
+  test(`${mode}: public-key encryption round trip, fresh envelopes, and authentication`, async () => {
+    const recipient = await createRecipient(mode);
+    const publicRecipient = { mode, id: recipient.id, publicKey: recipient.publicKey };
+    const note = 'Gate code 0042. Quiet knock, please. ☕ مرحبًا';
+    const envelope = await encryptNote(note, publicRecipient);
+    assert.equal(await decryptNote(envelope, recipient), note);
+    assert.equal(JSON.stringify(envelope).includes('0042'), false);
+    const second = await encryptNote(note, publicRecipient);
+    assert.notEqual(envelope.iv, second.iv);
+    assert.notEqual(envelope.capsule, second.capsule);
+    assert.notEqual(envelope.ciphertext, second.ciphertext);
+    for (const property of ['ciphertext', 'capsule', 'salt', 'iv']) {
+      const altered = structuredClone(envelope);
+      const bytes = Buffer.from(altered[property], 'base64');
+      bytes[0] ^= 1;
+      altered[property] = bytes.toString('base64');
+      await assert.rejects(decryptNote(altered, recipient));
+    }
+    for (const property of ['version', 'suite', 'recipient', 'noteId', 'createdAt']) {
+      const altered = structuredClone(envelope);
+      altered.header[property] += '-tampered';
+      await assert.rejects(decryptNote(altered, recipient));
+    }
+    const stranger = await createRecipient(mode);
+    await assert.rejects(decryptNote(envelope, stranger));
+    // Also reject a wrong private key even if the attacker preserves the expected recipient id.
+    await assert.rejects(decryptNote(envelope, { ...stranger, id: recipient.id }));
+    disposeRecipient(recipient);
+    disposeRecipient(stranger);
+  });
+}
+test('rejects unknown modes, empty notes and oversized notes', async () => {
+  await assert.rejects(createRecipient('unknown'));
+  const recipient = await createRecipient();
+  await assert.rejects(encryptNote('   ', recipient));
+  await assert.rejects(encryptNote('a'.repeat(1001), recipient));
+  disposeRecipient(recipient);
+});

