@@ -0,0 +1,59 @@
+import type {
+  TransitionBeforePreparationEvent,
+  TransitionBeforeSwapEvent,
+} from 'astro:transitions/client';
+
+const unreadyPages = new WeakSet<Document>();
+
+// Decode using the same responsive source and credentials as the rendered image.
+// Detached documents do not reliably fetch images until they join the live DOM.
+async function prepareImage(source: HTMLImageElement): Promise<void> {
+  const image = new Image();
+  if (source.hasAttribute('crossorigin')) image.crossOrigin = source.crossOrigin;
+  image.referrerPolicy = source.referrerPolicy;
+  image.sizes = source.sizes;
+  image.srcset = source.srcset;
+  image.src = source.src;
+  await image.decode();
+}
+
+document.addEventListener('astro:before-preparation', (event) => {
+  const preparation = event as TransitionBeforePreparationEvent;
+  const load = preparation.loader;
+  preparation.loader = async () => {
+    // Astro loads the incoming HTML and stylesheets while the old page stays visible.
+    await load();
+    if (preparation.defaultPrevented || preparation.signal.aborted) return;
+
+    const incoming = preparation.newDocument;
+    // History and fragment navigation can land anywhere down the page.
+    const selector = preparation.navigationType === 'traverse' || preparation.to.hash
+      ? 'img'
+      : 'img[data-transition-ready], img:not([loading="lazy"])';
+    const images = Array.from(incoming.querySelectorAll<HTMLImageElement>(selector));
+    const assets = Promise.all([
+      ...images.map(prepareImage),
+      document.fonts.load('500 48px "Grenze"', incoming.body.textContent || 'The DevTools Times'),
+      document.fonts.ready,
+    ]).then(() => true, () => false);
+
+    // Never hold navigation indefinitely for an unavailable third-party asset.
+    // Skip the animation if the complete snapshot cannot be prepared in time.
+    let timeout: ReturnType<typeof setTimeout>;
+    let cancel: () => void;
+    const interrupted = new Promise<boolean>((resolve) => {
+      timeout = setTimeout(() => resolve(false), 2500);
+      cancel = () => resolve(false);
+      preparation.signal.addEventListener('abort', cancel, { once: true });
+    });
+    const ready = await Promise.race([assets, interrupted]);
+    clearTimeout(timeout!);
+    preparation.signal.removeEventListener('abort', cancel!);
+    if (!ready) unreadyPages.add(incoming);
+  };
+});
+
+document.addEventListener('astro:before-swap', (event) => {
+  const swap = event as TransitionBeforeSwapEvent;
+  if (unreadyPages.has(swap.newDocument)) swap.viewTransition.skipTransition();
+});
