+const $ = selector => document.querySelector(selector);
+const canvas = $('#render');
+const context = canvas.getContext('2d');
+const sampleOptions = [16, 64, 128, 256];
+const original = [.75, .25, .25, .25, .25, .75, .999, .999, .999, .999, .999, .999];
+let colors = [...original];
+let worker;
+let renderId = 0;
+let currentSamples = 0;
+let failed = false;
+
+function updatePalette() {
+  document.querySelectorAll('.swatch').forEach((swatch, i) => {
+    const rgb = colors.slice(i * 3, i * 3 + 3).map(value => Math.round(Math.pow(value, 1 / 2.2) * 255));
+    swatch.style.setProperty('--swatch', `rgb(${rgb.join(' ')})`);
+  });
+}
+
+function handleError(message) {
+  failed = true;
+  for (const selector of ['#randomize', '#reset', '#samples']) $(selector).disabled = true;
+  $('#render-status').textContent = message;
+  $('#status-dot').className = 'status-dot error';
+  $('#elapsed').textContent = 'Preview available';
+  $('#progress-fill').style.width = '0%';
+}
+
+function render() {
+  if (!worker || failed) return;
+  const id = ++renderId;
+  currentSamples = 0;
+  $('#render-status').textContent = 'Tracing light…';
+  $('#elapsed').textContent = 'Preparing first pass';
+  $('#status-dot').className = 'status-dot';
+  $('#progress-fill').style.width = '0%';
+  // Keep the last image visible until the first new complete frame arrives.
+  worker.postMessage({ id, width: canvas.width, height: canvas.height,
+    samples: sampleOptions[Number($('#samples').value)],
+    seed: crypto.getRandomValues(new Uint32Array(1))[0], colors });
+}
+
+function randomColor() {
+  // Evenly varied hues with enough reflectance to keep the box illuminated.
+  const hue = Math.random() * 6;
+  const saturation = .35 + Math.random() * .4;
+  const value = .72 + Math.random() * .22;
+  const chroma = value * saturation;
+  const x = chroma * (1 - Math.abs(hue % 2 - 1));
+  const base = value - chroma;
+  const components = [[chroma,x,0],[x,chroma,0],[0,chroma,x],
+    [0,x,chroma],[x,0,chroma],[chroma,0,x]][Math.floor(hue)];
+  return components.map(component => component + base);
+}
+
+$('#randomize').addEventListener('click', () => {
+  colors = Array.from({ length: 4 }, randomColor).flat();
+  updatePalette();
+  render();
+});
+$('#reset').addEventListener('click', () => {
+  colors = [...original];
+  updatePalette();
+  render();
+});
+$('#samples').addEventListener('input', () => {
+  $('#sample-value').value = `${sampleOptions[Number($('#samples').value)]} spp`;
+});
+$('#samples').addEventListener('change', render);
+$('#download').addEventListener('click', () => {
+  const save = url => {
+    const link = document.createElement('a');
+    link.download = `smallpt-${currentSamples || 'preview'}spp.png`;
+    link.href = url;
+    link.click();
+  };
+  if (canvas.hidden) {
+    save(new URL('./assets/preview.png', import.meta.url).href);
+    return;
+  }
+  canvas.toBlob(blob => {
+    if (!blob) return;
+    const url = URL.createObjectURL(blob);
+    save(url);
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }, 'image/png');
+});
+
+updatePalette();
+if (!context || !('WebAssembly' in window) || !('Worker' in window)) {
+  handleError('This browser cannot run the renderer.');
+} else {
+  try {
+    worker = new Worker(new URL('./render-worker.js', import.meta.url), { type: 'module' });
+    worker.onmessage = ({ data }) => {
+      if (data.id !== renderId) return;
+      if (data.type === 'error') {
+        handleError('Renderer could not load. Reload to try again.');
+        console.error('smallpt:', data.message);
+        return;
+      }
+      context.putImageData(new ImageData(new Uint8ClampedArray(data.pixels.buffer), canvas.width, canvas.height), 0, 0);
+      canvas.hidden = false;
+      $('#preview').hidden = true;
+      currentSamples = data.samples;
+      $('#image-samples').textContent = `${data.samples} spp`;
+      $('#render-status').textContent = data.done ? `Render complete · ${data.samples} samples per pixel` : `Refining · ${data.samples} samples per pixel`;
+      $('#status-dot').className = `status-dot${data.done ? ' complete' : ''}`;
+      $('#elapsed').textContent = `${(data.elapsed / 1000).toFixed(1)} s`;
+      $('#progress-fill').style.width = `${data.progress * 100}%`;
+    };
+    worker.onerror = event => {
+      event.preventDefault();
+      handleError('Renderer could not load. Reload to try again.');
+    };
+    render();
+  } catch {
+    handleError('Renderer could not start in this browser.');
+  }
+}
