diff --git a/render-worker.js b/render-worker.js
new file mode 100644
index 0000000..3cc04aa
--- /dev/null
+++ b/render-worker.js
@@ -0,0 +1,42 @@
+import createSmallpt from './assets/smallpt.js';
+
+let wasm;
+let latestJob = 0;
+const yieldTask = () => new Promise(resolve => setTimeout(resolve, 0));
+
+self.onmessage = async ({ data }) => {
+  const job = ++latestJob;
+  try {
+    // Share initialization across rapidly replaced render requests.
+    wasm ??= createSmallpt();
+    const module = await wasm;
+    if (job !== latestJob) return;
+    const { width, height, samples, seed, colors, id } = data;
+    const pointer = module._malloc(colors.length * 4);
+    if (!pointer) throw new Error('Could not allocate scene colors.');
+    try {
+      module.HEAPF32.set(colors, pointer / 4);
+      module._init_scene(width, height, seed, pointer);
+    } finally {
+      module._free(pointer);
+    }
+    const started = performance.now();
+    const passes = samples / 4;
+    for (let pass = 0; pass < passes; pass++) {
+      for (let row = 0; row < height; row += 8) {
+        if (job !== latestJob) return;
+        module._render_rows(row, Math.min(8, height - row));
+        // Yield between strips to allow a new palette to cancel this job.
+        await yieldTask();
+      }
+      if (job !== latestJob) return;
+      const pointer = module._get_pixels();
+      const pixels = module.HEAPU8.slice(pointer, pointer + width * height * 4);
+      self.postMessage({ type: 'frame', id, pixels, samples: (pass + 1) * 4,
+        progress: (pass + 1) / passes, elapsed: performance.now() - started,
+        done: pass + 1 === passes }, [pixels.buffer]);
+    }
+  } catch (error) {
+    if (job === latestJob) self.postMessage({ type: 'error', id: data.id, message: error.message });
+  }
+};
