diff --git a/scripts/check-wasm.mjs b/scripts/check-wasm.mjs
new file mode 100644
index 0000000..717a262
--- /dev/null
+++ b/scripts/check-wasm.mjs
@@ -0,0 +1,37 @@
+// Execute the real browser Wasm artifact without a browser or HTTP server.
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import createSmallpt from '../assets/smallpt.js';
+
+const realFetch = globalThis.fetch;
+globalThis.fetch = async input => {
+  const url = new URL(input);
+  if (url.protocol !== 'file:') return realFetch(input);
+  return new Response(await readFile(url), { headers: { 'Content-Type': 'application/wasm' } });
+};
+try {
+  const wasm = await createSmallpt();
+  const width = 64, height = 48;
+  const pointer = wasm._malloc(12 * 4);
+  const original = [.75,.25,.25,.25,.25,.75,.999,.999,.999,.999,.999,.999];
+  const randomized = [.25,.85,.4,.85,.45,.2,.6,.8,.3,.8,.3,.7];
+  const render = (colors, passes = 2) => {
+    wasm.HEAPF32.set(colors, pointer / 4);
+    wasm._init_scene(width, height, 42, pointer);
+    for (let pass = 0; pass < passes; ++pass)
+      for (let row = 0; row < height; row += 8) wasm._render_rows(row, 8);
+    const result = wasm.HEAPU8.slice(wasm._get_pixels(), wasm._get_pixels() + width * height * 4);
+    assert.equal(result.length, width * height * 4);
+    for (let i = 3; i < result.length; i += 4) assert.equal(result[i], 255, 'Every pixel must be opaque');
+    assert.ok(result.some((value, i) => i % 4 !== 3 && value > 0), 'Render must contain light');
+    return result;
+  };
+  const baseline = render(original);
+  assert.deepEqual(render(original), baseline, 'Scene reset must be deterministic for a fixed seed');
+  assert.notDeepEqual(render(randomized), baseline, 'Changing colors must change rendered pixels');
+  assert.notDeepEqual(render(original, 3), baseline, 'Further samples must refine the image');
+  wasm._free(pointer);
+  console.log('Wasm checks passed: RGBA output, repeatable reset, changed palette, progressive accumulation.');
+} finally {
+  globalThis.fetch = realFetch;
+}
diff --git a/src/renderer.cpp b/src/renderer.cpp
new file mode 100644
index 0000000..6137645
--- /dev/null
+++ b/src/renderer.cpp
@@ -0,0 +1,64 @@
+// Browser adapter for Kevin Beason's MIT-licensed smallpt.
+#define SMALLPT_LIBRARY
+#pragma GCC diagnostic push
+#pragma GCC diagnostic ignored "-Wdangling-else"
+#include "../vendor/smallpt/smallpt.cpp"
+#pragma GCC diagnostic pop
+#include <vector>
+#include <cstdint>
+
+static int width, height;
+static unsigned int sceneSeed;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+static std::vector<unsigned int> passes;
+
+extern "C" {
+void init_scene(int w, int h, unsigned int seed, const float* colors) {
+  width = w; height = h; sceneSeed = seed;
+  accumulation.assign(w*h, Vec());
+  pixels.assign(w*h*4, 0);
+  passes.assign(h, 0);
+  // Only surface reflectance changes; geometry, emission and BRDFs stay original.
+  const int ids[] = {0, 1, 6, 7};
+  for (int i=0; i<4; ++i)
+    spheres[ids[i]].c = Vec(colors[i*3], colors[i*3+1], colors[i*3+2]);
+}
+
+void render_rows(int first, int count) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for (int y=first; y<first+count && y<height; ++y) {
+    unsigned int pass=++passes[y];
+    uint32_t hash = sceneSeed ^ (uint32_t(y+1)*2654435761u) ^ (pass*2246822519u);
+    unsigned short Xi[3] = {static_cast<unsigned short>(hash),
+      static_cast<unsigned short>(hash>>16), static_cast<unsigned short>(pass*7919u+y)};
+    for (int x=0; x<width; ++x) {
+      int i=(height-y-1)*width+x;
+      Vec r;
+      for(int sy=0; sy<2; ++sy) for(int sx=0; sx<2; ++sx) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+
+          cy*(((sy+.5+dy)/2+y)/height-.5)+cam.d;
+        r=r+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      accumulation[i]=accumulation[i]+r;
+      Vec c=accumulation[i]*(1./pass);
+      pixels[i*4]=toInt(c.x); pixels[i*4+1]=toInt(c.y);
+      pixels[i*4+2]=toInt(c.z); pixels[i*4+3]=255;
+    }
+  }
+}
+unsigned char* get_pixels() { return pixels.data(); }
+}
+
+#ifdef SMALLPT_PREVIEW
+int main() {
+  float colors[]={.75,.25,.25,.25,.25,.75,.999,.999,.999,.999,.999,.999};
+  init_scene(640,480,42,colors);
+  for(int p=0;p<64;++p) render_rows(0,480);
+  FILE* f=fopen("/tmp/smallpt-preview.rgba","wb");
+  fwrite(get_pixels(),1,640*480*4,f); fclose(f);
+}
+#endif
