+const $ = id => document.getElementById(id);
+const canvas = $('render');
+const ctx = canvas.getContext('2d');
+const original = [[0,.75,.25,.25],[1,.25,.25,.75],[2,.75,.75,.75],[4,.75,.75,.75],[5,.75,.75,.75],[6,.999,.999,.999],[7,.999,.999,.999]];
+let colors = original.map(c => [...c]);
+let worker, paused = false, running = false, paletteNumber = 0, hasImage = false;
+const preview = new Image();
+preview.onload = () => { if (!hasImage) {ctx.drawImage(preview,0,0,canvas.width,canvas.height); hasImage=true;} };
+preview.src = 'assets/preview.png';
+function updatePause() {
+  $('pause-label').textContent = running ? (paused ? 'Resume' : 'Pause') : 'Render again';
+  $('pause-icon').textContent = running ? (paused ? '▷' : 'Ⅱ') : '↻';
+}
+function fail(message) {
+  running = false;
+  $('status').textContent = message;
+  $('render-state').textContent = 'UNAVAILABLE';
+  updatePause();
+}
+function startRender() {
+  if (!window.Worker || !window.WebAssembly) { fail('This browser needs WebAssembly and Web Workers.'); return; }
+  if (worker) worker.terminate();
+  const width = Number($('resolution').value), height = width * .75;
+  // Keep the last render visible until the first complete pass arrives.
+  $('dimensions').textContent = `${width} × ${height}`;
+  $('spp').textContent = '0'; $('elapsed').textContent = '0.0s';
+  $('progress').style.width = '0%';
+  $('status').textContent = 'Preparing the scene';
+  $('render-state').textContent = 'RENDERING';
+  paused = false; running = true; updatePause();
+  worker = new Worker('assets/render-worker.js');
+  worker.onerror = () => { worker.terminate(); fail('Renderer could not load. Reload to try again.'); };
+  worker.onmessage = ({data}) => {
+    if (data.type === 'progress') {
+      $('progress').style.width = `${data.progress*100}%`;
+      $('elapsed').textContent = `${(data.elapsed/1000).toFixed(1)}s`;
+      if (!paused) $('status').textContent = `Tracing light · ${Math.floor(data.progress*100)}%`;
+    } else if (data.type === 'frame') {
+      if (canvas.width !== data.width || canvas.height !== data.height) { canvas.width=data.width; canvas.height=data.height; }
+      ctx.putImageData(new ImageData(new Uint8ClampedArray(data.pixels),data.width,data.height),0,0);
+      hasImage=true; $('spp').textContent = data.spp;
+    } else if (data.type === 'done') {
+      running = false; paused = false;
+      $('status').textContent = 'Render complete'; $('render-state').textContent = 'COMPLETE';
+      $('progress').style.width = '100%'; updatePause(); worker.terminate();
+    } else if (data.type === 'error') { fail('Render failed. Select Render again to retry.'); console.error(data.message); }
+  };
+  const seed = crypto.getRandomValues(new Uint32Array(1))[0];
+  worker.postMessage({type:'render',width,height,samples:Number($('quality').value),seed,colors});
+}
+function updatePalette() {
+  const ids = [0,1,2,6,7];
+  [...$('palette').children].forEach((swatch,index) => {
+    const color=colors.find(c=>c[0]===ids[index]);
+    swatch.style.setProperty('--swatch',`rgb(${color.slice(1).map(c=>Math.round(c*255)).join(',')})`);
+  });
+}
+// HSL palettes keep randomized reflectances bounded below one for path termination.
+function hueColor(h,s,l) {
+  const a=s*Math.min(l,1-l);
+  return [0,8,4].map(n=>{const k=(n+h/30)%12; return l-a*Math.max(-1,Math.min(k-3,9-k,1));});
+}
+$('randomize').onclick = () => {
+  const random = crypto.getRandomValues(new Uint32Array(5));
+  const hue = random[0]%360;
+  colors = original.map(c=>[...c]);
+  [0,1,2,6,7].forEach((id,i)=>{
+    const rgb=hueColor((hue+i*53+random[i]%40)%360, id===2?.18:.45, id>=6?.77:.52);
+    colors.find(c=>c[0]===id).splice(1,3,...rgb);
+  });
+  paletteNumber++; $('palette-name').textContent = `Color study ${String(paletteNumber).padStart(2,'0')}`;
+  updatePalette(); startRender();
+};
+$('reset').onclick = () => {colors=original.map(c=>[...c]); $('palette-name').textContent='The original'; updatePalette();startRender();};
+$('quality').onchange = startRender;
+$('resolution').onchange = startRender;
+$('pause').onclick = () => {
+  if (!running) {startRender(); return;}
+  paused=!paused; worker.postMessage({type:'pause',paused});
+  $('render-state').textContent=paused?'PAUSED':'RENDERING';
+  $('status').textContent=paused?'Render paused':'Tracing light'; updatePause();
+};
+$('download').onclick = () => {
+  if (!hasImage) return;
+  canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a'); a.href=url;a.download=`smallpt-${paletteNumber?'color-study-'+paletteNumber:'original'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');
+};
+$('expand').onclick = async () => {
+  try {if(document.fullscreenElement) await document.exitFullscreen(); else await canvas.parentElement.requestFullscreen();} catch { $('status').textContent='Fullscreen is unavailable in this view.'; }
+};
+startRender();
