+/* The C++ renderer runs entirely in this worker; the page only paints its pixels. */
+importScripts('smallpt.js');
+const runtime = createSmallpt();
+let paused = false;
+let active = false;
+const nextTask = () => new Promise(resolve => setTimeout(resolve, 0));
+onmessage = async ({data}) => {
+  if (data.type === 'pause') { paused = data.paused; return; }
+  if (data.type !== 'render' || active) return;
+  active = true;
+  try {
+    const m = await runtime;
+    const {width, height, samples, seed, colors} = data;
+    m._init(width, height, seed);
+    colors.forEach(([id,r,g,b]) => m._color(id,r,g,b));
+    let elapsed = 0;
+    for (let pass = 0; pass < samples / 4; pass++) {
+      for (let row = 0; row < height; row += 8) {
+        while (paused) await new Promise(resolve => setTimeout(resolve, 50));
+        const started = performance.now();
+        m._render_rows(row, 8, pass);
+        elapsed += performance.now() - started;
+        postMessage({type:'progress', progress:(pass + Math.min(row+8,height)/height)/(samples/4), elapsed});
+        await nextTask();
+      }
+      const ptr = m._pixels();
+      const pixels = m.HEAPU8.slice(ptr, ptr + width * height * 4);
+      postMessage({type:'frame', pixels, width, height, spp:(pass+1)*4, elapsed}, [pixels.buffer]);
+    }
+    postMessage({type:'done', elapsed});
+  } catch (error) {
+    postMessage({type:'error', message:String(error)});
+  }
+  active = false;
+};
