--- /dev/null
+++ b/scripts/check-wasm.cjs
@@ -0,0 +1,21 @@
+const assert = require('node:assert/strict');
+const createSmallpt = require('../assets/smallpt.js');
+(async () => {
+  const m=await createSmallpt();
+  function render(seed, tint=false) {
+    m._init(48,36,seed);
+    m._color(6,...(tint?[.2,.8,.3]:[.999,.999,.999]));
+    m._color(7,...(tint?[.8,.3,.2]:[.999,.999,.999]));
+    for(let pass=0;pass<4;pass++) m._render_rows(0,36,pass);
+    const data=m.HEAPU8.slice(m._pixels(),m._pixels()+48*36*4);
+    assert.equal(data.length,48*36*4);
+    assert(data.some((v,i)=>i%4!==3 && v>20),'render has visible light');
+    assert(data.every((v,i)=>i%4!==3 || v===255),'all pixels are opaque');
+    return data;
+  }
+  const original=render(42);
+  assert.deepEqual(original,render(42),'same seed reproduces output');
+  assert.notDeepEqual(original,render(42,true),'sphere colors change output');
+  assert.notDeepEqual(original,render(43),'new seed changes sampling');
+  console.log('WASM checks passed: pixels, alpha, determinism, sphere colors, random seeds.');
+})().catch(error=>{console.error(error);process.exitCode=1;});
diff --git a/scripts/render-preview.cjs b/scripts/render-preview.cjs
new file mode 100644
