--- /dev/null
+++ b/scripts/render-preview.cjs
@@ -0,0 +1,16 @@
+const fs = require('node:fs');
+const createSmallpt = require('../assets/smallpt.js');
+(async()=>{
+  const m = await createSmallpt();
+  const w=640,h=480,passes=32;
+  m._init(w,h,42);
+  for(let p=0;p<passes;p++) m._render_rows(0,h,p);
+  const bytes=m.HEAPU8.slice(m._pixels(),m._pixels()+w*h*4);
+  if (!bytes.some((v,i)=>i%4!==3 && v>0)) throw Error('Rendered image is empty');
+  const header=Buffer.from(`P6\n${w} ${h}\n255\n`);
+  const rgb=Buffer.alloc(w*h*3);
+  for(let i=0;i<w*h;i++) for(let c=0;c<3;c++) rgb[i*3+c]=bytes[i*4+c];
+  fs.writeFileSync('/tmp/smallpt-preview.ppm',Buffer.concat([header,rgb]));
+  require('node:child_process').execFileSync('convert',['/tmp/smallpt-preview.ppm','assets/preview.png']);
+  console.log(`Rendered ${w}x${h} at ${passes*4} spp using compiled WebAssembly.`);
+})();
