@@ -0,0 +1,42 @@
+// Browser adapter for Kevin Beason's smallpt. See LICENSE.txt.
+#define main smallpt_original_main
+#include "smallpt-original.cpp"
+#undef main
+#include <vector>
+#include <stdint.h>
+
+static int width, height;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+static unsigned int renderSeed;
+extern "C" {
+unsigned char* init_render(int w, int h, unsigned int seed, float ar, float ag, float ab, float br, float bg, float bb) {
+  width=w; height=h; renderSeed=seed;
+  accumulation.assign(w*h, Vec()); pixels.assign(w*h*4, 0);
+  spheres[0].c=Vec(ar,ag,ab); spheres[1].c=Vec(br,bg,bb);
+  // Preserve the original mirror and glass materials; tint their reflectance.
+  spheres[6].c=Vec(.65+.349*ar,.65+.349*ag,.65+.349*ab);
+  spheres[7].c=Vec(.65+.349*br,.65+.349*bg,.65+.349*bb);
+  return pixels.data();
+}
+void render_rows(int start, int count, int pass) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for(int y=start;y<start+count && y<height;y++) {
+    unsigned short Xi[3]={(unsigned short)renderSeed,(unsigned short)(renderSeed>>16),(unsigned short)(y*y*y+pass*7919)};
+    for(int x=0;x<width;x++) {
+      Vec sample;
+      for(int sy=0;sy<2;sy++) for(int sx=0;sx<2;sx++) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+cy*(((sy+.5+dy)/2+y)/height-.5)+cam.d;
+        sample=sample+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      int i=(height-y-1)*width+x;
+      accumulation[i]=accumulation[i]+sample;
+      Vec c=accumulation[i]*(1.0/(pass+1));
+      pixels[i*4]=toInt(c.x); pixels[i*4+1]=toInt(c.y); pixels[i*4+2]=toInt(c.z); pixels[i*4+3]=255;
+    }
+  }
+}
+}
