@@ -0,0 +1,96 @@
+const $ = (id) => document.getElementById(id);
+const canvas = $('render');
+const context = canvas.getContext('2d');
+let worker;
+let samples = 64;
+let paletteNumber = 1;
+let colors = [[.75, .25, .25], [.25, .25, .75]];
+let timer;
+let started;
+
+function render() {
+  worker?.terminate();
+  clearInterval(timer);
+  const width = Number($('resolution').value);
+  const height = width * .75;
+  canvas.width = width;
+  canvas.height = height;
+  canvas.style.opacity = '0';
+  $('reference').style.opacity = '.65';
+  $('status').textContent = 'Tracing light…';
+  $('status-dot').style.background = '#d1e99e';
+  $('canvas-state').textContent = paletteNumber === 1 ? 'Original scene' : `Palette ${String(paletteNumber).padStart(2, '0')}`;
+  $('render-size').textContent = `${width} × ${height}`;
+  $('spp').textContent = '0';
+  $('progress').style.width = '0%';
+  started = performance.now();
+  timer = setInterval(() => { $('elapsed').textContent = `${((performance.now() - started) / 1000).toFixed(1)}s`; }, 100);
+  try {
+    worker = new Worker(new URL('./wasm/render-worker.js', import.meta.url), {type: 'module'});
+    worker.onmessage = ({data}) => {
+      if (data.error) { fail(data.error); return; }
+      context.putImageData(new ImageData(new Uint8ClampedArray(data.pixels), width, height), 0, 0);
+      canvas.style.opacity = '1';
+      $('reference').style.opacity = '0';
+      $('spp').textContent = data.samples;
+      $('progress').style.width = `${data.samples / samples * 100}%`;
+      if (data.done) {
+        clearInterval(timer);
+        $('elapsed').textContent = `${(data.elapsed / 1000).toFixed(1)}s`;
+        $('status').textContent = 'Render complete';
+        worker.terminate();
+      } else {
+        $('status').textContent = `Tracing light · ${Math.round(data.samples / samples * 100)}%`;
+      }
+    };
+    worker.onerror = (event) => { event.preventDefault(); fail(event.message); };
+    const seed = crypto.getRandomValues(new Uint32Array(1))[0];
+    worker.postMessage({width, height, samples, seed, colors});
+  } catch(error) { fail(error.message); }
+}
+function fail(message) {
+  clearInterval(timer);
+  worker?.terminate();
+  $('status').textContent = 'Render unavailable · click Randomize to retry';
+  $('status-dot').style.background = '#e0a372';
+  $('reference').style.opacity = '1';
+  console.error('smallpt:', message);
+}
+function randomColor() {
+  const hue = crypto.getRandomValues(new Uint32Array(1))[0] / 4294967296 * 360;
+  const saturation = .35 + Math.random() * .35;
+  const lightness = .49 + Math.random() * .12;
+  const a = saturation * Math.min(lightness, 1-lightness);
+  return [0,8,4].map(n => {
+    const k = (n + hue / 30) % 12;
+    return Math.min(.86, lightness - a * Math.max(-1, Math.min(k-3, 9-k, 1)));
+  });
+}
+function hex(color) { return '#' + color.map(n => Math.round(n * 255).toString(16).padStart(2,'0')).join('').toUpperCase(); }
+$('randomize').addEventListener('click', () => {
+  colors = [randomColor(), randomColor()];
+  paletteNumber++;
+  $('palette-number').textContent = String(paletteNumber).padStart(2, '0');
+  ['a','b'].forEach((letter, index) => {
+    const value = hex(colors[index]);
+    $('swatch-' + letter).style.setProperty('--swatch', value);
+    $('hex-' + letter).textContent = value;
+  });
+  render();
+});
+document.querySelectorAll('[data-samples]').forEach(button => {
+  button.addEventListener('click', () => {
+    samples = Number(button.dataset.samples);
+    document.querySelectorAll('[data-samples]').forEach(el => {el.classList.toggle('selected', el === button); el.setAttribute('aria-pressed', String(el === button));});
+    render();
+  });
+  button.setAttribute('aria-pressed', String(Number(button.dataset.samples) === samples));
+});
+$('resolution').addEventListener('change', render);
+$('expand').addEventListener('click', () => {
+  const expanded = document.querySelector('.render-panel').classList.toggle('expanded');
+  $('expand').setAttribute('aria-label', expanded ? 'Close expanded render' : 'Expand render');
+});
+document.addEventListener('keydown', event => { if(event.key === 'Escape') document.querySelector('.render-panel').classList.remove('expanded'); });
+window.addEventListener('pagehide', () => { worker?.terminate(); clearInterval(timer); });
+render();
