new file mode 100644
index 0000000..ffd4ded
--- /dev/null
+++ b/public/wasm/render-worker.js
@@ -0,0 +1,17 @@
+import createSmallpt from './smallpt.js';
+const ready = createSmallpt();
+self.onmessage = async ({data}) => {
+  try {
+    const mod = await ready;
+    const {width, height, samples, seed, colors} = data;
+    const ptr = mod._init_render(width, height, seed, ...colors.flat());
+    const start = performance.now();
+    for (let pass = 0; pass < samples / 4; pass++) {
+      for (let row = 0; row < height; row += 8) mod._render_rows(row, 8, pass);
+      const pixels = mod.HEAPU8.slice(ptr, ptr + width * height * 4);
+      self.postMessage({pixels, width, height, samples: (pass + 1) * 4, elapsed: performance.now() - start, done: (pass + 1) * 4 === samples}, [pixels.buffer]);
+    }
+  } catch (error) {
+    self.postMessage({error: error.message || String(error)});
+  }
+};
