+#!/usr/bin/env bash
+set -euo pipefail
+cd "$(dirname "$0")/.."
+em++ native/smallpt-wasm.cpp -O3 -Wno-c++11-narrowing -Wno-dangling-else --no-entry -s MODULARIZE=1 -s EXPORT_ES6=1 -s ENVIRONMENT=worker -s ALLOW_MEMORY_GROWTH=1 -s FILESYSTEM=0 -s EXPORTED_FUNCTIONS='["_init_render","_render_rows"]' -s EXPORTED_RUNTIME_METHODS='["HEAPU8"]' -o public/wasm/smallpt.js
