@@ -0,0 +1,24 @@
+import assert from 'node:assert/strict';
+import fs from 'node:fs';
+import createSmallpt from '../public/wasm/smallpt.js';
+const bytes = fs.readFileSync(new URL('../public/wasm/smallpt.wasm', import.meta.url));
+const mod = await createSmallpt({
+  instantiateWasm(imports, receive) {
+    const instance = new WebAssembly.Instance(new WebAssembly.Module(bytes), imports);
+    receive(instance);
+    return instance.exports;
+  }
+});
+function render(colors) {
+  const ptr = mod._init_render(64, 48, 1234, ...colors);
+  for (let row = 0; row < 48; row += 8) mod._render_rows(row, 8, 0);
+  const data = mod.HEAPU8.slice(ptr, ptr + 64 * 48 * 4);
+  assert(data.some((value, index) => index % 4 !== 3 && value > 0), 'Image contains visible light');
+  for (let i = 3; i < data.length; i += 4) assert.equal(data[i], 255, 'Every row is rendered');
+  return data;
+}
+const original = render([.75, .25, .25, .25, .25, .75]);
+const randomized = render([.2, .7, .3, .8, .4, .2]);
+assert.notDeepEqual(original, randomized, 'Changing sphere colors changes the rendered pixels');
+assert.deepEqual(original, render([.75, .25, .25, .25, .25, .75]), 'New renders reset the accumulation');
+console.log('WASM check passed: visible RGBA output, color changes, and clean render resets.');
