+  <script>
+    const actionTarget = document.getElementById('action-target');
+    const actionButtons = document.querySelectorAll('button[commandfor="action-target"]');
+    const actionClasses = new Map([
+      ['--spin', 'is-spun'],
+      ['--grow', 'is-grown'],
+      ['--round', 'is-rounded'],
+    ]);
+
+    function handleAction(command) {
+      if (command === '--reset') {
+        actionTarget.classList.remove(...actionClasses.values());
+      } else {
+        const className = actionClasses.get(command);
+        if (!className) return;
+        actionTarget.classList.toggle(className);
+      }
+
+      actionButtons.forEach((button) => {
+        const className = actionClasses.get(button.getAttribute('command'));
+        if (className) {
+          button.setAttribute('aria-pressed', String(actionTarget.classList.contains(className)));
+        }
+      });
+    }
+
+    actionTarget.addEventListener('command', (event) => handleAction(event.command));
+
+    // Older browsers use the same handler without native invoker commands.
+    if (!('commandForElement' in HTMLButtonElement.prototype)) {
+      actionButtons.forEach((button) => {
+        button.addEventListener('click', (event) => {
+          if (!event.defaultPrevented) handleAction(button.getAttribute('command'));
+        });
+      });
