+  #heading;
+  #description;
+  #price;
+  #link;
+
+  get name() { return this.getAttribute('name') ?? ''; }
+  set name(value) { this.#setString('name', value); }
+
+  get description() { return this.getAttribute('description') ?? ''; }
+  set description(value) { this.#setString('description', value); }
+
+  get href() { return this.getAttribute('href') ?? ''; }
+  set href(value) { this.#setString('href', value); }
+
+  // Missing, invalid, infinite, and negative prices read as zero.
+  // An absent price attribute hides the optional price line.
+  get price() {
+    const value = Number(this.getAttribute('price'));
+    return Number.isFinite(value) && value >= 0 ? value : 0;
+  }
+  set price(value) {
+    if (value == null) {
+      this.removeAttribute('price');
+      return;
+    }
+    const number = Number(value);
+    this.setAttribute('price', String(Number.isFinite(number) && number >= 0 ? number : 0));
+  }
+
+  get disabled() { return this.hasAttribute('disabled'); }
+  set disabled(value) { this.toggleAttribute('disabled', Boolean(value)); }
+
+  connectedCallback() {
+    // Assignments made before registration must not shadow the accessors.
+    for (const property of reflectedProperties) {
+      if (Object.hasOwn(this, property)) {
+        const value = this[property];
+        delete this[property];
+        this[property] = value;
+      }
+    }
+
+    this.classList.add('card');
+    if (!this.#heading) {
+      // Reuse the static fallback markup, or create nodes for a new instance.
+      this.#heading = this.querySelector('h3') ?? this.appendChild(document.createElement('h3'));
+      this.#description = this.querySelector('p') ?? this.appendChild(document.createElement('p'));
+      this.#link = this.querySelector('a') ?? this.appendChild(document.createElement('a'));
+      this.#link.classList.add('btn');
+      this.#link.textContent = 'View Details';
+      this.#price = document.createElement('p');
+      this.#price.className = 'price';
+      this.#link.before(this.#price);
+    }
+    this.#render();
+    // The same callback is used on every connection, preventing duplicates.
+    this.#link.addEventListener('click', this.#handleClick);
+  }
+
+  disconnectedCallback() {
+    this.#link?.removeEventListener('click', this.#handleClick);
+  }
+
+  attributeChangedCallback(_name, oldValue, newValue) {
+    if (oldValue !== newValue && this.#heading) this.#render();
+  }
+
+  #setString(attribute, value) {
+    if (value == null) this.removeAttribute(attribute);
+    else this.setAttribute(attribute, String(value));
+  }
+
+  #render() {
+    this.#heading.textContent = this.name;
+    this.#description.textContent = this.description;
+    this.#price.hidden = !this.hasAttribute('price');
+    this.#price.textContent = currency.format(this.price);
+
+    // Restrict navigation to web URLs and relative paths, including script input.
+    let safeHref = null;
+    if (this.href) {
+      try {
+        const url = new URL(this.href, this.baseURI);
+        if (url.protocol === 'http:' || url.protocol === 'https:') safeHref = this.href;
+      } catch { /* Invalid URLs leave the details link unavailable. */ }
+    }
+    const unavailable = this.disabled || safeHref === null;
+    if (unavailable) {
+      this.#link.removeAttribute('href');
+      this.#link.setAttribute('role', 'link');
+      this.#link.setAttribute('aria-disabled', 'true');
+      this.#link.tabIndex = -1;
+    } else {
+      this.#link.setAttribute('href', safeHref);
+      this.#link.removeAttribute('role');
+      this.#link.removeAttribute('aria-disabled');
+      this.#link.removeAttribute('tabindex');
+    }
+  }
+
+  #handleClick = (event) => {
+    if (this.#link.getAttribute('aria-disabled') === 'true') event.preventDefault();
+  };
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
