+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { Window } from 'happy-dom';
+
+const window = new Window({ url: 'https://daily-grind.example/' });
+for (const name of ['document', 'HTMLElement', 'customElements', 'CustomEvent']) {
+  globalThis[name] = window[name];
+}
+await import('./coffee-card.js');
+
+function card() {
+  const element = document.createElement('coffee-card');
+  document.body.append(element);
+  return element;
+}
+
+test('string properties and attributes update the isolated card content', () => {
+  const first = card();
+  const second = card();
+  first.name = 'Maple Oat Latte';
+  first.setAttribute('description', 'Creamy oat milk.');
+  first.href = '/menu/seasonal';
+  assert.equal(first.getAttribute('name'), 'Maple Oat Latte');
+  assert.equal(first.description, 'Creamy oat milk.');
+  assert.equal(first.shadowRoot.querySelector('h3').textContent, first.name);
+  assert.equal(first.shadowRoot.querySelector('.description').textContent, first.description);
+  assert.equal(first.shadowRoot.querySelector('a').getAttribute('href'), '/menu/seasonal');
+  assert.equal(second.name, '');
+  first.name = '<img src=x onerror=alert(1)>';
+  assert.equal(first.shadowRoot.querySelector('img'), null);
+  first.name = null;
+  first.href = null;
+  assert.equal(first.hasAttribute('name'), false);
+  assert.equal(first.name, '');
+  assert.equal(first.href, '/menu');
+  first.href = 'javascript:alert(1)';
+  assert.equal(first.shadowRoot.querySelector('a').getAttribute('href'), '/menu');
+  first.remove();
+  second.remove();
+});
+
+test('price reflects as a finite nonnegative number and can be omitted', () => {
+  const element = card();
+  const price = element.shadowRoot.querySelector('.price');
+  assert.equal(element.price, 0);
+  assert.equal(price.hidden, true);
+  element.price = 5.5;
+  assert.equal(element.getAttribute('price'), '5.5');
+  assert.equal(price.textContent, '$5.50');
+  assert.equal(price.hidden, false);
+  element.setAttribute('price', '4.25');
+  assert.equal(element.price, 4.25);
+  assert.equal(price.textContent, '$4.25');
+  for (const invalid of ['oops', '-2', 'Infinity']) {
+    element.setAttribute('price', invalid);
+    assert.equal(element.price, 0);
+    assert.equal(price.textContent, '$0.00');
+  }
+  element.price = NaN;
+  assert.equal(element.getAttribute('price'), '0');
+  element.price = null;
+  assert.equal(element.hasAttribute('price'), false);
+  assert.equal(price.hidden, true);
+  element.remove();
+});
+
+test('featured follows boolean attribute presence, including the string false', () => {
+  const element = card();
+  const badge = element.shadowRoot.querySelector('.featured');
+  assert.equal(element.featured, false);
+  assert.equal(badge.hidden, true);
+  element.featured = true;
+  assert.equal(element.getAttribute('featured'), '');
+  assert.equal(badge.hidden, false);
+  element.featured = false;
+  assert.equal(element.hasAttribute('featured'), false);
+  element.setAttribute('featured', 'false');
+  assert.equal(element.featured, true);
+  assert.equal(badge.hidden, false);
+  element.removeAttribute('featured');
+  assert.equal(element.featured, false);
+  assert.equal(badge.hidden, true);
+  element.remove();
+});
+
+test('connection lifecycle cleans up and restores a single cancelable event listener', () => {
+  const element = card();
+  element.name = 'Cold Brew';
+  const link = element.shadowRoot.querySelector('a');
+  let selections = 0;
+  let localSelections = 0;
+  element.addEventListener('coffee-select', () => localSelections++);
+  const onSelect = (event) => {
+    selections++;
+    assert.equal(event.detail.name, 'Cold Brew');
+    event.preventDefault();
+  };
+  document.body.addEventListener('coffee-select', onSelect);
+  const click = () => {
+    const event = new window.MouseEvent('click', { bubbles: true, cancelable: true, composed: true });
+    link.dispatchEvent(event);
+    return event;
+  };
+  assert.equal(click().defaultPrevented, true);
+  assert.equal(selections, 1);
+  element.remove();
+  assert.equal(click().defaultPrevented, false);
+  assert.equal(localSelections, 1);
+  document.body.append(element);
+  assert.equal(click().defaultPrevented, true);
+  assert.equal(selections, 2);
+  element.remove();
+  document.body.append(element);
+  click();
+  assert.equal(selections, 3);
+  assert.equal(localSelections, 3);
+  document.body.removeEventListener('coffee-select', onSelect);
+  element.remove();
+});
+
+test('properties set before upgrade take precedence over declarative attributes', () => {
+  const element = document.createElement('late-coffee-card');
+  element.setAttribute('name', 'Original');
+  element.name = 'Pre-upgrade name';
+  element.price = 6;
+  element.featured = true;
+  // Register a subclass to exercise the same upgrade path after property assignment.
+  customElements.define('late-coffee-card', class extends customElements.get('coffee-card') {});
+  document.body.append(element);
+  const upgraded = document.querySelector('late-coffee-card');
+  assert.equal(upgraded.name, 'Pre-upgrade name');
+  assert.equal(upgraded.getAttribute('name'), 'Pre-upgrade name');
+  assert.equal(upgraded.getAttribute('price'), '6');
+  assert.equal(upgraded.hasAttribute('featured'), true);
+  upgraded.remove();
+});
