+  $('preview-label').textContent = `YOUR ${voucher ? 'VOUCHER' : 'RECEIPT'} PREVIEW`;
+  $('receipt-type').textContent = voucher ? 'GIFT VOUCHER' : 'COFFEE RECEIPT';
+  $('preview-amount').textContent = money(payload.amountCents || 0);
+  $('preview-recipient').textContent = payload.recipient || 'Your name here';
+  $('preview-description').textContent = payload.description || 'A little daily pick-me-up';
+  $('preview-recipient-label').textContent = voucher ? 'A gift for' : 'Prepared for';
+  $('preview-date').textContent = formatDate(payload.issuedAt);
+  $('preview-id').textContent = payload.id || 'Assigned on signing';
+  if (signed) {
+    $('document-state').textContent = verified ? '✓ Signature verified' : '✓ Digitally signed';
