+  validatePayload(payload);
+  const doc = { version: 1, suite: SUITE, keyId: signer.id, payload: structuredClone(payload) };
+  doc.signature = encode(await crypto.subtle.sign(params, signer.privateKey, signedBytes(doc)));
+  return doc;
+}
+export async function verifyDocument(doc, trusted) {
+  if (!doc || doc.version !== 1 || doc.suite !== SUITE || Object.keys(doc).sort().join(',') !== 'keyId,payload,signature,suite,version') throw new Error('Unsupported or malformed signed document.');
+  validatePayload(doc.payload);
+  if (!trusted || doc.keyId !== trusted.id) throw new Error('Unknown issuer key. Import a public key from an issuer you trust.');
+  const valid = await crypto.subtle.verify(params, trusted.publicKey, decode(doc.signature), signedBytes(doc));
+  if (!valid) throw new Error('Signature invalid. This document may have been changed.');
+  return doc.payload;
+}
+export async function exportVerifier(signer) {
+  return { format: 'daily-grind-public-key-v1', suite: SUITE, fingerprint: signer.id, publicKey: encode(await crypto.subtle.exportKey('raw', signer.publicKey)) };
+}
+export async function importVerifier(data) {
+  if (!data || data.format !== 'daily-grind-public-key-v1' || data.suite !== SUITE) throw new Error('Choose a Daily Grind public key file.');
+  const publicKey = await crypto.subtle.importKey('raw', decode(data.publicKey), { name: 'ECDSA', namedCurve: 'P-256' }, true, ['verify']);
+  const id = await keyId(publicKey);
+  if (id !== data.fingerprint) throw new Error('Public key fingerprint does not match.');
+  return { publicKey, id };
+}
