--- /dev/null
+++ b/tests/signing.test.mjs
@@ -0,0 +1,38 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createSigner, signDocument, verifyDocument, exportVerifier, importVerifier } from '../signing.mjs';
+const payload = type => ({ type, issuer: 'The Daily Grind · Local issuer', id: 'DG-TEST-123', issuedAt: new Date().toISOString(), currency: 'USD', amountCents: 550, recipient: 'Alex Morgan', description: 'A little daily pick-me-up' });
+for (const type of ['receipt', 'voucher']) {
+  test(`${type}: sign, export/import verifier, and verify after JSON round trip`, async () => {
+    const signer = await createSigner();
+    assert.equal(signer.privateKey.extractable, false);
+    await assert.rejects(crypto.subtle.exportKey('pkcs8', signer.privateKey));
+    const doc = await signDocument(signer, payload(type));
+    const trusted = await importVerifier(JSON.parse(JSON.stringify(await exportVerifier(signer))));
+    assert.deepEqual(await verifyDocument(JSON.parse(JSON.stringify(doc)), trusted), doc.payload);
+    for (const [field, changed] of Object.entries({ amountCents: 900, recipient: 'Someone else', description: 'Changed', type: type === 'receipt' ? 'voucher' : 'receipt', currency: 'EUR', issuedAt: '2020-01-01T00:00:00Z', id: 'DG-CHANGED' })) {
+      const altered = structuredClone(doc); altered.payload[field] = changed;
+      await assert.rejects(verifyDocument(altered, trusted), undefined, `Reject changed ${field}`);
+    }
+    const reordered = Object.fromEntries(Object.entries(doc.payload).reverse());
+    assert.deepEqual(await verifyDocument({ ...doc, payload: reordered }, trusted), reordered);
+    await assert.rejects(verifyDocument({ ...doc, signature: 'AAAA' }, trusted));
+    await assert.rejects(verifyDocument({ ...doc, version: 2 }, trusted));
+    await assert.rejects(verifyDocument({ ...doc, suite: 'none' }, trusted));
+    await assert.rejects(verifyDocument({ ...doc, extra: true }, trusted));
+    await assert.rejects(verifyDocument(doc, await createSigner()), /Unknown issuer/);
+    await assert.rejects(verifyDocument({ ...doc, keyId: 'attacker' }, trusted), /Unknown issuer/);
+  });
+}
+test('reject malformed documents, invalid payloads, and substituted keys', async () => {
+  const signer = await createSigner();
+  for (const amountCents of [0, -1, 1.5, NaN, Infinity, 100001]) await assert.rejects(signDocument(signer, { ...payload('receipt'), amountCents }));
+  for (const doc of [null, {}, [], { version: 1 }]) await assert.rejects(verifyDocument(doc, signer));
+  const exported = await exportVerifier(signer);
+  await assert.rejects(importVerifier({ ...exported, fingerprint: 'fake' }), /fingerprint/);
+  await assert.rejects(importVerifier({ ...exported, suite: 'RSA' }));
+  const attacker = await createSigner();
+  const forged = await signDocument(attacker, payload('voucher'));
+  forged.keyId = signer.id;
+  await assert.rejects(verifyDocument(forged, signer), /Signature invalid/);
+});

