+// A signed envelope never supplies its own trusted key. The caller pins the
+// public key saved by this workspace before attempting signature verification.
+export const ALGORITHM = 'ECDSA-P256-SHA256';
+const signatureAlgorithm = { name: 'ECDSA', hash: 'SHA-256' };
+const encoder = new TextEncoder();
+
+export function canonicalize(value) {
+  if (value === null || typeof value !== 'object') return JSON.stringify(value);
+  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
+  return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + canonicalize(value[key])).join(',') + '}';
+}
+
+export function toBase64(bytes) {
+  return btoa(String.fromCharCode(...new Uint8Array(bytes)));
+}
+
+function fromBase64(value) {
+  if (typeof value !== 'string' || !/^[A-Za-z0-9+/]{86}==$/.test(value)) throw new Error('The signature format is invalid. Choose an original signed JSON file.');
+  const result = Uint8Array.from(atob(value), char => char.charCodeAt(0));
+  if (toBase64(result) !== value) throw new Error('The signature encoding is invalid.');
+  return result;
+}
+
+export async function keyFingerprint(publicKey) {
+  const spki = await crypto.subtle.exportKey('spki', publicKey);
+  const digest = await crypto.subtle.digest('SHA-256', spki);
+  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
+}
+
+export async function generateSigningKey() {
+  const pair = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
+  return { ...pair, keyId: await keyFingerprint(pair.publicKey), createdAt: new Date().toISOString() };
+}
+
+function exactFields(value, fields) {
+  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).sort().join(',') !== fields.sort().join(',')) {
+    throw new Error('This document has missing or unsupported fields. Choose a Daily Grind signed JSON file.');
+  }
+}
+function textField(value, max, allowEmpty = false) {
+  if (typeof value !== 'string' || value.length > max || (!allowEmpty && !value.trim())) throw new Error('The document contains invalid text fields.');
+}
+function cents(value) {
+  if (!Number.isSafeInteger(value) || value < 1 || value > 10000000) throw new Error('The document amount is invalid.');
+}
+
+export function validatePayload(payload) {
+  const common = ['id', 'reference', 'type', 'issuedAt', 'currency'];
+  if (payload?.type === 'receipt') {
+    exactFields(payload, [...common, 'customer', 'items', 'totalCents']);
+    textField(payload.customer, 100);
+    if (!Array.isArray(payload.items) || payload.items.length < 1 || payload.items.length > 50) throw new Error('The receipt items are invalid.');
+    for (const item of payload.items) {
+      exactFields(item, ['name', 'quantity', 'unitPriceCents']);
+      textField(item.name, 100);
+      cents(item.unitPriceCents);
+      if (!Number.isInteger(item.quantity) || item.quantity < 1 || item.quantity > 50) throw new Error('The receipt quantity is invalid.');
+    }
+    cents(payload.totalCents);
+    if (payload.items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0) !== payload.totalCents) throw new Error('The receipt total does not match its items.');
+  } else if (payload?.type === 'voucher') {
+    exactFields(payload, [...common, 'recipient', 'amountCents', 'message']);
+    textField(payload.recipient, 100);
+    textField(payload.message, 240, true);
+    cents(payload.amountCents);
+  } else {
+    throw new Error('This is not a supported receipt or gift voucher.');
+  }
+  textField(payload.id, 60);
+  textField(payload.reference, 60);
+  if (!/^[A-Za-z0-9-]+$/.test(payload.reference)) throw new Error('The document reference is invalid.');
+  if (payload.currency !== 'USD') throw new Error('This workspace supports USD documents only.');
+  if (typeof payload.issuedAt !== 'string' || Number.isNaN(Date.parse(payload.issuedAt)) || new Date(payload.issuedAt).toISOString() !== payload.issuedAt) throw new Error('The document date is invalid.');
+}
+
+export async function signDocument(payload, key) {
+  validatePayload(payload);
+  const signed = { version: 1, algorithm: ALGORITHM, keyId: key.keyId, payload };
+  const bytes = await crypto.subtle.sign(signatureAlgorithm, key.privateKey, encoder.encode(canonicalize(signed)));
+  return { ...signed, signature: toBase64(bytes) };
+}
+
+export async function verifyDocument(document, trustedKey) {
+  exactFields(document, ['version', 'algorithm', 'keyId', 'payload', 'signature']);
+  if (document.version !== 1 || document.algorithm !== ALGORITHM) throw new Error('This document version or signing algorithm is not supported.');
+  if (document.keyId !== trustedKey.keyId) throw new Error('Unrecognized signing key. This document was not signed by this browser’s saved key. Its issuer cannot be confirmed here.');
+  validatePayload(document.payload);
+  const signature = fromBase64(document.signature);
+  const { signature: omitted, ...signed } = document;
+  const valid = await crypto.subtle.verify(signatureAlgorithm, trustedKey.publicKey, signature, encoder.encode(canonicalize(signed)));
+  if (!valid) throw new Error('Signature does not match. The document was changed or was not signed with this workspace’s key.');
+  return document.payload;
+}
