+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { generateSigningKey, signDocument, verifyDocument, canonicalize } from './signing.js';
+
+const receipt = () => ({
+  id: crypto.randomUUID(), reference: 'DG-1042', type: 'receipt', issuedAt: new Date().toISOString(),
+  currency: 'USD', customer: 'Alex Morgan', items: [{ name: 'Maple Oat Latte', quantity: 2, unitPriceCents: 575 }], totalCents: 1150
+});
+const voucher = () => ({
+  id: crypto.randomUUID(), reference: 'GIFT-1042', type: 'voucher', issuedAt: new Date().toISOString(),
+  currency: 'USD', recipient: 'Alex Morgan', amountCents: 2500, message: 'Coffee is on me. ☕'
+});
+
+test('both document types survive JSON export and verify against their issuer', async () => {
+  const key = await generateSigningKey();
+  assert.equal(key.privateKey.extractable, false);
+  await assert.rejects(crypto.subtle.exportKey('jwk', key.privateKey));
+  for (const payload of [receipt(), voucher()]) {
+    const signed = await signDocument(payload, key);
+    const transported = JSON.parse(JSON.stringify(signed));
+    assert.deepEqual(await verifyDocument(transported, key), payload);
+  }
+});
+test('changes to signed receipt and voucher fields are rejected', async () => {
+  const key = await generateSigningKey();
+  for (const payload of [receipt(), voucher()]) {
+    const signed = await signDocument(payload, key);
+    if (payload.type === 'receipt') signed.payload.customer = 'Someone else';
+    else signed.payload.amountCents = 5000;
+    await assert.rejects(verifyDocument(signed, key), /Signature does not match/);
+  }
+});
+test('wrong issuer and a substituted signature do not verify', async () => {
+  const [first, second] = await Promise.all([generateSigningKey(), generateSigningKey()]);
+  const signed = await signDocument(receipt(), first);
+  await assert.rejects(verifyDocument(signed, second), /Unrecognized signing key/);
+  signed.keyId = second.keyId;
+  await assert.rejects(verifyDocument(signed, second), /Signature does not match/);
+});
+test('canonical signing ignores object property order but protects envelope fields', async () => {
+  const key = await generateSigningKey();
+  const signed = await signDocument(voucher(), key);
+  const reordered = Object.fromEntries(Object.entries(signed).reverse());
+  reordered.payload = Object.fromEntries(Object.entries(signed.payload).reverse());
+  assert.deepEqual(await verifyDocument(reordered, key), signed.payload);
+  reordered.version = 2;
+  await assert.rejects(verifyDocument(reordered, key), /not supported/);
+  assert.equal(canonicalize({ z: 2, a: 1 }), '{"a":1,"z":2}');
+});
+test('malformed, extra, missing and mismatched fields are rejected', async () => {
+  const key = await generateSigningKey();
+  for (const value of [null, [], {}, { payload: {} }]) await assert.rejects(verifyDocument(value, key));
+  const signed = await signDocument(receipt(), key);
+  await assert.rejects(verifyDocument({ ...signed, publicKey: {} }, key), /unsupported fields/);
+  await assert.rejects(verifyDocument({ ...signed, signature: 'not base64' }, key), /signature format/);
+  await assert.rejects(signDocument({ ...receipt(), totalCents: 1 }, key), /does not match/);
+  await assert.rejects(signDocument({ ...voucher(), amountCents: -10 }, key), /amount is invalid/);
+});
