+---
+
+<top-stories-carousel class="block bg-white border-b border-gray-300" role="region" aria-roledescription="carousel" aria-label="Top Stories">
+    <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
+        <div class="flex flex-wrap items-center justify-between gap-3 mb-3">
+            <h2 class="text-sm font-bold uppercase tracking-widest text-gray-900">Top Stories</h2>
+            <div class="flex items-center gap-3">
+                <span data-status class="text-xs text-gray-500" aria-live="polite" aria-atomic="true">
+                    {articles.length ? `1 of ${articles.length}` : 'No stories'}
+                </span>
+                <button type="button" data-previous aria-label="Previous story" disabled={articles.length < 2} class="border border-gray-300 px-3 py-1 text-sm font-semibold hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-600 disabled:opacity-40 disabled:cursor-not-allowed">← Previous</button>
+                <button type="button" data-next aria-label="Next story" disabled={articles.length < 2} class="border border-gray-300 px-3 py-1 text-sm font-semibold hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-600 disabled:opacity-40 disabled:cursor-not-allowed">Next →</button>
+            </div>
+        </div>
+        <div class="stories-viewport">
+            {articles.map((article, index) => (
+                <article data-slide class:list={['story', { 'is-active': index === 0 }]} role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${articles.length}`} aria-hidden={index !== 0 ? 'true' : 'false'} inert={index !== 0}>
