@@ -0,0 +1,139 @@
+(() => {
+  const panel = document.querySelector('[data-draggable]');
+  const handle = panel.querySelector('[data-drag-handle]');
+  const status = document.getElementById('cart-status');
+  const content = document.getElementById('cart-content');
+  const collapse = panel.querySelector('.cart-collapse');
+  const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+  const drinks = {
+    'maple-oat-latte': { name: 'Maple Oat Latte', price: 550 },
+    espresso: { name: 'Dark Roast Espresso', price: 300 },
+    'cold-brew': { name: 'Cold Brew', price: 450 }
+  };
+  const form = document.getElementById('quick-order-form');
+  const drink = document.getElementById('cart-drink');
+  const size = document.getElementById('cart-size');
+  const quantity = document.getElementById('cart-quantity');
+  const clear = document.getElementById('cart-clear');
+  const checkout = document.getElementById('cart-checkout');
+  let cart = [];
+  let pointerId = null;
+  let offsetX = 0;
+  let offsetY = 0;
+  let moved = false;
+
+  const announce = (message) => { status.textContent = message; };
+  const unitPrice = () => drinks[drink.value].price + (size.value === 'large' ? 100 : 0);
+
+  // Pointer, keyboard, docking, and resize all share the same viewport bounds.
+  function moveTo(left, top) {
+    const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth - 12);
+    const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight - 12);
+    panel.style.left = `${Math.max(Math.min(12, maxLeft), Math.min(left, maxLeft))}px`;
+    panel.style.top = `${Math.max(Math.min(12, maxTop), Math.min(top, maxTop))}px`;
+    panel.style.right = 'auto';
+    panel.style.bottom = 'auto';
+  }
+
+  function keepReachable() {
+    const rect = panel.getBoundingClientRect();
+    moveTo(rect.left, rect.top);
+  }
+
+  handle.hidden = false;
+  collapse.hidden = false;
+  panel.querySelector('.cart-movement').hidden = false;
+  document.getElementById('cart-summary').hidden = false;
+
+  handle.addEventListener('pointerdown', (event) => {
+    if (event.button !== 0 || !event.isPrimary || pointerId !== null) return;
+    const rect = panel.getBoundingClientRect();
+    offsetX = event.clientX - rect.left;
+    offsetY = event.clientY - rect.top;
+    pointerId = event.pointerId;
+    moved = false;
+    handle.setPointerCapture(pointerId);
+  });
+  handle.addEventListener('pointermove', (event) => {
+    if (event.pointerId !== pointerId) return;
+    moved = true;
+    handle.classList.add('dragging');
+    moveTo(event.clientX - offsetX, event.clientY - offsetY);
+  });
+  function finishDrag(event) {
+    if (event.pointerId !== pointerId) return;
+    if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
+    pointerId = null;
+    handle.classList.remove('dragging');
+    if (moved) announce('Quick order panel moved.');
+    moved = false;
+  }
+  handle.addEventListener('pointerup', finishDrag);
+  handle.addEventListener('pointercancel', finishDrag);
+  handle.addEventListener('lostpointercapture', finishDrag);
+  handle.addEventListener('keydown', (event) => {
+    const directions = { ArrowLeft: [-15, 0], ArrowRight: [15, 0], ArrowUp: [0, -15], ArrowDown: [0, 15] };
+    const direction = directions[event.key];
+    if (!direction) return;
+    event.preventDefault();
+    const rect = panel.getBoundingClientRect();
+    moveTo(rect.left + direction[0], rect.top + direction[1]);
+    announce(`Quick order panel moved ${event.key.slice(5).toLowerCase()}.`);
+  });
+  panel.querySelectorAll('[data-dock]').forEach((button) => {
+    button.addEventListener('click', () => {
+      moveTo(button.dataset.dock === 'left' ? 12 : window.innerWidth - panel.offsetWidth - 12,
+        window.innerHeight - panel.offsetHeight - 12);
+      announce(`Quick order panel docked ${button.dataset.dock}.`);
+    });
+  });
+  collapse.addEventListener('click', () => {
+    content.hidden = !content.hidden;
+    collapse.setAttribute('aria-expanded', String(!content.hidden));
+    collapse.setAttribute('aria-label', content.hidden ? 'Expand quick order' : 'Minimize quick order');
+    collapse.textContent = content.hidden ? '+' : '−';
+    keepReachable();
+  });
+  window.addEventListener('resize', keepReachable);
+  new ResizeObserver(keepReachable).observe(panel);
+
+  function updatePrice() {
+    const count = quantity.validity.valid ? quantity.valueAsNumber : 1;
+    document.getElementById('cart-item-price').textContent = `· ${money.format(unitPrice() * count / 100)}`;
+  }
+  form.addEventListener('input', updatePrice);
+  form.addEventListener('change', updatePrice);
+
+  function renderCart() {
+    const count = cart.reduce((sum, item) => sum + item.quantity, 0);
+    const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
+    document.getElementById('cart-count').textContent = `Your cart · ${count} ${count === 1 ? 'cup' : 'cups'}`;
+    document.getElementById('cart-total').textContent = money.format(total / 100);
+    const items = cart.map((item) => {
+      const li = document.createElement('li');
+      li.textContent = `${item.quantity} × ${item.size === 'large' ? 'Large' : 'Regular'} ${drinks[item.drink].name}`;
+      return li;
+    });
+    document.getElementById('cart-items').replaceChildren(...items);
+    clear.disabled = !cart.length;
+    checkout.hidden = !cart.length;
+    // Carry selections to the existing ordering route; no order is placed here.
+    const params = new URLSearchParams({ cart: JSON.stringify(cart.map(({ drink, size, quantity }) => ({ drink, size, quantity }))) });
+    checkout.href = `/order-online?${params}`;
+  }
+  form.addEventListener('submit', (event) => {
+    event.preventDefault();
+    if (!form.reportValidity()) return;
+    const existing = cart.find((item) => item.drink === drink.value && item.size === size.value);
+    if (existing) existing.quantity += quantity.valueAsNumber;
+    else cart.push({ drink: drink.value, size: size.value, quantity: quantity.valueAsNumber, price: unitPrice() });
+    renderCart();
+    announce(`${quantity.valueAsNumber} ${drinks[drink.value].name} added to your cart. Total ${document.getElementById('cart-total').textContent}.`);
+  });
+  clear.addEventListener('click', () => {
+    cart = [];
+    renderCart();
+    form.querySelector('button[type="submit"]').focus();
+    announce('Your coffee cart is empty.');
+  });
+})();

