+(() => {
+  'use strict';
+
+  const host = document.querySelector('#views');
+  const routes = new Set(['home', 'menu', 'locations', 'rewards', 'account']);
+  // Cached nodes remain connected: hiding a view preserves its entire DOM subtree.
+  const views = new Map([
+    ['home', { element: host.querySelector('[data-view="home"]'), scrollY: 0, focus: null }],
+  ]);
+  let activeRoute = null;
+
+  function initializeView(route, element) {
+    if (route === 'menu' || route === 'locations') {
+      const isMenu = route === 'menu';
+      const search = element.querySelector(isMenu ? '[data-menu-search]' : '[data-location-search]');
+      const category = element.querySelector('[data-menu-category]');
+      const cards = [...element.querySelectorAll('.card')];
+      const empty = element.querySelector(isMenu ? '[data-menu-empty]' : '[data-location-empty]');
+      const filter = () => {
+        const query = search.value.trim().toLocaleLowerCase();
+        let count = 0;
+        for (const card of cards) {
+          const matches = card.textContent.toLocaleLowerCase().includes(query)
+            && (!category || category.value === 'all' || card.dataset.category === category.value);
+          card.hidden = !matches;
+          if (matches) count += 1;
+        }
+        empty.hidden = count > 0;
+      };
+      search.addEventListener('input', filter);
+      category?.addEventListener('change', filter);
+    }
+
+    if (route === 'account') {
+      const form = element.querySelector('[data-account-form]');
+      const status = element.querySelector('[data-account-status]');
+      const storageKey = 'daily-grind-preferences';
+      try {
+        const saved = JSON.parse(localStorage.getItem(storageKey) || 'null');
+        if (saved && typeof saved.displayName === 'string') {
+          form.elements.displayName.value = saved.displayName.slice(0, 80);
+        }
+        if (saved && typeof saved.favoriteDrink === 'string') {
+          form.elements.favoriteDrink.value = saved.favoriteDrink;
+        }
+      } catch {
+        // A storage restriction or stale data must not prevent using the form.
+      }
+      form.addEventListener('input', () => { status.textContent = ''; });
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        try {
+          localStorage.setItem(storageKey, JSON.stringify({
+            displayName: form.elements.displayName.value,
+            favoriteDrink: form.elements.favoriteDrink.value,
+          }));
+          status.textContent = 'Preferences saved in this browser.';
+        } catch {
+          status.textContent = 'Browser storage is unavailable. Your preferences will stay here while this page is open.';
+        }
+      });
+    }
+  }
+
+  function getView(route) {
+    if (!views.has(route)) {
+      const fragment = document.querySelector(`#view-${route}`).content.cloneNode(true);
+      const element = fragment.firstElementChild;
+      host.append(fragment);
+      initializeView(route, element);
+      views.set(route, { element, scrollY: 0, focus: null });
+    }
+    return views.get(route);
+  }
+
+  function navigate() {
+    const requested = location.hash.replace(/^#\/?/, '').replace(/\/$/, '') || 'home';
+    const route = routes.has(requested) ? requested : 'home';
+    if (route === activeRoute) return;
+
+    const isInitial = activeRoute === null;
+    if (!isInitial) {
+      const previous = views.get(activeRoute);
+      previous.scrollY = window.scrollY;
+      previous.focus = previous.element.contains(document.activeElement) ? document.activeElement : null;
+      previous.element.hidden = true;
+    } else {
+      views.get('home').element.hidden = true;
+    }
+
+    const view = getView(route);
+    view.element.hidden = false;
+    activeRoute = route;
+    document.title = route === 'home'
+      ? 'The Daily Grind | Artisanal Coffee'
+      : `${route === 'account' ? 'My Account' : route[0].toUpperCase() + route.slice(1)} | The Daily Grind`;
+    for (const link of document.querySelectorAll('nav a')) {
+      const selected = link.getAttribute('href') === (route === 'home' ? '#/' : `#/${route}`);
+      if (selected) link.setAttribute('aria-current', 'page');
+      else link.removeAttribute('aria-current');
+    }
+
+    if (!isInitial) {
+      const focusTarget = view.focus?.isConnected && !view.focus.closest('[hidden]')
+        ? view.focus : view.element.querySelector('h1');
+      if (focusTarget) {
+        if (focusTarget.tagName === 'H1') focusTarget.tabIndex = -1;
+        focusTarget.focus({ preventScroll: true });
+      }
+      window.scrollTo(0, view.scrollY);
+    }
+  }
+
+  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
+  window.addEventListener('hashchange', navigate);
+  navigate();
+})();
