diff --git a/src/scripts/section-navigation.ts b/src/scripts/section-navigation.ts
new file mode 100644
index 0000000..8067c86
--- /dev/null
+++ b/src/scripts/section-navigation.ts
@@ -0,0 +1,73 @@
+import { sections, type SectionId } from '../utils/sections';
+
+const host = document.querySelector<HTMLElement>('[data-section-views]');
+
+if (host) {
+  const views = new Map(
+    Array.from(host.querySelectorAll<HTMLElement>('[data-section-view]'), view =>
+      [view.dataset.sectionView as SectionId, view] as const),
+  );
+  const baseUrl = host.dataset.baseUrl!;
+  const pathToSection = new Map(sections.map(section =>
+    [new URL(`${baseUrl}${section.path}`, location.origin).pathname.replace(/\/$/, ''), section] as const));
+  const scrollPositions = new Map<SectionId, number>();
+  let currentView = host.dataset.initialView as SectionId;
+
+  // The section router owns same-document history; other links navigate normally.
+  history.scrollRestoration = 'manual';
+
+  function updateNavigation() {
+    document.querySelectorAll<HTMLAnchorElement>('[data-section-link]').forEach(link => {
+      if (link.dataset.sectionLink === currentView) link.setAttribute('aria-current', 'page');
+      else link.removeAttribute('aria-current');
+    });
+  }
+
+  function showSection(section: typeof sections[number]) {
+    const nextView = views.get(section.id)!;
+    if (section.id !== currentView) {
+      scrollPositions.set(currentView, window.scrollY);
+      const previousView = views.get(currentView)!;
+      previousView.classList.add('is-inactive');
+      previousView.inert = true;
+      previousView.setAttribute('aria-hidden', 'true');
+
+      // Never detach or replace a view: hydrated islands and local DOM state survive.
+      nextView.classList.remove('is-inactive');
+      nextView.inert = false;
+      nextView.setAttribute('aria-hidden', 'false');
+      currentView = section.id;
+    }
+
+    document.title = section.title;
+    updateNavigation();
+    nextView.focus({ preventScroll: true });
+    window.scrollTo({ top: scrollPositions.get(section.id) ?? 0, behavior: 'instant' });
+  }
+
+  document.addEventListener('click', event => {
+    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+    const link = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
+    if (!link || link.hasAttribute('download') || (link.target && link.target !== '_self')) return;
+
+    const url = new URL(link.href);
+    if (url.origin !== location.origin || url.search || url.hash) return;
+    const section = pathToSection.get(url.pathname.replace(/\/$/, ''));
+    if (!section) return;
+
+    event.preventDefault();
+    if (section.id === currentView) return;
+    history.pushState(null, '', url);
+    showSection(section);
+  });
+
+  window.addEventListener('popstate', () => {
+    const section = pathToSection.get(location.pathname.replace(/\/$/, ''));
+    if (section && section.id !== currentView) showSection(section);
+  });
+
+  // Native history handles scroll again when this document enters the back/forward cache.
+  window.addEventListener('pagehide', () => { history.scrollRestoration = 'auto'; });
+  window.addEventListener('pageshow', () => { history.scrollRestoration = 'manual'; });
+  updateNavigation();
+}
