+---
+import Layout from './Layout.astro';
+import TopNews from '../components/views/TopNews.astro';
+import Multimedia from '../components/views/Multimedia.astro';
+import Reports from '../components/views/Reports.astro';
+import CategoryView from '../components/views/CategoryView.astro';
+import { sections, type SectionId } from '../utils/sections';
+
+interface Props { active: SectionId }
+const { active } = Astro.props;
+const current = sections.find(section => section.id === active)!;
+---
+<Layout title={current.title}>
+  <div data-section-views>
+    {sections.map(section => (
+      <div
+        id={`view-${section.id}`}
+        data-section-view={section.id}
+        aria-label={section.label}
+        tabindex="-1"
+        hidden={section.id !== active}
+      >
+        {section.id === 'top-news' && <TopNews />}
+        {section.id === 'world' && <CategoryView category="world" />}
+        {section.id === 'politics' && <CategoryView category="politics" />}
+        {section.id === 'multimedia' && <Multimedia />}
+        {section.id === 'reports' && <Reports />}
+      </div>
+    ))}
+  </div>
+  <p class="sr-only" role="status" aria-live="polite" data-section-status></p>
+  <script>
+    import '../scripts/section-navigation';
+  </script>
+</Layout>
