new file mode 100644
index 0000000..6a2e2e7
--- /dev/null
+++ b/src/scripts/section-navigation.ts
@@ -0,0 +1,72 @@
+import { sections, type SectionId } from '../utils/sections';
+
+const host = document.querySelector<HTMLElement>('[data-section-views]');
+
+if (host) {
+  const normalize = (path: string) => path.replace(/\/$/, '');
+  const sectionAt = (url: URL) => url.origin === location.origin && !url.search
+    ? sections.find(section => normalize(section.href) === normalize(url.pathname))
+    : undefined;
+  const views = new Map(sections.map(section => [
+    section.id,
+    host.querySelector<HTMLElement>(`[data-section-view="${section.id}"]`)!,
+  ]));
+  const positions = new Map<SectionId, { x: number; y: number }>();
+  let active = sections.find(section => !views.get(section.id)!.hidden)!.id;
+
+  history.scrollRestoration = 'manual';
+
+  function show(url: URL, push: boolean) {
+    const section = sectionAt(url);
+    if (!section) return;
+
+    positions.set(active, { x: window.scrollX, y: window.scrollY });
+    if (push) {
+      history.replaceState({ ...history.state, sectionScroll: positions.get(active) }, '');
+      history.pushState({}, '', url);
+    }
+
+    // Toggle the same connected nodes. Islands, media and form state stay mounted.
+    for (const [id, view] of views) view.hidden = id !== section.id;
+    active = section.id;
+    document.title = section.title;
+    document.querySelectorAll<HTMLAnchorElement>('[data-section-link]').forEach(link => {
+      if (link.dataset.sectionLink === active) link.setAttribute('aria-current', 'page');
+      else link.removeAttribute('aria-current');
+    });
+    const view = views.get(active)!;
+    view.focus({ preventScroll: true });
+    const position = (!push && history.state?.sectionScroll) || positions.get(active) || { x: 0, y: 0 };
+    if (url.hash) {
+      let target: HTMLElement | null = null;
+      try { target = document.getElementById(decodeURIComponent(url.hash.slice(1))); } catch { /* Invalid fragment. */ }
+      if (target && view.contains(target)) target.scrollIntoView();
+      else window.scrollTo(position.x, position.y);
+    } else {
+      window.scrollTo(position.x, position.y);
+    }
+    const status = document.querySelector('[data-section-status]');
+    if (status) status.textContent = `${section.label} section`;
+  }
+
+  document.addEventListener('click', event => {
+    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+    const link = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
+    if (!link || link.hasAttribute('download') || (link.target && link.target !== '_self') || link.hasAttribute('data-astro-reload')) return;
+    const url = new URL(link.href);
+    if (!sectionAt(url)) return;
+    event.preventDefault();
+    if (url.href !== location.href) show(url, true);
+  });
+
+  window.addEventListener('popstate', () => {
+    const url = new URL(location.href);
+    if (sectionAt(url)) show(url, false);
+    else location.reload();
+  });
+
+  // Store the current entry as well, so back/forward can restore its own position.
+  window.addEventListener('scroll', () => {
+    history.replaceState({ ...history.state, sectionScroll: { x: window.scrollX, y: window.scrollY } }, '');
+  }, { passive: true });
+}
