diff --git a/tests/section-navigation.test.mjs b/tests/section-navigation.test.mjs
new file mode 100644
index 0000000..f2f5502
--- /dev/null
+++ b/tests/section-navigation.test.mjs
@@ -0,0 +1,132 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { readFileSync } from 'node:fs';
+import { stripTypeScriptTypes } from 'node:module';
+import { runInNewContext } from 'node:vm';
+
+const sectionSource = readFileSync(new URL('../src/utils/sections.ts', import.meta.url), 'utf8')
+  .replace('import.meta.env.BASE_URL', "'/devtools-times/'")
+  .replaceAll('export ', '');
+const routerSource = readFileSync(new URL('../src/scripts/section-navigation.ts', import.meta.url), 'utf8')
+  .replace(/^import .*;\n/, '');
+const script = stripTypeScriptTypes(`${sectionSource}\n${routerSource}`);
+
+function setup(initial = '/devtools-times/') {
+  const location = new URL(initial, 'https://example.com');
+  const listeners = {};
+  const listen = (type, handler) => { listeners[type] = handler; };
+  const ids = ['top-news', 'world', 'politics', 'multimedia', 'reports'];
+  const initialId = ids.find(id => location.pathname.endsWith(id)) || 'top-news';
+  const views = new Map(ids.map(id => [id, {
+    hidden: id !== initialId,
+    focus() {},
+    state: { value: '', playing: false },
+  }]));
+  class Element {}
+  class Link extends Element {
+    constructor(href) { super(); this.href = new URL(href, location).href; this.target = ''; }
+    closest() { return this; }
+    hasAttribute() { return false; }
+  }
+  const links = ids.map(id => ({
+    dataset: { sectionLink: id },
+    attributes: {},
+    setAttribute(key, value) { this.attributes[key] = value; },
+    removeAttribute(key) { delete this.attributes[key]; },
+  }));
+  const entries = [{ url: location.href, state: null }];
+  let index = 0;
+  const history = {
+    get state() { return entries[index].state; },
+    replaceState(state) { entries[index].state = state; },
+    pushState(state, _, url) {
+      entries.splice(++index);
+      entries.push({ state, url: String(url) });
+      location.href = String(url);
+    },
+  };
+  const window = {
+    scrollX: 0, scrollY: 0, addEventListener: listen,
+    scrollTo(x, y) { this.scrollX = x; this.scrollY = y; },
+  };
+  const document = {
+    title: '', addEventListener: listen,
+    querySelector(selector) {
+      if (selector === '[data-section-views]') return {
+        querySelector(selector) { return views.get(selector.match(/="(.*?)"/)[1]); },
+      };
+      return {};
+    },
+    querySelectorAll() { return links; },
+  };
+  runInNewContext(script, { document, window, history, location, URL, Element });
+  function click(path, extra = {}) {
+    const event = { target: new Link(path), button: 0, preventDefault() { this.defaultPrevented = true; }, ...extra };
+    listeners.click(event);
+    return event;
+  }
+  function go(delta) {
+    index += delta;
+    location.href = entries[index].url;
+    listeners.popstate();
+  }
+  return { click, go, views, document, links, window, entries, location };
+}
+
+test('section switches retain DOM state and restore scroll with back/forward', () => {
+  const app = setup();
+  const original = app.views.get('top-news');
+  original.state.value = 'unfinished text';
+  original.state.playing = true;
+  app.window.scrollY = 640;
+  assert.equal(app.click('category/world').defaultPrevented, true);
+  assert.equal(original.hidden, true);
+  assert.equal(app.views.get('world').hidden, false);
+  assert.equal(app.window.scrollY, 0);
+  app.window.scrollY = 120;
+  app.click('/devtools-times/reports');
+  assert.equal(app.document.title, 'Reports');
+  assert.equal(app.links.at(-1).attributes['aria-current'], 'page');
+  app.go(-1);
+  assert.equal(app.window.scrollY, 120);
+  app.go(-1);
+  assert.equal(app.views.get('top-news'), original);
+  assert.equal(original.hidden, false);
+  assert.equal(original.state.value, 'unfinished text');
+  assert.equal(original.state.playing, true);
+  assert.equal(app.window.scrollY, 640);
+  app.go(1);
+  assert.equal(app.views.get('world').hidden, false);
+  assert.equal(app.window.scrollY, 120);
+  assert.equal([...app.views.values()].filter(view => !view.hidden).length, 1);
+});
+
+test('native link behaviors and unsupported destinations are preserved', () => {
+  const app = setup('/devtools-times/?campaign=example');
+  for (const [path, options] of [
+    ['reports', { ctrlKey: true }],
+    ['reports', { metaKey: true }],
+    ['reports', { button: 1 }],
+    ['articles/example', {}],
+    ['reports?filter=latest', {}],
+    ['https://other.example/devtools-times/reports', {}],
+  ]) assert.equal(app.click(path, options).defaultPrevented, undefined);
+  assert.equal(app.entries.length, 1);
+  assert.equal(app.click('reports/').defaultPrevented, true);
+  assert.equal(app.views.get('reports').hidden, false);
+});
+
+
+test('each section supports direct entry and repeated returns without replacing nodes', () => {
+  for (const route of ['category/world', 'category/politics', 'multimedia', 'reports']) {
+    const app = setup(`/devtools-times/${route}`);
+    const original = new Map(app.views);
+    for (let visit = 0; visit < 3; visit++) {
+      for (const path of ['', 'category/world', 'category/politics', 'multimedia', 'reports']) {
+        app.click(`/devtools-times/${path}`);
+        assert.equal([...app.views.values()].filter(view => !view.hidden).length, 1);
+        for (const [id, node] of original) assert.equal(app.views.get(id), node);
+      }
+    }
+  }
+});

