+// The native select in the light DOM remains usable if FACE is unavailable.
+if ('attachInternals' in HTMLElement.prototype &&
+    'ElementInternals' in window && 'setFormValue' in ElementInternals.prototype) {
+  class StarRating extends HTMLElement {
+    static formAssociated = true;
+    static observedAttributes = ['required', 'value'];
+
+    #internals;
+    #value = '';
+    #dirty = false;
+    #disabled = false;
+    #showError = false;
+    #radios;
+    #labels = ['Not my cup', 'Could be better', 'Pretty good', 'Loved it', 'Made my day'];
+
+    constructor() {
+      super();
+      this.#internals = this.attachInternals();
+      this.#internals.role = 'group';
+      const root = this.attachShadow({ mode: 'open', delegatesFocus: true });
+      root.innerHTML = `
+        <style>
+          :host { display: block; }
+          :host([hidden]) { display: none; }
+          .stars { display: flex; gap: 5px; width: fit-content; }
+          label { position: relative; display: grid; place-items: center; width: 48px; height: 48px; cursor: pointer; border-radius: 6px; }
+          input { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
