--- /dev/null
+++ b/feedback.js
@@ -0,0 +1,24 @@
+const feedbackForm = document.querySelector('#coffee-feedback');
+const feedbackStatus = document.querySelector('#feedback-status');
+
+feedbackForm.addEventListener('submit', event => {
+  // The browser runs constraint validation before dispatching submit.
+  event.preventDefault();
+  const feedback = Object.fromEntries(new FormData(feedbackForm));
+  try {
+    localStorage.setItem('daily-grind-feedback', JSON.stringify({
+      ...feedback,
+      savedAt: new Date().toISOString()
+    }));
+    feedbackStatus.textContent = 'Thanks for spilling the beans! Your feedback has been saved on this device.';
+  } catch {
+    feedbackStatus.textContent = 'Your browser could not save your feedback. Your answers are still here — please try again.';
+  }
+});
+
+feedbackForm.addEventListener('reset', () => {
+  feedbackStatus.textContent = '';
+});
+feedbackForm.addEventListener('input', () => {
+  feedbackStatus.textContent = '';
+});
