+  <script>
+    const form = document.querySelector('#coffee-preferences');
+    const status = document.querySelector('#preferences-status');
+    const fields = [...form.querySelectorAll('.content-sized')];
+    const storageKey = 'daily-grind-preferences';
+    const measure = document.createElement('span');
+    measure.setAttribute('aria-hidden', 'true');
+    Object.assign(measure.style, {
+      position: 'absolute', visibility: 'hidden', whiteSpace: 'pre',
+      pointerEvents: 'none', top: '0', left: '0'
+    });
+    document.body.append(measure);
+
+    // Measure actual glyph widths as a fallback for browsers without field-sizing.
+    function sizeField(field) {
+      const style = getComputedStyle(field);
+      measure.style.font = style.font;
+      measure.style.letterSpacing = style.letterSpacing;
+      const content = field.tagName === 'SELECT'
+        ? field.selectedOptions[0].text
+        : field.value || field.placeholder || ' ';
+      const width = Math.max(...content.split('\n').map(line => {
+        measure.textContent = line || ' ';
+        return measure.getBoundingClientRect().width;
+      }));
+      const chrome = parseFloat(style.paddingLeft) + parseFloat(style.paddingRight)
+        + parseFloat(style.borderLeftWidth) + parseFloat(style.borderRightWidth);
+      const arrow = field.tagName === 'SELECT' ? 16 : 2;
+      field.style.width = `${Math.ceil(width + chrome + arrow)}px`;
+      if (field.tagName === 'TEXTAREA') {
+        field.style.height = '0px';
+        field.style.height = `${field.scrollHeight + parseFloat(style.borderTopWidth)
+          + parseFloat(style.borderBottomWidth)}px`;
+      }
+    }
+
+    try {
+      const saved = JSON.parse(localStorage.getItem(storageKey));
+      if (saved) fields.forEach(field => {
+        if (typeof saved[field.name] === 'string' &&
+          (field.tagName !== 'SELECT' || [...field.options].some(option => option.value === saved[field.name]))) {
+          field.value = saved[field.name];
+        }
+      });
+    } catch { /* The form remains usable when storage is unavailable. */ }
+
+    fields.forEach(field => {
+      sizeField(field);
+      field.addEventListener('input', () => { sizeField(field); status.textContent = ''; });
+      field.addEventListener('change', () => sizeField(field));
+    });
+    new ResizeObserver(() => fields.forEach(sizeField)).observe(form);
+    document.fonts.ready.then(() => fields.forEach(sizeField));
+
+    form.addEventListener('submit', event => {
+      event.preventDefault();
+      try {
+        localStorage.setItem(storageKey, JSON.stringify(Object.fromEntries(new FormData(form))));
