diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..2a5b8ad
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,37 @@
+import { useEffect, useId, useRef, type ReactNode } from 'react';
+
+interface Props {
+  title: string;
+  isOpen: boolean;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+export default function Modal({ title, isOpen, onClose, children }: Props) {
+  const ref = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+
+  useEffect(() => {
+    const dialog = ref.current;
+    if (!dialog) return;
+    if (isOpen && !dialog.open) {
+      // React's autoFocus runs during mounting, while the dialog is still hidden.
+      // Set the native attribute before opening so showModal chooses the search field.
+      dialog.querySelector('[data-initial-focus]')?.setAttribute('autofocus', '');
+      dialog.showModal();
+    }
+    if (!isOpen && dialog.open) dialog.close();
+  }, [isOpen]);
+
+  return (
+    <dialog ref={ref} className="modal" aria-labelledby={titleId} closedBy="any" onClose={onClose}>
+      <div className="flex justify-between items-center gap-4 p-4 border-b border-gray-200">
+        <h1 id={titleId} className="text-xl font-semibold">{title}</h1>
+        <form method="dialog">
+          <button type="submit" className="p-2 hover:text-amber-700">Close</button>
+        </form>
+      </div>
+      {children}
+    </dialog>
+  );
+}
diff --git a/src/components/NavigationPopover.tsx b/src/components/NavigationPopover.tsx
new file mode 100644
index 0000000..234017f
--- /dev/null
+++ b/src/components/NavigationPopover.tsx
@@ -0,0 +1,21 @@
+import { useId, useRef, useState, type ReactNode } from 'react';
+
+export default function NavigationPopover({ label, children, active = false }: { label: string; children: ReactNode; active?: boolean }) {
+  const id = useId();
+  const trigger = useRef<HTMLButtonElement>(null);
+  const panel = useRef<HTMLDivElement>(null);
+  const [open, setOpen] = useState(false);
+  return (
+    <>
+      <button ref={trigger} type="button" commandFor={id} command="toggle-popover" aria-controls={id} aria-expanded={open} className={`p-2 whitespace-nowrap hover:text-amber-700 ${active ? 'text-amber-800' : ''}`}>
+        {label} <span aria-hidden="true">⌄</span>
+      </button>
+      <div ref={panel} id={id} popover="auto" className="navigation-popover" onToggle={event => setOpen(event.newState === 'open')}>
+        <div className="flex justify-end mb-3">
+          <button type="button" onClick={() => { panel.current?.hidePopover(); trigger.current?.focus(); }} className="p-2 hover:text-amber-700">Close {label}</button>
+        </div>
+        {children}
+      </div>
+    </>
+  );
+}
