+import { useEffect, useId, useState } from 'react';
+import Modal from './Modal';
+
+interface Article { slug: string; title: string; summary: string; }
+
+export default function SearchFlyout({ onClose }: { onClose: () => void }) {
+  const [articles, setArticles] = useState<Article[]>([]);
+  const [query, setQuery] = useState('');
+  const [loading, setLoading] = useState(true);
+  const [error, setError] = useState('');
+  const inputId = useId();
+
+  useEffect(() => {
+    const controller = new AbortController();
+    async function load() {
+      try {
+        const response = await fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal: controller.signal });
+        if (!response.ok) throw new Error('Could not load articles. Please close search and try again.');
+        setArticles(await response.json());
+      } catch (error) {
+        if (!controller.signal.aborted) setError(error instanceof Error ? error.message : 'Could not load articles.');
+      } finally {
+        if (!controller.signal.aborted) setLoading(false);
+      }
+    }
+    void load();
+    return () => controller.abort();
+  }, []);
+
+  const term = query.trim().toLowerCase();
+  const results = term ? articles.filter(article => `${article.title} ${article.summary}`.toLowerCase().includes(term)) : articles.slice(0, 3);
+
+  return (
+    <Modal title="Search" isOpen onClose={onClose}>
+      <search className="block p-4">
+        <form onSubmit={event => event.preventDefault()}>
+          <label htmlFor={inputId} className="block font-semibold mb-2">Search articles</label>
+          <input id={inputId} type="search" name="q" value={query} onChange={event => setQuery(event.target.value)} data-initial-focus autoCapitalize="none" autoCorrect="off" spellCheck={false} enterKeyHint="search" className="w-full p-2 border border-gray-500 rounded-md" />
+          <button type="submit" className="mt-2 p-2 border rounded-md">Search</button>
+        </form>
+      </search>
+      <div className="p-4" aria-busy={loading}>
+        <p role="status">{loading ? 'Loading articles…' : error || (term ? `${results.length} results` : 'Featured articles')}</p>
+        {!loading && !error && <ul className="space-y-2 mt-3">
+          {results.map(article => (
+            <li key={article.slug}>
+              <a href={`${import.meta.env.BASE_URL}articles/${article.slug}`} className="block hover:bg-gray-100 p-3 rounded-md">
+                <h2 className="font-bold text-lg">{article.title}</h2>
+                <p className="text-sm text-gray-600">{article.summary}</p>
+              </a>
+            </li>
+          ))}
+        </ul>}
+      </div>
+    </Modal>
+  );
 }
