diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..e0abff7
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,38 @@
+import { useLayoutEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  titleId: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+/** The native modal supplies inert background content, Escape and focus containment. */
+export default function Modal({ id, titleId, onClose, children }: Props) {
+  const ref = useRef<HTMLDialogElement>(null);
+
+  useLayoutEffect(() => {
+    const trigger = document.activeElement;
+    const dialog = ref.current!;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (trigger instanceof HTMLElement && trigger.isConnected) trigger.focus();
+    };
+  }, []);
+
+  return (
+    <dialog ref={ref} id={id} aria-labelledby={titleId} className="overlay-dialog" onClose={onClose}
+      onClick={event => {
+        if (event.target !== event.currentTarget) return;
+        const bounds = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) {
+          event.currentTarget.close();
+        }
+      }}>
+      <button type="button" onClick={() => ref.current?.close()} aria-label="Close dialog"
+        className="absolute top-2 right-2 p-2 text-gray-600 hover:text-amber-700">✕</button>
+      {children}
+    </dialog>
+  );
+}
