+(() => {
+  'use strict';
+
+  const supported = globalThis.PerformanceObserver?.supportedEntryTypes ?? [];
+  const supports = (type) => supported.includes(type);
+  const reports = [];
+  const limit = 100;
+  // Public, local-only telemetry. An analytics adapter can subscribe to the event.
+  window.dailyGrindPerformance = {
+    reports,
+    supported: {
+      interactionPaint: supports('interaction-contentful-paint'),
+      softNavigation: supports('soft-navigation'),
+    },
+  };
+
+  function report(detail) {
+    reports.push(Object.freeze(detail));
+    if (reports.length > limit) reports.shift();
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail }));
+  }
+
+  function observe(type, callback, options = {}) {
+    if (!supports(type)) return null;
+    const observer = new PerformanceObserver((list) => callback(list.getEntries()));
+    observer.observe({ type, buffered: true, ...options });
+    return observer;
+  }
+
+  const inputs = [];
+  const interactions = new Map();
+  let activeNavigation = null;
+
+  function remember(id, value) {
+    interactions.set(id, value);
+    if (interactions.size > limit) interactions.delete(interactions.keys().next().value);
+  }
+
+  function targetInfo(target) {
+    const element = target?.closest?.('[data-performance-target]');
+    if (!element) return null;
+    const link = target.closest('a');
+    return {
+      target: element.dataset.performanceTarget,
+      destination: link ? new URL(link.href).pathname : null,
+    };
+  }
+
+  // Capture input timestamps without preventing clicks or changing navigation.
+  // ICP can start at pointerdown/keydown rather than the later click event.
+  if (supports('interaction-contentful-paint')) {
+    for (const type of ['pointerdown', 'keydown', 'click']) {
+      document.addEventListener(type, (event) => {
+        if (!event.isTrusted) return;
+        const info = targetInfo(event.target);
+        if (!info) return;
+        inputs.push({ startTime: event.timeStamp, ...info });
+        if (inputs.length > limit) inputs.shift();
+      }, { capture: true, passive: true });
+    }
+  }
+
+  function interactionReport(entry, state) {
+    report({
+      type: 'interaction-paint',
+      interactionId: entry.interactionId,
+      ...state.info,
+      startTime: entry.startTime,
+      duration: entry.duration,
+      size: entry.largestContentfulPaint?.size ?? null,
+    });
+    state.reported = entry;
+  }
+
+  function handlePaints(entries) {
+    for (const entry of entries) {
+      if (!entry.interactionId) continue;
+      let state = interactions.get(entry.interactionId);
+      if (!state) {
+        // Fast events may fall below Event Timing's minimum duration threshold.
+        const input = inputs.find((input) => Math.abs(input.startTime - entry.startTime) < 1);
+        state = { info: input ? { target: input.target, destination: input.destination } : null };
+        remember(entry.interactionId, state);
+      }
+      state.paint = entry;
+      if (state.info) interactionReport(entry, state);
+      // navigationId can still refer to the previous route for early paints.
+      if (activeNavigation?.entry.interactionId === entry.interactionId) {
+        activeNavigation.paint = entry;
+      }
+    }
+  }
+
+  // Event Timing supplies the exact interaction ID and source element when
+  // available; ICP supplies the asynchronous contentful-paint duration.
+  function handleEvents(entries) {
+    for (const entry of entries) {
+      if (!entry.interactionId) continue;
+      const info = targetInfo(entry.target);
+      if (!info) continue;
+      const state = interactions.get(entry.interactionId) ?? {};
+      state.info = info;
+      remember(entry.interactionId, state);
+      if (state.paint && state.reported !== state.paint) interactionReport(state.paint, state);
+    }
+  }
+
+  const eventObserver = supports('interaction-contentful-paint')
+    ? observe('event', handleEvents, { durationThreshold: 16 }) : null;
+
+  function finalizeNavigation() {
+    if (!activeNavigation) return;
+    const { entry, paint } = activeNavigation;
+    activeNavigation = null;
+    report({
+      type: 'soft-navigation',
+      destination: new URL(entry.name, location.href).pathname,
+      navigationId: entry.navigationId,
+      interactionId: entry.interactionId,
+      startTime: entry.startTime,
+      fcpDuration: entry.duration,
+      lcpDuration: paint?.duration ?? null,
+      size: paint?.largestContentfulPaint?.size ?? null,
+    });
+  }
+
+  function handleNavigations(entries) {
+    for (const entry of entries) {
+      finalizeNavigation();
+      activeNavigation = {
+        entry,
+        // Includes content painted before the URL changed.
+        paint: entry.getLargestInteractionContentfulPaint(),
+      };
+    }
+  }
+
+  const navigationObserver = supports('interaction-contentful-paint')
+    ? observe('soft-navigation', handleNavigations) : null;
+  const paintObserver = observe('interaction-contentful-paint', handlePaints);
+
+  function flush() {
+    // Drain queued entries before finalizing a hidden/departing view.
+    if (eventObserver) handleEvents(eventObserver.takeRecords());
+    if (navigationObserver) handleNavigations(navigationObserver.takeRecords());
+    if (paintObserver) handlePaints(paintObserver.takeRecords());
+    finalizeNavigation();
+  }
+
+  document.addEventListener('visibilitychange', () => {
+    if (document.visibilityState === 'hidden') flush();
+  });
+  window.addEventListener('pagehide', flush);
+})();
