+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+const source = readFileSync(`${__dirname}/performance-monitor.js`, 'utf8');
+function setup(types = ['event', 'interaction-contentful-paint', 'soft-navigation']) {
+  const observers = new Map();
+  const listeners = new Map();
+  const emitted = [];
+  const document = {
+    visibilityState: 'visible',
+    addEventListener: (name, callback) => listeners.set(name, callback),
+  };
+  const window = {
+    dispatchEvent: (event) => emitted.push(event.detail),
+    addEventListener: (name, callback) => listeners.set(name, callback),
+  };
+  class PerformanceObserver {
+    static supportedEntryTypes = types;
+    constructor(callback) { this.callback = callback; this.queue = []; }
+    observe(options) { this.options = options; observers.set(options.type, this); }
+    takeRecords() { return this.queue.splice(0); }
+    deliver(...entries) { this.callback({ getEntries: () => entries }); }
+  }
+  vm.runInNewContext(source, {
+    window, document, URL, location: { href: 'https://coffee.example/' },
+    PerformanceObserver: types === null ? undefined : PerformanceObserver,
+    CustomEvent: class { constructor(name, options) { this.detail = options.detail; } },
+  });
+  return { observers, listeners, emitted, document, window };
+}
+function target(name) {
+  return { closest: (selector) => selector === 'a'
+    ? { href: 'https://coffee.example/menu' }
+    : { dataset: { performanceTarget: name } } };
+}
+function paint(interactionId, duration, size = 100) {
+  return { interactionId, startTime: 10, duration, navigationId: 'old', largestContentfulPaint: { size } };
+}
+
+test('unsupported browsers skip observers and keep telemetry API usable', () => {
+  for (const types of [[], null]) {
+    const app = setup(types);
+    assert.equal(app.observers.size, 0);
+    assert.equal(app.window.dailyGrindPerformance.supported.interactionPaint, false);
+    app.listeners.get('pagehide')();
+    assert.equal(app.emitted.length, 0);
+  }
+});
+
+test('source attribution survives observer delivery order and later async paints', () => {
+  const app = setup();
+  const paints = app.observers.get('interaction-contentful-paint');
+  paints.deliver(paint(1, 80));
+  assert.equal(app.emitted.length, 0);
+  app.observers.get('event').deliver({ interactionId: 1, target: target('order-now') });
+  paints.deliver(paint(1, 450, 200));
+  assert.deepEqual(app.emitted.map((r) => r.duration), [80, 450]);
+  assert.equal(app.emitted[1].target, 'order-now');
+  paints.deliver(paint(2, 500)); // Untracked interaction has no source attribution.
+  assert.equal(app.emitted.length, 2);
+  for (const observer of app.observers.values()) assert.equal(observer.options.buffered, true);
+});
+
+test('fast trusted inputs are attributed even without an Event Timing entry', () => {
+  const app = setup(['interaction-contentful-paint']);
+  app.listeners.get('pointerdown')({ isTrusted: true, target: target('seasonal-cold-brew'), timeStamp: 10 });
+  app.observers.get('interaction-contentful-paint').deliver(paint(3, 150));
+  assert.equal(app.emitted[0].target, 'seasonal-cold-brew');
+  assert.equal(app.emitted[0].duration, 150);
+});
+
+test('soft navigation seeds pre-URL paints, matches interaction IDs, and drains on hide', () => {
+  const app = setup();
+  const nav = app.observers.get('soft-navigation');
+  nav.deliver({
+    name: 'https://coffee.example/menu?private=value', interactionId: 4,
+    navigationId: 'new', startTime: 10, duration: 50,
+    getLargestInteractionContentfulPaint: () => paint(4, 100),
+  });
+  app.observers.get('interaction-contentful-paint').deliver(paint(5, 900));
+  app.observers.get('interaction-contentful-paint').queue.push(paint(4, 250));
+  app.document.visibilityState = 'hidden';
+  app.listeners.get('visibilitychange')();
+  app.listeners.get('pagehide')();
+  assert.equal(app.emitted.length, 1);
+  assert.equal(app.emitted[0].fcpDuration, 50);
+  assert.equal(app.emitted[0].lcpDuration, 250);
+  assert.equal(app.emitted[0].destination, '/menu');
+});
+
+test('new navigation finalizes seeded candidate and report history stays bounded', () => {
+  const app = setup();
+  const nav = app.observers.get('soft-navigation');
+  for (let i = 1; i <= 105; i++) {
+    nav.deliver({ name: 'https://coffee.example/menu', interactionId: i,
+      duration: 40, startTime: 10, navigationId: i,
+      getLargestInteractionContentfulPaint: () => paint(i, 120),
+    });
+  }
+  app.listeners.get('pagehide')();
