+(() => {
+  'use strict';
+
+  const limit = 100;
+  const measurements = [];
+  const pending = new Set();
+  let sequence = 0;
+
+  function start(kind, label, startedAt = performance.now()) {
+    if (document.visibilityState !== 'visible') return null;
+    const sample = { id: ++sequence, kind, label, startedAt };
+    pending.add(sample);
+    return sample;
+  }
+
+  function cancel(sample) {
+    if (!sample) return;
+    cancelAnimationFrame(sample.frame);
+    clearTimeout(sample.timer);
+    pending.delete(sample);
+  }
+
+  function publish(sample) {
+    if (!pending.has(sample)) return;
+    const duration = sample.eventDuration ?? performance.now() - sample.startedAt;
+    const measurement = Object.freeze({
+      id: sample.id,
+      kind: sample.kind,
+      label: sample.label,
+      startTime: sample.startedAt,
+      duration,
+      source: sample.eventDuration === undefined ? 'paint-opportunity' : 'event-timing',
+    });
+    cancel(sample);
+    measurements.push(measurement);
+    if (measurements.length > limit) measurements.shift();
+    const name = `daily-grind:${sample.kind}`;
+    // Keep User Timing storage bounded independently of the in-memory history.
+    performance.clearMeasures(name);
+    performance.measure(name, {
+      start: sample.startedAt,
+      duration,
+      detail: measurement,
+    });
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail: measurement }));
+  }
+
+  function afterPaint(sample) {
+    if (!sample || !pending.has(sample)) return;
+    // Two frames allow a rendering opportunity between callbacks. The task also
+    // gives Event Timing observers a chance to deliver the browser's duration.
+    sample.frame = requestAnimationFrame(() => {
+      sample.frame = requestAnimationFrame(() => {
+        sample.timer = setTimeout(() => publish(sample), 0);
+      });
+    });
+  }
+
+  function eventStart(event) {
+    // Older engines use epoch-based event timestamps.
+    return event.timeStamp > performance.now() + 60000
+      ? event.timeStamp - performance.timeOrigin
+      : event.timeStamp;
+  }
+
+  document.addEventListener('click', (event) => {
+    if (!(event.target instanceof Element)) return;
+    const target = event.target.closest(
+      'nav a, .hero .btn, [data-performance-section="seasonal-favorites"] .card',
+    );
+    if (!target) return;
+    const label = target.matches('nav a')
+      ? `navigation:${target.textContent.trim()}`
+      : target.matches('.hero .btn')
+        ? 'order-now'
+        : `seasonal:${target.querySelector('h3')?.textContent.trim() || 'card'}`;
+    const sample = start('click-to-paint', label, eventStart(event));
+    if (sample) sample.target = event.target;
+    afterPaint(sample);
+  }, { capture: true, passive: true });
+
+  if (typeof PerformanceObserver !== 'undefined'
+      && PerformanceObserver.supportedEntryTypes?.includes('event')) {
+    try {
+      const observer = new PerformanceObserver((list) => {
+        for (const entry of list.getEntries()) {
+          if (entry.name !== 'click') continue;
+          for (const sample of pending) {
+            if (sample.kind === 'click-to-paint'
+                && sample.target === entry.target
+                && Math.abs(sample.startedAt - entry.startTime) < 1) {
+              sample.eventDuration = entry.duration;
+            }
+          }
+        }
+      });
+      observer.observe({ type: 'event', buffered: true, durationThreshold: 16 });
+    } catch {
+      // Engines without Event Timing options still get frame-based estimates.
+    }
+  }
+
+  // Call at the start of a view change; resolve update only after its DOM commit.
+  async function measureViewSwitch(label, update) {
+    const sample = start('view-switch-to-paint', label);
+    try {
+      const result = await update();
+      afterPaint(sample);
+      return result;
+    } catch (error) {
+      cancel(sample);
+      throw error;
+    }
+  }
+
+  // History changes cover synchronous routers. Async routers should use the
+  // explicit hook above so loading and the final DOM commit are included.
+  for (const method of ['pushState', 'replaceState']) {
+    const original = history[method];
+    history[method] = function (...args) {
+      const sample = start('view-switch-to-paint', `history:${method}`);
+      try {
+        const result = original.apply(this, args);
+        afterPaint(sample);
+        return result;
+      } catch (error) {
+        cancel(sample);
+        throw error;
+      }
+    };
+  }
+  for (const event of ['popstate', 'hashchange']) {
+    window.addEventListener(event, () => {
+      afterPaint(start('view-switch-to-paint', `history:${event}`));
+    });
+  }
+
+  function cancelPending() {
+    for (const sample of pending) cancel(sample);
+  }
+  document.addEventListener('visibilitychange', () => {
+    if (document.visibilityState !== 'visible') cancelPending();
+  });
+  window.addEventListener('pagehide', cancelPending);
+
+  window.dailyGrindPerformance = Object.freeze({
+    measureViewSwitch,
+    getMeasurements: () => measurements.slice(),
+  });
+})();
