new file mode 100644
index 0000000..e01e735
--- /dev/null
+++ b/performance-monitor.test.cjs
@@ -0,0 +1,121 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+function setup() {
+  const listeners = {};
+  const frames = new Map();
+  const tasks = new Map();
+  const reports = [];
+  const measures = [];
+  let id = 0;
+  let now = 100;
+  let observe;
+  class Element {
+    textContent = 'Menu';
+    closest() { return this; }
+    matches(selector) { return selector === 'nav a'; }
+  }
+  const context = {
+    Element,
+    document: {
+      visibilityState: 'visible',
+      addEventListener: (name, callback) => { listeners[name] = callback; },
+    },
+    window: {
+      addEventListener: (name, callback) => { listeners[name] = callback; },
+      dispatchEvent: (event) => reports.push(event.detail),
+    },
+    history: {
+      pushState(value) { if (value === 'fail') throw new Error('history failed'); return value; },
+      replaceState() {},
+    },
+    performance: {
+      now: () => now,
+      timeOrigin: 1000000,
+      clearMeasures() {},
+      measure: (name, options) => measures.push({ name, ...options }),
+    },
+    requestAnimationFrame: (callback) => { frames.set(++id, callback); return id; },
+    cancelAnimationFrame: (key) => frames.delete(key),
+    setTimeout: (callback) => { tasks.set(++id, callback); return id; },
+    clearTimeout: (key) => tasks.delete(key),
+    CustomEvent: class { constructor(type, options) { Object.assign(this, { type }, options); } },
+    PerformanceObserver: class {
+      static supportedEntryTypes = ['event'];
+      constructor(callback) { observe = callback; }
+      observe() {}
+    },
+  };
+  vm.runInNewContext(readFileSync(`${__dirname}/performance-monitor.js`, 'utf8'), context);
+  function flush() {
+    for (let i = 0; i < 2; i++) {
+      now += 16;
+      const callbacks = [...frames.values()];
+      frames.clear();
+      callbacks.forEach((callback) => callback());
+    }
+    const callbacks = [...tasks.values()];
+    tasks.clear();
+    callbacks.forEach((callback) => callback());
+  }
+  return { context, listeners, reports, measures, flush, Element,
+    observe: (entry) => observe({ getEntries: () => [entry] }) };
+}
+
+test('click timing waits through rendering opportunities and uses native timing when delivered', () => {
+  const app = setup();
+  const target = new app.Element();
+  app.listeners.click({ target, timeStamp: 90 });
+  assert.equal(app.reports.length, 0);
+  app.observe({ name: 'click', target, startTime: 90, duration: 40 });
+  app.flush();
+  assert.equal(app.reports[0].duration, 40);
+  assert.equal(app.reports[0].source, 'event-timing');
+  assert.equal(app.reports[0].label, 'navigation:Menu');
+  assert.equal(app.measures[0].name, 'daily-grind:click-to-paint');
+});
+
+test('fallback estimates paint and normalizes epoch event timestamps', () => {
+  const app = setup();
+  app.listeners.click({ target: new app.Element(), timeStamp: 1000090 });
+  app.flush();
+  assert.equal(app.reports[0].duration, 42);
+  assert.equal(app.reports[0].source, 'paint-opportunity');
+});
+
+test('explicit view hook includes asynchronous work and preserves return and errors', async () => {
+  const app = setup();
+  let commit;
+  const update = app.context.window.dailyGrindPerformance.measureViewSwitch('menu',
+    () => new Promise((resolve) => { commit = resolve; }));
+  app.flush();
+  assert.equal(app.reports.length, 0);
+  commit('done');
+  assert.equal(await update, 'done');
+  app.flush();
+  assert.equal(app.reports[0].kind, 'view-switch-to-paint');
+  assert.equal(app.reports[0].duration, 64);
+  await assert.rejects(app.context.window.dailyGrindPerformance.measureViewSwitch('failed',
+    () => { throw new Error('update failed'); }), /update failed/);
+  app.flush();
+  assert.equal(app.reports.length, 1);
+});
+
+test('history preserves behavior and hidden or unloaded pages discard unfinished timings', () => {
+  const app = setup();
+  assert.equal(app.context.history.pushState('ok'), 'ok');
+  app.flush();
+  assert.equal(app.reports[0].label, 'history:pushState');
+  assert.throws(() => app.context.history.pushState('fail'), /history failed/);
+  app.listeners.popstate();
+  app.listeners.pagehide();
+  app.flush();
+  assert.equal(app.reports.length, 1);
+  app.listeners.hashchange();
+  app.context.document.visibilityState = 'hidden';
+  app.listeners.visibilitychange();
+  app.flush();
+  assert.equal(app.reports.length, 1);
+});

