--- /dev/null
+++ b/media.js
@@ -0,0 +1,42 @@
+// Deferred URLs start in data attributes so the preload scanner cannot fetch them.
+(() => {
+  const players = document.querySelectorAll('video[loading="lazy"], audio[loading="lazy"]');
+
+  function hydrate(player) {
+    if (!player.dataset.src) return;
+    if (player.dataset.poster) {
+      player.poster = player.dataset.poster;
+      delete player.dataset.poster;
+    }
+    player.preload = player.dataset.preload || 'none';
+    player.src = player.dataset.src;
+    delete player.dataset.preload;
+    delete player.dataset.src;
+  }
+
+  let observer;
+  for (const player of players) {
+    // Detect each element independently for browsers shipping video before audio.
+    if ('loading' in player) {
+      hydrate(player); // Native lazy loading gates poster, metadata, and media requests.
+    } else if ('IntersectionObserver' in window) {
+      observer ??= new IntersectionObserver((entries) => {
+        for (const entry of entries) {
+          if (!entry.isIntersecting) continue;
+          hydrate(entry.target);
+          observer.unobserve(entry.target);
+        }
+      }, { rootMargin: '200px 0px' });
+      observer.observe(player);
+    } else {
+      // Very old browsers: require an explicit action instead of fetching offscreen media.
+      const button = document.querySelector(`[data-load-media="${player.id}"]`);
+      button.hidden = false;
+      button.addEventListener('click', () => {
+        hydrate(player);
+        player.focus();
+        button.hidden = true;
+      }, { once: true });
+    }
+  }
+})();
