+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { test } = require('node:test');
+const vm = require('node:vm');
+
+const script = readFileSync('media.js', 'utf8');
+
+function setup({ native = false, intersection = true } = {}) {
+  const players = ['roasting-video', 'podcast-audio'].map((id, index) => ({
+    id,
+    dataset: { src: `${id}.mp4`, preload: 'metadata', ...(index ? {} : { poster: 'poster.jpg' }) },
+    preload: 'none',
+    ...(native ? { loading: 'lazy' } : {}),
+    focus() { this.focused = true; },
+  }));
+  const buttons = players.map(() => ({
+    hidden: true,
+    addEventListener(type, listener) { this.click = listener; },
+  }));
+  let observer;
+  class IntersectionObserver {
+    constructor(callback, options) {
+      Object.assign(this, { callback, options, observed: new Set() });
+      observer = this;
+    }
+    observe(player) { this.observed.add(player); }
+    unobserve(player) { this.observed.delete(player); }
+  }
+  vm.runInNewContext(script, {
+    window: intersection ? { IntersectionObserver } : {},
+    IntersectionObserver,
+    document: {
+      querySelectorAll: () => players,
+      querySelector: (selector) => buttons[players.findIndex((p) => selector.includes(p.id))],
+    },
+  });
+  return { players, buttons, observer };
+}
+
+test('fallback withholds posters and metadata until each player approaches', () => {
+  const { players, observer } = setup();
+  assert.equal(observer.options.rootMargin, '200px 0px');
+  for (const player of players) {
+    assert.equal(player.src, undefined);
+    assert.equal(player.poster, undefined);
+    assert.equal(player.preload, 'none');
+  }
+  observer.callback([{ target: players[0], isIntersecting: false }]);
+  assert.equal(players[0].src, undefined);
+  observer.callback([{ target: players[0], isIntersecting: true }]);
+  assert.equal(players[0].src, 'roasting-video.mp4');
+  assert.equal(players[0].poster, 'poster.jpg');
+  assert.equal(players[0].preload, 'metadata');
+  assert.equal(observer.observed.has(players[0]), false);
+  assert.equal(players[1].src, undefined);
+  observer.callback([{ target: players[1], isIntersecting: true }]);
+  assert.equal(players[1].src, 'podcast-audio.mp4');
+  assert.equal(observer.observed.size, 0);
+});
+
+test('native media loading receives the URLs while preserving lazy loading', () => {
+  const { players, observer } = setup({ native: true });
+  assert.equal(observer, undefined);
+  for (const player of players) {
+    assert.equal(player.loading, 'lazy');
+    assert.ok(player.src);
+    assert.equal(player.preload, 'metadata');
+    assert.equal(player.dataset.src, undefined);
+  }
+});
+
+test('without IntersectionObserver, resources require an explicit action', () => {
+  const { players, buttons } = setup({ intersection: false });
+  assert.ok(buttons.every((button) => !button.hidden));
+  assert.ok(players.every((player) => !player.src));
+  buttons[0].click();
+  assert.ok(players[0].src);
+  assert.equal(players[0].focused, true);
+  assert.equal(buttons[0].hidden, true);
+  assert.equal(players[1].src, undefined);
+});
+
+test('HTML exposes only hero resources to the preload scanner', () => {
+  const html = readFileSync('index.html', 'utf8');
+  const tags = [...html.matchAll(/<(video|audio)\b[^>]*>/g)].map((match) => match[0]);
+  assert.equal(tags.length, 3);
+  assert.doesNotMatch(tags[0], /loading="lazy"/);
+  assert.match(tags[0], /\ssrc="media\/morning-coffee.mp4"/);
+  for (const tag of tags.slice(1)) {
+    assert.match(tag, /loading="lazy"/);
+    assert.match(tag, /preload="none"/);
+    assert.doesNotMatch(tag, /\s(?:src|poster)="/);
+    assert.match(tag, /\scontrols(?:\s|>)/);
+  }
+  for (const tag of tags.filter((tag) => tag.startsWith('<video'))) {
+    assert.match(tag, /width="\d+" height="\d+"/);
+  }
+  for (const path of [...html.matchAll(/(?:src|poster)="(media\/[^\"]+)"/g)]) {
+    assert.ok(readFileSync(path[1]).length > 0, `${path[1]} exists`);
+  }
+});

