+(() => {
+  const players = [...document.querySelectorAll('[data-lazy-media]')];
+  const approachDistance = 200;
+
+  function preparePlayer(player) {
+    if (player.dataset.mediaReady) return;
+    player.dataset.mediaReady = 'true';
+
+    // A poster is a network request too: keep it out of the active HTML
+    // attributes until the player is near the viewport.
+    if (player.dataset.poster) {
+      player.poster = player.dataset.poster;
+      delete player.dataset.poster;
+    }
+    player.querySelectorAll('source[data-src]').forEach(source => {
+      source.src = source.dataset.src;
+      delete source.dataset.src;
+    });
+    player.preload = 'metadata';
+    player.load();
+  }
+
+  players.forEach(player => {
+    // Keyboard or pointer interaction can also prepare a player immediately.
+    player.addEventListener('focus', () => preparePlayer(player), { once: true });
+    player.addEventListener('pointerdown', () => preparePlayer(player), { once: true });
+    const showError = () => {
+      const message = player.parentElement.querySelector('.media-error');
+      if (message) message.hidden = false;
+    };
+    player.addEventListener('error', showError);
+    player.querySelectorAll('source').forEach(source => source.addEventListener('error', showError));
+  });
+
+  if ('IntersectionObserver' in window) {
+    const observer = new IntersectionObserver(entries => {
+      entries.forEach(entry => {
+        if (!entry.isIntersecting) return;
+        preparePlayer(entry.target);
+        observer.unobserve(entry.target);
+      });
+    }, { rootMargin: `${approachDistance}px`, threshold: 0 });
+    players.forEach(player => observer.observe(player));
+  } else {
+    // Older browsers still defer offscreen requests, rather than loading all
+    // players as a fallback. Remove listeners when every player is prepared.
+    let scheduled = false;
+    function checkPositions() {
+      scheduled = false;
+      players.forEach(player => {
+        if (player.dataset.mediaReady) return;
+        const rect = player.getBoundingClientRect();
+        if (rect.bottom >= -approachDistance && rect.top <= window.innerHeight + approachDistance &&
+            rect.right >= -approachDistance && rect.left <= window.innerWidth + approachDistance) {
+          preparePlayer(player);
+        }
+      });
+      if (players.every(player => player.dataset.mediaReady)) {
+        window.removeEventListener('scroll', scheduleCheck);
+        window.removeEventListener('resize', scheduleCheck);
+      }
+    }
+    function scheduleCheck() {
+      if (scheduled) return;
+      scheduled = true;
+      window.requestAnimationFrame(checkPositions);
+    }
+    window.addEventListener('scroll', scheduleCheck, { passive: true });
+    window.addEventListener('resize', scheduleCheck);
+    checkPositions();
+  }
+})();
