@@ -0,0 +1,107 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync, existsSync } = require('node:fs');
+const vm = require('node:vm');
+const code = readFileSync('media.js', 'utf8');
+
+function setup(withObserver = true) {
+  const listeners = new Map();
+  const players = [100, 1400, 2200].map((top, index) => {
+    const source = { dataset: { src: `media-${index}.mp4` }, addEventListener() {} };
+    const events = {};
+    const message = { hidden: true };
+    return {
+      dataset: index < 2 ? { poster: `poster-${index}.jpg` } : {},
+      preload: 'none',
+      loads: 0,
+      source,
+      events,
+      message,
+      top,
+      parentElement: { querySelector: () => message },
+      addEventListener: (name, fn) => { events[name] = fn; },
+      querySelectorAll: () => [source],
+      load() { this.loads++; },
+      getBoundingClientRect() { return { top: this.top, bottom: this.top + 200, left: 0, right: 600 }; },
+    };
+  });
+  let callback;
+  const observed = new Set();
+  const window = {
+    innerHeight: 800, innerWidth: 1200,
+    addEventListener: (name, fn) => listeners.set(name, fn),
+    removeEventListener: name => listeners.delete(name),
+    requestAnimationFrame: fn => fn(),
+  };
+  class Observer {
+    constructor(fn, options) { callback = fn; assert.equal(options.rootMargin, '200px'); }
+    observe(player) { observed.add(player); }
+    unobserve(player) { observed.delete(player); }
+  }
+  if (withObserver) window.IntersectionObserver = Observer;
+  vm.runInNewContext(code, {
+    document: { querySelectorAll: () => players }, window, IntersectionObserver: Observer,
+  });
+  return { players, listeners, observed, intersect: (player, visible) => callback([{ target: player, isIntersecting: visible }]) };
+}
+
+test('initial HTML cannot request deferred posters or media', () => {
+  const html = readFileSync('index.html', 'utf8');
+  const tags = html.match(/<(?:video|audio|source)\b[^>]*>/g);
+  assert.equal(tags.length, 6);
+  for (const tag of tags) {
+    assert.doesNotMatch(tag, /\s(?:src|poster|autoplay)\s*[=>]/);
+    if (!tag.startsWith('<source')) assert.match(tag, /preload="none"/);
+    for (const [, path] of tag.matchAll(/data-(?:src|poster)="(assets\/[^"?]+)"/g)) {
+      assert.ok(existsSync(path), `${path} must exist`);
+    }
+  }
+  assert.doesNotMatch(html, /<link[^>]+rel="preload"/);
+  assert.doesNotMatch(html, /url\s*\(/);
+});
+
+test('offscreen players make no requests; approaching players activate once', () => {
+  const { players, observed, intersect } = setup();
+  for (const player of players) {
+    assert.equal(player.source.src, undefined);
+    assert.equal(player.poster, undefined);
+    assert.equal(player.preload, 'none');
+    assert.equal(player.loads, 0);
+  }
+  intersect(players[1], false);
+  assert.equal(players[1].loads, 0);
+  for (const player of players) {
+    intersect(player, true);
+    assert.ok(player.source.src);
+    assert.equal(player.preload, 'metadata');
+    assert.equal(player.loads, 1);
+    assert.ok(!observed.has(player));
+    intersect(player, true);
+    player.events.focus();
+    assert.equal(player.loads, 1);
+  }
+  assert.equal(players[1].poster, 'poster-1.jpg');
+});
+
+test('keyboard interaction prepares a player and network errors have a visible fallback', () => {
+  const { players } = setup();
+  players[2].events.focus();
+  assert.equal(players[2].loads, 1);
+  players[2].events.error();
+  assert.equal(players[2].message.hidden, false);
+});
+
+test('fallback defers distant players and cleans up after the last approaches', () => {
+  const { players, listeners } = setup(false);
+  assert.equal(players[0].loads, 1);
+  assert.equal(players[1].loads, 0);
+  assert.equal(players[2].source.src, undefined);
+  players[1].top = 1000;
+  listeners.get('scroll')();
+  assert.equal(players[1].loads, 1);
+  assert.equal(players[2].loads, 0);
+  players[2].top = 900;
+  listeners.get('resize')();
+  assert.equal(players[2].loads, 1);
+  assert.equal(listeners.size, 0);
+});

