@@ -0,0 +1,136 @@
+(() => {
+  'use strict';
+
+  const secure = window.isSecureContext;
+  document.getElementById('secure-context-notice').hidden = secure;
+
+  function validateEndpoint(value, space) {
+    const url = new URL(value);
+    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+      throw new Error('Use an HTTP or HTTPS status URL without credentials or a fragment.');
+    }
+    const host = url.hostname.toLowerCase();
+    const parts = host.split('.').map(Number);
+    const ipv4 = parts.length === 4 && parts.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+    const loopback = (ipv4 && parts[0] === 127) || host === '[::1]' || host === 'localhost' || host.endsWith('.localhost');
+    const local = (ipv4 && (parts[0] === 10 || (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) ||
+      (parts[0] === 192 && parts[1] === 168) || (parts[0] === 169 && parts[1] === 254))) ||
+      host.endsWith('.local') || /^\[(?:f[cd][0-9a-f]{2}:|fe[89ab][0-9a-f]:)/i.test(host);
+    if (space === 'loopback' ? !loopback : !local) {
+      throw new Error(space === 'loopback'
+        ? 'Use a loopback address such as 127.0.0.1, localhost, or [::1] for the helper.'
+        : 'Use the brewer’s private LAN address (such as 192.168.1.100) or a .local hostname.');
+    }
+    return url.href;
+  }
+
+  document.querySelectorAll('[data-connection]').forEach(form => {
+    const kind = form.dataset.connection;
+    const space = kind === 'brewer' ? 'local' : 'loopback';
+    const permissionName = space === 'local' ? 'local-network' : 'loopback-network';
+    const permissionLabel = space === 'local' ? 'Local network' : 'Loopback network';
+    const input = form.elements.endpoint;
+    const connect = form.querySelector('[type="submit"]');
+    const disconnect = form.querySelector('[type="button"]');
+    const badge = document.getElementById(`${kind}-badge`);
+    const status = document.getElementById(`${kind}-status`);
+    const permissionUI = document.getElementById(`${kind}-permission`);
+    let permissionState = 'prompt';
+    let controller = null;
+
+    function render(state, message) {
+      badge.dataset.state = state;
+      badge.textContent = { idle: 'Not connected', checking: 'Connecting…', connected: 'Connected', error: 'Needs attention' }[state];
+      status.textContent = message;
+      form.setAttribute('aria-busy', String(state === 'checking'));
+      connect.disabled = !secure || permissionState === 'denied' || state === 'checking';
+      connect.textContent = state === 'connected' ? 'Check again' : `Connect ${kind}`;
+      disconnect.hidden = !['checking', 'connected'].includes(state);
+      disconnect.textContent = state === 'checking' ? 'Cancel' : 'Disconnect';
+    }
+
+    function reset(message) {
+      controller?.abort();
+      controller = null;
+      render('idle', message);
+    }
+
+    function updatePermission(state, supported = true) {
+      permissionState = state;
+      permissionUI.textContent = supported
+        ? `${permissionLabel} permission: ${{ granted: 'allowed', prompt: 'ask when connecting', denied: 'blocked' }[state]}`
+        : `${permissionLabel} permission: browser-managed (status unavailable)`;
+      if (state === 'denied') {
+        controller?.abort();
+        controller = null;
+        render('error', `Access blocked. Open this site’s browser settings, allow ${permissionLabel} access, then connect again.`);
+      } else {
+        connect.disabled = !secure || badge.dataset.state === 'checking';
+        if (badge.dataset.state === 'error') render('idle', 'Permission updated. Connect to try again.');
+      }
+    }
+
+    // Querying permission does not make a network request or display a prompt.
+    async function observePermission() {
+      try {
+        if (!navigator.permissions?.query) throw new Error('Unsupported');
+        const permission = await navigator.permissions.query({ name: permissionName });
+        updatePermission(permission.state);
+        permission.addEventListener('change', () => updatePermission(permission.state));
+      } catch {
+        // Unknown permission names must not prevent an explicit connection attempt.
+        updatePermission('prompt', false);
+      }
+    }
+    observePermission();
+
+    input.addEventListener('input', () => {
+      input.setCustomValidity('');
+      reset('Address updated. Connect to check this endpoint.');
+    });
+    disconnect.addEventListener('click', () => reset('Disconnected from this page. No equipment settings were changed.'));
+
+    form.addEventListener('submit', async event => {
+      event.preventDefault();
+      if (!secure || permissionState === 'denied' || controller) return;
+      let endpoint;
+      try {
+        endpoint = validateEndpoint(input.value.trim(), space);
+      } catch (error) {
+        input.setCustomValidity(error.message);
+        input.reportValidity();
+        return;
+      }
+
+      const attempt = new AbortController();
+      controller = attempt;
+      let timedOut = false;
+      const timer = setTimeout(() => { timedOut = true; attempt.abort(); }, 15000);
+      render('checking', `Checking the endpoint. Allow ${permissionLabel} access if your browser asks.`);
+      try {
+        // Keep this request in the user-initiated submit handler; never probe on load.
+        const response = await fetch(endpoint, {
+          method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+          redirect: 'error', referrerPolicy: 'no-referrer',
+          targetAddressSpace: space, signal: attempt.signal,
+        });
+        if (!response.ok) throw new Error(`Endpoint returned HTTP ${response.status}. Check its status URL and configuration.`);
+        // A readable successful response establishes reachability; no API payload is assumed.
+        if (response.body) response.body.cancel().catch(() => {});
+        if (controller !== attempt) return;
+        render('connected', `Endpoint reached at ${new Date().toLocaleTimeString()}. Select Check again to refresh; this is not a live connection.`);
+      } catch (error) {
+        if (controller !== attempt) return;
+        const setup = kind === 'brewer'
+          ? 'Check that the brewer is on and this device is on the shop’s Wi-Fi.'
+          : 'Open the desktop helper on this computer and confirm its port.';
+        const message = timedOut ? 'Connection timed out.' : error instanceof TypeError
+          ? 'The endpoint could not be reached or browser access was blocked.' : error.message;
+        render('error', `${message} ${setup} Allow ${permissionLabel} access in site settings. The endpoint must allow this website through CORS; if browser support is limited, try current Chrome or Edge.`);
+      } finally {
+        clearTimeout(timer);
+        if (controller === attempt) controller = null;
+      }
+    });
+  });
+})();
