+export function validateEndpoint(value, kind) {
+  let url;
+  try { url = new URL(value); } catch { throw new Error('Enter a complete http:// or https:// status URL.'); }
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS URL without a password or fragment.');
+  }
+  const octets = url.hostname.split('.').map(Number);
+  const ipv4 = /^\d+\.\d+\.\d+\.\d+$/.test(url.hostname) && octets.every(n => n >= 0 && n <= 255);
+  const privateIp = ipv4 && (octets[0] === 10 ||
+    (octets[0] === 192 && octets[1] === 168) ||
+    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31));
+  if (kind === 'brewer' && !privateIp) {
+    throw new Error('Enter the brewer’s private Wi-Fi IPv4 address, such as 192.168.1.100.');
+  }
+  if (kind === 'helper' && !['127.0.0.1', 'localhost'].includes(url.hostname)) {
+    throw new Error('The desktop helper must use 127.0.0.1 or localhost on this computer.');
+  }
+  if (!['brewer', 'helper'].includes(kind)) throw new Error('Unknown equipment type.');
+  return url;
+}
+
+export async function readStatus(url, kind, signal, fetcher = globalThis.fetch) {
+  const response = await fetcher(url.href, {
+    method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+    redirect: 'error', referrerPolicy: 'no-referrer', signal,
+    targetAddressSpace: kind === 'brewer' ? 'local' : 'loopback',
+  });
+  if (!response.ok) throw new Error(`Device returned HTTP ${response.status}. Check its status URL.`);
+  let data;
+  try { data = await response.json(); } catch { throw new Error('The device must return JSON from its status URL.'); }
+  if (!data || typeof data.status !== 'string' || !data.status.trim()) {
+    throw new Error('The device response needs a nonempty “status” string. See device setup below.');
+  }
+  return { status: data.status.trim().slice(0, 160), name: typeof data.name === 'string' ? data.name.slice(0, 80) : '' };
+}
+
+function setupPanel(form) {
+  const kind = form.dataset.connection;
+  const input = form.elements.endpoint;
+  const connect = form.querySelector('.connect-button');
+  const disconnect = form.querySelector('.disconnect-button');
+  const badge = form.querySelector('.connection-state');
+  const message = form.querySelector('.connection-message');
+  const connectLabel = connect.textContent;
+  let controller;
+  let pollTimer;
+  let endpoint;
+
+  function render(state, detail) {
+    badge.dataset.state = state;
+    badge.textContent = { disconnected: 'Not connected', connecting: 'Connecting…', connected: 'Connected', error: 'Connection failed' }[state];
+    message.textContent = detail;
+    input.disabled = state === 'connecting' || state === 'connected';
+    connect.disabled = state === 'connecting';
+    connect.hidden = state === 'connected';
+    connect.textContent = state === 'connecting' ? 'Connecting…' : state === 'error' ? 'Try again' : connectLabel;
+    disconnect.hidden = !['connecting', 'connected'].includes(state);
+    disconnect.textContent = state === 'connecting' ? 'Cancel' : 'Disconnect';
+    form.setAttribute('aria-busy', String(state === 'connecting'));
+  }
+
+  function stop() {
+    clearTimeout(pollTimer);
+    controller?.abort();
+    controller = undefined;
+  }
+
+  async function check(initial) {
+    const request = new AbortController();
+    controller = request;
+    let timedOut = false;
+    const timeout = setTimeout(() => { timedOut = true; request.abort(); }, 10000);
+    try {
+      const data = await readStatus(endpoint, kind, request.signal);
+      if (controller !== request) return;
+      render('connected', `${data.name || (kind === 'brewer' ? 'Brewer' : 'Desktop helper')}: ${data.status} · Checked ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
+      pollTimer = setTimeout(() => check(false), 15000);
+    } catch (error) {
+      if (controller !== request) return;
+      const reason = timedOut ? 'No response within 10 seconds.' :
+        error instanceof TypeError ? 'Could not reach the device. Check its address, browser permissions, and CORS setup.' : error.message;
+      render('error', `${initial ? '' : 'Connection lost. '}${reason}`);
+    } finally {
+      clearTimeout(timeout);
+      if (controller === request) controller = undefined;
+    }
+  }
+
+  form.addEventListener('submit', event => {
+    event.preventDefault();
+    stop();
+    input.removeAttribute('aria-invalid');
+    try { endpoint = validateEndpoint(input.value.trim(), kind); }
+    catch (error) {
+      render('error', error.message);
+      input.setAttribute('aria-invalid', 'true');
+      input.focus();
+      return;
+    }
+    render('connecting', 'Contacting your device. Allow access if your browser asks.');
+    check(true);
+  });
+  disconnect.addEventListener('click', () => {
+    stop();
+    render('disconnected', 'Disconnected. Status checks have stopped.');
+    connect.focus();
+  });
+  // A restored page must require a fresh, intentional connection.
+  window.addEventListener('pagehide', () => {
+    stop();
+    render('disconnected', 'Disconnected. Connect again to check your equipment.');
+  });
+}
+
+if (typeof document !== 'undefined') {
+  document.querySelectorAll('[data-connection]').forEach(setupPanel);
+}
