+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { validateEndpoint, readStatus } from './equipment.mjs';
+
+test('accepts private brewer addresses and loopback helper addresses', () => {
+  for (const host of ['192.168.1.100', '10.0.0.2', '172.16.0.2', '172.31.255.254']) {
+    assert.equal(validateEndpoint(`http://${host}/api/status`, 'brewer').hostname, host);
+  }
+  for (const host of ['127.0.0.1', 'localhost']) {
+    assert.equal(validateEndpoint(`http://${host}:8765/api/status`, 'helper').port, '8765');
+  }
+});
+
+test('rejects wrong network targets and unsafe URL forms before requesting', () => {
+  for (const host of ['172.15.0.1', '172.32.0.1', '8.8.8.8', '127.0.0.1', 'example.com']) {
+    assert.throws(() => validateEndpoint(`http://${host}/`, 'brewer'));
+  }
+  for (const value of ['http://192.168.1.100/', 'http://localhost.example.com/', 'file:///tmp/status', 'http://user:pass@localhost/', 'http://localhost/#fragment', 'not a URL']) {
+    assert.throws(() => validateEndpoint(value, 'helper'));
+  }
+});
+
+test('status requests use CORS, correct address space, no credentials or redirects', async () => {
+  for (const [kind, address, space] of [['brewer', '192.168.1.100', 'local'], ['helper', '127.0.0.1', 'loopback']]) {
+    const url = validateEndpoint(`http://${address}/api/status`, kind);
+    const signal = new AbortController().signal;
+    const result = await readStatus(url, kind, signal, async (target, options) => {
+      assert.equal(target, url.href);
+      assert.equal(options.targetAddressSpace, space);
+      assert.equal(options.credentials, 'omit');
+      assert.equal(options.mode, 'cors');
+      assert.equal(options.redirect, 'error');
+      assert.equal(options.cache, 'no-store');
+      assert.equal(options.signal, signal);
+      return { ok: true, json: async () => ({ name: 'Counter brewer', status: ' ready ' }) };
+    });
+    assert.deepEqual(result, { name: 'Counter brewer', status: 'ready' });
+  }
+});
+
+test('does not report connection success for HTTP errors or invalid status responses', async () => {
+  const url = new URL('http://127.0.0.1/api/status');
+  await assert.rejects(readStatus(url, 'helper', undefined, async () => ({ ok: false, status: 503 })), /HTTP 503/);
+  await assert.rejects(readStatus(url, 'helper', undefined, async () => ({ ok: true, json: async () => { throw new SyntaxError(); } })), /return JSON/);
+  for (const data of [null, {}, { status: '' }, { status: 1 }]) {
+    await assert.rejects(readStatus(url, 'helper', undefined, async () => ({ ok: true, json: async () => data })), /status/);
+  }
+});
+
+test('network and cancellation errors propagate for the panel to handle', async () => {
+  const url = new URL('http://127.0.0.1/api/status');
+  await assert.rejects(readStatus(url, 'helper', undefined, async () => { throw new TypeError('Failed to fetch'); }), /Failed to fetch/);
+  const controller = new AbortController();
+  controller.abort();
+  await assert.rejects(readStatus(url, 'helper', controller.signal, async (_, { signal }) => {
+    signal.throwIfAborted();
+  }), { name: 'AbortError' });
+});
