+import { useEffect, useRef, useState } from 'react';
+import type { FormEvent } from 'react';
+import { diagnosticsUrl } from '../utils/diagnostics';
+import type { AddressSpace } from '../utils/diagnostics';
+
+type NetworkPermission = 'local-network' | 'loopback-network';
+type Permission = PermissionState | 'unknown';
+type Result = { ok: boolean; message: string };
+
+function Connection({ space, title, initialUrl, description }: {
+  space: AddressSpace; title: string; initialUrl: string; description: string;
+}) {
+  const permissionName: NetworkPermission = space === 'local' ? 'local-network' : 'loopback-network';
+  const permissionLabel = space === 'local' ? 'Local network' : 'Loopback network';
+  const [endpoint, setEndpoint] = useState(initialUrl);
+  const [permission, setPermission] = useState<Permission>('unknown');
+  const [secure, setSecure] = useState<boolean | null>(null);
+  const [busy, setBusy] = useState(false);
+  const [result, setResult] = useState<Result | null>(null);
+  const active = useRef<AbortController | null>(null);
+
+  useEffect(() => {
+    setSecure(window.isSecureContext);
+    let disposed = false;
+    let status: PermissionStatus | undefined;
+    const update = () => { if (!disposed && status) setPermission(status.state); };
+    async function observePermission() {
+      try {
+        // Some browsers do not recognize the granular permission names yet.
+        status = await navigator.permissions.query({ name: permissionName as PermissionName });
+        if (disposed) return;
+        update();
+        status.addEventListener('change', update);
+      } catch {
+        if (!disposed) setPermission('unknown');
+      }
+    }
+    void observePermission();
+    return () => {
+      disposed = true;
+      status?.removeEventListener('change', update);
+      active.current?.abort();
+    };
+  }, [permissionName]);
+
+  async function connect(event: FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    if (active.current) return;
+    setResult(null);
+    if (!window.isSecureContext) {
+      setResult({ ok: false, message: 'Open The DevTools Times over HTTPS to access local endpoints.' });
+      return;
+    }
+    if (permission === 'denied') return;
+    let url: string;
+    try {
+      url = diagnosticsUrl(endpoint, space);
+    } catch (error) {
+      setResult({ ok: false, message: (error as Error).message });
+      return;
+    }
+    const controller = new AbortController();
+    active.current = controller;
+    setBusy(true);
+    let timedOut = false;
+    const timeout = window.setTimeout(() => {
+      timedOut = true;
+      controller.abort();
+    }, 20000);
+    try {
+      // Keep the nonstandard option typed without changing global DOM definitions.
+      const options: RequestInit & { targetAddressSpace: AddressSpace } = {
+        method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+        redirect: 'error', referrerPolicy: 'no-referrer',
+        signal: controller.signal, targetAddressSpace: space,
+      };
+      const response = await fetch(url, options);
+      await response.body?.cancel();
+      if (!response.ok) {
+        setResult({ ok: false, message: `Endpoint responded with HTTP ${response.status}. Check the URL and service configuration, then retry.` });
+      } else {
