+export type AddressSpace = 'local' | 'loopback';
+
+/** Validate the normalized host so each control only targets its stated network. */
+export function diagnosticsUrl(value: string, space: AddressSpace): string {
+  let url: URL;
+  try {
+    url = new URL(value.trim());
+  } catch {
+    throw new Error('Enter a complete HTTP or HTTPS endpoint URL, including its port and path.');
+  }
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS URL without credentials or a fragment.');
+  }
+  const host = url.hostname.toLowerCase();
+  const ipv4 = /^\d+\.\d+\.\d+\.\d+$/.test(host) ? host.split('.').map(Number) : null;
+  const loopback = host === 'localhost' || host.endsWith('.localhost') || host === '[::1]' || ipv4?.[0] === 127;
+  const privateLan = (ipv4 && (
+    ipv4[0] === 10 ||
+    (ipv4[0] === 172 && ipv4[1] >= 16 && ipv4[1] <= 31) ||
+    (ipv4[0] === 192 && ipv4[1] === 168) ||
+    (ipv4[0] === 169 && ipv4[1] === 254)
+  )) || host.endsWith('.local') || /^\[(?:f[cd][0-9a-f]{2}:|fe[89ab][0-9a-f]:)/.test(host);
+  if (space === 'loopback' ? !loopback : !privateLan || loopback) {
+    throw new Error(space === 'loopback'
+      ? 'Use a loopback address such as 127.0.0.1, localhost, or [::1].'
+      : 'Use a private LAN address such as 192.168.1.100 or device.local.');
+  }
+  return url.href;
+}

