+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { diagnosticsEndpoint, diagnosticsRequest } from './diagnostics.ts';
+
+test('accepts private LAN endpoints and preserves port, path, and query', () => {
+  for (const host of ['192.168.1.100', '10.0.0.8', '172.16.0.2', '172.31.255.1', 'device.local', '[fd00::1]', '[fe80::1]']) {
+    const endpoint = `http://${host}:8080/health?check=1`;
+    assert.equal(diagnosticsEndpoint(endpoint, 'local'), endpoint);
+  }
+});
+
+test('accepts loopback destinations only for the companion CLI', () => {
+  for (const host of ['127.0.0.1', '127.0.0.2', 'localhost', 'cli.localhost', '[::1]']) {
+    const endpoint = `http://${host}:3000/health`;
+    assert.equal(diagnosticsEndpoint(endpoint, 'loopback'), endpoint);
+    assert.throws(() => diagnosticsEndpoint(endpoint, 'local'));
+  }
+  assert.throws(() => diagnosticsEndpoint('http://192.168.1.100/health', 'loopback'));
+});
+
+test('rejects public, malformed, credential-bearing, and non-HTTP endpoints', () => {
+  for (const endpoint of ['invalid', 'http://example.com', 'http://127.evil.example', 'http://192.168.1.1.example.com', 'http://172.32.0.1', 'http://8.8.8.8', 'http://[2001:4860::8888]', 'file:///etc/hosts', 'ftp://192.168.1.1', 'http://user:secret@192.168.1.1', 'http://192.168.1.1/#fragment']) {
+    assert.throws(() => diagnosticsEndpoint(endpoint, 'local'), endpoint);
+    assert.throws(() => diagnosticsEndpoint(endpoint, 'loopback'), endpoint);
+  }
+});
+
+test('uses distinct network spaces and readable, credential-free, abortable requests', () => {
+  const signal = new AbortController().signal;
+  for (const space of ['local', 'loopback'] as const) {
+    const options = diagnosticsRequest(space, signal);
+    assert.equal(options.targetAddressSpace, space);
+    assert.equal(options.method, 'GET');
+    assert.equal(options.mode, 'cors');
+    assert.equal(options.credentials, 'omit');
+    assert.equal(options.redirect, 'error');
+    assert.equal(options.cache, 'no-store');
+    assert.equal(options.referrerPolicy, 'no-referrer');
+    assert.equal(options.signal, signal);
+  }
+});
