@@ -0,0 +1,44 @@
+export type AddressSpace = 'local' | 'loopback';
+
+// Keep the two destinations distinct; never send diagnostics to a public host.
+export function diagnosticsEndpoint(value: string, space: AddressSpace): string {
+  let url: URL;
+  try {
+    url = new URL(value);
+  } catch {
+    throw new Error('Enter a complete URL, including http:// or https://.');
+  }
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS URL without credentials or a fragment.');
+  }
+
+  const host = url.hostname;
+  const octets = host.split('.').map(Number);
+  const ipv4 = octets.length === 4 && octets.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+  const loopback = host === 'localhost' || host.endsWith('.localhost') || host === '[::1]' || (ipv4 && octets[0] === 127);
+  const privateIPv4 = ipv4 && (octets[0] === 10 ||
+    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) ||
+    (octets[0] === 192 && octets[1] === 168));
+  const privateIPv6 = /^\[(?:f[cd][0-9a-f]{2}:|fe[89ab][0-9a-f]:)/i.test(host);
+  const local = !loopback && (privateIPv4 || privateIPv6 || host.endsWith('.local'));
+
+  if (space === 'loopback' ? !loopback : !local) {
+    throw new Error(space === 'loopback'
+      ? 'Use a loopback address such as http://127.0.0.1:3000/health.'
+      : 'Use a private LAN address such as http://192.168.1.100:8080/health or a .local hostname.');
+  }
+  return url.href;
+}
+
+export function diagnosticsRequest(space: AddressSpace, signal: AbortSignal): RequestInit & { targetAddressSpace: AddressSpace } {
+  return {
+    method: 'GET',
+    mode: 'cors',
+    credentials: 'omit',
+    cache: 'no-store',
+    redirect: 'error',
+    referrerPolicy: 'no-referrer',
+    targetAddressSpace: space,
+    signal,
+  };
+}

