+
+async function initialize() {
+  const response = await fetch('/migration.config.json', { cache: 'no-store' });
+  if (!response.ok) throw new Error('App move configuration is unavailable.');
+  const config = await response.json();
+  const isOld = location.origin === config.oldOrigin;
+  const isNew = location.origin === config.newOrigin;
+  // Source checkouts and deployments at unrelated origins never transfer data.
+  if (!isOld && !isNew) return;
+
+  if (location.pathname === '/transfer.html') {
+    if (!isOld || !window.opener) return;
+    const parent = window.opener;
+    const status = document.querySelector('#transfer-status');
+    window.addEventListener('message', event => {
+      if (event.source !== parent || !trustedOrigin(event, config.newOrigin) ||
+          event.data?.type !== 'daily-grind:request' ||
+          typeof event.data.nonce !== 'string' || event.data.nonce.length !== 36) return;
+      try {
+        const payload = exportSettings(localStorage, config);
+        parent.postMessage({ type: 'daily-grind:settings', nonce: event.data.nonce, payload }, config.newOrigin);
