+      } catch {
+        parent.postMessage({ type: 'daily-grind:error', nonce: event.data.nonce }, config.newOrigin);
+        status.textContent = 'Settings could not be read. Your original settings are still here.';
+      }
+    });
+    return;
+  }
+
+  const notice = document.querySelector('#migration-notice');
+  if (!notice) return;
+  notice.hidden = false;
+  const title = document.createElement('h2');
+  title.textContent = isOld ? 'The Daily Grind is moving' : 'Bring your settings with you';
+  const description = document.createElement('p');
+  description.textContent = isOld
+    ? 'Open our new home and transfer your preferences before accepting the app update. Keep this app until your settings are saved.'
+    : 'Transfer your preferences from the old app. Preferences already set here will be kept.';
+  const status = document.createElement('p');
+  status.setAttribute('role', 'status');
+  notice.append(title, description);
+  function button(text, handler) {
+    const element = document.createElement('button');
+    element.type = 'button';
+    element.textContent = text;
+    element.addEventListener('click', handler);
+    notice.append(element);
+    return element;
+  }
+
+  if (isOld) {
+    const link = document.createElement('a');
+    link.href = `${config.newOrigin}/`;
+    link.textContent = 'Open the new Daily Grind';
+    notice.append(link, document.createElement('br'));
+    button('Download settings backup', () => {
+      try {
+        const blob = new Blob([JSON.stringify(exportSettings(localStorage, config))], { type: 'application/json' });
+        const url = URL.createObjectURL(blob);
+        const download = document.createElement('a');
+        download.href = url;
+        download.download = 'daily-grind-settings.json';
+        download.click();
+        setTimeout(() => URL.revokeObjectURL(url), 1000);
+        status.textContent = 'Import this backup at the new app to finish transferring your settings.';
+      } catch (error) { status.textContent = `Backup failed: ${error.message}`; }
+    });
+  } else {
+    const transfer = button('Transfer my settings', () => {
+      // A top-level popup reads the original storage, avoiding iframe partitioning.
+      const nonce = crypto.randomUUID();
+      const popup = window.open(`${config.oldOrigin}/transfer.html`, '_blank', 'popup,width=520,height=400');
+      if (!popup) {
+        status.textContent = 'Allow the transfer window, or download a settings backup from the old app and import it below.';
+        return;
+      }
+      transfer.disabled = true;
+      status.textContent = 'Connecting to your old app…';
+      const cleanup = () => {
+        clearInterval(timer);
+        clearTimeout(timeout);
+        window.removeEventListener('message', receive);
+        transfer.disabled = false;
+        popup.close();
+      };
+      const receive = event => {
+        if (event.source !== popup || !trustedOrigin(event, config.oldOrigin) || event.data?.nonce !== nonce ||
+            !['daily-grind:settings', 'daily-grind:error'].includes(event.data?.type)) return;
+        try {
+          if (event.data.type === 'daily-grind:error') throw new Error('The old app could not read your preferences.');
+          importSettings(localStorage, event.data.payload, config);
+          status.textContent = 'Settings saved. You can now accept the browser’s app update. If no update is offered, install this site from your browser’s app menu.';
+        } catch (error) { status.textContent = `Transfer failed: ${error.message} Your old settings have been kept. You can retry or import a backup.`; }
+        cleanup();
+      };
+      window.addEventListener('message', receive);
+      const timer = setInterval(() => {
+        if (popup.closed) {
+          status.textContent = 'Transfer window closed. You can retry or import a backup.';
+          cleanup();
+        } else {
+          popup.postMessage({ type: 'daily-grind:request', nonce }, config.oldOrigin);
+        }
+      }, 400);
+      const timeout = setTimeout(() => {
+        status.textContent = 'Could not connect. Download a backup from the old app, then import it below.';
+        cleanup();
+      }, 30000);
+    });
+    const label = document.createElement('label');
+    label.textContent = 'Or import a settings backup: ';
+    const input = document.createElement('input');
+    input.type = 'file';
+    input.accept = 'application/json,.json';
+    input.addEventListener('change', async () => {
+      try {
+        const file = input.files[0];
+        if (!file) return;
+        if (file.size > MAX_BYTES) throw new Error('The settings backup is too large.');
+        importSettings(localStorage, JSON.parse(await file.text()), config);
+        status.textContent = 'Settings saved. You can now update the app, or install this site from your browser’s app menu.';
+      } catch (error) { status.textContent = `Import failed: ${error.message}`; }
+      input.value = '';
+    });
+    label.append(input);
+    notice.append(label);
+    const fallback = document.createElement('p');
+    fallback.textContent = 'Supported browsers can keep your existing app shortcuts through an app update. Other browsers require installing this site again and recreating shortcuts. Sign in again and grant permissions when requested.';
+    notice.append(fallback);
+  }
+  notice.append(status);
+}
+
+initialize().catch(() => {
+  const status = document.querySelector('#transfer-status');
+  if (status) status.textContent = 'The transfer is unavailable. Return to the app and try a settings backup.';
+});
