+import { readFile, mkdir, cp, writeFile } from 'node:fs/promises';
+import { validateConfig } from './migration-config.mjs';
+
+const config = validateConfig(JSON.parse(await readFile('migration.config.json', 'utf8')));
+const base = JSON.parse(await readFile('manifest.webmanifest', 'utf8'));
+for (const role of ['old', 'new']) {
+  const directory = `dist/${role}`;
+  await mkdir(`${directory}/.well-known`, { recursive: true });
+  for (const file of ['index.html', 'icon.svg', 'migration.js', 'settings-transfer.js', 'transfer.html']) {
+    await cp(file, `${directory}/${file}`);
+  }
+  const manifest = { ...base, id: config[`${role}Id`] };
+  if (role === 'old') {
+    manifest.migrate_to = { id: config.newId, install_url: `${config.newOrigin}/` };
+  } else {
+    manifest.migrate_from = [{ id: config.oldId, install_url: `${config.oldOrigin}/` }];
+  }
+  await writeFile(`${directory}/manifest.webmanifest`, JSON.stringify(manifest, null, 2));
+  await writeFile(`${directory}/migration.config.json`, JSON.stringify({ ...config, role }, null, 2));
+  await writeFile(`${directory}/.well-known/web-app-origin-association`, JSON.stringify(
+    role === 'old' ? { [config.newId]: { allow_migration: true } } : {}, null, 2));
+}
+console.log('Built dist/old and dist/new. Configure real origins before deploying.');
