+import { getDomain } from 'tldts';
+
+export function validateConfig(config) {
+  const urls = ['oldOrigin', 'newOrigin'].map(key => {
+    const url = new URL(config[key]);
+    if (url.protocol !== 'https:' || url.username || url.password ||
+        url.pathname !== '/' || url.search || url.hash) {
+      throw new Error(`${key} must be an HTTPS origin without a path or credentials`);
+    }
+    return url;
+  });
+  const [old, next] = urls;
+  const domain = getDomain(old.hostname, { allowPrivateDomains: true });
+  if (!domain || domain !== getDomain(next.hostname, { allowPrivateDomains: true }) || old.origin === next.origin) {
+    throw new Error('Migration requires two distinct HTTPS origins on the same registrable domain');
+  }
+  const normalized = { ...config, oldOrigin: old.origin, newOrigin: next.origin };
+  for (const [key, origin] of [['oldId', old.origin], ['newId', next.origin]]) {
+    const id = new URL(config[key], origin);
+    if (!config[key] || id.origin !== origin || id.hash || id.username || id.password) {
+      throw new Error(`${key} must be an app ID on its corresponding origin without a fragment`);
+    }
+    normalized[key] = id.href;
+  }
+  if (!Array.isArray(config.settingsKeys) || !config.settingsKeys.length ||
+      config.settingsKeys.some(key => typeof key !== 'string' || !key || key.length > 200) ||
+      new Set(config.settingsKeys).size !== config.settingsKeys.length) {
+    throw new Error('settingsKeys must be a nonempty list of unique configuration storage keys');
+  }
+  return normalized;
+}
