@@ -0,0 +1,58 @@
+export const MAX_BYTES = 256 * 1024;
+
+export function trustedOrigin(event, expected) {
+  try {
+    if (event.origin === 'null') return false;
+    if ('Origin' in globalThis) {
+      let sender;
+      try { sender = Origin.from(event); }
+      catch { sender = Origin.from(event.origin); }
+      return sender.isSameOrigin(Origin.from(expected));
+    }
+    const actual = new URL(event.origin);
+    return actual.origin !== 'null' && actual.origin === new URL(expected).origin;
+  } catch { return false; }
+}
+
+export function exportSettings(storage, config) {
+  const settings = Object.create(null);
+  for (const key of config.settingsKeys) {
+    const value = storage.getItem(key);
+    if (value !== null) settings[key] = value;
+  }
+  const payload = { version: 1, from: config.oldOrigin, to: config.newOrigin, settings };
+  validatePayload(payload, config);
+  return payload;
+}
+
+export function validatePayload(payload, config) {
+  if (!payload || payload.version !== 1 || payload.from !== config.oldOrigin ||
+      payload.to !== config.newOrigin || !payload.settings ||
+      typeof payload.settings !== 'object' || Array.isArray(payload.settings)) {
+    throw new Error('This settings backup is not for this app move.');
+  }
+  const entries = Object.entries(payload.settings);
+  if (entries.some(([key, value]) => !config.settingsKeys.includes(key) || typeof value !== 'string') ||
+      new TextEncoder().encode(JSON.stringify(payload)).length > MAX_BYTES) {
+    throw new Error('The settings backup contains unsupported or oversized data.');
+  }
+  return entries;
+}
+
+export function importSettings(storage, payload, config) {
+  const entries = validatePayload(payload, config);
+  const written = [];
+  try {
+    for (const [key, value] of entries) {
+      // Keep preferences already set at the destination. Never erase the source.
+      if (storage.getItem(key) === null) {
+        storage.setItem(key, value);
+        written.push(key);
+      }
+    }
+  } catch (error) {
+    for (const key of written) storage.removeItem(key);
+    throw error;
+  }
+  return written.length;
+}
