@@ -0,0 +1,93 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { validateConfig } from '../scripts/migration-config.mjs';
+import { trustedOrigin, exportSettings, importSettings, validatePayload } from '../settings-transfer.js';
+
+const config = {
+  oldOrigin: 'https://old.example.co.uk', newOrigin: 'https://new.example.co.uk',
+  oldId: '/', newId: '/', settingsKeys: ['daily-grind.settings', 'daily-grind.preferences']
+};
+function storage(initial = {}) {
+  const map = new Map(Object.entries(initial));
+  return { getItem: key => map.get(key) ?? null, setItem: (key, value) => map.set(key, value), removeItem: key => map.delete(key) };
+}
+const payload = settings => ({ version: 1, from: config.oldOrigin, to: config.newOrigin, settings });
+
+test('requires distinct HTTPS origins sharing a registrable domain, including private suffixes', () => {
+  assert.equal(validateConfig(config).oldId, `${config.oldOrigin}/`);
+  for (const newOrigin of ['https://other.co.uk', 'http://new.example.co.uk', config.oldOrigin, 'https://new.example.co.uk/route', 'https://user@new.example.co.uk']) {
+    assert.throws(() => validateConfig({ ...config, newOrigin }));
+  }
+  assert.throws(() => validateConfig({ ...config, oldOrigin: 'https://a.github.io', newOrigin: 'https://b.github.io' }));
+  assert.throws(() => validateConfig({ ...config, newId: 'https://attacker.example/' }));
+  assert.throws(() => validateConfig({ ...config, oldId: '/#fragment' }));
+});
+
+test('origin fallback rejects opaque, malformed and lookalike senders, normalizes ports', () => {
+  for (const origin of ['null', 'invalid', 'https://old.example.co.uk.evil.com', config.newOrigin, 'http://old.example.co.uk']) {
+    assert.equal(trustedOrigin({ origin }, config.oldOrigin), false);
+  }
+  assert.equal(trustedOrigin({ origin: 'https://old.example.co.uk:443' }, config.oldOrigin), true);
+});
+
+test('uses native Origin when available', () => {
+  const original = globalThis.Origin;
+  let used = false;
+  globalThis.Origin = { from(value) {
+    used = true;
+    const origin = new URL(typeof value === 'string' ? value : value.origin).origin;
+    return { origin, isSameOrigin: other => origin === other.origin };
+  } };
+  try {
+    assert.equal(trustedOrigin({ origin: config.oldOrigin }, config.oldOrigin), true);
+    assert.equal(used, true);
+  } finally {
+    if (original === undefined) delete globalThis.Origin;
+    else globalThis.Origin = original;
+  }
+});
+
+test('copies only approved settings; preserves source and destination configuration', () => {
+  const source = storage({ 'daily-grind.settings': '{"theme":"dark"}', 'daily-grind.preferences': 'oat', token: 'secret' });
+  const backup = exportSettings(source, config);
+  assert.equal(backup.settings.token, undefined);
+  const target = storage({ 'daily-grind.preferences': 'almond' });
+  assert.equal(importSettings(target, backup, config), 1);
+  assert.equal(target.getItem('daily-grind.settings'), '{"theme":"dark"}');
+  assert.equal(target.getItem('daily-grind.preferences'), 'almond');
+  assert.equal(source.getItem('daily-grind.preferences'), 'oat');
+  assert.equal(importSettings(target, backup, config), 0);
+});
+
+test('rejects malformed, wrong-origin, unapproved and oversized payloads before writing', () => {
+  for (const data of [null, {}, { ...payload({}), from: config.newOrigin }, payload([]), payload({ token: 'secret' }), payload({ 'daily-grind.settings': 123 }), payload({ 'daily-grind.settings': 'x'.repeat(256 * 1024) })]) {
+    assert.throws(() => validatePayload(data, config));
+  }
+});
+
+test('rolls back partial writes when storage quota fails', () => {
+  const target = storage();
+  const set = target.setItem;
+  target.setItem = (key, value) => {
+    if (key === 'daily-grind.preferences') throw new Error('QuotaExceededError');
+    set(key, value);
+  };
+  assert.throws(() => importSettings(target, payload({ 'daily-grind.settings': 'dark', 'daily-grind.preferences': 'oat' }), config));
+  assert.equal(target.getItem('daily-grind.settings'), null);
+});
+
+test('built manifests have reciprocal IDs, discoverable manifests, and old-origin authorization', async () => {
+  const old = JSON.parse(await readFile('dist/old/manifest.webmanifest'));
+  const next = JSON.parse(await readFile('dist/new/manifest.webmanifest'));
+  const authorization = JSON.parse(await readFile('dist/old/.well-known/web-app-origin-association'));
+  const generated = JSON.parse(await readFile('dist/new/migration.config.json'));
+  assert.equal(old.id, generated.oldId);
+  assert.equal(next.id, generated.newId);
+  assert.equal(old.migrate_to.id, next.id);
+  assert.equal(next.migrate_from[0].id, old.id);
+  assert.equal(authorization[next.id].allow_migration, true);
+  for (const role of ['old', 'new']) {
+    assert.match(await readFile(`dist/${role}/index.html`, 'utf8'), /rel="manifest" href="\/manifest.webmanifest"/);
+  }
+});
