+import { cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+import assert from 'node:assert/strict';
+
+const root = fileURLToPath(new URL('../', import.meta.url));
+const args = process.argv.slice(2);
+if (args.length !== 0 && (args.length !== 2 || args[0] !== '--config')) {
+  throw new Error('Usage: npm run build -- [--config migration.config.json]');
+}
+const base = JSON.parse(await readFile(path.join(root, 'manifest.webmanifest'), 'utf8'));
+const html = await readFile(path.join(root, 'index.html'), 'utf8');
+assert(html.includes('href="/manifest.webmanifest"'), 'Page must link its manifest');
+
+function origin(value) {
+  const url = new URL(value);
+  assert(url.protocol === 'https:' && url.href === `${url.origin}/` && !url.username && !url.password,
+    'Use a bare HTTPS origin, without paths, credentials, query strings, or fragments');
+  return url.origin;
+}
+function identity(value, host) {
+  assert(typeof value === 'string' && value.length > 0, 'Manifest IDs must be explicit');
+  const url = new URL(value, host);
+  assert(url.origin === host && !url.hash, 'Manifest ID must belong to its origin and have no fragment');
+  return url.href;
+}
+
+// Validate everything before replacing any build output.
+let config;
+if (args.length) {
+  config = JSON.parse(await readFile(path.resolve(args[1]), 'utf8'));
+  config.oldOrigin = origin(config.oldOrigin);
+  config.newOrigin = origin(config.newOrigin);
+  assert(config.oldOrigin !== config.newOrigin, 'Migration must use different origins');
+  config.oldId = identity(config.oldId, config.oldOrigin);
+  config.newId = identity(config.newId, config.newOrigin);
+}
+const dist = path.join(root, 'dist');
+await rm(dist, { recursive: true, force: true });
+async function bundle(name, manifest) {
+  const directory = path.join(dist, name);
+  await mkdir(directory, { recursive: true });
+  await writeFile(path.join(directory, 'index.html'), html);
+  await cp(path.join(root, 'icons'), path.join(directory, 'icons'), { recursive: true });
+  await writeFile(path.join(directory, 'manifest.webmanifest'), JSON.stringify(manifest, null, 2) + '\n');
+  for (const icon of manifest.icons) {
+    const bytes = await readFile(path.join(directory, icon.src));
+    assert.equal(bytes.subarray(1, 4).toString(), 'PNG');
+    const size = Number(icon.sizes.split('x')[0]);
+    assert.equal(bytes.readUInt32BE(16), size);
+    assert.equal(bytes.readUInt32BE(20), size);
+  }
+  return directory;
+}
+if (!config) {
+  await bundle('current', base);
+  console.log('Built dist/current. Supply --config to build both migration origins.');
+} else {
+  const { oldOrigin, newOrigin, oldId, newId } = config;
+  const oldManifest = { ...base, id: oldId, migrate_to: { id: newId, install_url: `${newOrigin}/` } };
+  const newManifest = { ...base, id: newId, migrate_from: [{ id: oldId, install_url: `${oldOrigin}/`, behavior: 'suggest' }] };
+  await bundle('new', newManifest);
+  const oldDirectory = await bundle('old', oldManifest);
+  const association = { [newId]: { allow_migration: true } };
+  await mkdir(path.join(oldDirectory, '.well-known'), { recursive: true });
+  await writeFile(path.join(oldDirectory, '.well-known/web-app-origin-association'), JSON.stringify(association, null, 2) + '\n');
+  assert.equal(newManifest.migrate_from[0].id, oldManifest.id);
+  assert.equal(oldManifest.migrate_to.id, newManifest.id);
+  assert.equal(association[newManifest.id].allow_migration, true);
+  console.log(`Built and validated dist/old for ${oldOrigin} and dist/new for ${newOrigin}.`);
+}

