+      drawer.classList.remove('is-closing');
+      document.body.style.overflow = previousOverflow;
+      menuButton.setAttribute('aria-expanded', 'false');
+      menuButton.focus();
+    });
+
+    drawer.addEventListener('click', (event) => {
+      const bounds = drawer.getBoundingClientRect();
+      if (event.target === drawer && (event.clientX < bounds.left || event.clientX > bounds.right ||
+          event.clientY < bounds.top || event.clientY > bounds.bottom)) {
+        closeDrawer();
+      }
+      if (event.target.closest('a')) closeDrawer();
+    });
+
+    drawer.addEventListener('pointerdown', (event) => {
+      const bounds = drawer.getBoundingClientRect();
+      if (!event.isPrimary || event.button !== 0 || event.clientX < bounds.left || event.clientX > bounds.right) return;
+      swipeStart = { x: event.clientX, y: event.clientY, id: event.pointerId };
+    });
+    document.addEventListener('pointerup', (event) => {
+      if (!swipeStart || event.pointerId !== swipeStart.id) return;
+      const distanceX = event.clientX - swipeStart.x;
+      const distanceY = Math.abs(event.clientY - swipeStart.y);
+      swipeStart = null;
+      if (distanceX > 60 && distanceX > distanceY * 1.5) closeDrawer();
+    });
+    document.addEventListener('pointercancel', () => { swipeStart = null; });
+  </script>
 </body>

 </html>

