+  <script>
+    (() => {
+      const scene = document.querySelector('.coffee-scene');
+      const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
+      if (!scene || !('IntersectionObserver' in window)) return;
+
+      const layers = Array.from(scene.querySelectorAll('[data-parallax]'));
+      let visible = false;
+      let listening = false;
+      let frame = 0;
+      let sceneCenter = 0;
+      let viewportHeight = window.innerHeight;
+
+      const render = () => {
+        frame = 0;
+        const distance = window.scrollY + viewportHeight / 2 - sceneCenter;
+        layers.forEach((layer) => {
+          const offset = Math.max(-64, Math.min(64, distance * Number(layer.dataset.parallax)));
+          layer.style.transform = `translate3d(0, ${offset}px, 0)`;
+        });
+      };
+
+      const schedule = () => {
+        if (!frame) frame = window.requestAnimationFrame(render);
+      };
+
+      const measure = () => {
+        const bounds = scene.getBoundingClientRect();
+        sceneCenter = bounds.top + window.scrollY + bounds.height / 2;
+        viewportHeight = window.innerHeight;
+        if (listening) schedule();
+      };
+
+      const sync = () => {
+        const shouldListen = visible && !motionPreference.matches && !document.hidden;
+        if (shouldListen === listening) return;
+        listening = shouldListen;
+        scene.classList.toggle('is-moving', listening);
+        if (listening) {
+          measure();
+          window.addEventListener('scroll', schedule, { passive: true });
+        } else {
+          window.removeEventListener('scroll', schedule);
+          window.cancelAnimationFrame(frame);
+          frame = 0;
+          layers.forEach((layer) => layer.style.removeProperty('transform'));
+        }
+      };
+
+      const observer = new IntersectionObserver(([entry]) => {
+        visible = entry.isIntersecting;
+        sync();
+      });
+      observer.observe(scene);
+      window.addEventListener('resize', measure, { passive: true });
+      window.addEventListener('load', measure, { once: true });
+      motionPreference.addEventListener('change', sync);
+      document.addEventListener('visibilitychange', sync);
+      if ('ResizeObserver' in window) new ResizeObserver(measure).observe(document.body);
+    })();
+  </script>
