index 0000000..9995d02
--- /dev/null
+++ b/tests/passkeys.test.mjs
@@ -0,0 +1,117 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createDemoRepository, createApiRepository, syncAuthenticator, validateSnapshot, validateName } from '../passkeys.mjs';
+
+const liveSnapshot = () => ({ authenticated: true, complete: true, rpId: 'coffee.example', userId: 'dXNlcg', hasAlternativeSignIn: true, passkeys: [
+  { id: 'key-1', credentialId: 'Y3JlZDE', name: 'Laptop', provider: 'Password manager' },
+  { id: 'key-2', credentialId: 'Y3JlZDI', name: 'Phone', provider: 'Password manager' },
+] });
+const memoryStorage = () => {
+  const values = new Map();
+  return { getItem: key => values.get(key) ?? null, setItem: (key, value) => values.set(key, value) };
+};
+
+test('demo renames persist, deletion persists through an empty list, reset restores samples', async () => {
+  const storage = memoryStorage();
+  const repository = createDemoRepository(storage);
+  let state = await repository.list();
+  const id = state.passkeys[0].id;
+  await repository.rename(id, '  My laptop  ');
+  assert.equal((await createDemoRepository(storage).list()).passkeys[0].name, 'My laptop');
+  for (const key of state.passkeys) state = await repository.remove(key.id);
+  assert.equal(state.passkeys.length, 0);
+  assert.equal((await createDemoRepository(storage).list()).passkeys.length, 0);
+  assert.equal((await repository.reset()).passkeys.length, 3);
+});
+
+test('invalid and missing names are rejected, while text labels remain plain data', () => {
+  for (const name of ['', '   ', 'x'.repeat(51), 'bad\nname']) assert.throws(() => validateName(name));
+  assert.equal(validateName('<script>alert(1)</script>'), '<script>alert(1)</script>');
+});
+
+test('storage failures do not report a successful mutation or remove a passkey', async () => {
+  const repository = createDemoRepository({ getItem() { throw new Error(); }, setItem() { throw new Error(); } });
+  const before = await repository.list();
+  await assert.rejects(repository.remove(before.passkeys[0].id), /couldn’t save/);
+  assert.deepEqual((await repository.list()).passkeys, before.passkeys);
+});
+
+test('only authenticated complete snapshots can reach an authenticator', async () => {
+  let calls = 0;
+  const api = { async signalAllAcceptedCredentials() { calls++; } };
+  const snapshot = liveSnapshot();
+  for (const change of [{ complete: false }, { authenticated: false }, { userId: '' }, { passkeys: [{ id: '1', credentialId: 'not valid', name: 'Bad', provider: 'Bad' }] }]) {
+    await assert.rejects(syncAuthenticator({ ...snapshot, ...change }, api, true));
+  }
+  assert.throws(() => validateSnapshot({ ...snapshot, passkeys: [snapshot.passkeys[0], snapshot.passkeys[0]] }));
+  assert.equal(calls, 0);
+});
+
+test('demo credentials never reach browser authenticator APIs', async () => {
+  const repository = createDemoRepository(memoryStorage());
+  const snapshot = await repository.list();
+  const api = { signalAllAcceptedCredentials() { assert.fail('demo must never signal'); } };
+  assert.equal(await syncAuthenticator(snapshot, api, true), 'demo');
+});
+
+test('live sync sends exactly the server-authoritative remaining credentials, including none', async () => {
+  const snapshot = liveSnapshot();
+  snapshot.passkeys.shift();
+  const received = [];
+  const api = { async signalAllAcceptedCredentials(options) { received.push(options); } };
+  assert.equal(await syncAuthenticator(snapshot, api, true), 'sent');
+  assert.deepEqual(received[0], { rpId: 'coffee.example', userId: 'dXNlcg', allAcceptedCredentialIds: ['Y3JlZDI'] });
+  snapshot.passkeys = [];
+  await syncAuthenticator(snapshot, api, true);
+  assert.deepEqual(received[1].allAcceptedCredentialIds, []);
+});
+
+test('unsupported browsers and provider failures are reported without undoing account changes', async () => {
+  const snapshot = liveSnapshot();
+  assert.equal(await syncAuthenticator(snapshot, {}, true), 'unsupported');
+  assert.equal(await syncAuthenticator(snapshot, {}, false), 'unsupported');
+  assert.equal(await syncAuthenticator(snapshot, { async signalAllAcceptedCredentials() { throw new Error('provider unavailable'); } }, true), 'failed');
+  assert.equal(snapshot.passkeys.length, 2);
+});
+
+test('API adapter uses authenticated requests, CSRF protection, and authoritative mutation responses', async () => {
+  globalThis.location = { origin: 'https://coffee.example' };
+  const calls = [];
+  let snapshot = liveSnapshot();
+  const repository = createApiRepository('/api/account/passkeys', 'test-token', async (url, options) => {
+    calls.push({ url, options });
+    if (options.method === 'DELETE') snapshot = { ...snapshot, passkeys: snapshot.passkeys.filter(k => k.id !== 'key-1') };
+    if (options.method === 'PATCH') snapshot = { ...snapshot, passkeys: snapshot.passkeys.map(k => k.id === 'key-2' ? { ...k, name: JSON.parse(options.body).name } : k) };
+    return { ok: true, status: 200, json: async () => snapshot };
+  });
+  const initial = await repository.list();
+  assert.equal(initial.demo, false);
+  const renamed = await repository.rename('key-2', ' My phone ');
+  assert.equal(renamed.passkeys[1].name, 'My phone');
+  const removed = await repository.remove('key-1');
+  assert.equal(removed.passkeys.length, 1);
+  assert.equal(calls[2].url, '/api/account/passkeys/key-1');
+  assert.equal(calls[2].options.method, 'DELETE');
+  assert.equal(calls[2].options.credentials, 'same-origin');
+  assert.equal(calls[2].options.headers['X-CSRF-Token'], 'test-token');
+  assert.equal(calls[2].options.cache, 'no-store');
+  assert.equal(calls[2].options.redirect, 'error');
+});
+
+test('cross-origin APIs, missing CSRF, expired sessions and server lockout protection fail closed', async () => {
+  globalThis.location = { origin: 'https://coffee.example' };
+  assert.throws(() => createApiRepository('https://other.example/keys', 'token'), /same-origin/);
+  const noCSRF = createApiRepository('/keys', '', () => assert.fail('must reject before sending'));
+  await assert.rejects(noCSRF.remove('key'), /token/);
+  for (const [status, message] of [[401, /session has expired/], [403, /authorize/], [409, /only sign-in/], [500, /couldn’t save/]]) {
+    const repository = createApiRepository('/keys', 'token', async () => ({ ok: false, status }));
+    await assert.rejects(repository.remove('key'), message);
+  }
+});
+
+test('mutation success is not reported if the server snapshot does not confirm the change', async () => {
+  globalThis.location = { origin: 'https://coffee.example' };
+  const repository = createApiRepository('/keys', 'token', async () => ({ ok: true, status: 200, json: async () => liveSnapshot() }));
+  await assert.rejects(repository.remove('key-1'), /wasn’t confirmed/);
+  await assert.rejects(repository.rename('key-1', 'Changed'), /wasn’t confirmed/);
+});

