@@ -0,0 +1,170 @@
+import { useEffect, useRef, useState } from 'react';
+import { KeyIcon, ShieldCheckIcon } from '@heroicons/react/24/outline';
+import providers from '../data/passkey-providers.json';
+import { isPasskeyList, syncPasskeys, type PasskeyList } from '../lib/passkeys';
+
+const endpoint = `${import.meta.env.BASE_URL}api/account/passkeys`;
+const button = 'rounded border border-gray-300 px-3 py-2 text-sm font-semibold hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-900 disabled:opacity-50 disabled:cursor-wait';
+
+async function request(url: string, init?: RequestInit) {
+  const response = await fetch(url, { ...init, cache: 'no-store' });
+  const data = await response.json();
+  if (!response.ok) throw new Error(response.status === 401
+    ? 'Your session has expired. Please sign in again.'
+    : data.error || 'Unable to complete this request. Please try again.');
+  return data;
+}
+
+function date(value?: number | null) {
+  if (value == null) return 'Not used yet';
+  const parsed = new Date(value);
+  return Number.isNaN(parsed.getTime()) ? 'Unavailable' : parsed.toLocaleDateString(undefined, {
+    year: 'numeric', month: 'short', day: 'numeric',
+  });
+}
+
+export default function PasskeySettings() {
+  const [data, setData] = useState<PasskeyList | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState('');
+  const [notice, setNotice] = useState('');
+  const [sync, setSync] = useState('');
+  const [editing, setEditing] = useState<string | null>(null);
+  const [removing, setRemoving] = useState<string | null>(null);
+  const [name, setName] = useState('');
+  const listHeading = useRef<HTMLHeadingElement>(null);
+
+  async function refresh() {
+    const next = await request(endpoint);
+    if (!isPasskeyList(next)) throw new Error('The account service returned invalid passkey data.');
+    setData(next);
+    // Passive sync must never block management or turn a successful change into an error.
+    void syncPasskeys(next).then(result => setSync(result === 'sent'
+      ? 'Your browser has been notified of your current passkeys.'
+      : 'You may need to remove unused passkeys from your password manager manually.'));
+  }
+
+  useEffect(() => {
+    let active = true;
+    // Do not signal an abandoned page's potentially stale credential list.
+    request(endpoint).then(next => {
+      if (!active) return;
+      if (!isPasskeyList(next)) throw new Error('The account service returned invalid passkey data.');
+      setData(next);
+      void syncPasskeys(next).then(result => {
+        if (active) setSync(result === 'sent'
+          ? 'Your browser has been notified of your current passkeys.'
+          : 'You may need to remove unused passkeys from your password manager manually.');
+      });
+    }).catch(err => { if (active) setError(err.message); })
+      .finally(() => { if (active) setLoading(false); });
+    return () => { active = false; };
+  }, []);
+
+  async function change(id: string, method: 'PUT' | 'DELETE') {
+    setBusy(true);
+    setError('');
+    setNotice('');
+    try {
+      await request(`${endpoint}/${encodeURIComponent(id)}`, {
+        method, headers: { 'Content-Type': 'application/json' },
+        ...(method === 'PUT' ? { body: JSON.stringify({ name: name.trim() }) } : {}),
+      });
+      setEditing(null);
+      setRemoving(null);
+      setNotice(method === 'PUT' ? 'Passkey display name updated.' : 'Passkey removed. It can no longer be used to sign in.');
+      // Hide stale records even if the authoritative refetch fails after a successful mutation.
+      setData(null);
+      try { await refresh(); } catch {
+        setError('Your change was saved, but the list could not be refreshed. Retry to update the list and browser sync.');
+      }
+      listHeading.current?.focus();
+    } catch (err) {
+      setError(err instanceof Error ? err.message : 'Unable to update this passkey.');
+    } finally { setBusy(false); }
+  }
+
+  async function retry() {
+    setLoading(true);
+    setError('');
+    try { await refresh(); } catch (err) {
+      setError(err instanceof Error ? err.message : 'Unable to load passkeys.');
+    } finally { setLoading(false); }
+  }
+
+  return <section aria-labelledby="passkeys-title" className="border border-gray-200 rounded-lg bg-white">
+    <div className="p-6 sm:p-8 border-b border-gray-200">
+      <div className="flex items-center gap-3 mb-3">
+        <KeyIcon className="size-6" aria-hidden="true" />
+        <h2 id="passkeys-title" ref={listHeading} tabIndex={-1} className="text-2xl font-bold">Passkeys</h2>
+      </div>
+      <p className="text-gray-600 max-w-2xl">Manage the passkeys you use to sign in to The DevTools Times. Give them memorable names or remove ones you no longer use.</p>
+    </div>
+    <div className="p-6 sm:p-8" aria-busy={loading || busy}>
+      <div role="status" className="text-sm text-green-800">{notice}</div>
+      {error && <div role="alert" className="mb-4 rounded bg-red-50 p-4 text-sm text-red-800">
+        <p>{error}</p>
+        <div className="flex gap-4 mt-3">
+          <button className={button} disabled={busy || loading} onClick={retry}>Retry</button>
+          <a className="underline self-center" href={`${import.meta.env.BASE_URL}signin`}>Sign in</a>
+        </div>
+      </div>}
+      {loading && <p role="status" className="text-gray-600">Loading your passkeys…</p>}
+      {data && <>
+        <p className="text-xs uppercase tracking-wider font-semibold text-gray-500 mb-4 mt-3">{data.credentials.length} registered {data.credentials.length === 1 ? 'passkey' : 'passkeys'}</p>
+        {data.credentials.length === 0 ? <div className="py-8 text-center bg-gray-50 rounded">
+          <KeyIcon aria-hidden="true" className="size-8 mx-auto mb-3 text-gray-400" />
+          <h3 className="font-semibold">No passkeys registered</h3>
