+        </div> : <ul className="divide-y divide-gray-200">
+          {data.credentials.map(key => {
+            const provider = key.aaguid && key.aaguid !== '00000000-0000-0000-0000-000000000000'
+              ? (providers as Record<string, { name: string; icon_light?: string }>)[key.aaguid.toLowerCase()] : undefined;
+            const label = key.name || provider?.name || 'Passkey';
+            return <li key={key.id} className="py-5 first:pt-0">
+              <div className="flex flex-wrap items-start gap-4">
+                <div className="bg-gray-100 rounded-lg p-3 shrink-0">
+                  {provider?.icon_light ? <img src={provider.icon_light} alt="" width={24} height={24} /> : <KeyIcon className="size-6 text-gray-600" aria-hidden="true" />}
+                </div>
+                <div className="flex-1 min-w-0">
+                  <h3 className="font-semibold break-words">{label}</h3>
+                  <p className="text-sm text-gray-500">{provider?.name || 'Unknown passkey provider'}</p>
+                  <dl className="text-xs text-gray-600 flex flex-wrap gap-x-5 gap-y-1 mt-2">
+                    <div><dt className="inline">Added: </dt><dd className="inline">{date(key.registeredAt)}</dd></div>
+                    <div><dt className="inline">Last used: </dt><dd className="inline">{date(key.lastUsedAt)}</dd></div>
+                  </dl>
+                </div>
+                <div className="flex gap-2">
+                  <button className={button} disabled={busy || loading} aria-label={`Rename ${label}`} onClick={() => { setEditing(key.id); setRemoving(null); setName(label); }}>Rename</button>
+                  <button className={`${button} text-red-700`} disabled={busy || loading} aria-label={`Remove ${label}`} onClick={() => { setRemoving(key.id); setEditing(null); }}>Remove</button>
+                </div>
+              </div>
+              {editing === key.id && <form className="mt-4 rounded bg-gray-50 p-4" onSubmit={event => { event.preventDefault(); void change(key.id, 'PUT'); }}>
+                <label htmlFor={`name-${key.id}`} className="block text-sm font-medium mb-2">Passkey display name</label>
+                <input id={`name-${key.id}`} autoFocus required maxLength={80} value={name} disabled={busy || loading} onChange={event => setName(event.target.value)} className="w-full rounded border border-gray-300 bg-white px-3 py-2 focus-visible:outline-2" />
+                <p className="mt-2 text-xs text-gray-500">This label is only used in your account settings.</p>
+                <div className="flex gap-2 mt-3">
+                  <button className={`${button} bg-gray-900 text-white hover:bg-gray-700`} disabled={busy || loading || !name.trim()} type="submit">{busy ? 'Saving…' : 'Save name'}</button>
+                  <button className={button} disabled={busy || loading} type="button" onClick={() => setEditing(null)}>Cancel</button>
+                </div>
+              </form>}
+              {removing === key.id && <div className="mt-4 rounded border border-red-200 bg-red-50 p-4">
+                <p className="text-sm font-semibold">Remove “{label}”?</p>
+                <p className="text-sm text-gray-700 mt-1">You will no longer be able to sign in with this passkey. Make sure you can use your password or another passkey before removing it.</p>
+                <div className="flex gap-2 mt-3">
+                  <button autoFocus className={button} disabled={busy || loading} onClick={() => setRemoving(null)}>Keep passkey</button>
+                  <button className={`${button} bg-red-700 text-white hover:bg-red-800`} disabled={busy || loading} onClick={() => change(key.id, 'DELETE')}>{busy ? 'Removing…' : 'Remove passkey'}</button>
+                </div>
+              </div>}
+            </li>;
+          })}
+        </ul>}
+      </>}
+    </div>
+    <div className="flex gap-3 border-t border-gray-200 bg-gray-50 p-6 sm:px-8 rounded-b-lg text-sm text-gray-600">
+      <ShieldCheckIcon aria-hidden="true" className="size-5 shrink-0" />
+      <p>{sync || 'Supported browsers can keep your saved passkeys in sync when you remove a key.'}</p>
+    </div>
+  </section>;
+}
