+import type { APIContext } from 'astro';
+
+export interface AccountSession { token: string; username: string }
+
+export function json(data: unknown, status = 200) {
+  return Response.json(data, { status, headers: { 'Cache-Control': 'no-store' } });
+}
+
+export function sameOrigin(request: Request) {
+  return request.headers.get('Origin') === new URL(request.url).origin;
+}
+
+export async function accountSession(context: Pick<APIContext, 'session'>): Promise<AccountSession | undefined> {
+  return await context.session?.get('account') as AccountSession | undefined;
+}
+
+// The same identity service used for reader registration and sign-in.
+export function identityFetch(path: string, init: RequestInit = {}) {
+  const base = import.meta.env.IDENTITY_API_URL ||
+    'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+  return fetch(`${base.replace(/\/$/, '')}/${path}`, {
+    ...init, redirect: 'error', signal: AbortSignal.timeout(15000),
+    headers: { 'Content-Type': 'application/json', ...init.headers },
+  });
+}
+
+export async function requireAccount(context: APIContext) {
+  const account = await accountSession(context);
+  if (!account) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+  if (context.request.method !== 'GET' && !sameOrigin(context.request)) {
+    return json({ error: 'This request must come from this site.' }, 403);
+  }
+  return account;
+}
+
+export async function upstreamError(response: Response, context: APIContext) {
+  if (response.status === 401 || response.status === 403) {
+    await context.session?.delete('account');
+    return json({ error: 'Your session has expired. Please sign in again.' }, 401);
+  }
+  if (response.status === 404) return json({ error: 'Passkey not found. Refresh the list and try again.' }, 404);
+  return json({ error: 'The account service could not complete this request. Please try again.' }, 502);
+}
