+++ b/src/lib/passkeys.ts
@@ -0,0 +1,55 @@
+export interface Passkey {
+  id: string;
+  name: string;
+  aaguid?: string;
+  registeredAt: number;
+  lastUsedAt?: number | null;
+}
+
+export interface PasskeyList {
+  rpId: string;
+  userId: string;
+  credentials: Passkey[];
+}
+
+export function isBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 &&
+    value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+export function isPasskeyList(value: unknown): value is PasskeyList {
+  if (!value || typeof value !== 'object') return false;
+  const data = value as PasskeyList;
+  return typeof data.rpId === 'string' && data.rpId.length > 0 &&
+    isBase64Url(data.userId) && Array.isArray(data.credentials) &&
+    data.credentials.every(key => key && isBase64Url(key.id) &&
+      typeof key.name === 'string' && Number.isFinite(key.registeredAt) &&
+      (key.lastUsedAt == null || Number.isFinite(key.lastUsedAt)));
+}
+
+type SignalAPI = {
+  signalAllAcceptedCredentials?: (options: {
+    rpId: string; userId: string; allAcceptedCredentialIds: string[];
+  }) => Promise<void>;
+};
+
+export async function syncPasskeys(data: PasskeyList): Promise<'sent' | 'unsupported' | 'failed'> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) return 'unsupported';
+  const api = window.PublicKeyCredential as unknown as SignalAPI;
+  if (!api.signalAllAcceptedCredentials) return 'unsupported';
+  if (!isPasskeyList(data)) {
+    console.warn('Passkey synchronization skipped: invalid server credential data.');
+    return 'failed';
+  }
+  try {
+    await api.signalAllAcceptedCredentials({
+      rpId: data.rpId,
+      userId: data.userId,
+      allAcceptedCredentialIds: data.credentials.map(key => key.id),
+    });
+    return 'sent';
+  } catch {
+    console.warn('The browser could not synchronize passkeys.');
+    return 'failed';
+  }
+}
