+++ b/src/pages/api/account/passkeys/[id].ts
@@ -0,0 +1,36 @@
+import type { APIRoute } from 'astro';
+import { identityFetch, json, requireAccount, upstreamError } from '../../../../lib/account-server';
+import { isBase64Url, isPasskeyList } from '../../../../lib/passkeys';
+
+const mutate: APIRoute = async context => {
+  const account = await requireAccount(context);
+  if (account instanceof Response) return account;
+  const id = context.params.id;
+  if (!isBase64Url(id)) return json({ error: 'Invalid passkey ID.' }, 400);
+  let name: string | undefined;
+  if (context.request.method === 'PUT') {
+    try {
+      const body = await context.request.json();
+      name = typeof body?.name === 'string' ? body.name.trim() : '';
+      if (!name || name.length > 80) return json({ error: 'Use a display name between 1 and 80 characters.' }, 400);
+    } catch { return json({ error: 'Invalid request.' }, 400); }
+  }
+  try {
+    const headers = { Authorization: `Bearer ${account.token}` };
+    // Check ownership using the service's authenticated account list, never client-supplied user IDs.
+    const listResponse = await identityFetch('credentials', { headers });
+    if (!listResponse.ok) return upstreamError(listResponse, context);
+    const list = await listResponse.json();
+    if (!isPasskeyList(list)) return json({ error: 'The account service returned invalid passkey data.' }, 502);
+    if (!list.credentials.some(key => key.id === id)) return json({ error: 'Passkey not found.' }, 404);
+    const response = await identityFetch(`credential/${encodeURIComponent(id)}`, {
+      method: context.request.method, headers,
+      ...(name !== undefined ? { body: JSON.stringify({ name }) } : {}),
+    });
+    if (!response.ok) return upstreamError(response, context);
+    return json({ success: true });
+  } catch { return json({ error: 'Unable to update this passkey. Please try again.' }, 502); }
+};
+
+export const PUT = mutate;
+export const DELETE = mutate;
