@@ -0,0 +1,19 @@
+import type { APIRoute } from 'astro';
+import { identityFetch, json, requireAccount, upstreamError } from '../../../../lib/account-server';
+import { isPasskeyList } from '../../../../lib/passkeys';
+
+export const GET: APIRoute = async context => {
+  const account = await requireAccount(context);
+  if (account instanceof Response) return account;
+  try {
+    const response = await identityFetch('credentials', { headers: { Authorization: `Bearer ${account.token}` } });
+    if (!response.ok) return upstreamError(response, context);
+    const data = await response.json();
+    if (!isPasskeyList(data)) return json({ error: 'The account service returned invalid passkey data.' }, 502);
+    // Never expose public keys, counters, or other authentication internals.
+    return json({ rpId: data.rpId, userId: data.userId, credentials: data.credentials.map(key => ({
+      id: key.id, name: key.name, aaguid: typeof key.aaguid === 'string' ? key.aaguid : undefined,
+      registeredAt: key.registeredAt, lastUsedAt: key.lastUsedAt,
+    })) });
+  } catch { return json({ error: 'Unable to load passkeys. Please try again.' }, 502); }
+};
