@@ -0,0 +1,28 @@
+import type { APIRoute } from 'astro';
+import { identityFetch, json, sameOrigin } from '../../../lib/account-server';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!sameOrigin(request)) return json({ error: 'Invalid request origin.' }, 403);
+  if (!session) return json({ error: 'Account sessions are unavailable.' }, 503);
+  let body;
+  try { body = await request.json(); } catch { return json({ error: 'Invalid request.' }, 400); }
+  const { username, password } = body ?? {};
+  if (typeof username !== 'string' || !username.trim() || typeof password !== 'string' || !password) {
+    return json({ error: 'Enter your username and password.' }, 400);
+  }
+  try {
+    const response = await identityFetch('login', {
+      method: 'POST', body: JSON.stringify({ username, password }),
+    });
+    if (!response.ok) return json({ error: 'Sign-in failed. Check your username and password.' }, response.status === 429 ? 429 : 401);
+    const data = await response.json();
+    if (typeof data.token !== 'string' || !data.token) {
+      return json({ error: 'The identity service did not return an account session.' }, 502);
+    }
+    await session.regenerate();
+    await session.set('account', { token: data.token, username });
+    return json({ success: true });
+  } catch {
+    return json({ error: 'The sign-in service is unavailable. Please try again.' }, 502);
+  }
+};
