+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { GET } from '../src/pages/api/account/passkeys/index';
+import { PUT, DELETE } from '../src/pages/api/account/passkeys/[id]';
+import { POST as signIn } from '../src/pages/api/account/signin';
+
+const list = { rpId: 'example.com', userId: 'dXNlci0x', credentials: [
+  { id: 'Y3JlZC0x', name: 'Laptop', registeredAt: 1700000000000, publicKey: 'private-internals' },
+] };
+function context(method = 'GET', signedIn = true, origin = 'https://news.example.com', name = 'New name') {
+  return {
+    request: new Request('https://news.example.com/api/account/passkeys/Y3JlZC0x', {
+      method, headers: { Origin: origin, 'Content-Type': 'application/json' },
+      ...(method === 'PUT' ? { body: JSON.stringify({ name }) } : {}),
+    }),
+    params: { id: 'Y3JlZC0x' },
+    session: { get: async () => signedIn ? { token: 'secret-token', username: 'reader' } : undefined, delete: async () => {} },
+  } as any;
+}
+
+test('requires sign-in and rejects cross-origin mutations before upstream access', async () => {
+  assert.equal((await GET(context('GET', false))).status, 401);
+  assert.equal((await DELETE(context('DELETE', true, 'https://attacker.example'))).status, 403);
