@@ -0,0 +1,209 @@
+import express from 'express';
+import { DatabaseSync } from 'node:sqlite';
+import { randomBytes } from 'node:crypto';
+import { mkdirSync } from 'node:fs';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const port = Number(process.env.PORT || 11222);
+const origin = new URL(process.env.APP_ORIGIN || `http://localhost:${port}`).origin;
+const rpID = process.env.RP_ID || new URL(origin).hostname;
+const secure = origin.startsWith('https:');
+if (process.env.NODE_ENV === 'production' && !secure) throw new Error('Set APP_ORIGIN to your public HTTPS origin in production.');
+const dataDir = process.env.DATA_DIR || join(root, 'data');
+mkdirSync(dataDir, { recursive: true, mode: 0o700 });
+const db = new DatabaseSync(join(dataDir, 'accounts.sqlite'));
+db.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
+CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, displayName TEXT NOT NULL);
+CREATE TABLE IF NOT EXISTS credentials (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), publicKey TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, name TEXT NOT NULL, aaguid TEXT, deviceType TEXT, backedUp INTEGER, registeredAt INTEGER NOT NULL, lastUsedAt INTEGER);`);
+const sessions = new Map();
+const rates = new Map();
+const app = express();
+app.disable('x-powered-by');
+app.use(express.json({ limit: '32kb' }));
+app.use((req, res, next) => {
+  res.set({ 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'strict-origin-when-cross-origin', 'Permissions-Policy': 'publickey-credentials-create=(self), publickey-credentials-get=(self)', 'Content-Security-Policy': "default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https://images.unsplash.com; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" });
+  if (secure) res.set('Strict-Transport-Security', 'max-age=31536000');
+  next();
+});
+const fail = (status, message) => Object.assign(new Error(message), { status });
+const token = () => randomBytes(32).toString('base64url');
+const list = userId => db.prepare('SELECT * FROM credentials WHERE userId = ? ORDER BY registeredAt DESC').all(userId);
+const findUser = id => db.prepare('SELECT * FROM users WHERE id = ?').get(id);
+function snapshot(user) {
+  return { user, rpId: rpID, userId: user.id, credentials: list(user.id).map(({ publicKey, counter, transports, ...credential }) => ({ ...credential, transports: JSON.parse(transports), backedUp: Boolean(credential.backedUp) })) };
+}
+function setCookie(res, id) {
+  res.cookie('dg_session', id, { httpOnly: true, sameSite: 'strict', secure, path: '/', maxAge: 8 * 60 * 60 * 1000 });
+}
+function rotate(req, res, userId) {
+  sessions.delete(req.sessionId);
+  const id = token();
+  const session = { userId, expires: Date.now() + 8 * 60 * 60 * 1000, verifiedAt: 0 };
+  sessions.set(id, session);
+  setCookie(res, id);
+  req.session = session;
+  req.sessionId = id;
+}
+app.use('/api', (req, res, next) => {
+  res.set('Cache-Control', 'no-store');
+  // Reject cross-origin mutation, including requests without a browser Origin.
+  if (req.method !== 'GET' && req.headers.origin !== origin) return next(fail(403, 'This request must come from the Daily Grind website.'));
+  const now = Date.now();
+  const rateKey = req.socket.remoteAddress;
+  const rate = rates.get(rateKey) || { start: now, count: 0 };
+  if (now - rate.start > 60000) { rate.start = now; rate.count = 0; }
+  rates.set(rateKey, rate);
+  if (++rate.count > 100) return next(fail(429, 'Too many requests. Please try again in a minute.'));
+  const id = req.headers.cookie?.split(';').map(part => part.trim()).find(part => part.startsWith('dg_session='))?.slice(11);
+  let session = sessions.get(id);
+  if (session && session.expires <= now) { sessions.delete(id); session = null; }
+  if (!session) {
+    const sessionId = token();
+    session = { expires: now + 8 * 60 * 60 * 1000 };
+    sessions.set(sessionId, session);
+    setCookie(res, sessionId);
+    req.sessionId = sessionId;
+  } else req.sessionId = id;
+  req.session = session;
+  next();
+});
+function requireUser(req) {
+  const user = req.session.userId && findUser(req.session.userId);
+  if (!user) throw fail(401, 'Please sign in to continue.');
+  return user;
+}
+function requireRecent(req) {
+  requireUser(req);
+  if (!req.session.verifiedAt || Date.now() - req.session.verifiedAt > 120000) throw fail(403, 'Please verify your identity again to continue.');
+}
+function remember(req, challenge) {
+  const pending = req.session.challenges ||= new Map();
+  for (const [key, value] of pending) if (value.expires < Date.now()) pending.delete(key);
+  // Keep autofill and explicit ceremonies separate, bounded to avoid unbounded storage.
+  if (pending.size >= 10) pending.delete(pending.keys().next().value);
+  pending.set(challenge.value, challenge);
+}
+function consume(req, purpose) {
+  let value;
+  try {
+    const data = JSON.parse(Buffer.from(req.body.response.clientDataJSON, 'base64url').toString('utf8'));
+    value = data.challenge;
+  } catch { throw fail(400, 'Invalid passkey response. Please try again.'); }
+  const challenge = req.session.challenges?.get(value);
+  req.session.challenges?.delete(value);
+  if (!challenge || challenge.purpose !== purpose || challenge.expires < Date.now()) throw fail(400, 'This passkey request expired. Please try again.');
+  return challenge;
+}
+function profile(body) {
+  const displayName = typeof body.displayName === 'string' ? body.displayName.trim() : '';
+  const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
+  if (!displayName || displayName.length > 80 || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw fail(400, 'Enter your name and a valid email address.');
+  return { displayName, email };
+}
+app.get('/api/session', (req, res) => {
+  const user = req.session.userId && findUser(req.session.userId);
+  res.json(user ? snapshot(user) : { user: null });
+});
+app.post('/api/register/options', async (req, res) => {
+  const adding = Boolean(req.session.userId);
+  if (adding) requireRecent(req);
+  const user = adding ? requireUser(req) : { id: token(), ...profile(req.body) };
+  if (!adding && db.prepare('SELECT id FROM users WHERE email = ?').get(user.email)) throw fail(409, 'An account with this email already exists. Sign in with your saved passkey.');
+  const options = await generateRegistrationOptions({ rpName: 'The Daily Grind', rpID, userID: Buffer.from(user.id, 'base64url'), userName: user.email, userDisplayName: user.displayName, attestationType: 'none', authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required' }, excludeCredentials: adding ? list(user.id).map(c => ({ id: c.id, transports: JSON.parse(c.transports) })) : [] });
+  remember(req, { purpose: 'register', value: options.challenge, user, adding, expires: Date.now() + 300000 });
+  res.json(options);
+});
+app.post('/api/register/verify', async (req, res) => {
+  const challenge = consume(req, 'register');
+  if (challenge.adding) { requireRecent(req); if (req.session.userId !== challenge.user.id) throw fail(403, 'Account changed. Please try again.'); }
+  const result = await verifyRegistrationResponse({ response: req.body, expectedChallenge: challenge.value, expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true });
+  if (!result.verified || !result.registrationInfo) throw fail(400, 'We couldn’t verify this passkey. Please try again.');
+  const { credential, aaguid, credentialDeviceType, credentialBackedUp } = result.registrationInfo;
+  const user = challenge.user;
+  db.exec('BEGIN IMMEDIATE');
+  try {
+    if (!challenge.adding) db.prepare('INSERT INTO users (id, email, displayName) VALUES (?, ?, ?)').run(user.id, user.email, user.displayName);
+    db.prepare('INSERT INTO credentials (id,userId,publicKey,counter,transports,name,aaguid,deviceType,backedUp,registeredAt) VALUES (?,?,?,?,?,?,?,?,?,?)').run(credential.id, user.id, Buffer.from(credential.publicKey).toString('base64url'), credential.counter, JSON.stringify(credential.transports || []), 'My passkey', aaguid, credentialDeviceType, Number(credentialBackedUp), Date.now());
+    db.exec('COMMIT');
+  } catch (error) { db.exec('ROLLBACK'); if (error.code?.startsWith('ERR_SQLITE')) throw fail(409, 'That account or passkey already exists. Please sign in or try another passkey.'); throw error; }
+  rotate(req, res, user.id);
+  res.json(snapshot(user));
+});
+for (const purpose of ['login', 'reauth']) {
+  app.post(`/api/${purpose}/options`, async (req, res) => {
+    const user = purpose === 'reauth' ? requireUser(req) : null;
+    const credentials = user ? list(user.id) : [];
+    if (user && !credentials.length) throw fail(400, 'There are no passkeys available for this account.');
+    const options = await generateAuthenticationOptions({ rpID, userVerification: 'required', allowCredentials: credentials.map(c => ({ id: c.id, transports: JSON.parse(c.transports) })) });
+    remember(req, { purpose, value: options.challenge, userId: user?.id, expires: Date.now() + 300000 });
+    res.json(options);
+  });
+  app.post(`/api/${purpose}/verify`, async (req, res) => {
+    const challenge = consume(req, purpose);
+    const currentUser = purpose === 'reauth' ? requireUser(req) : null;
+    const credential = db.prepare('SELECT * FROM credentials WHERE id = ?').get(typeof req.body.id === 'string' ? req.body.id : '');
+    if (!credential) throw fail(404, 'This passkey is no longer registered. Please choose another passkey.');
+    if (currentUser && (credential.userId !== currentUser.id || challenge.userId !== currentUser.id)) throw fail(403, 'Use a passkey belonging to your signed-in account.');
+    const userHandle = req.body.response?.userHandle;
+    if (userHandle && userHandle !== credential.userId) throw fail(403, 'This passkey does not match the account.');
+    const result = await verifyAuthenticationResponse({ response: req.body, expectedChallenge: challenge.value, expectedOrigin: origin, expectedRPID: rpID, credential: { id: credential.id, publicKey: Buffer.from(credential.publicKey, 'base64url'), counter: credential.counter, transports: JSON.parse(credential.transports) }, requireUserVerification: true });
+    if (!result.verified) throw fail(400, 'We couldn’t verify your identity. Please try again.');
+    // Conditional update prevents concurrent requests from rolling the signature counter back.
+    const update = db.prepare('UPDATE credentials SET counter = ?, lastUsedAt = ? WHERE id = ? AND counter = ?').run(result.authenticationInfo.newCounter, Date.now(), credential.id, credential.counter);
+    if (!update.changes) throw fail(409, 'Your passkey changed during sign-in. Please try again.');
+    if (purpose === 'login') rotate(req, res, credential.userId);
+    else req.session.verifiedAt = Date.now();
+    res.json(snapshot(findUser(credential.userId)));
+  });
+}
+app.put('/api/profile', (req, res) => {
+  requireRecent(req);
+  const user = requireUser(req);
+  const updated = profile(req.body);
+  const existing = db.prepare('SELECT id FROM users WHERE email = ? AND id != ?').get(updated.email, user.id);
+  if (existing) throw fail(409, 'That email is already associated with another account.');
+  db.prepare('UPDATE users SET email = ?, displayName = ? WHERE id = ?').run(updated.email, updated.displayName, user.id);
+  req.session.verifiedAt = 0;
+  res.json(snapshot(findUser(user.id)));
+});
+app.put('/api/credentials/:id', (req, res) => {
+  const user = requireUser(req);
+  const name = typeof req.body.name === 'string' ? req.body.name.trim() : '';
+  if (!name || name.length > 80) throw fail(400, 'Give your passkey a name of 1–80 characters.');
+  const result = db.prepare('UPDATE credentials SET name = ? WHERE id = ? AND userId = ?').run(name, req.params.id, user.id);
+  if (!result.changes) throw fail(404, 'Passkey not found.');
+  res.json(snapshot(user));
+});
+app.delete('/api/credentials/:id', (req, res) => {
+  requireRecent(req);
+  const user = requireUser(req);
+  if (list(user.id).length <= 1) throw fail(400, 'Add a backup passkey before removing your last one.');
+  const result = db.prepare('DELETE FROM credentials WHERE id = ? AND userId = ?').run(req.params.id, user.id);
+  if (!result.changes) throw fail(404, 'Passkey not found.');
+  req.session.verifiedAt = 0;
+  res.json(snapshot(user));
+});
+app.post('/api/logout', (req, res) => {
+  sessions.delete(req.sessionId);
+  res.clearCookie('dg_session', { httpOnly: true, sameSite: 'strict', secure, path: '/' });
+  res.json({ success: true });
+});
+app.use('/api', (req, res, next) => next(fail(404, 'Account endpoint not found.')));
+app.get(['/', '/account'], (req, res) => res.sendFile(join(root, 'index.html')));
+app.get('/styles.css', (req, res) => res.sendFile(join(root, 'styles.css')));
+app.use('/assets', express.static(join(root, 'assets'), { index: false }));
+app.use((error, req, res, next) => {
+  if (res.headersSent) return next(error);
+  const status = error.status || 400;
+  res.status(status).json({ error: error.status ? error.message : 'Passkey verification failed. Please try again.' });
+});
+// Sessions intentionally expire on restart. Passkey public keys and profiles persist in SQLite.
+setInterval(() => {
+  const now = Date.now();
+  for (const [id, session] of sessions) if (session.expires < now) sessions.delete(id);
+  for (const [id, rate] of rates) if (now - rate.start > 60000) rates.delete(id);
+}, 60000).unref();
+app.listen(port, '0.0.0.0', () => console.log(`Daily Grind listening on port ${port}; passkey origin: ${origin}`));
