+export function createApp({ origin, databasePath = 'data/accounts.sqlite', staticDirectory = 'dist' }) {
+  const url = new URL(origin);
+  if (url.origin !== origin || (url.protocol !== 'https:' && !(url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname)))) {
+    throw new Error('APP_ORIGIN must be an HTTPS origin (HTTP is allowed on localhost).');
+  }
+  mkdirSync(dirname(databasePath), { recursive: true });
+  const db = new DatabaseSync(databasePath);
+  db.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
+    CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL);
+    CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), public_key BLOB NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, name TEXT NOT NULL, created_at INTEGER NOT NULL, last_used INTEGER, backed_up INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), expires INTEGER NOT NULL, grant_action TEXT, grant_expires INTEGER);
+    CREATE TABLE IF NOT EXISTS challenges (session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, challenge TEXT NOT NULL, expires INTEGER NOT NULL, payload TEXT NOT NULL);
+    CREATE INDEX IF NOT EXISTS passkeys_user ON passkeys(user_id);`);
+  const app = express();
+  app.disable('x-powered-by');
+  app.use((req, res, next) => {
+    res.set({ 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin', 'Permissions-Policy': 'publickey-credentials-create=(self), publickey-credentials-get=(self)', 'Content-Security-Policy': "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https://images.unsplash.com; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" });
+    next();
+  });
+  const limits = new Map();
+  app.use('/api', (req, res, next) => {
+    res.set('Cache-Control', 'no-store');
+    if (req.method !== 'GET' && req.headers.origin !== origin) return res.status(403).json({ error: 'This request must come from the Daily Grind website.' });
+    const now = Date.now();
+    for (const [key, value] of limits) if (value.reset < now) limits.delete(key);
+    const key = req.socket.remoteAddress;
+    const rate = limits.get(key) || { count: 0, reset: now + 60000 };
+    rate.count++;
+    limits.set(key, rate);
+    if (rate.count > 100) return res.status(429).json({ error: 'Too many requests. Please wait a minute and try again.' });
+    next();
+  });
+  app.use('/api', express.json({ limit: '32kb', type: 'application/json' }));
+  const cookieName = url.protocol === 'https:' ? '__Host-dg_session' : 'dg_session';
+  function setCookie(res, token, age = SESSION_MS) {
+    res.setHeader('Set-Cookie', `${cookieName}=${token}; HttpOnly; SameSite=Lax; Path=/; Max-Age=${Math.floor(age / 1000)}${url.protocol === 'https:' ? '; Secure' : ''}`);
+  }
+  function newSession(res, userID = null, oldID) {
+    if (oldID) db.prepare('DELETE FROM sessions WHERE id=?').run(oldID);
+    const token = randomBytes(32).toString('base64url');
+    const session = { id: hash(token), user_id: userID, expires: Date.now() + SESSION_MS };
+    db.prepare('INSERT INTO sessions (id,user_id,expires) VALUES (?,?,?)').run(session.id, userID, session.expires);
+    setCookie(res, token);
+    return session;
+  }
+  app.use('/api', (req, res, next) => {
+    db.prepare('DELETE FROM sessions WHERE expires < ?').run(Date.now());
+    db.prepare('DELETE FROM challenges WHERE expires < ?').run(Date.now());
+    const token = req.headers.cookie?.split(';').map(c => c.trim()).find(c => c.startsWith(`${cookieName}=`))?.slice(cookieName.length + 1);
+    req.accountSession = token && db.prepare('SELECT * FROM sessions WHERE id=?').get(hash(token));
+    if (!req.accountSession) req.accountSession = newSession(res);
+    next();
+  });
+  function signedIn(req) {
+    const id = req.accountSession.user_id;
+    if (!id) fail('Your session has ended. Sign in again to continue.', 401);
+    return id;
+  }
+  function requireGrant(req, action) {
+    const session = db.prepare('SELECT * FROM sessions WHERE id=?').get(req.accountSession.id);
+    if (session.grant_action !== action || session.grant_expires < Date.now()) fail('Verify with your passkey to continue.', 403);
+    db.prepare('UPDATE sessions SET grant_action=NULL, grant_expires=NULL WHERE id=?').run(session.id);
+  }
+  const keysFor = id => db.prepare('SELECT * FROM passkeys WHERE user_id=? ORDER BY created_at').all(id);
+  const descriptors = id => keysFor(id).map(k => ({ id: k.id, transports: JSON.parse(k.transports) }));
+  function account(id) {
+    return { user: db.prepare('SELECT id,name,email FROM users WHERE id=?').get(id), passkeys: keysFor(id).map(k => ({ id: k.id, name: k.name, createdAt: k.created_at, lastUsed: k.last_used, backedUp: Boolean(k.backed_up) })) };
+  }
+  function saveChallenge(req, kind, challenge, payload) {
+    db.prepare('INSERT OR REPLACE INTO challenges VALUES (?,?,?,?,?)').run(req.accountSession.id, kind, challenge, Date.now() + CHALLENGE_MS, JSON.stringify(payload));
+  }
+  function takeChallenge(req, kind) {
+    const challenge = db.prepare('DELETE FROM challenges WHERE session_id=? RETURNING *').get(req.accountSession.id);
+    if (!challenge || challenge.kind !== kind || challenge.expires < Date.now()) fail('This passkey request expired. Please try again.');
+    return { ...challenge, payload: JSON.parse(challenge.payload) };
+  }
+  app.get('/api/account', (req, res) => res.json(req.accountSession.user_id ? account(req.accountSession.user_id) : { user: null, passkeys: [] }));
+  app.post('/api/register/options', async (req, res) => {
+    if (req.accountSession.user_id) fail('Sign out before creating a different account.');
+    const user = { ...profile(req.body), id: randomUUID() };
+    if (db.prepare('SELECT id FROM users WHERE email=?').get(user.email)) fail('An account already uses that email. Sign in with its passkey.', 409);
+    const name = text(req.body.passkeyName, 'passkey name', 60);
+    const options = await generateRegistrationOptions({ rpName: 'The Daily Grind', rpID: url.hostname, userName: user.email, userDisplayName: user.name, userID: new TextEncoder().encode(user.id), attestationType: 'none', authenticatorSelection: { residentKey: 'required', userVerification: 'required' } });
+    saveChallenge(req, 'register', options.challenge, { user, name });
+    res.json(options);
+  });
+  async function verifyRegistration(req, res, adding) {
+    const challenge = takeChallenge(req, adding ? 'add' : 'register');
+    const result = await verifyRegistrationResponse({ response: req.body.credential, expectedChallenge: challenge.challenge, expectedOrigin: origin, expectedRPID: url.hostname, requireUserVerification: true });
+    if (!result.verified) fail('The passkey could not be verified. Please try again.');
+    const { credential, credentialBackedUp } = result.registrationInfo;
+    const user = adding ? { id: signedIn(req) } : challenge.payload.user;
+    if (adding && challenge.payload.userID !== user.id) fail('Account changed. Please sign in again.', 401);
+    db.exec('BEGIN IMMEDIATE');
+    try {
+      if (!adding) db.prepare('INSERT INTO users VALUES (?,?,?)').run(user.id, user.name, user.email);
+      if (keysFor(user.id).length >= 10) fail('You can save up to 10 passkeys.');
+      db.prepare('INSERT INTO passkeys VALUES (?,?,?,?,?,?,?,?,?)').run(credential.id, user.id, credential.publicKey, credential.counter, JSON.stringify(credential.transports || []), challenge.payload.name, Date.now(), null, Number(credentialBackedUp));
+      db.exec('COMMIT');
+    } catch (error) { db.exec('ROLLBACK'); throw error; }
+    if (!adding) newSession(res, user.id, req.accountSession.id);
+    res.json(account(user.id));
+  }
+  app.post('/api/register/verify', (req, res) => verifyRegistration(req, res, false));
+  app.post('/api/authenticate/options', async (req, res) => {
+    const action = req.body.action || 'signin';
+    if (action !== 'signin' && !/^(profile|add|rename:[A-Za-z0-9_-]+|delete:[A-Za-z0-9_-]+)$/.test(action)) fail('Invalid verification request.');
+    const userID = action === 'signin' ? null : signedIn(req);
+    const options = await generateAuthenticationOptions({ rpID: url.hostname, userVerification: 'required', ...(userID ? { allowCredentials: descriptors(userID) } : {}) });
+    saveChallenge(req, 'authenticate', options.challenge, { action, userID });
+    res.json(options);
+  });
+  app.post('/api/authenticate/verify', async (req, res) => {
+    const challenge = takeChallenge(req, 'authenticate');
+    const key = db.prepare('SELECT * FROM passkeys WHERE id=?').get(req.body.credential?.id || '');
+    if (!key || (challenge.payload.userID && key.user_id !== challenge.payload.userID)) fail('This passkey does not belong to this account. Try another passkey.', 401);
+    if (challenge.payload.action !== 'signin' && signedIn(req) !== key.user_id) fail('Account changed. Sign in again.', 401);
+    if (req.body.credential.response?.userHandle && req.body.credential.response.userHandle !== Buffer.from(key.user_id).toString('base64url')) fail('This passkey does not belong to this account.', 401);
+    const result = await verifyAuthenticationResponse({ response: req.body.credential, expectedChallenge: challenge.challenge, expectedOrigin: origin, expectedRPID: url.hostname, credential: { id: key.id, publicKey: new Uint8Array(key.public_key), counter: key.counter, transports: JSON.parse(key.transports) }, requireUserVerification: true });
+    if (!result.verified) fail('The passkey could not be verified.', 401);
+    const updated = db.prepare('UPDATE passkeys SET counter=?, last_used=?, backed_up=? WHERE id=? AND counter=?').run(result.authenticationInfo.newCounter, Date.now(), Number(result.authenticationInfo.credentialBackedUp), key.id, key.counter);
+    if (!updated.changes) fail('Another sign-in was completed. Please try again.', 409);
+    if (challenge.payload.action === 'signin') newSession(res, key.user_id, req.accountSession.id);
+    else db.prepare('UPDATE sessions SET grant_action=?, grant_expires=? WHERE id=?').run(challenge.payload.action, Date.now() + 120000, req.accountSession.id);
+    res.json(account(key.user_id));
+  });
+  app.post('/api/passkeys/options', async (req, res) => {
+    const userID = signedIn(req);
+    const name = text(req.body.name, 'passkey name', 60);
+    if (keysFor(userID).length >= 10) fail('You can save up to 10 passkeys.');
+    requireGrant(req, 'add');
+    const user = account(userID).user;
+    const options = await generateRegistrationOptions({ rpName: 'The Daily Grind', rpID: url.hostname, userName: user.email, userDisplayName: user.name, userID: new TextEncoder().encode(user.id), excludeCredentials: descriptors(userID), attestationType: 'none', authenticatorSelection: { residentKey: 'required', userVerification: 'required' } });
+    saveChallenge(req, 'add', options.challenge, { userID, name });
+    res.json(options);
+  });
+  app.post('/api/passkeys/verify', (req, res) => verifyRegistration(req, res, true));
+  app.patch('/api/account', (req, res) => {
+    const id = signedIn(req);
+    const user = profile(req.body);
+    requireGrant(req, 'profile');
+    db.prepare('UPDATE users SET name=?,email=? WHERE id=?').run(user.name, user.email, id);
+    res.json(account(id));
+  });
+  app.patch('/api/passkeys/:id', (req, res) => {
+    const userID = signedIn(req);
+    const name = text(req.body.name, 'passkey name', 60);
+    requireGrant(req, `rename:${req.params.id}`);
+    if (!db.prepare('UPDATE passkeys SET name=? WHERE id=? AND user_id=?').run(name, req.params.id, userID).changes) fail('Passkey no longer exists.', 404);
+    res.json(account(userID));
+  });
+  app.delete('/api/passkeys/:id', (req, res) => {
+    const userID = signedIn(req);
+    requireGrant(req, `delete:${req.params.id}`);
+    if (keysFor(userID).length <= 1) fail('Keep at least one passkey to avoid losing access. Add another before removing this one.');
+    if (!db.prepare('DELETE FROM passkeys WHERE id=? AND user_id=?').run(req.params.id, userID).changes) fail('Passkey no longer exists.', 404);
+    // Other sessions must sign in again after a credential is removed.
+    db.prepare('DELETE FROM sessions WHERE user_id=? AND id<>?').run(userID, req.accountSession.id);
+    res.json(account(userID));
+  });
+  app.post('/api/logout', (req, res) => {
+    db.prepare('DELETE FROM sessions WHERE id=?').run(req.accountSession.id);
+    setCookie(res, '', 0);
+    res.json({ ok: true });
+  });
+  app.use('/api', (req, res) => res.status(404).json({ error: 'Account endpoint not found.' }));
+  app.use((error, req, res, next) => {
+    if (!req.path.startsWith('/api/')) return next(error);
+    const duplicate = error.code === 'ERR_SQLITE_ERROR' && error.message.includes('UNIQUE');
+    const status = duplicate ? 409 : (error.status || 400);
+    res.status(status).json({ error: duplicate ? 'That email or passkey is already registered. Try signing in.' : error.status ? error.message : 'The passkey request could not be completed. Please try again.' });
+  });
+  app.use(express.static(staticDirectory));
+  app.get('/account', (req, res) => res.redirect('/#account'));
+  return { app, db };
+}
