+      background.current?.abort();
+      const abort = new AbortController();
+      background.current = abort;
+      authenticatePasskey(abort.signal, true).then(() => {
+        if (!abort.signal.aborted) window.location.assign(accountURL);
+      }).catch(error => {
+        if (!abort.signal.aborted && !(error instanceof DOMException && error.name === 'NotAllowedError')) setError(friendlyError(error));
+      });
