@@ -0,0 +1,78 @@
+
+export type CredentialSummary = {
+  id: string; name: string; provider: string; providerIcon?: string; registeredAt: number;
+  lastUsedAt: number | null; deviceType: string; backedUp: boolean;
+};
+export type Account = {
+  user: { id: string; username: string; displayName: string };
+  rpId: string; credentials: CredentialSummary[];
+};
+export class ApiError extends Error {
+  constructor(message: string, public status: number, public code?: string) { super(message); }
+}
+export const accountURL = `${import.meta.env.BASE_URL}account/settings`;
+export async function api<T = Account>(action: string, body?: unknown, signal?: AbortSignal): Promise<T> {
+  const response = await fetch(`${import.meta.env.BASE_URL}api/auth/${action}`, {
+    method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin', signal,
+    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+  const data = await response.json().catch(() => ({ error: 'The account service returned an invalid response.' }));
+  if (!response.ok) throw new ApiError(data.error || 'Unable to complete the request.', response.status, data.code);
+  return data;
+}
+export async function capabilities() {
+  if (!window.isSecureContext || !window.PublicKeyCredential || !navigator.credentials) return { supported: false, canCreate: false, conditionalGet: false };
+  await import('webauthn-polyfills');
+  const available = await PublicKeyCredential.getClientCapabilities().catch(() => ({} as Record<string, boolean>));
+  return { supported: true, canCreate: Boolean(available.passkeyPlatformAuthenticator && available.conditionalGet), conditionalGet: Boolean(available.conditionalGet) };
+}
+export function friendlyError(error: unknown) {
+  if (error instanceof DOMException) {
+    if (error.name === 'NotAllowedError') return 'The passkey request was cancelled or timed out. Try again, use another device, or use your password.';
+    if (error.name === 'InvalidStateError') return 'A passkey from this provider already exists. Use it to sign in or choose another provider.';
+    if (error.name === 'SecurityError') return 'Passkeys are unavailable for this website address. Use your password to continue.';
+    if (error.name === 'AbortError') return '';
+  }
+  return error instanceof ApiError ? error.message : 'Unable to reach the account service. Please try again.';
+}
+async function unknownCredential(rpId: string, credentialId: string) {
+  if (!PublicKeyCredential.signalUnknownCredential) return;
+  try { await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId }); }
+  catch (error) { console.warn('Passkey manager synchronization unavailable.', error); }
+}
+export async function registerPasskey(name: string, promotion: boolean, signal: AbortSignal): Promise<Account> {
+  const { options, ceremonyId } = await api<{ options: PublicKeyCredentialCreationOptionsJSON; ceremonyId: string }>('registration/options', { promotion }, signal);
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(options);
+  const credential = await navigator.credentials.create({ publicKey, signal }) as PublicKeyCredential | null;
+  if (!credential) throw new Error('No passkey returned.');
+  const encoded = credential.toJSON();
+  try { return await api('registration/verify', { ceremonyId, credential: encoded, name }, signal); }
+  catch (error) { await unknownCredential(publicKey.rp.id!, credential.id); throw error; }
+}
+export async function authenticatePasskey(signal: AbortSignal, conditional = false, reauth = false): Promise<Account> {
+  const route = reauth ? 'reauth' : 'authentication';
+  const { options, ceremonyId } = await api<{ options: PublicKeyCredentialRequestOptionsJSON; ceremonyId: string }>(`${route}/options`, {}, signal);
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(options);
+  const credential = await navigator.credentials.get({ publicKey, signal, ...(conditional ? { mediation: 'conditional' as const } : {}) }) as PublicKeyCredential | null;
+  if (!credential) throw new Error('No passkey returned.');
+  try { return await api(`${route}/verify`, { ceremonyId, credential: credential.toJSON() }, signal); }
+  catch (error) {
+    if (error instanceof ApiError && error.status === 404) await unknownCredential(publicKey.rpId!, credential.id);
+    throw error;
+  }
+}
+function base64url(value: string) { return value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value); }
+export async function syncPasskeys(account: Account) {
+  if (!window.PublicKeyCredential?.signalAllAcceptedCredentials) return;
+  const ids = account.credentials.map(key => key.id);
+  if (!base64url(account.user.id) || !ids.every(base64url)) return;
+  try { await PublicKeyCredential.signalAllAcceptedCredentials({ rpId: account.rpId, userId: account.user.id, allAcceptedCredentialIds: ids }); }
+  catch (error) { console.warn('Passkey manager synchronization unavailable.', error); }
+}
+export async function syncProfile(account: Account) {
+  if (!window.PublicKeyCredential?.signalCurrentUserDetails || !base64url(account.user.id)) return;
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId: account.rpId, userId: account.user.id, name: account.user.username, displayName: account.user.displayName });
+  } catch (error) { console.warn('Passkey profile synchronization unavailable.', error); }
+}
