--- /dev/null
+++ b/src/lib/server/auth-store.ts
@@ -0,0 +1,68 @@
+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import { createHash, randomBytes } from 'node:crypto';
+import type { WebAuthnCredential } from '@simplewebauthn/server';
+
+export type User = { id: string; username: string; displayName: string };
+export type Passkey = {
+  id: string; userId: string; publicKey: string; counter: number; transports: string[];
+  name: string; provider: string; aaguid: string; deviceType: string; backedUp: boolean;
+  registeredAt: number; lastUsedAt: number | null;
+};
+export type AuthSession = { token: string; userId: string | null; expires: number; verifiedAt: number };
+export type Ceremony = {
+  id: string; sessionToken: string; userId: string | null; kind: 'registration' | 'authentication' | 'reauthentication';
+  challenge: string; origin: string; rpId: string; expires: number;
+};
+let database: DatabaseSync;
+export function db() {
+  if (!database) {
+    const path = resolve(process.env.AUTH_DB_PATH || './data/auth.sqlite');
+    mkdirSync(dirname(path), { recursive: true });
+    database = new DatabaseSync(path);
+    database.exec(`
+      PRAGMA journal_mode = WAL;
+      PRAGMA foreign_keys = ON;
+      PRAGMA busy_timeout = 5000;
+      CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, displayName TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, userId TEXT REFERENCES users(id), expires INTEGER NOT NULL, verifiedAt INTEGER NOT NULL DEFAULT 0);
+      CREATE TABLE IF NOT EXISTS ceremonies (id TEXT PRIMARY KEY, sessionToken TEXT NOT NULL, userId TEXT, kind TEXT NOT NULL, challenge TEXT NOT NULL, origin TEXT NOT NULL, rpId TEXT NOT NULL, expires INTEGER NOT NULL);
+    `);
+  }
+  return database;
+}
+export const randomId = () => randomBytes(32).toString('base64url');
+export const hashToken = (token: string) => createHash('sha256').update(token).digest('hex');
+export function findUser(id: string): User | undefined {
+  return db().prepare('SELECT * FROM users WHERE id = ?').get(id) as User | undefined;
+}
+export function ensureUser(username: string): User {
+  const existing = db().prepare('SELECT * FROM users WHERE username = ?').get(username) as User | undefined;
+  if (existing) return existing;
+  const id = randomId();
+  db().prepare('INSERT OR IGNORE INTO users VALUES (?, ?, ?)').run(id, username, username);
+  return db().prepare('SELECT * FROM users WHERE username = ?').get(username) as User;
+}
+export function listPasskeys(userId: string): Passkey[] {
+  return (db().prepare('SELECT data FROM passkeys WHERE userId = ?').all(userId) as { data: string }[]).map(row => JSON.parse(row.data));
+}
+export function findPasskey(id: string): Passkey | undefined {
+  const row = db().prepare('SELECT data FROM passkeys WHERE id = ?').get(id) as { data: string } | undefined;
+  return row ? JSON.parse(row.data) : undefined;
+}
+export function credentialFor(key: Passkey): WebAuthnCredential {
+  return { id: key.id, publicKey: new Uint8Array(Buffer.from(key.publicKey, 'base64url')), counter: key.counter, transports: key.transports as WebAuthnCredential['transports'] };
+}
+export function savePasskey(key: Passkey) {
+  db().prepare('UPDATE passkeys SET data = ? WHERE id = ? AND userId = ?').run(JSON.stringify(key), key.id, key.userId);
+}
+export function consumeCeremony(id: string, sessionToken: string): Ceremony | undefined {
+  // DELETE RETURNING atomically makes every challenge single use, including failed attempts.
+  return db().prepare('DELETE FROM ceremonies WHERE id = ? AND sessionToken = ? AND expires > ? RETURNING *').get(id, sessionToken, Date.now()) as Ceremony | undefined;
+}
+export function cleanup() {
+  db().prepare('DELETE FROM ceremonies WHERE expires <= ?').run(Date.now());
+  db().prepare('DELETE FROM sessions WHERE expires <= ?').run(Date.now());
+}
