+import type { APIContext, APIRoute } from 'astro';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import type { RegistrationResponseJSON, AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { db, randomId, hashToken, ensureUser, findUser, findPasskey, listPasskeys, credentialFor, savePasskey, consumeCeremony, cleanup } from '../../../lib/server/auth-store';
+import providers from '../../../lib/server/passkey-providers.json';
+import type { AuthSession, Passkey, User } from '../../../lib/server/auth-store';
+
+const remoteAPI = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+const cookieName = 'times_auth';
+class AuthError extends Error {
+  constructor(message: string, public status = 400, public code?: string) { super(message); }
+}
+function json(data: unknown, status = 200) {
+  return new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+}
+function configuration(context: APIContext) {
+  const origin = new URL(process.env.PASSKEY_ORIGIN || context.url.origin).origin;
+  const rpId = process.env.PASSKEY_RP_ID || new URL(origin).hostname;
+  return { origin, rpId };
+}
+function session(context: APIContext): AuthSession | undefined {
+  const raw = context.cookies.get(cookieName)?.value;
+  if (!raw) return;
+  return db().prepare('SELECT * FROM sessions WHERE token = ? AND expires > ?').get(hashToken(raw), Date.now()) as AuthSession | undefined;
+}
+function newSession(context: APIContext, userId: string | null, verified = false): AuthSession {
+  const raw = randomId();
+  const token = hashToken(raw);
+  const expires = Date.now() + (userId ? 7 * 86400000 : 3600000);
+  const verifiedAt = verified ? Date.now() : 0;
+  const old = session(context);
+  if (old) db().prepare('DELETE FROM sessions WHERE token = ?').run(old.token);
+  db().prepare('INSERT INTO sessions VALUES (?, ?, ?, ?)').run(token, userId, expires, verifiedAt);
+  context.cookies.set(cookieName, raw, {
+    httpOnly: true, sameSite: 'lax', secure: configuration(context).origin.startsWith('https:'),
+    path: import.meta.env.BASE_URL, maxAge: Math.floor((expires - Date.now()) / 1000),
+  });
+  return { token, userId, expires, verifiedAt };
+}
+function requireUser(context: APIContext) {
+  const current = session(context);
+  const user = current?.userId && findUser(current.userId);
+  if (!current || !user) throw new AuthError('Please sign in to continue.', 401);
+  return { current, user };
+}
+function requireRecent(current: AuthSession) {
+  if (Date.now() - current.verifiedAt > 5 * 60000) throw new AuthError('Verify your identity to continue.', 403, 'REAUTH_REQUIRED');
+}
+function view(user: User, context: APIContext) {
+  return {
+    user, rpId: configuration(context).rpId,
+    credentials: listPasskeys(user.id).map(({ publicKey, counter, ...key }) => key),
+  };
+}
+async function passwordAuth(username: string, password: string, action: 'login' | 'register') {
+  let response: Response;
+  try {
+    response = await fetch(`${remoteAPI}/${action}`, {
+      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password }), signal: AbortSignal.timeout(15000),
+    });
+  } catch { throw new AuthError('The account service is unavailable. Please try again.', 503); }
+  if (!response.ok) {
+    throw new AuthError(action === 'login' ? 'The username or password is incorrect.' : 'Unable to create this account. Try another username and a password with at least 8 characters and a number.', action === 'login' ? 401 : 400);
+  }
+}
+function text(value: unknown, label: string, max = 80): string {
+  if (typeof value !== 'string' || !value.trim() || value.trim().length > max) throw new AuthError(`Enter a ${label} of 1–${max} characters.`);
+  return value.trim();
+}
+const handle: APIRoute = async (context) => {
+  try {
+    const { request, params } = context;
+    const action = params.action;
+    const { origin, rpId } = configuration(context);
+    // Astro's global origin check is disabled; protect every auth mutation explicitly.
+    if (request.method !== 'GET' && request.headers.get('Origin') !== origin) throw new AuthError('This request must come from this website.', 403);
+    cleanup();
+    if (request.method === 'GET' && action === 'account') {
+      const { user } = requireUser(context);
+      return json(view(user, context));
+    }
+    if (request.method !== 'POST') return json({ error: 'Method not allowed.' }, 405);
+    const body = await request.json().catch(() => { throw new AuthError('Invalid request.'); });
+    if (action === 'login' || action === 'signup') {
+      const username = text(body.username, 'username');
+      if (typeof body.password !== 'string' || !body.password || body.password.length > 1024) throw new AuthError('Enter your password.');
+      if (action === 'signup') {
+        if (body.password.length < 8 || !/\d/.test(body.password)) throw new AuthError('Use at least 8 characters and a number.');
+        await passwordAuth(username, body.password, 'register');
+      }
+      try { await passwordAuth(username, body.password, 'login'); }
+      catch (error) {
+        if (action === 'signup') throw new AuthError('Your account was created, but automatic sign-in failed. Sign in with your new username and password to add a passkey.', 401, 'ACCOUNT_CREATED');
+        throw error;
+      }
+      const user = ensureUser(username);
+      newSession(context, user.id, true);
+      return json(view(user, context));
+    }
+    if (action === 'logout') {
+      const current = session(context);
+      if (current) db().prepare('DELETE FROM sessions WHERE token = ?').run(current.token);
+      context.cookies.delete(cookieName, { path: import.meta.env.BASE_URL });
+      return json({ success: true });
+    }
+    if (action === 'reauth/password') {
+      const { current, user } = requireUser(context);
+      if (typeof body.password !== 'string' || !body.password || body.password.length > 1024) throw new AuthError('Enter your password.');
+      await passwordAuth(user.username, body.password, 'login');
+      db().prepare('UPDATE sessions SET verifiedAt = ? WHERE token = ?').run(Date.now(), current.token);
+      return json({ success: true });
+    }
+    if (action === 'registration/options' || action === 'authentication/options' || action === 'reauth/options') {
+      const kind = action === 'registration/options' ? 'registration' : action === 'reauth/options' ? 'reauthentication' : 'authentication';
+      let current = session(context);
+      let user: User | undefined;
+      if (kind !== 'authentication') {
+        ({ current, user } = requireUser(context));
+        if (kind === 'registration') requireRecent(current);
+      } else if (current?.userId) {
+        throw new AuthError('You are already signed in. Open account settings.', 409);
+      }
+      if (!current) current = newSession(context, null);
+      const keys = user ? listPasskeys(user.id) : [];
+      if (kind === 'reauthentication' && !keys.length) throw new AuthError('No passkeys are registered. Verify with your password.');
+      const options = kind === 'registration'
+        ? await generateRegistrationOptions({
+          rpID: rpId, rpName: 'The DevTools Times', userName: user!.username, userDisplayName: user!.displayName,
+          userID: new Uint8Array(Buffer.from(user!.id, 'base64url')), attestationType: 'none',
+          supportedAlgorithmIDs: [-7, -257],
+          excludeCredentials: keys.map(key => ({ id: key.id, transports: key.transports })),
