+      const ceremonyId = randomId();
+      // Keep concurrent tabs/autofill independent; cap outstanding challenges per session.
+      db().prepare('DELETE FROM ceremonies WHERE sessionToken = ? AND id NOT IN (SELECT id FROM ceremonies WHERE sessionToken = ? ORDER BY expires DESC LIMIT 9)').run(current.token, current.token);
+      db().prepare('INSERT INTO ceremonies VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(ceremonyId, current.token, user?.id || null, kind, options.challenge, origin, rpId, Date.now() + 5 * 60000);
