+          transports: info.credential.transports || [], name: text(body.name || 'My passkey', 'passkey name'),
+          provider: (info.aaguid !== '00000000-0000-0000-0000-000000000000' && (providers as Record<string, string>)[info.aaguid]) || 'Unknown passkey provider', aaguid: info.aaguid, deviceType: info.credentialDeviceType, backedUp: info.credentialBackedUp, registeredAt: Date.now(), lastUsedAt: null,
+        };
