+    }
+    if (action === 'passkey/rename' || action === 'passkey/delete' || action === 'profile') {
+      const { current, user } = requireUser(context);
+      requireRecent(current);
+      if (action === 'profile') {
+        const displayName = text(body.displayName, 'display name');
+        db().prepare('UPDATE users SET displayName = ? WHERE id = ?').run(displayName, user.id);
+        return json(view({ ...user, displayName }, context));
+      }
+      const key = typeof body.id === 'string' && findPasskey(body.id);
+      if (!key || key.userId !== user.id) throw new AuthError('Passkey not found.', 404);
