+    return json({ error: 'Not found.' }, 404);
+  } catch (error) {
+    if (error instanceof AuthError) return json({ error: error.message, code: error.code }, error.status);
+    // Do not expose assertion data, credentials, or internal database details.
+    console.warn('Authentication request failed:', error instanceof Error ? error.name : 'UnknownError');
