@@ -0,0 +1,57 @@
+import { after, test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+
+const directory = mkdtempSync(join(tmpdir(), 'times-auth-test-'));
+process.env.AUTH_DB_PATH = join(directory, 'auth.sqlite');
+// Exercise the store directly; do not load an HTTP/server entrypoint.
+const { db, ensureUser, randomId, hashToken, consumeCeremony, listPasskeys, findPasskey, savePasskey, credentialFor, cleanup } = await import('../src/lib/server/auth-store.ts');
+after(() => { db().close(); rmSync(directory, { recursive: true, force: true }); });
+
+function challenge(sessionToken = 'session-a', expires = Date.now() + 10000) {
+  const id = randomId();
+  db().prepare('INSERT INTO ceremonies VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(id, sessionToken, null, 'authentication', randomId(), 'https://news.example.com', 'news.example.com', expires);
+  return id;
+}
+test('challenges are session-bound, expiring, and atomically single-use', () => {
+  const id = challenge();
+  assert.equal(consumeCeremony(id, 'different-session'), undefined);
+  assert.equal(consumeCeremony(id, 'session-a')?.id, id);
+  assert.equal(consumeCeremony(id, 'session-a'), undefined, 'replay must be rejected');
+  assert.equal(consumeCeremony(challenge('session-a', Date.now() - 1), 'session-a'), undefined);
+});
+test('parallel tabs retain independent challenge records', () => {
+  const a = challenge(); const b = challenge();
+  assert.ok(consumeCeremony(a, 'session-a'));
+  assert.ok(consumeCeremony(b, 'session-a'));
+});
+test('account IDs are opaque base64url and exact usernames map consistently', () => {
+  const user = ensureUser('reader');
+  assert.equal(ensureUser('reader').id, user.id);
+  assert.match(user.id, /^[A-Za-z0-9_-]+$/);
+  assert.equal(Buffer.from(user.id, 'base64url').length, 32);
+  assert.notEqual(ensureUser('other-reader').id, user.id);
+  assert.notEqual(hashToken('token-a'), hashToken('token-b'));
+  assert.notEqual(hashToken('token-a'), 'token-a');
+});
+test('credentials preserve key bytes and updates cannot cross account ownership', () => {
+  const owner = ensureUser('reader'); const other = ensureUser('other-reader');
+  const publicKey = Buffer.from([0, 255, 1, 2, 3]).toString('base64url');
+  const key = { id: randomId(), userId: owner.id, publicKey, counter: 9, transports: ['internal'], name: 'Original', provider: 'Unknown passkey provider', aaguid: '00000000-0000-0000-0000-000000000000', deviceType: 'multiDevice', backedUp: true, registeredAt: Date.now(), lastUsedAt: null };
+  db().prepare('INSERT INTO passkeys VALUES (?, ?, ?)').run(key.id, key.userId, JSON.stringify(key));
+  assert.equal(listPasskeys(other.id).length, 0);
+  assert.deepEqual(Array.from(credentialFor(key).publicKey), [0, 255, 1, 2, 3]);
+  savePasskey({ ...key, userId: other.id, name: 'Not allowed' });
+  assert.equal(findPasskey(key.id)?.name, 'Original');
+  savePasskey({ ...key, name: 'Renamed' });
+  assert.equal(listPasskeys(owner.id)[0].name, 'Renamed');
+});
+test('expired sessions and challenges are removed', () => {
+  const expired = challenge('expired', Date.now() - 1000);
+  db().prepare('INSERT INTO sessions VALUES (?, ?, ?, ?)').run('expired', null, Date.now() - 1000, 0);
+  cleanup();
+  assert.equal(db().prepare('SELECT id FROM ceremonies WHERE id = ?').get(expired), undefined);
+  assert.equal(db().prepare('SELECT token FROM sessions WHERE token = ?').get('expired'), undefined);
+});

