+import React, { useEffect, useRef, useState } from 'react';
+import { ArrowLeftIcon, ArrowRightOnRectangleIcon, ComputerDesktopIcon, EllipsisHorizontalIcon, PlusIcon, XMarkIcon, PencilSquareIcon, TrashIcon, UserCircleIcon, LockClosedIcon } from '@heroicons/react/24/outline';
+import type { Account, Passkey } from '../lib/auth';
+import { AuthError, authenticatePasskey, authMessage, authRequest, pageUrl, registerPasskey } from '../lib/auth';
+import { FingerPrintIcon, ShieldCheckIcon, KeyIcon, Notice, PasskeyInfo, usePasskeySupport } from './AuthShared';
+
+type Action = { kind: 'add' } | { kind: 'rename' | 'remove'; key: Passkey };
+function dateLabel(value?: string) {
+  if (!value) return 'Not used yet';
+  const date = new Date(value);
+  return Number.isNaN(date.getTime()) ? 'Unavailable' : date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
+}
+
+export default function AccountSettings() {
+  const [account, setAccount] = useState<Account | null>(null);
+  const [keys, setKeys] = useState<Passkey[]>([]);
+  const [loading, setLoading] = useState(true);
+  const [error, setError] = useState<string | null>(null);
+  const [success, setSuccess] = useState<string | null>(null);
+  const [action, setAction] = useState<Action | null>(null);
+  const [stage, setStage] = useState<'confirm' | 'reauth'>('confirm');
+  const [name, setName] = useState('');
+  const [password, setPassword] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [modalError, setModalError] = useState<string | null>(null);
+  const [menu, setMenu] = useState<string | null>(null);
+  const dialog = useRef<HTMLDialogElement>(null);
+  const supported = usePasskeySupport();
+
+  async function load() {
+    setLoading(true); setError(null);
+    try {
+      const session = await authRequest<{ user: Account | null }>('/session');
+      setAccount(session.user);
+      if (session.user) {
+        const data = await authRequest<{ passkeys: Passkey[] }>('/passkeys');
+        setKeys(data.passkeys);
+      } else setKeys([]);
+    } catch (error) { setError(authMessage(error)); }
+    finally { setLoading(false); }
+  }
+  useEffect(() => { load(); }, []);
+  useEffect(() => {
+    if (action && !dialog.current?.open) dialog.current?.showModal();
+    else if (!action) dialog.current?.close();
+  }, [action]);
+  function open(next: Action) {
+    setMenu(null); setModalError(null); setStage('confirm'); setPassword(''); setName(next.kind === 'rename' ? next.key.name : ''); setAction(next);
+  }
+  function close() { if (!busy) { setAction(null); setPassword(''); } }
+  async function perform() {
+    if (!action) return;
+    setBusy(true); setModalError(null); setSuccess(null);
+    try {
+      if (action.kind === 'add') await registerPasskey(undefined, name);
+      else await authRequest(`/passkeys/${encodeURIComponent(action.key.id)}`, action.kind === 'rename' ? { name: name.trim() } : {}, action.kind === 'rename' ? 'PATCH' : 'DELETE');
+      const data = await authRequest<{ passkeys: Passkey[] }>('/passkeys');
+      setKeys(data.passkeys);
+      setSuccess(action.kind === 'add' ? 'Your passkey has been added. You can use it the next time you sign in.' : action.kind === 'rename' ? 'Passkey name updated.' : 'Passkey removed from your account.');
+      setAction(null); setPassword('');
+    } catch (error) {
+      if (error instanceof AuthError && (error.status === 403 || error.status === 401)) { setStage('reauth'); setModalError('For your security, verify your identity before making this change.'); }
+      else setModalError(authMessage(error));
+    } finally { setBusy(false); }
+  }
+  async function reauthenticate(method: 'passkey' | 'password') {
+    setBusy(true); setModalError(null);
+    try {
+      if (method === 'passkey') await authenticatePasskey('reauth');
+      else await authRequest('/reauthenticate', { password });
+      setPassword(''); setStage('confirm');
+    } catch (error) { setModalError(authMessage(error)); }
+    finally { setBusy(false); }
+  }
+  async function signOut() {
+    setBusy(true); setError(null);
+    try { await authRequest('/logout', {}); window.location.assign(pageUrl('signin')); }
+    catch (error) { setError(authMessage(error)); }
+    finally { setBusy(false); }
+  }
+  return <div className="settings-page">
+    <div className="auth-breadcrumb"><a href={pageUrl('')}>The DevTools Times</a><span>/</span><span>Your account</span></div>
+    <div className="settings-heading"><div><span className="auth-eyebrow">A SPACE OF YOUR OWN</span><h1>Account settings</h1><p>A few details. A little peace of mind.</p></div><a className="back-reading" href={pageUrl('')}><ArrowLeftIcon />Back to reading</a></div>
+    <div className="settings-layout">
+      <aside className="settings-sidebar"><div className="account-avatar"><UserCircleIcon /></div><strong>{account?.username || 'Your Times account'}</strong><span>THE DEVTOOLS TIMES READER</span><nav aria-label="Account settings"><a className="active" href="#security" aria-current="page"><ShieldCheckIcon />Sign-in & security</a><a href={pageUrl('')}><KeyIcon />Latest stories</a></nav>{account ? <button onClick={signOut} disabled={busy}><ArrowRightOnRectangleIcon />Sign out</button> : <a className="sidebar-signin" href={pageUrl('signin')}>Sign in to your account →</a>}</aside>
+      <section className="settings-main" id="security">
+        <div className="section-heading"><div><h2>Sign-in & security</h2><p>Simple ways to keep your account yours.</p></div><span className="private-label"><LockClosedIcon />ONLY YOU</span></div>
+        <Notice error={error} success={success} />
