+import React, { useEffect, useState } from 'react';
+import { FingerPrintIcon, ShieldCheckIcon, ArrowRightIcon, CheckIcon, KeyIcon, DevicePhoneMobileIcon } from '@heroicons/react/24/outline';
+import { pageUrl, supportsPasskeys } from '../lib/auth';
+
+export { FingerPrintIcon, ShieldCheckIcon, ArrowRightIcon, CheckIcon, KeyIcon, DevicePhoneMobileIcon };
+export function usePasskeySupport() {
+  const [supported, setSupported] = useState<boolean | null>(null);
+  useEffect(() => setSupported(supportsPasskeys()), []);
+  return supported;
+}
+export function Notice({ error, success }: { error?: string | null; success?: string | null }) {
+  return <>{error && <div className="auth-notice error" role="alert">{error}</div>}{success && <div className="auth-notice success" role="status">{success}</div>}</>;
+}
+export function AuthShell({ children, signup = false }: { children: React.ReactNode; signup?: boolean }) {
+  return <div className="auth-page">
+    <div className="auth-breadcrumb"><a href={pageUrl('')}>The DevTools Times</a><span>/</span><span>Your account</span></div>
+    <div className="auth-layout">
+      <aside className="auth-editorial">
+        <div className="auth-eyebrow"><span className="edition-line" /> THE READER’S EDITION</div>
+        <h1>A better way<br />to stay <em>informed.</em></h1>
+        <p className="auth-intro">Independent perspectives. Stories that matter.<br className="desktop-break" /> A little more understanding, every day.</p>
+        <div className="editorial-rule" />
+        <div className="auth-benefit"><div className="benefit-icon"><KeyIcon /></div><div><h3>Your news. One simple sign-in.</h3><p>Save your reading list and pick up where you left off.</p></div></div>
+        <div className="auth-benefit"><div className="benefit-icon"><ShieldCheckIcon /></div><div><h3>Less to remember. More peace of mind.</h3><p>Passkeys keep your account secure without a password.</p></div></div>
+        <div className="editorial-note"><span className="note-mark">“</span><p>For the curious.<br />For the well-informed.<br /><strong>For you.</strong></p><span className="note-edition">THE DEVTOOLS TIMES<br />EST. 2024</span></div>
+      </aside>
+      <section className="auth-card" aria-label={signup ? 'Create an account' : 'Sign in'}>{children}</section>
+    </div>
+    <div className="auth-page-footer"><ShieldCheckIcon /><span>Your privacy is part of our promise.</span><a href={pageUrl('legal/privacy')}>Privacy policy <ArrowRightIcon /></a></div>
+  </div>;
+}
+export function PasskeyInfo() {
+  return <details className="passkey-info"><summary>What is a passkey?<span>+</span></summary><p>A passkey lets you sign in with your fingerprint, face, device PIN, or security key. Your device keeps it safe, and your biometric information is never shared with us. You can also use a passkey from another device.</p></details>;
+}
+export function LegalNote() {
+  return <p className="auth-legal">By continuing, you agree to our <a href={pageUrl('legal/terms')}>Terms of Service</a> and acknowledge our <a href={pageUrl('legal/privacy')}>Privacy Policy</a>.</p>;
+}
