diff --git a/src/lib/auth.ts b/src/lib/auth.ts
new file mode 100644
index 0000000..d972775
--- /dev/null
+++ b/src/lib/auth.ts
@@ -0,0 +1,91 @@
+// The authentication service owns sessions, challenges, and credential verification.
+export const authBase = (import.meta.env?.PUBLIC_AUTH_API_URL || 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api').replace(/\/$/, '');
+export const pageUrl = (path: string) => `${import.meta.env?.BASE_URL || '/devtools-times/'}${path}`;
+
+export class AuthError extends Error {
+  status: number;
+  constructor(message: string, status: number) { super(message); this.status = status; }
+}
+
+export async function authRequest<T = Record<string, unknown>>(path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST'): Promise<T> {
+  let response: Response;
+  try {
+    response = await fetch(`${authBase}${path}`, {
+      method, credentials: 'include', headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
+      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
+    });
+  } catch { throw new Error('We couldn’t reach the sign-in service. Check your connection and try again.'); }
+  if (!response.ok) {
+    if (response.status === 401) throw new AuthError('Please sign in again to continue.', 401);
+    if (response.status === 404 || response.status === 501) throw new AuthError('This feature is not available from the sign-in service yet. Please use your password or try again later.', response.status);
+    if (response.status === 429) throw new AuthError('Too many attempts. Please wait a moment and try again.', 429);
+    throw new AuthError('We couldn’t complete that request. Check your details and try again.', response.status);
+  }
+  if (response.status === 204) return {} as T;
+  return response.json();
+}
+
+export function supportsPasskeys() {
+  return window.isSecureContext && typeof PublicKeyCredential !== 'undefined' && !!navigator.credentials;
+}
+
+function decode(value: string): ArrayBuffer {
+  const raw = atob(value.replace(/-/g, '+').replace(/_/g, '/'));
+  return Uint8Array.from(raw, c => c.charCodeAt(0)).buffer;
+}
+function encode(value: ArrayBuffer): string {
+  return btoa(Array.from(new Uint8Array(value), b => String.fromCharCode(b)).join('')).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+type DescriptorJSON = Omit<PublicKeyCredentialDescriptor, 'id'> & { id: string };
+type CreationJSON = Omit<PublicKeyCredentialCreationOptions, 'challenge' | 'user' | 'excludeCredentials'> & {
+  challenge: string; user: { id: string; name: string; displayName: string }; excludeCredentials?: DescriptorJSON[];
+};
+type RequestJSON = Omit<PublicKeyCredentialRequestOptions, 'challenge' | 'allowCredentials'> & { challenge: string; allowCredentials?: DescriptorJSON[] };
+type Ceremony<T> = { options: T; ceremonyId: string };
+
+function serialize(credential: PublicKeyCredential) {
+  const response = credential.response;
+  const common = { id: credential.id, rawId: encode(credential.rawId), type: credential.type, authenticatorAttachment: credential.authenticatorAttachment, clientExtensionResults: credential.getClientExtensionResults() };
+  if (response instanceof AuthenticatorAttestationResponse) {
+    return { ...common, response: { clientDataJSON: encode(response.clientDataJSON), attestationObject: encode(response.attestationObject), transports: response.getTransports?.() || [] } };
+  }
+  const assertion = response as AuthenticatorAssertionResponse;
+  return { ...common, response: { clientDataJSON: encode(assertion.clientDataJSON), authenticatorData: encode(assertion.authenticatorData), signature: encode(assertion.signature), userHandle: assertion.userHandle ? encode(assertion.userHandle) : null } };
