+export async function registerPasskey(username?: string, name?: string) {
+  if (!supportsPasskeys()) throw new Error('Passkeys aren’t supported in this browser. Use a password or try a current browser over HTTPS.');
+  const { options, ceremonyId } = await authRequest<Ceremony<CreationJSON>>('/passkeys/register/options', { username });
+  const publicKey: PublicKeyCredentialCreationOptions = {
+    ...options, challenge: decode(options.challenge), user: { ...options.user, id: decode(options.user.id) },
+    excludeCredentials: options.excludeCredentials?.map(item => ({ ...item, id: decode(item.id) })),
+    authenticatorSelection: { ...options.authenticatorSelection, residentKey: 'required', userVerification: 'required' },
+  };
