+
+export async function authenticatePasskey(purpose: 'signin' | 'reauth' = 'signin', username?: string) {
+  if (!supportsPasskeys()) throw new Error('Passkeys aren’t supported in this browser. You can still use your password.');
+  const { options, ceremonyId } = await authRequest<Ceremony<RequestJSON>>('/passkeys/authenticate/options', { purpose, username: username?.trim() || undefined });
+  const credential = await navigator.credentials.get({ publicKey: {
+    ...options, challenge: decode(options.challenge), userVerification: 'required',
+    allowCredentials: options.allowCredentials?.map(item => ({ ...item, id: decode(item.id) })),
+  } }) as PublicKeyCredential | null;
+  if (!credential) throw new Error('No passkey was selected. Please try again.');
+  return authRequest('/passkeys/authenticate/verify', { ceremonyId, credential: serialize(credential), purpose });
+}
