+import { test, afterEach } from 'node:test';
+import assert from 'node:assert/strict';
+import { authRequest, authenticatePasskey, registerPasskey, authMessage, supportsPasskeys, AuthError } from '../src/lib/auth.ts';
+
+const originals = new Map(['fetch', 'window', 'navigator', 'PublicKeyCredential', 'AuthenticatorAttestationResponse'].map(name => [name, Object.getOwnPropertyDescriptor(globalThis, name)]));
+afterEach(() => { for (const [name, descriptor] of originals) { if (descriptor) Object.defineProperty(globalThis, name, descriptor); else delete globalThis[name]; } });
+const mockGlobal = (name, value) => Object.defineProperty(globalThis, name, { configurable: true, value });
+const buffer = () => Uint8Array.from([251, 255, 0]).buffer;
+const encoded = '-_8A';
+function browser(credentials) {
+  mockGlobal('window', { isSecureContext: true });
+  mockGlobal('PublicKeyCredential', class {});
+  mockGlobal('AuthenticatorAttestationResponse', class {});
+  mockGlobal('navigator', { credentials });
+}
+function credential(attestation = false) {
+  const response = attestation ? new AuthenticatorAttestationResponse() : {};
+  Object.assign(response, attestation ? { clientDataJSON: buffer(), attestationObject: buffer(), getTransports: () => ['internal'] } : { clientDataJSON: buffer(), authenticatorData: buffer(), signature: buffer(), userHandle: null });
+  return { id: 'credential-id', rawId: buffer(), type: 'public-key', authenticatorAttachment: 'platform', getClientExtensionResults: () => ({}), response };
+}
+
+test('requests include session cookies and reject service failures', async () => {
+  mockGlobal('fetch', async (url, options) => {
+    assert.equal(options.credentials, 'include');
+    assert.equal(options.method, 'POST');
+    assert.deepEqual(JSON.parse(options.body), { username: 'reader' });
+    return new Response('{}', { status: 403 });
+  });
+  await assert.rejects(authRequest('/reauthenticate', { username: 'reader' }), error => error instanceof AuthError && error.status === 403);
+});
+
+test('sign-in decodes options, requires user verification, and sends signed response for server verification', async () => {
+  browser({ get: async ({ publicKey }) => {
+    assert.deepEqual(new Uint8Array(publicKey.challenge), new Uint8Array(buffer()));
+    assert.deepEqual(new Uint8Array(publicKey.allowCredentials[0].id), new Uint8Array(buffer()));
+    assert.equal(publicKey.userVerification, 'required');
+    return credential();
+  } });
+  const calls = [];
+  mockGlobal('fetch', async (url, options) => {
+    calls.push({ url, body: JSON.parse(options.body) });
+    return Response.json(calls.length === 1 ? { ceremonyId: 'challenge-1', options: { challenge: encoded, allowCredentials: [{ id: encoded, type: 'public-key' }] } } : { verified: true });
+  });
+  await authenticatePasskey('reauth');
+  assert.equal(calls.length, 2);
+  assert.equal(calls[1].body.ceremonyId, 'challenge-1');
+  assert.equal(calls[1].body.purpose, 'reauth');
+  assert.equal(calls[1].body.credential.response.signature, encoded);
+  assert.equal(calls[1].body.credential.response.userHandle, null);
+});
+
+test('registration creates discoverable credentials and sends attestation plus transports', async () => {
+  browser({ create: async ({ publicKey }) => {
+    assert.equal(publicKey.authenticatorSelection.residentKey, 'required');
+    assert.equal(publicKey.authenticatorSelection.userVerification, 'required');
+    assert.deepEqual(new Uint8Array(publicKey.user.id), new Uint8Array(buffer()));
+    return credential(true);
+  } });
+  const calls = [];
+  mockGlobal('fetch', async (url, options) => {
+    calls.push(JSON.parse(options.body));
+    return Response.json(calls.length === 1 ? { ceremonyId: 'register-1', options: { challenge: encoded, user: { id: encoded, name: 'reader', displayName: 'Reader' }, rp: { name: 'The Times' }, pubKeyCredParams: [{ type: 'public-key', alg: -7 }] } } : { verified: true });
+  });
+  await registerPasskey('reader', 'Laptop');
+  assert.equal(calls[1].name, 'Laptop');
+  assert.equal(calls[1].credential.response.attestationObject, encoded);
+  assert.deepEqual(calls[1].credential.response.transports, ['internal']);
+});
+
+test('canceling a device prompt never submits a verification', async () => {
+  browser({ get: async () => { throw new DOMException('Canceled', 'NotAllowedError'); } });
+  let requests = 0;
+  mockGlobal('fetch', async () => { requests++; return Response.json({ ceremonyId: 'challenge-2', options: { challenge: encoded } }); });
+  await assert.rejects(authenticatePasskey(), error => /canceled or timed out/.test(authMessage(error)));
+  assert.equal(requests, 1);
+});
+
+test('unsupported contexts do not start registration or authentication', async () => {
+  browser({});
+  mockGlobal('window', { isSecureContext: false });
+  assert.equal(supportsPasskeys(), false);
+  mockGlobal('fetch', () => assert.fail('Must not request options'));
+  await assert.rejects(registerPasskey('reader'), /aren’t supported/);
+  await assert.rejects(authenticatePasskey(), /aren’t supported/);
+});
+
+test('verification failure is never reported as successful authentication', async () => {
+  browser({ get: async () => credential() });
+  let requests = 0;
+  mockGlobal('fetch', async () => ++requests === 1 ? Response.json({ ceremonyId: 'challenge-3', options: { challenge: encoded } }) : new Response('{}', { status: 401 }));
+  await assert.rejects(authenticatePasskey(), error => error instanceof AuthError && error.status === 401);
+});
+
+test('unavailable service and network errors provide actionable messages', async () => {
+  mockGlobal('fetch', async () => new Response('{}', { status: 404 }));
+  await assert.rejects(authRequest('/passkeys'), /not available/);
+  mockGlobal('fetch', async () => { throw new TypeError('Network error'); });
+  await assert.rejects(authRequest('/session'), /Check your connection/);
+});

