+// Module scripts run after parsing, so the server-provided card trees are ready.
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['favorite'];
+
+  #button;
+
+  get favorite() {
+    return this.hasAttribute('favorite');
+  }
+
+  set favorite(value) {
+    this.toggleAttribute('favorite', Boolean(value));
+  }
+
+  connectedCallback() {
+    // Older browsers leave DSD templates inert. Reuse that same markup there.
+    // Never attach over an existing root: that would clear the server's DOM.
+    if (!this.shadowRoot) {
+      const template = this.querySelector('template[shadowrootmode="open"]');
+      if (!template) return;
+      this.attachShadow({ mode: 'open' }).append(template.content);
+      template.remove();
+    }
+
+    // Reconnecting a card must preserve both its nodes and its single listener.
+    if (this.#button) return;
+    this.#button = this.shadowRoot.getElementById('favorite');
+    if (!this.#button) return;
