@@ -0,0 +1,68 @@
+import assert from 'node:assert/strict';
+import { readFile, readdir, stat } from 'node:fs/promises';
+import path from 'node:path';
+
+const root = process.cwd();
+const headers = await readFile('_headers', 'utf8');
+const csp = headers.match(/^  Content-Security-Policy: (.+)$/m)?.[1];
+assert(csp, 'An enforced HTTP Content-Security-Policy is required.');
+for (const directive of [
+  "default-src 'none'", "script-src 'none'", "style-src 'self'",
+  "img-src 'self'", "connect-src 'none'", "object-src 'none'",
+  "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'",
+  "require-trusted-types-for 'script'", "trusted-types 'none'",
+]) {
+  assert(csp.split('; ').includes(directive), `Missing CSP directive: ${directive}`);
+}
+for (const header of [
+  'Referrer-Policy: no-referrer', 'X-Content-Type-Options: nosniff',
+  'X-Frame-Options: DENY', 'Cross-Origin-Resource-Policy: same-origin',
+  'Cross-Origin-Opener-Policy: same-origin-allow-popups',
+  'Strict-Transport-Security: max-age=300',
+]) assert(headers.includes(header), `Missing header: ${header}`);
+for (const feature of ['camera', 'microphone', 'geolocation', 'payment', 'browsing-topics']) {
+  assert(headers.includes(`${feature}=()`), `${feature} must be disabled.`);
+}
+
+async function localAsset(url) {
+  assert(/^\/(?!\/)[\w/.-]+$/.test(url), `Resource must use a plain same-origin path: ${url}`);
+  const file = path.resolve(root, `.${url}`);
+  assert(file.startsWith(`${root}${path.sep}`), 'Resource escapes the site directory.');
+  assert((await stat(file)).isFile(), `Missing local resource: ${url}`);
+}
+
+async function htmlFiles(directory) {
+  const files = [];
+  for (const entry of await readdir(directory, { withFileTypes: true })) {
+    const file = path.join(directory, entry.name);
+    if (entry.isDirectory()) files.push(...await htmlFiles(file));
+    else {
+      assert(entry.isFile() && file.endsWith('.html'), `Unaudited published file: ${file}`);
+      files.push(file);
+    }
+  }
+  return files;
+}
+const pages = ['index.html', ...await htmlFiles('privacy-policy')];
+for (const file of pages) {
+  const html = await readFile(file, 'utf8');
+  assert(!/<(?:script|iframe|object|embed|form|input|textarea|select|style|base)\b/i.test(html),
+    `${file}: data collection, inline styles, scripts, and embeds require a fresh privacy review.`);
+  assert(!/\s(?:on[\w]+|style|ping|srcset)\s*=/i.test(html), `${file}: unsafe or unaudited attribute.`);
+  assert(!/(?:javascript:|data:|https?:\/\/|\/\/[^\s<])/i.test(html), `${file}: unaudited external URL.`);
+  const meta = html.match(/<meta http-equiv="Content-Security-Policy" content="([^"]+)">/)?.[1];
+  assert.equal(`${meta}; frame-ancestors 'none'`, csp, `${file}: meta and HTTP CSP drifted.`);
+  assert(html.includes('<meta name="referrer" content="no-referrer">'), `${file}: missing referrer fallback.`);
+  for (const match of html.matchAll(/\b(?:src|href)="([^"]+)"/g)) {
+    const url = match[1];
+    if (/\.(?:css|js|jpg|png|webp|svg)$/.test(url)) await localAsset(url);
+  }
+}
+const assetNames = await readdir('assets');
+assert.deepEqual(assetNames.sort(), ['coffee.jpg', 'styles.css'], 'New assets require a privacy review.');
+const css = await readFile('assets/styles.css', 'utf8');
+assert(!/@import|https?:|\/\//i.test(css), 'External CSS resources are prohibited.');
+for (const match of css.matchAll(/url\(['"]?([^'"\s)]+)['"]?\)/g)) await localAsset(match[1]);
+const pkg = JSON.parse(await readFile('package.json', 'utf8'));
+assert.equal(Object.keys(pkg.dependencies ?? {}).length, 0, 'New runtime dependencies require a privacy review.');
+console.log('Privacy audit passed: local assets, no client scripts or collection, matching restrictive policies.');
