new file mode 100644
index 0000000..8242837
--- /dev/null
+++ b/tests/privacy.test.mjs
@@ -0,0 +1,73 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile, readdir, stat } from 'node:fs/promises';
+
+const root = new URL('../', import.meta.url);
+const read = (path) => readFile(new URL(path, root), 'utf8');
+const pages = ['index.html', 'privacy-policy/index.html'];
+
+test('all published HTML avoids active content and collection surfaces', async () => {
+  for (const path of pages) {
+    const html = await read(path);
+    assert.doesNotMatch(html, /<(script|iframe|object|embed|form|input|textarea|select)\b/i, path);
+    assert.doesNotMatch(html, /\s(?:on\w+|style|ping|srcdoc)\s*=/i, path);
+    for (const [, url] of html.matchAll(/(?:src|href|action)\s*=\s*["']([^"']*)["']/gi)) {
+      assert.match(url, /^\/(?!\/)[^\s?#]*$/, `${path}: unexpected destination ${url}`);
+    }
+    assert.doesNotMatch(html, /<link[^>]*\b(?:preconnect|dns-prefetch|prefetch|prerender)\b/i);
+    assert.match(html, /<meta name="referrer" content="no-referrer">/);
+  }
+});
+
+test('local stylesheet and photo need no third-party resource or client script', async () => {
+  const css = await read('assets/styles.css');
+  assert.doesNotMatch(css, /@import|https?:|\/\/|data:|expression\s*\(/i);
+  for (const [, url] of css.matchAll(/url\(['"]?([^'"\s)]+)['"]?\)/g)) {
+    assert.match(url, /^\/assets\//);
+    assert.ok((await stat(new URL(url.slice(1), root))).isFile());
+  }
+  assert.ok((await stat(new URL('assets/coffee-hero.jpg', root))).size > 1000);
+  assert.deepEqual((await readdir(new URL('assets/', root))).sort(), ['coffee-hero.jpg', 'styles.css']);
+  const pkg = JSON.parse(await read('package.json'));
+  assert.equal(Object.keys(pkg.dependencies ?? {}).length, 0);
+});
+
+test('CSP and headers deny data transmission, execution, and sensitive permissions', async () => {
+  const headers = JSON.parse(await read('security-headers.json'));
+  const directives = new Map(headers['Content-Security-Policy'].split(';').map((s) => {
+    const [key, ...values] = s.trim().split(/\s+/);
+    return [key, values.join(' ')];
+  }));
+  for (const key of ['default-src', 'script-src', 'connect-src', 'form-action', 'base-uri', 'frame-ancestors', 'worker-src', 'object-src', 'frame-src']) {
+    assert.equal(directives.get(key), "'none'", key);
+  }
+  assert.equal(directives.get('style-src'), "'self'");
+  assert.equal(directives.get('img-src'), "'self'");
+  assert.equal(headers['Referrer-Policy'], 'no-referrer');
+  assert.equal(headers['Cache-Control'], 'no-store');
+  assert.equal(headers['X-Content-Type-Options'], 'nosniff');
+  assert.equal(headers['X-Frame-Options'], 'DENY');
+  assert.match(headers['Strict-Transport-Security'], /^max-age=31536000$/);
+  for (const feature of ['camera', 'microphone', 'geolocation', 'payment', 'usb']) {
+    assert.ok(headers['Permissions-Policy'].includes(`${feature}=()`));
+  }
+  for (const page of pages) {
+    const html = await read(page);
+    const meta = html.match(/http-equiv="Content-Security-Policy" content="([^"]+)"/)[1];
+    assert.equal(meta, headers['Content-Security-Policy'].replace("; frame-ancestors 'none'; upgrade-insecure-requests", ''));
+    assert.ok(html.indexOf('http-equiv="Content-Security-Policy"') < html.indexOf('<link'));
+  }
+});
+
+test('build contains only public resources and applies every configured response header', async () => {
+  const headers = JSON.parse(await read('security-headers.json'));
+  const builtHeaders = await read('dist/_headers');
+  assert.equal(builtHeaders, '/*\n' + Object.entries(headers).map(([name, value]) => `  ${name}: ${value}\n`).join(''));
+  assert.deepEqual((await readdir(new URL('dist/', root))).sort(), ['_headers', 'assets', 'index.html', 'privacy-policy']);
+  for (const page of [...pages, 'assets/styles.css']) {
+    assert.equal(await read(`dist/${page}`), await read(page));
+  }
+  const home = await read('dist/index.html');
+  assert.match(home, /href="\/privacy-policy\/"/);
+  assert.doesNotMatch(home, /href="\/logout"/);
+});

