@@ -0,0 +1,18 @@
+const serviceUrl = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+// Keep authentication data out of URLs, referrers, cookies, and browser storage.
+export async function submitCredentials(action: 'login' | 'register', username: string, password: string): Promise<boolean> {
+  const response = await fetch(`${serviceUrl}/${action}`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    credentials: 'omit',
+    cache: 'no-store',
+    referrerPolicy: 'no-referrer',
+    redirect: 'error',
+    body: JSON.stringify({ username, password }),
+  });
+
+  // The UI only needs the outcome, never raw errors, account details, or tokens.
+  await response.body?.cancel();
+  return response.ok;
+}
