+import { test } from 'node:test';
+import { submitCredentials } from '../src/utils/auth.ts';
+
+for (const action of ['login', 'register']) {
+  test(`${action} sends only required credentials with privacy protections`, async (t) => {
+    const response = new Response('sensitive response', { status: 200 });
+    const fetchMock = t.mock.method(globalThis, 'fetch', async (url, options) => {
+      assert.equal(url, `https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/${action}`);
+      assert.equal(options.method, 'POST');
+      assert.deepEqual(JSON.parse(options.body), { username: 'reader', password: 'example-password1' });
+      assert.deepEqual(options.headers, { 'Content-Type': 'application/json' });
+      assert.equal(options.credentials, 'omit');
+      assert.equal(options.cache, 'no-store');
+      assert.equal(options.referrerPolicy, 'no-referrer');
+      assert.equal(options.redirect, 'error');
+      return response;
+    });
+
+    assert.equal(await submitCredentials(action, 'reader', 'example-password1'), true);
+    assert.equal(fetchMock.mock.callCount(), 1);
+    assert.equal(response.bodyUsed, true);
+  });
+}
+
+test('raw service failures are discarded even when the response is not JSON', async (t) => {
+  t.mock.method(globalThis, 'fetch', async () => new Response('account exists: private details', { status: 400 }));
+  assert.equal(await submitCredentials('register', 'reader', 'example-password1'), false);
+});
+
+test('network failures propagate to the form for generic error handling and cleanup', async (t) => {
+  t.mock.method(globalThis, 'fetch', async () => { throw new TypeError('network error'); });
+  await assert.rejects(submitCredentials('login', 'reader', 'example-password1'), TypeError);
+});

