@@ -0,0 +1,11 @@
+# The Daily Grind
+
+Requires Node.js 20 or newer. `npm start` serves the homepage and same-origin signup endpoint on `PORT` (default 11222); `HOST` defaults to `0.0.0.0`. Terminate HTTPS at your production reverse proxy and preserve the public Host header. Set `PUBLIC_ORIGIN` to the canonical public origin if the proxy rewrites Host.
+
+`POST /api/newsletter` accepts JSON or URL-encoded `email`. Successful submissions are appended to `data/newsletter.jsonl`, outside the explicit public asset routes. Set `NEWSLETTER_FILE` to an absolute path on persistent writable storage in production. These addresses stay on this server; no third-party mailing service or email delivery is configured. Protect and back up this file as customer data. Native form submissions work without JavaScript; the enhanced form handles policy blocks, network failures, timeouts, and HTTP failures with an accessible retry message.
+
+All responses enforce `Connection-Allowlist` for the response origin and exactly `https://images.unsplash.com`. Redirect and WebRTC exceptions are intentionally omitted, preserving their blocking defaults. Security reports go to the same-origin `/api/security-reports`; only aggregate report counts are logged, never report URLs or bodies.
+
+CSP provides a fallback with same-origin requests/forms, Unsplash images, nonce-authorized JavaScript, and no workers, frames, objects, or inline styles. Connection-Allowlist has limited browser support and cannot be polyfilled. In browsers that ignore it, CSP protects fetches, forms, and subresources but cannot fully restrict navigation, WebRTC, or speculative connections. Use a supporting browser where the complete connection boundary is required. The allowlisted photo host remains a trusted destination.
+
+`npm test` runs isolated handler and client checks with mocked requests; it starts no HTTP server and does not import `server.mjs`.
diff --git a/app.mjs b/app.mjs
new file mode 100644
index 0000000..9d126e3
--- /dev/null
+++ b/app.mjs
@@ -0,0 +1,136 @@
+import { randomBytes } from 'node:crypto';
+import { readFile, mkdir, appendFile } from 'node:fs/promises';
+import { resolve, dirname } from 'node:path';
+
+const root = new URL('./', import.meta.url);
+const assets = new Map([
+  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
+  ['/newsletter.js', ['newsletter.js', 'text/javascript; charset=utf-8']],
+]);
+
+function securityHeaders(res, nonce) {
+  // Apply to every response, including any future worker scripts and error pages.
+  res.setHeader('Connection-Allowlist', '(response-origin "https://images.unsplash.com"); report-to=security');
+  res.setHeader('Reporting-Endpoints', 'security="/api/security-reports"');
+  res.setHeader('Content-Security-Policy', [
+    "default-src 'none'",
+    `script-src 'nonce-${nonce}' 'strict-dynamic'`,
+    "script-src-attr 'none'",
+    "style-src 'self'",
+    "connect-src 'self'",
+    "img-src 'self' https://images.unsplash.com",
+    "form-action 'self'",
+    "worker-src 'none'",
+    "frame-src 'none'",
+    "object-src 'none'",
+    "base-uri 'none'",
+    "frame-ancestors 'none'",
+    "require-trusted-types-for 'script'",
+    "trusted-types 'none'",
+    'report-to security',
+  ].join('; '));
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'no-referrer');
+  res.setHeader('X-DNS-Prefetch-Control', 'off');
+  res.setHeader('Cache-Control', 'no-store');
+}
+
+function send(req, res, code, body, type = 'text/plain; charset=utf-8') {
+  res.writeHead(code, { 'Content-Type': type });
+  res.end(req.method === 'HEAD' ? undefined : body);
+}
+
+function result(req, res, code, message, ok = false) {
+  if (req.headers.accept?.includes('application/json')) {
+    send(req, res, code, JSON.stringify({ ok, message }), 'application/json; charset=utf-8');
+  } else {
+    // Messages are developer-authored constants. Never reflect customer input.
+    send(req, res, code, `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Newsletter | The Daily Grind</title><link rel="stylesheet" href="/styles.css"><main class="container"><h1>Newsletter signup</h1><p>${message}</p><a href="/">Back to The Daily Grind</a></main></html>`, 'text/html; charset=utf-8');
+  }
+}
+
+function readBody(req, limit) {
+  return new Promise((resolveBody, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > limit) {
+        chunks.length = 0;
+        reject(Object.assign(new Error('Too large'), { status: 413 }));
+      } else {
+        chunks.push(chunk);
+      }
+    });
+    req.on('end', () => resolveBody(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+    req.on('aborted', () => reject(new Error('Aborted')));
+  });
+}
+
+function isSameOrigin(req) {
+  const site = req.headers['sec-fetch-site'];
+  if (site && !['same-origin', 'none'].includes(site)) return false;
+  const origin = req.headers.origin;
+  if (!origin) return true; // Non-browser clients / older browsers; no authenticated state here.
+  try {
+    if (process.env.PUBLIC_ORIGIN) return origin === new URL(process.env.PUBLIC_ORIGIN).origin;
+    const url = new URL(origin);
+    return ['http:', 'https:'].includes(url.protocol) && url.host === req.headers.host;
+  } catch {
+    return false;
+  }
+}
+
+// Handler is separate from the listening entrypoint, so checks need no running server.
+export async function handleRequest(req, res) {
+  const nonce = randomBytes(18).toString('base64');
+  securityHeaders(res, nonce);
+  try {
+    const path = new URL(req.url, 'http://local.invalid').pathname;
+    if (path === '/api/newsletter' || path === '/api/security-reports') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        return result(req, res, 405, 'Please submit the signup form from the homepage.');
+      }
+      if (!isSameOrigin(req)) return result(req, res, 403, 'Please return to the homepage and try again.');
+      if (path === '/api/security-reports') {
+        const reports = JSON.parse(await readBody(req, 65536));
+        // Retain only aggregate counts: reports can contain emails or secrets in URLs.
+        const count = Array.isArray(reports) ? reports.length : 1;
+        console.info('Browser security reports received:', count);
+        return send(req, res, 204, '');
+      }
+      const contentType = req.headers['content-type']?.split(';')[0].trim();
+      if (!['application/json', 'application/x-www-form-urlencoded'].includes(contentType)) {
+        return result(req, res, 415, 'Please submit the signup form from the homepage.');
+      }
+      const raw = await readBody(req, 4096);
+      const data = contentType === 'application/json' ? JSON.parse(raw) : Object.fromEntries(new URLSearchParams(raw));
+      const email = typeof data?.email === 'string' ? data.email.trim() : '';
+      if (email.length > 254 || !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)) {
+        return result(req, res, 400, 'Please enter a valid email address and try again.');
+      }
+      const file = resolve(process.env.NEWSLETTER_FILE || new URL('data/newsletter.jsonl', root).pathname);
+      await mkdir(dirname(file), { recursive: true, mode: 0o700 });
+      await appendFile(file, JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n', { mode: 0o600 });
+      return result(req, res, 201, 'You’re on the list! Thanks for joining The Daily Grind.', true);
+    }
+    if (!['GET', 'HEAD'].includes(req.method)) {
+      res.setHeader('Allow', 'GET, HEAD');
+      return send(req, res, 405, 'Method not allowed');
+    }
+    if (path === '/' || path === '/index.html') {
+      const template = await readFile(new URL('index.html', root), 'utf8');
+      return send(req, res, 200, template.replace('{{SCRIPT_NONCE}}', nonce), 'text/html; charset=utf-8');
+    }
+    const asset = assets.get(path);
+    if (asset) return send(req, res, 200, await readFile(new URL(asset[0], root)), asset[1]);
+    return send(req, res, 404, 'Page not found');
+  } catch (error) {
+    const status = error.status || (error instanceof SyntaxError ? 400 : 503);
+    return result(req, res, status, status === 413
+      ? 'This request is too large. Please return to the signup form and try again.'
+      : 'We couldn’t complete your request. Please return to the homepage and try again.');
+  }
+}
diff --git a/app.test.mjs b/app.test.mjs
new file mode 100644
index 0000000..f267890
--- /dev/null
+++ b/app.test.mjs
@@ -0,0 +1,82 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { Readable } from 'node:stream';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { runInNewContext } from 'node:vm';
+import { handleRequest } from './app.mjs';
+
+async function request(path, { method = 'GET', body = '', headers = {} } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url: path, method, headers: { host: 'coffee.test', ...headers } });
+  const response = { headers: {}, setHeader(name, value) { this.headers[name.toLowerCase()] = value; },
+    writeHead(status, headers) { this.status = status; for (const [key, value] of Object.entries(headers)) this.setHeader(key, value); },
+    end(body) { this.body = body?.toString() || ''; } };
+  await handleRequest(req, response);
+  return response;
+}
+
+test('document enforces exact connection boundary, nonce CSP, and accessible form', async () => {
+  const res = await request('/');
+  assert.equal(res.status, 200);
+  assert.equal(res.headers['connection-allowlist'], '(response-origin "https://images.unsplash.com"); report-to=security');
+  assert.equal(res.headers['reporting-endpoints'], 'security="/api/security-reports"');
+  const nonce = res.body.match(/<script nonce="([^"]+)"/)[1];
+  assert.ok(res.headers['content-security-policy'].includes(`script-src 'nonce-${nonce}'`));
+  for (const directive of ["connect-src 'self'", "img-src 'self' https://images.unsplash.com", "form-action 'self'", "worker-src 'none'"]) {
+    assert.ok(res.headers['content-security-policy'].includes(directive));
+  }
+  assert.doesNotMatch(res.body, /<style|style=|\{\{SCRIPT_NONCE\}\}/);
+  assert.match(res.body, /action="\/api\/newsletter" method="post"/);
+  assert.match(res.body, /role="status"/);
+  assert.notEqual(nonce, (await request('/')).body.match(/<script nonce="([^"]+)"/)[1]);
+});
+
+test('signup persists valid addresses only, handles failures and supports native forms', async () => {
+  const dir = await mkdtemp(join(tmpdir(), 'daily-grind-'));
+  const previous = process.env.NEWSLETTER_FILE;
+  process.env.NEWSLETTER_FILE = join(dir, 'subscribers.jsonl');
+  const options = { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json', origin: 'https://coffee.test' } };
+  try {
+    const ok = await request('/api/newsletter', { ...options, body: 'email=customer%40example.com' });
+    assert.equal(ok.status, 201);
+    assert.equal(JSON.parse(ok.body).ok, true);
+    const saved = await readFile(process.env.NEWSLETTER_FILE, 'utf8');
+    assert.equal(JSON.parse(saved).email, 'customer@example.com');
+    assert.equal((await request('/api/newsletter', { ...options, body: 'email=invalid' })).status, 400);
+    assert.equal((await request('/api/newsletter', { ...options, body: 'x'.repeat(5000) })).status, 413);
+    assert.equal((await request('/api/newsletter', { ...options, headers: { ...options.headers, origin: 'https://attacker.test' }, body: 'email=bad%40example.com' })).status, 403);
+    assert.equal(await readFile(process.env.NEWSLETTER_FILE, 'utf8'), saved);
+    assert.equal((await request('/data/newsletter.jsonl')).status, 404);
+    const native = await request('/api/newsletter', { ...options, headers: { ...options.headers, accept: 'text/html' }, body: 'email=native%40example.com' });
+    assert.equal(native.status, 201);
+    assert.match(native.body, /You’re on the list/);
+    process.env.NEWSLETTER_FILE = dir; // A directory cannot be appended to.
+    const failed = await request('/api/newsletter', { ...options, body: 'email=customer%40example.com' });
+    assert.equal(failed.status, 503);
+    assert.equal(JSON.parse(failed.body).ok, false);
+  } finally {
+    if (previous === undefined) delete process.env.NEWSLETTER_FILE;
