--- /dev/null
+++ b/newsletter.js
@@ -0,0 +1,35 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (button.disabled) return;
+  button.disabled = true;
+  form.setAttribute('aria-busy', 'true');
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 15000);
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
+      body: new URLSearchParams({ email: form.elements.email.value }),
+      signal: controller.signal,
+      mode: 'same-origin',
+      redirect: 'error',
+    });
+    if (!response.ok) throw new Error('Signup failed');
+    const result = await response.json();
+    if (result.ok !== true) throw new Error('Signup not confirmed');
+    status.textContent = 'You’re on the list! Thanks for joining The Daily Grind.';
+    form.reset();
+  } catch {
+    // Policy blocks, offline connections, timeouts and server failures all reach here.
+    status.textContent = 'We couldn’t confirm your signup. Please check your connection and try again.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+    form.removeAttribute('aria-busy');
+  }
+});
