--- /dev/null
+++ b/app.mjs
@@ -0,0 +1,92 @@
+import { readFile, mkdir, appendFile } from 'node:fs/promises';
+import { resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+export const contentSecurityPolicy = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self'",
+  "font-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "object-src 'none'",
+  "frame-ancestors 'none'",
+].join('; ');
+
+const assets = new Map([
+  ['/', ['index.html', 'text/html; charset=utf-8']],
+  ['/index.html', ['index.html', 'text/html; charset=utf-8']],
+  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
+  ['/newsletter.js', ['newsletter.js', 'text/javascript; charset=utf-8']],
+]);
+
+async function saveSubscription(email) {
+  const directory = resolve(process.env.DATA_DIR || fileURLToPath(new URL('./data', import.meta.url)));
+  await mkdir(directory, { recursive: true, mode: 0o700 });
+  await appendFile(resolve(directory, 'newsletter.jsonl'),
+    JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n',
+    { mode: 0o600 });
+}
+
+export function createHandler({ save = saveSubscription } = {}) {
+  return async (req, res) => {
+    res.setHeader('Content-Security-Policy', contentSecurityPolicy);
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('Referrer-Policy', 'no-referrer');
+    res.setHeader('Cache-Control', 'no-store');
+
+    const send = (code, message) => {
+      res.statusCode = code;
+      res.setHeader('Content-Type', 'application/json; charset=utf-8');
+      res.end(JSON.stringify({ message }));
+    };
+
+    try {
+      const path = new URL(req.url, 'http://localhost').pathname;
+      if (path === '/api/newsletter') {
+        if (req.method !== 'POST') {
+          res.setHeader('Allow', 'POST');
+          return send(405, 'Please submit the signup form.');
+        }
+        const type = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+        if (!['application/json', 'application/x-www-form-urlencoded'].includes(type)) {
+          return send(415, 'Unsupported signup format.');
+        }
+        let body = '';
+        let size = 0;
+        req.setEncoding('utf8');
+        for await (const chunk of req) {
+          size += Buffer.byteLength(chunk);
+          if (size > 2048) return send(413, 'The signup request is too large.');
+          body += chunk;
+        }
+        let email;
+        try {
+          email = type === 'application/json' ? JSON.parse(body).email : new URLSearchParams(body).get('email');
+        } catch {
+          return send(400, 'Please provide a valid email address.');
+        }
+        if (typeof email !== 'string' || email.trim().length > 254 ||
+            !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email.trim())) {
+          return send(400, 'Please provide a valid email address.');
+        }
+        await save(email.trim());
+        return send(201, 'Thanks for signing up! You’re on the Daily Grind list.');
+      }
+      const asset = assets.get(path);
+      if (!asset) return send(404, 'Page not found.');
+      if (!['GET', 'HEAD'].includes(req.method)) {
+        res.setHeader('Allow', 'GET, HEAD');
+        return send(405, 'Method not allowed.');
+      }
+      const body = await readFile(new URL(asset[0], import.meta.url));
+      res.statusCode = 200;
+      res.setHeader('Content-Type', asset[1]);
+      res.end(req.method === 'HEAD' ? undefined : body);
+    } catch {
+      send(500, 'We couldn’t complete your request. Please try again later.');
+    }
+  };
+}
