@@ -0,0 +1,37 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+
+document.addEventListener('securitypolicyviolation', (event) => {
+  if (event.effectiveDirective === 'connect-src') {
+    status.textContent = 'A request was blocked to protect your information. Please try again.';
+  }
+});
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (!form.reportValidity()) return;
+  button.disabled = true;
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 10000);
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ email: form.elements.email.value.trim() }),
+      signal: controller.signal,
+      mode: 'same-origin',
+      redirect: 'error',
+    });
+    const result = await response.json();
+    if (!response.ok) throw new Error('Signup failed');
+    status.textContent = result.message;
+    form.reset();
+  } catch {
+    status.textContent = 'We couldn’t complete your signup. Please check your connection and try again.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+  }
+});
