--- /dev/null
+++ b/test/newsletter.test.mjs
@@ -0,0 +1,114 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { Readable } from 'node:stream';
+import { readFile } from 'node:fs/promises';
+import vm from 'node:vm';
+import { createHandler, contentSecurityPolicy } from '../app.mjs';
+
+async function request({ url = '/api/newsletter', method = 'POST', body = '{"email":"coffee@example.com"}', type = 'application/json', save = async () => {} } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url, method, headers: { 'content-type': type } });
+  const res = {
+    headers: {},
+    setHeader(name, value) { this.headers[name] = value; },
+    end(value) { this.body = value?.toString() || ''; },
+  };
+  await createHandler({ save })(req, res);
+  return res;
+}
+
+test('serves the homepage and local assets with restrictive response headers', async () => {
+  for (const url of ['/', '/index.html', '/styles.css', '/newsletter.js']) {
+    const res = await request({ url, method: 'GET' });
+    assert.equal(res.statusCode, 200);
+    assert.equal(res.headers['Content-Security-Policy'], contentSecurityPolicy);
+    assert.equal(res.headers['X-Content-Type-Options'], 'nosniff');
+  }
+  assert.match(contentSecurityPolicy, /default-src 'none'/);
+  assert.match(contentSecurityPolicy, /connect-src 'self';/);
+  assert.match(contentSecurityPolicy, /img-src 'self' https:\/\/images\.unsplash\.com;/);
+  assert.match(contentSecurityPolicy, /form-action 'self'/);
+  assert.match(contentSecurityPolicy, /base-uri 'none'/);
+  assert.doesNotMatch(contentSecurityPolicy, /unsafe-inline|unsafe-eval|\*/);
+  const page = await request({ url: '/', method: 'GET' });
+  assert.doesNotMatch(page.body, /<style|style=|<script(?![^>]*src=)/);
+  const missing = await request({ url: '/data/newsletter.jsonl', method: 'GET' });
+  assert.equal(missing.statusCode, 404);
+  assert.equal(missing.headers['Content-Security-Policy'], contentSecurityPolicy);
+});
+
+test('stores submitted addresses before confirming success, including native form posts', async () => {
+  const saved = [];
+  const save = async (email) => saved.push(email);
+  assert.equal((await request({ save })).statusCode, 201);
+  assert.equal((await request({ save, type: 'application/x-www-form-urlencoded', body: 'email=beans%40example.com' })).statusCode, 201);
+  assert.deepEqual(saved, ['coffee@example.com', 'beans@example.com']);
+});
+
+test('rejects invalid, oversized, unsupported, and malformed submissions without saving', async () => {
+  const save = async () => assert.fail('Invalid submissions must not be stored');
+  for (const body of ['{}', 'null', '{', '{"email":"invalid"}', '{"email":"a@b.com\\nBcc: other@example.com"}']) {
+    assert.equal((await request({ body, save })).statusCode, 400);
+  }
+  assert.equal((await request({ body: 'x'.repeat(2049), save })).statusCode, 413);
+  assert.equal((await request({ type: 'text/plain', save })).statusCode, 415);
+  assert.equal((await request({ method: 'GET', save })).statusCode, 405);
+});
+
+test('returns a customer-safe error when storage fails', async () => {
+  const res = await request({ save: async () => { throw new Error('private filesystem details'); } });
+  assert.equal(res.statusCode, 500);
+  assert.match(JSON.parse(res.body).message, /try again/);
+  assert.doesNotMatch(res.body, /filesystem/);
+});
+
+async function client(fetch) {
+  const listeners = {};
+  const button = { disabled: false };
+  const status = { textContent: '' };
+  const form = {
+    elements: { email: { value: 'coffee@example.com' } },
+    querySelector: () => button,
+    reportValidity: () => true,
+    reset() { this.resetCalled = true; },
+    addEventListener(name, fn) { listeners[name] = fn; },
+  };
+  const document = {
+    querySelector: (selector) => selector === '#newsletter-form' ? form : status,
+    addEventListener(name, fn) { listeners[name] = fn; },
+  };
+  vm.runInNewContext(await readFile(new URL('../newsletter.js', import.meta.url), 'utf8'), {
+    document, fetch, AbortController, setTimeout, clearTimeout,
+  });
+  return { listeners, button, status, form };
+}
+
+test('client submits only to its own endpoint and announces success', async () => {
+  const ui = await client(async (url, options) => {
+    assert.equal(url, '/api/newsletter');
+    assert.equal(options.mode, 'same-origin');
+    assert.equal(options.redirect, 'error');
+    assert.equal(JSON.parse(options.body).email, 'coffee@example.com');
+    return { ok: true, json: async () => ({ message: 'Thank you!' }) };
+  });
+  await ui.listeners.submit({ preventDefault() {} });
+  assert.equal(ui.status.textContent, 'Thank you!');
+  assert.equal(ui.form.resetCalled, true);
+  assert.equal(ui.button.disabled, false);
+});
+
+test('client announces network, HTTP, malformed-response, and CSP failures', async () => {
+  for (const fetch of [
+    async () => { throw new TypeError('Failed to fetch'); },
+    async () => ({ ok: false, json: async () => ({}) }),
+    async () => ({ ok: true, json: async () => { throw new Error('Invalid JSON'); } }),
+  ]) {
+    const ui = await client(fetch);
+    await ui.listeners.submit({ preventDefault() {} });
+    assert.match(ui.status.textContent, /couldn’t complete your signup/);
+    assert.equal(ui.button.disabled, false);
+    assert.equal(ui.form.resetCalled, undefined);
+    ui.listeners.securitypolicyviolation({ effectiveDirective: 'connect-src' });
+    assert.match(ui.status.textContent, /blocked to protect your information/);
+  }
+});

