+    let activeCard = null;
+    let navigating = false;
+    let listScroll = 0;
+    let detailScroll = 0;
+
+    async function navigate(card) {
+      if (navigating || (card === null && !activeCard)) return;
+      navigating = true;
+      const opening = card !== null;
+      if (opening) {
+        activeCard = card;
+        listScroll = window.scrollY;
+        detailScroll = Math.min(listScroll, listPage.offsetTop);
+        card.classList.add('selected');
+      }
+
+      const update = () => {
+        if (opening) {
+          const image = card.querySelector('img');
+          hero.src = image.currentSrc || image.src;
+          hero.alt = image.alt;
+          title.textContent = card.querySelector('.title').textContent;
+          document.getElementById('description').textContent = card.dataset.description;
+        }
+        listPage.hidden = opening;
+        detailPage.hidden = !opening;
+        window.scrollTo({ top: opening ? detailScroll : listScroll, behavior: 'instant' });
+      };
+
+      try {
+        if (document.startViewTransition && !reducedMotion.matches) {
+          const transition = document.startViewTransition(update);
+          // A skipped animation must still complete navigation and focus routing.
+          await transition.finished;
+        } else {
+          update();
+        }
+      } catch (error) {
+        // Animation failure is cosmetic; ensure the requested view is visible.
+        if (detailPage.hidden === opening) update();
+      } finally {
+        (opening ? title : listHeading).focus({ preventScroll: true });
+        if (!opening) {
+          activeCard.classList.remove('selected');
+          activeCard = null;
+        }
+        navigating = false;
+      }
+    }
+
+    cards.forEach(card => {
+      card.querySelector('a').addEventListener('click', event => {
+        event.preventDefault();
+        navigate(card);
+      });
+    });
