diff --git a/tests/reviews.test.cjs b/tests/reviews.test.cjs
new file mode 100644
index 0000000..a83caca
--- /dev/null
+++ b/tests/reviews.test.cjs
@@ -0,0 +1,79 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { JSDOM } = require('jsdom');
+
+function page(withSanitizer = true) {
+  const dom = new JSDOM(readFileSync('index.html', 'utf8'), { runScripts: 'outside-only' });
+  if (withSanitizer) dom.window.eval(readFileSync('vendor/purify.min.js', 'utf8'));
+  dom.window.eval(dom.window.document.querySelector('script:not([src])').textContent);
+  return dom;
+}
+
+function post(dom, index, name, html) {
+  const form = dom.window.document.querySelectorAll('.review-form')[index];
+  form.elements.namedItem('reviewer').value = name;
+  form.elements.namedItem('feedback').value = html;
+  form.dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
+  return form.closest('.reviews');
+}
+
+test('each drink renders rich feedback independently, with plain-text author names', () => {
+  const dom = page();
+  for (let i = 0; i < 3; i++) {
+    const section = post(dom, i, '<img src=x onerror=alert(1)>', '<p>Great <strong>coffee</strong> and <em>flavor</em>!</p><ul><li>Smooth</li></ul><a href="https://example.com" title="Details">Details</a>');
+    assert.equal(section.querySelector('.review-list > li > strong').textContent, '<img src=x onerror=alert(1)>');
+    assert.equal(section.querySelector('.review-body strong').textContent, 'coffee');
+    assert.equal(section.querySelector('.review-body li').textContent, 'Smooth');
+    assert.equal(section.querySelector('.review-body a').getAttribute('href'), 'https://example.com');
+    assert.equal(section.querySelectorAll('.review-list > li').length, 1);
+    assert.equal(section.querySelector('.review-empty').hidden, true);
+    assert.equal(section.querySelector('textarea').value, '');
+  }
+  dom.window.close();
+});
+
+test('removes executable elements, dangerous URLs, styles, handlers, and clobbering attributes', () => {
+  const dom = page();
+  const section = post(dom, 0, 'Customer', `
+    <script>window.compromised = true</script><iframe srcdoc="<script>alert(1)</script>"></iframe>
+    <img src=x onerror="window.compromised=true"><svg onload="window.compromised=true"><a href="javascript:alert(1)">SVG</a></svg>
+    <math><mtext><img src=x onerror=alert(1)></mtext></math>
+    <p id="DOMPurify" name="sanitize" style="position:fixed" onclick="alert(1)" data-x="x" aria-label="fake">Good <b>coffee</b></p>
+    <a href="jav&#x61;script:alert(1)" onmouseover="alert(1)">bad</a>
+    <a href="data:text/html,attack">data</a><a href="//evil.example">relative</a>
+    <a href="https://example.com" target="_blank">safe</a>
+    <form><input name="DOMPurify"></form><template><img src=x onerror=alert(1)></template>`);
+  const body = section.querySelector('.review-body');
+  assert.ok(body.textContent.includes('Good coffee'));
+  assert.equal(body.querySelector('script, iframe, img, svg, math, form, input, template'), null);
+  for (const element of body.querySelectorAll('*')) {
+    for (const attr of element.attributes) {
+      assert.ok(['href', 'title'].includes(attr.name), attr.name);
+      if (attr.name === 'href') assert.match(attr.value, /^https?:\/\//i);
+    }
+  }
+  assert.equal(dom.window.compromised, undefined);
+  dom.window.close();
+});
+
+test('rejects empty sanitized feedback and whitespace names, then allows a correction', () => {
+  const dom = page();
+  let section = post(dom, 0, 'Customer', '<script>alert(1)</script><img src=x>');
+  assert.equal(section.querySelectorAll('.review-list > li').length, 0);
+  assert.match(section.querySelector('.review-status').textContent, /visible text/);
+  section = post(dom, 0, '   ', '<p>Nice!</p>');
+  assert.equal(section.querySelectorAll('.review-list > li').length, 0);
+  section = post(dom, 0, 'Customer', '<p>Nice!</p>');
+  assert.equal(section.querySelectorAll('.review-list > li').length, 1);
+  dom.window.close();
+});
+
+test('fails closed if the sanitizer cannot load', () => {
+  const dom = page(false);
+  for (const button of dom.window.document.querySelectorAll('.review-form button')) assert.equal(button.disabled, true);
+  const section = post(dom, 0, 'Customer', '<img src=x onerror=alert(1)>');
+  assert.equal(section.querySelector('.review-list').children.length, 0);
+  assert.match(section.querySelector('.review-status').textContent, /unavailable/);
+  dom.window.close();
+});
