     .btn:hover {
       background: #3e2723;
     }

+    .operations {
+      margin-top: 48px;
+      padding: 28px;
+      border: 1px solid var(--secondary);
+      border-radius: 12px;
+      background: #fff;
+    }
+
+    .queue-heading, .queue-toolbar, .task-title {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 12px;
+      flex-wrap: wrap;
+    }
+
+    .eyebrow { font-size: .75rem; text-transform: uppercase; letter-spacing: .12em; }
+    .queue-description { margin: 8px 0 20px; max-width: 68ch; }
+    .queue-status { font-size: .8rem; border-radius: 20px; padding: 4px 12px; background: #edf3ec; color: #315c37; }
+    .task-controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
+    .task-button { padding: 16px; text-align: left; background: #faf8f6; color: var(--text); border: 1px solid var(--secondary); border-radius: 8px; cursor: pointer; font: inherit; }
+    .task-button strong, .task-button small { display: block; }
+    .task-button small { margin-top: 8px; font-size: .8rem; }
+    .task-button:hover { background: #f0e8e3; border-color: var(--primary); }
+    .priority { display: inline-block; font-size: .7rem; padding: 2px 8px; border-radius: 4px; margin-top: 8px; }
+    .urgent { color: #922f20; background: #fce8e1; }
+    .standard { color: #735009; background: #fff0c9; }
+    .background { color: #365c70; background: #e7f0f6; }
+    .queue-toolbar { margin: 20px 0; }
+    button.btn { border: 0; font: inherit; cursor: pointer; margin: 0; }
+    .reset-button { border: 0; background: none; color: var(--primary); text-decoration: underline; cursor: pointer; font: inherit; font-size: .85rem; }
+    button:disabled { cursor: not-allowed; opacity: .5; }
+    button:focus-visible { outline: 3px solid #a66016; outline-offset: 4px; }
+    .queue-stats { display: flex; gap: 24px; font-size: .85rem; margin-bottom: 20px; flex-wrap: wrap; }
+    .queue-stats strong { font-size: 1.3rem; margin-right: 4px; }
+    .queue-panels { display: grid; grid-template-columns: 1.15fr 1fr; gap: 24px; border-top: 1px solid #eee7e3; padding-top: 20px; }
+    .queue-panels h3 { font-size: .9rem; margin-bottom: 12px; }
+    .task-list, .activity-log { list-style: none; max-height: 290px; overflow-y: auto; padding-right: 6px; }
+    .task-row { padding: 10px 0; border-bottom: 1px solid #eee7e3; font-size: .85rem; }
+    .task-row .priority { margin: 0; }
+    .task-detail { display: flex; justify-content: space-between; gap: 12px; margin-top: 6px; font-size: .75rem; color: #715b52; }
+    .task-row progress { display: block; width: 100%; height: 6px; margin-top: 8px; accent-color: var(--primary); }
+    .activity-log { font-size: .8rem; color: #715b52; }
+    .activity-log li { padding: 7px 0; border-bottom: 1px solid #eee7e3; }
+    .activity-log time { font-variant-numeric: tabular-nums; margin-right: 8px; }
+    .queue-empty { color: #715b52; font-size: .85rem; padding: 16px 0; }
+    .queue-note { margin-top: 20px; font-size: .75rem; color: #715b52; }
+    @media (max-width: 650px) {
+      .operations { padding: 20px; }
+      .task-controls, .queue-panels { grid-template-columns: 1fr; }
+    }
+
     footer {
       background: var(--secondary);
       text-align: center;
       padding: 40px 20px;
