+        telemetry: { name: 'Telemetry logging', priority: 2, label: 'Background', steps: 100 }
+      };
+      const queue = [];
+      let sequence = 0;
+      let completed = 0;
+      let processing = false;
+      let activeTask = null;
+      const get = (id) => document.getElementById(id);
+
+      function log(message) {
+        const item = document.createElement('li');
+        const time = document.createElement('time');
+        const now = new Date();
+        time.dateTime = now.toISOString();
+        time.textContent = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
+        const text = document.createElement('span');
+        text.textContent = message;
+        item.append(time, text);
+        get('activity-list').prepend(item);
+        while (get('activity-list').children.length > 30) get('activity-list').lastElementChild.remove();
+        get('activity-placeholder').hidden = true;
+      }
+
+      function render() {
+        get('queued-count').textContent = queue.length - (activeTask ? 1 : 0);
+        get('running-count').textContent = activeTask ? 1 : 0;
+        get('completed-count').textContent = completed;
+        get('queue-status').textContent = queue.length ? 'Processing' : 'Ready';
+        const list = get('queue-list');
+        if (!queue.length) {
+          list.innerHTML = '<div class="queue-empty"><strong>All caught up.</strong>Run a task or a mixed batch to get started.</div>';
+          return;
+        }
+        list.replaceChildren(...queue.map((task) => {
+          const row = document.createElement('div');
+          row.className = 'task-row';
+          // Names and labels come exclusively from the fixed definitions above.
+          row.innerHTML = `<div class="task-topline"><span class="task-name">${task.name} #${task.id}</span><span class="task-state">${task === activeTask ? 'Running' : task.done ? 'Paused' : 'Queued'}</span></div><div class="task-detail"><span>${task.label} priority</span><span>${Math.floor(task.done / task.steps * 100)}%</span></div><progress class="task-progress" max="${task.steps}" value="${task.done}" aria-label="${task.name} #${task.id} progress"></progress>`;
+          return row;
+        }));
+      }
+
+      function enqueue(types) {
+        for (const type of types) {
+          const task = { ...definitions[type], id: ++sequence, done: 0 };
+          queue.push(task);
+          log(`${task.name} #${task.id} queued · ${task.label.toLowerCase()}`);
+        }
+        // FIFO for equal priorities; reconsider priorities after every short slice.
+        queue.sort((a, b) => a.priority - b.priority || a.id - b.id);
+        render();
+        if (!processing) void processQueue();
+      }
+
+      async function processQueue() {
+        processing = true;
+        try {
+          while (queue.length) {
+            const task = queue[0];
+            if (activeTask !== task) {
+              if (activeTask) log(`${activeTask.name} #${activeTask.id} paused for higher-priority work`);
+              activeTask = task;
+              log(`${task.name} #${task.id} ${task.done ? 'resumed' : 'started'}`);
+              get('queue-announcement').textContent = `${task.name} running. ${queue.length - 1} tasks waiting.`;
+            }
+            // Bound each work slice to 3ms, then yield to input and painting.
+            const deadline = performance.now() + 3;
+            let value = 0;
+            while (performance.now() < deadline) value = Math.sqrt(value + 123.456);
+            task.done++;
