+]);
+const directives = new Set([
+  'default-src', 'script-src', 'script-src-elem', 'script-src-attr', 'style-src',
+  'style-src-elem', 'style-src-attr', 'img-src', 'connect-src', 'font-src',
+  'object-src', 'base-uri', 'frame-ancestors', 'form-action', 'frame-src',
+  'worker-src', 'require-trusted-types-for', 'trusted-types',
+]);
+
+function createHandler({ origin = process.env.PUBLIC_ORIGIN, log = console.info } = {}) {
+  // Never use untrusted Host/Forwarded headers for the reporting destination.
+  if (origin) {
+    const url = new URL(origin);
+    if (url.protocol !== 'https:' || url.origin !== origin) {
+      throw new Error('PUBLIC_ORIGIN must be an HTTPS origin without a trailing slash');
+    }
+  }
+  const html = fs.readFileSync(path.join(__dirname, 'index.html'));
+  const css = fs.readFileSync(path.join(__dirname, 'styles.css'));
+  const policy = [
+    "default-src 'none'", "script-src 'none' 'report-sample'",
+    "script-src-attr 'none'", "style-src 'self'", "style-src-attr 'none'",
+    'img-src https://images.unsplash.com', "connect-src 'none'",
+    "object-src 'none'", "base-uri 'none'", "frame-ancestors 'none'",
+    "form-action 'self'", "require-trusted-types-for 'script'", "trusted-types 'none'",
+    'report-uri /security-reports', ...(origin ? ['report-to default'] : []),
+  ].join('; ');
+
+  return async function handle(req, res) {
+    res.setHeader('Content-Security-Policy', policy);
+    res.setHeader('X-Frame-Options', 'DENY');
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('Referrer-Policy', 'no-referrer');
+    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=()');
+    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+    res.setHeader('Cache-Control', 'no-store');
+    res.setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+    if (origin) {
+      res.setHeader('Reporting-Endpoints', `default="${origin}/security-reports"`);
+      // Short initial lifetime; HTTPS terminates at the deployment proxy.
+      res.setHeader('Strict-Transport-Security', 'max-age=300');
+    } else if (req.socket?.encrypted) {
+      res.setHeader('Strict-Transport-Security', 'max-age=300');
+    }
+
+    function send(status, body = '', type = 'text/plain; charset=utf-8') {
+      res.statusCode = status;
+      if (status === 204) return res.end();
+      res.setHeader('Content-Type', type);
+      res.setHeader('Content-Length', Buffer.byteLength(body));
+      res.end(req.method === 'HEAD' ? undefined : body);
+    }
+
+    let pathname;
+    try {
+      if (!req.url.startsWith('/') || req.url.startsWith('//')) throw new Error();
+      pathname = new URL(req.url, 'http://localhost').pathname;
+    } catch {
+      return send(400, 'Bad request');
+    }
+    const site = req.headers['sec-fetch-site'];
+    const untrusted = site === 'cross-site' || site === 'same-site';
+    const navigation = req.method === 'GET' && req.headers['sec-fetch-mode'] === 'navigate'
+      && req.headers['sec-fetch-dest'] === 'document';
+    if (untrusted && !navigation) return send(403, 'Forbidden');
+
+    if (pathname === '/security-reports') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        return send(405, 'Method not allowed');
+      }
+      const type = (req.headers['content-type'] || '').split(';')[0].trim();
+      if (!['application/csp-report', 'application/reports+json', 'application/json'].includes(type)) {
+        return send(415, 'Unsupported media type');
+      }
+      // Reports are untrusted: bound memory and never log URLs, samples or identifiers.
+      let size = 0;
+      const chunks = [];
+      try {
+        for await (const chunk of req.iterator({ destroyOnReturn: false })) {
+          size += Buffer.byteLength(chunk);
+          if (size > 16384) {
+            // Drain without buffering; breaking the default iterator destroys HTTP sockets.
+            req.resume();
+            return send(413, 'Report too large');
+          }
+          chunks.push(Buffer.from(chunk));
+        }
+        const payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+        const reports = Array.isArray(payload) ? payload : [payload];
+        if (reports.length > 50) return send(413, 'Too many reports');
+        const counts = Object.create(null);
+        for (const report of reports) {
+          const body = report?.['csp-report'] || report?.body;
+          const directive = body?.['effective-directive'] || body?.effectiveDirective;
+          if (directives.has(directive)) counts[directive] = (counts[directive] || 0) + 1;
+        }
+        if (Object.keys(counts).length) log(JSON.stringify({ securityViolations: counts }));
+        return send(204);
+      } catch {
+        return send(400, 'Invalid report');
+      }
+    }
+
+    if (!['GET', 'HEAD'].includes(req.method)) {
+      res.setHeader('Allow', 'GET, HEAD');
+      return send(405, 'Method not allowed');
+    }
+    if (pathname === '/logout' || pathname === '/logout/') {
+      // Third-party links, speculative loads and HEAD must not sign visitors out.
+      if (untrusted || req.headers['sec-purpose']?.includes('prefetch')
+        || req.headers.purpose === 'prefetch') return send(403, 'Forbidden');
+      if (req.method === 'HEAD') return send(200);
+      res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+      // Root-path cookie fallback for clients without Clear-Site-Data support.
+      const names = new Set(['session', '__Host-session']);
+      for (const cookie of (req.headers.cookie || '').split(';')) {
+        const name = cookie.split('=')[0].trim();
+        if (/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(name)) names.add(name);
+      }
+      res.setHeader('Set-Cookie', [...names].map(name =>
+        `${name}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; SameSite=Lax${origin || req.socket?.encrypted || name.startsWith('__Host-') || name.startsWith('__Secure-') ? '; Secure' : ''}`));
+      return send(200, '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Signed out | The Daily Grind</title></head><body><main><h1>You are signed out</h1><p><a href="/">Return to The Daily Grind</a></p></main></body></html>', 'text/html; charset=utf-8');
+    }
+    if (pathname === '/styles.css') return send(200, css, 'text/css; charset=utf-8');
+    if (pages.has(pathname)) return send(200, html, 'text/html; charset=utf-8');
+    return send(404, 'Not found');
+  };
+}
+module.exports = { createHandler };
