new file mode 100644
index 0000000..bd2a75a
--- /dev/null
+++ b/test/security.test.js
@@ -0,0 +1,112 @@
+'use strict';
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { Readable } = require('node:stream');
+const fs = require('node:fs');
+const { createHandler } = require('../app');
+
+// Exercise HTTP semantics in memory; never import server.js or open a listener.
+async function request(url, { method = 'GET', headers = {}, body = '', handler = createHandler({ origin: 'https://coffee.example' }) } = {}) {
+  const req = Readable.from(body ? [body] : []);
+  Object.assign(req, { url, method, headers, socket: {} });
+  const res = { headers: {}, setHeader(name, value) { this.headers[name] = value; }, end(body) { this.body = body; } };
+  await handler(req, res);
+  return res;
+}
+
+test('pages and stylesheet work with strict CSP and correct MIME types', async () => {
+  const home = await request('/');
+  assert.equal(home.statusCode, 200);
+  assert.match(home.headers['Content-Security-Policy'], /script-src 'none'/);
+  assert.match(home.headers['Content-Security-Policy'], /require-trusted-types-for 'script'/);
+  assert.match(home.headers['Content-Security-Policy'], /trusted-types 'none'/);
+  assert.match(home.headers['Content-Security-Policy'], /img-src https:\/\/images.unsplash.com/);
+  assert.equal(home.headers['Reporting-Endpoints'], 'default="https://coffee.example/security-reports"');
+  assert.equal(home.headers['X-Frame-Options'], 'DENY');
+  assert.equal(home.headers['X-Content-Type-Options'], 'nosniff');
+  const html = String(home.body);
+  assert.doesNotMatch(html, /<script\b|<style\b|\sstyle=|\son\w+=|javascript:/i);
+  assert.match(html, /href="\/styles.css"/);
+  for (const [, link] of html.matchAll(/href="(\/[^"#]*)"/g)) {
+    assert.equal((await request(link)).statusCode, 200, link);
+  }
+  const css = await request('/styles.css');
+  assert.equal(css.headers['Content-Type'], 'text/css; charset=utf-8');
+  assert.equal(String(css.body), fs.readFileSync('styles.css', 'utf8'));
+});
+
+test('logout clears browser state and expires incoming cookies without echoing values', async () => {
+  for (const url of ['/logout', '/logout/']) {
+    const res = await request(url, { headers: { cookie: 'session=secret; other=private', 'sec-fetch-site': 'same-origin' } });
+    assert.equal(res.statusCode, 200);
+    assert.equal(res.headers['Clear-Site-Data'], '"cookies", "storage", "cache"');
+    assert.equal(res.headers['Cache-Control'], 'no-store');
+    for (const name of ['session', 'other', '__Host-session']) {
+      assert.ok(res.headers['Set-Cookie'].some(cookie => cookie.startsWith(`${name}=;`) && cookie.includes('Max-Age=0') && cookie.includes('Secure')));
+    }
+    assert.doesNotMatch(JSON.stringify(res), /secret|private/);
+  }
+});
+
+test('cross-site logout, prefetch and HEAD cannot clear state', async () => {
+  for (const options of [
+    { headers: { 'sec-fetch-site': 'cross-site', 'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'document' } },
+    { headers: { 'sec-fetch-site': 'same-site' } },
+    { headers: { 'sec-purpose': 'prefetch' } },
+    { method: 'HEAD' },
+  ]) {
+    const res = await request('/logout', options);
+    assert.equal(res.headers['Clear-Site-Data'], undefined);
+    assert.equal(res.headers['Set-Cookie'], undefined);
+  }
+});
+
+test('resource isolation allows incoming page links but rejects foreign subresource reads', async () => {
+  const headers = { 'sec-fetch-site': 'cross-site', 'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'document' };
+  assert.equal((await request('/', { headers })).statusCode, 200);
+  assert.equal((await request('/styles.css', { headers: { ...headers, 'sec-fetch-mode': 'no-cors', 'sec-fetch-dest': 'style' } })).statusCode, 403);
+  assert.equal((await request('/')).headers.Vary, 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+});
+
+test('project files, invalid URLs and unsupported methods are not served', async () => {
+  for (const url of ['/server.js', '/package.json', '/.git/config', '/unknown', '/%2e%2e/package.json']) {
+    const res = await request(url);
+    assert.equal(res.statusCode, 404);
+    assert.ok(res.headers['Content-Security-Policy']);
+  }
+  assert.equal((await request('//attacker.example/')).statusCode, 400);
+  assert.equal((await request('/', { method: 'POST' })).statusCode, 405);
+  assert.equal((await request('/', { method: 'HEAD' })).body, undefined);
+});
+
+test('both reporting formats log only allowlisted directive counts', async () => {
+  const logs = [];
+  const handler = createHandler({ origin: 'https://coffee.example', log: value => logs.push(value) });
+  for (const body of [
+    { 'csp-report': { 'effective-directive': 'script-src', 'document-uri': 'https://coffee.example/?secret', 'script-sample': 'private' } },
+    [{ type: 'csp-violation', body: { effectiveDirective: 'script-src', sourceFile: 'private' } }],
+  ]) {
+    const res = await request('/security-reports', { method: 'POST', headers: { 'content-type': 'application/reports+json' }, body: JSON.stringify(body), handler });
+    assert.equal(res.statusCode, 204);
+  }
+  assert.deepEqual(logs, Array(2).fill('{"securityViolations":{"script-src":1}}'));
+});
+
+test('report ingestion rejects malformed, oversized and foreign submissions', async () => {
+  const options = { method: 'POST', headers: { 'content-type': 'application/csp-report' } };
+  assert.equal((await request('/security-reports', { ...options, body: '{' })).statusCode, 400);
+  assert.equal((await request('/security-reports', { ...options, body: 'x'.repeat(16385) })).statusCode, 413);
+  assert.equal((await request('/security-reports', { ...options, body: JSON.stringify(Array(51).fill({})) })).statusCode, 413);
+  assert.equal((await request('/security-reports', { ...options, headers: { 'content-type': 'text/plain' } })).statusCode, 415);
+  assert.equal((await request('/security-reports', { ...options, headers: { ...options.headers, 'sec-fetch-site': 'cross-site' } })).statusCode, 403);
+});
+
+test('production origin is explicit and local HTTP does not receive HSTS', async () => {
+  for (const origin of ['http://coffee.example', 'https://coffee.example/', 'https://user:pass@coffee.example']) {
