@@ -0,0 +1,109 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const vm = require('node:vm');
+
+function setup({ webOtp = false, responses = [] } = {}) {
+  const ids = ['phone-form', 'otp-form', 'phone', 'otp', 'send-code', 'verify-code', 'resend-code', 'phone-error', 'otp-error', 'verification-status', 'resend-row', 'purpose-rewards', 'purpose-order'];
+  const elements = Object.fromEntries(ids.map(id => [id, {
+    value: '', textContent: '', attributes: {}, handlers: {}, hidden: false,
+    addEventListener(event, handler) { this.handlers[event] = handler; },
+    setAttribute(key, value) { this.attributes[key] = value; },
+    removeAttribute(key) { delete this.attributes[key]; },
+    focus() { this.focused = true; },
+    reportValidity() { return true; },
+    requestSubmit() { this.submitted = this.handlers.submit({ preventDefault() {} }); },
+  }]));
+  elements['phone-form'].action = 'https://daily.example/api/auth/sms/send';
+  elements['otp-form'].action = 'https://daily.example/api/auth/sms/verify';
+  elements['purpose-rewards'].value = 'rewards';
+  elements['purpose-order'].value = 'order';
+  elements['phone'].value = '+1 (415) 555-0123';
+  const calls = [], events = {}, sms = {}, timers = new Map();
+  let timerId = 0;
+  const window = { isSecureContext: true, location: { assign(path) { calls.push({ redirect: path }); } }, addEventListener(name, fn) { events[name] = fn; } };
+  if (webOtp) window.OTPCredential = class {};
+  const context = {
+    document: {
+      getElementById: id => elements[id],
+      querySelector: () => elements['purpose-rewards'],
+      querySelectorAll: selector => selector === '[data-purpose]' ? [] : [elements['purpose-rewards'], elements['purpose-order']],
+    }, window, AbortController,
+    navigator: { credentials: { get(options) {
+      sms.signal = options.signal;
+      return new Promise(resolve => { sms.resolve = resolve; });
+    } } },
+    setTimeout: fn => { timers.set(++timerId, fn); return timerId; },
+    clearTimeout: id => timers.delete(id), setInterval: () => ++timerId, clearInterval() {},
+    fetch: async (url, options) => {
+      calls.push({ url, body: JSON.parse(options.body) });
+      const result = responses.shift() || { status: 200, data: { challengeId: 'challenge-1' } };
+      return { ok: result.status === 200, status: result.status, headers: { get: () => result.html ? 'text/html' : 'application/json' }, json: async () => result.data };
+    },
+  };
+  vm.runInNewContext(fs.readFileSync('verification.js', 'utf8'), context);
+  const submit = id => elements[id].handlers.submit({ preventDefault() {} });
+  return { elements, calls, sms, events, submit };
+}
+
+test('requests an SMS, preserves leading zeros, and continues only after server verification', async () => {
+  const app = setup({ responses: [{ status: 200, data: { challengeId: 'server-id' } }, { status: 200, data: { verified: true } }] });
+  await app.submit('phone-form');
+  assert.equal(app.calls[0].body.phone, '+14155550123');
+  assert.equal(app.elements['resend-row'].hidden, false);
+  app.elements.otp.value = '012345';
+  await app.submit('otp-form');
+  assert.deepEqual(app.calls[1].body, { challengeId: 'server-id', code: '012345', purpose: 'rewards' });
+  assert.equal(app.calls[2].redirect, '/rewards');
+});
+
+test('an unavailable static endpoint never claims to send a code or authenticate', async () => {
+  const app = setup({ responses: [{ status: 404, html: true }] });
+  await app.submit('phone-form');
+  assert.match(app.elements['phone-error'].textContent, /unavailable/);
+  assert.equal(app.elements['verification-status'].textContent, '');
+  app.elements.otp.value = '123456';
+  await app.submit('otp-form');
+  assert.equal(app.calls.length, 1);
+  assert.match(app.elements['phone-error'].textContent, /Request a code/);
+});
+
+test('WebOTP fills and submits through the handler, and aborts its listener', async () => {
+  const app = setup({ webOtp: true, responses: [{ status: 200, data: { challengeId: 'id' } }, { status: 200, data: { verified: true } }] });
+  await app.submit('phone-form');
+  app.sms.resolve({ code: '012345' });
+  await new Promise(resolve => setImmediate(resolve));
+  assert.equal(app.elements.otp.value, '012345');
+  assert.equal(app.calls[1].body.code, '012345');
+  assert.equal(app.sms.signal.aborted, true);
+});
+
+test('changing the number invalidates the challenge and discards late SMS results', async () => {
+  const app = setup({ webOtp: true });
+  await app.submit('phone-form');
+  app.elements.phone.value = '+14155550199';
+  app.elements.phone.handlers.input();
+  assert.equal(app.sms.signal.aborted, true);
+  app.sms.resolve({ code: '999999' });
+  await new Promise(resolve => setImmediate(resolve));
+  assert.equal(app.elements.otp.value, '');
+  assert.equal(app.calls.length, 1);
+});
+
+test('server rejection stays on the code field and never redirects', async () => {
+  const app = setup({ responses: [{ status: 200, data: { challengeId: 'id' } }, { status: 401, data: {} }] });
+  await app.submit('phone-form');
+  app.elements.otp.value = '999999';
+  await app.submit('otp-form');
+  assert.match(app.elements['otp-error'].textContent, /incorrect or expired/);
+  assert.equal(app.elements.otp.attributes['aria-invalid'], 'true');
+  assert.equal(app.calls.length, 2);
+  assert.equal(app.elements['verify-code'].disabled, false);
+});
+
+test('page exit aborts pending SMS extraction', async () => {
+  const app = setup({ webOtp: true });
+  await app.submit('phone-form');
+  app.events.pagehide();
+  assert.equal(app.sms.signal.aborted, true);
+});
