+/* Real SMS delivery and verification require the server contract in SMS-INTEGRATION.md.
+   Codes and authentication decisions must never be generated or trusted in the client. */
+(() => {
+  const phoneForm = document.getElementById('phone-form');
+  const otpForm = document.getElementById('otp-form');
+  const phone = document.getElementById('phone');
+  const otp = document.getElementById('otp');
+  const send = document.getElementById('send-code');
+  const verify = document.getElementById('verify-code');
+  const resend = document.getElementById('resend-code');
+  const phoneError = document.getElementById('phone-error');
+  const otpError = document.getElementById('otp-error');
+  const status = document.getElementById('verification-status');
+  const purposeInputs = document.querySelectorAll('input[name="purpose"]');
+  let challenge = null;
+  let busy = false;
+  let smsController = null;
+  let smsTimeout = null;
+  let cooldownTimer = null;
+  let cooldownUntil = 0;
+  let requestController = null;
+
+  const currentPurpose = () => document.querySelector('input[name="purpose"]:checked').value;
+  const normalizedPhone = () => phone.value.replace(/[ ()-]/g, '');
+  function setError(input, element, message) {
+    element.textContent = message;
+    if (message) input.setAttribute('aria-invalid', 'true');
+    else input.removeAttribute('aria-invalid');
+  }
+  function stopListening() {
+    smsController?.abort();
+    smsController = null;
+    clearTimeout(smsTimeout);
+  }
+  async function listenForSms() {
+    stopListening();
+    if (!window.isSecureContext || !('OTPCredential' in window) || !navigator.credentials) return;
+    const controller = new AbortController();
+    smsController = controller;
+    const expectedChallenge = challenge;
+    smsTimeout = setTimeout(() => controller.abort(), 120000);
+    try {
+      const credential = await navigator.credentials.get({
+        otp: { transport: ['sms'] }, signal: controller.signal,
+      });
+      if (controller.signal.aborted || !credential || challenge !== expectedChallenge || !challenge) return;
+      otp.value = credential.code;
+      setError(otp, otpError, '');
+      otpForm.requestSubmit();
+    } catch {
+      // Dismissal, lack of permission, and unsupported contexts retain manual entry/autofill.
+    } finally {
+      if (smsController === controller) stopListening();
+    }
+  }
+  function syncButtons() {
+    send.disabled = busy || Date.now() < cooldownUntil;
+    resend.disabled = busy || Date.now() < cooldownUntil;
+    verify.disabled = busy;
+    phone.readOnly = busy;
+    purposeInputs.forEach(input => { input.disabled = busy; });
+  }
+  function startCooldown(seconds = 30) {
+    clearInterval(cooldownTimer);
+    cooldownUntil = Date.now() + seconds * 1000;
+    const update = () => {
+      const remaining = Math.max(0, Math.ceil((cooldownUntil - Date.now()) / 1000));
+      resend.textContent = remaining ? `Resend in ${remaining}s` : 'Resend code';
+      send.textContent = remaining ? `Wait ${remaining}s` : (challenge ? 'Send again' : 'Send code ↗');
+      syncButtons();
+      if (!remaining) clearInterval(cooldownTimer);
+    };
+    update();
+    cooldownTimer = setInterval(update, 1000);
+  }
+  async function post(url, payload) {
+    const controller = new AbortController();
+    requestController = controller;
+    const timeout = setTimeout(() => controller.abort(), 15000);
+    try {
+      const response = await fetch(url, {
