+import type { APIRoute } from 'astro';
+import { normalizePhone } from './phone';
+
+const REGISTER_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register';
+const reply = (status: number, data: Record<string, unknown>) => new Response(JSON.stringify(data), {
+  status,
+  headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+});
+
+async function verifyRequest(resource: string, fields: Record<string, string>) {
+  const { TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_VERIFY_SERVICE_SID, TWILIO_VERIFY_TEMPLATE_SID } = process.env;
+  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN || !TWILIO_VERIFY_SERVICE_SID || !TWILIO_VERIFY_TEMPLATE_SID) {
+    throw new Error('SMS_UNAVAILABLE');
+  }
+  return fetch(`https://verify.twilio.com/v2/Services/${encodeURIComponent(TWILIO_VERIFY_SERVICE_SID)}/${resource}`, {
+    method: 'POST',
+    headers: {
+      Authorization: `Basic ${Buffer.from(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`).toString('base64')}`,
+      'Content-Type': 'application/x-www-form-urlencoded',
+    },
+    body: new URLSearchParams(resource === 'Verifications'
+      ? { ...fields, TemplateSid: TWILIO_VERIFY_TEMPLATE_SID } : fields),
+    signal: AbortSignal.timeout(15000),
+  });
+}
+
+export const handleSignup: APIRoute = async ({ request, session, url, clientAddress }) => {
+  // Origin checking is disabled globally for this app; enforce it for signup.
+  if (request.headers.get('Origin') !== url.origin) return reply(403, { error: 'Please submit from this website.' });
+  if (!session) return reply(503, { error: 'Sign-up is temporarily unavailable.' });
+  let body;
+  try { body = await request.json(); } catch { return reply(400, { error: 'Invalid request.' }); }
+  if (!body || typeof body !== 'object') return reply(400, { error: 'Invalid request.' });
+  const phone = typeof body.phone === 'string' ? normalizePhone(body.phone) : null;
+  if (!phone) return reply(400, { error: 'Enter a phone number with its country code, such as +14155552671.' });
+  const now = Date.now();
+  const pending = await session.get('signupPhone');
+
+  try {
+    if (body.action === 'send') {
+      const lastSent = await session.get('signupLastSent');
+      if (lastSent && now - lastSent < 30000) {
+        return reply(429, { error: 'Please wait 30 seconds before requesting another code.' });
+      }
+      // Reserve the cooldown before contacting the provider, including failed sends.
+      await session.set('signupLastSent', now);
+      const response = await verifyRequest('Verifications', { To: phone, Channel: 'sms', RateLimits: JSON.stringify({ signup_phone: phone, signup_ip: clientAddress }) });
+      const data = await response.json();
+      if (!response.ok || data.status !== 'pending' || typeof data.sid !== 'string') {
+        return reply(response.status === 429 ? 429 : 502, { error: 'The SMS could not be sent. Check your number and try again shortly.' });
+      }
+      await session.set('signupPhone', { phone, sid: data.sid, expiresAt: now + 600000, attempts: 0, approved: false });
+      return reply(200, { sent: true });
+    }
+
+    if (body.action !== 'register') return reply(400, { error: 'Invalid action.' });
+    if (!pending || pending.phone !== phone || pending.expiresAt <= now) {
+      return reply(400, { error: 'Your verification has expired. Request a new code.' });
+    }
+    if (typeof body.username !== 'string' || !body.username.trim() || body.username.length > 100 ||
+        typeof body.password !== 'string' || body.password.length < 8 || !/[0-9]/.test(body.password)) {
+      return reply(400, { error: 'Enter a username and a password of at least 8 characters containing a number.' });
+    }
+    if (!pending.approved) {
+      if (typeof body.code !== 'string' || !/^[0-9]{6}$/.test(body.code)) {
+        return reply(400, { error: 'Enter the six-digit code from your SMS.' });
+      }
+      if (pending.attempts >= 5) return reply(429, { error: 'Too many attempts. Request a new code.' });
+      pending.attempts += 1;
+      await session.set('signupPhone', pending);
+      const response = await verifyRequest('VerificationCheck', { VerificationSid: pending.sid, Code: body.code });
+      const data = await response.json();
+      if (!response.ok || data.status !== 'approved') {
+        return reply(400, { error: 'The code is incorrect or expired. Try again or request a new code.' });
+      }
+      // Preserve approval for a retry if the registration service fails.
+      pending.approved = true;
+      await session.set('signupPhone', pending);
+    }
+    const registration = await fetch(REGISTER_URL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: body.username.trim(), password: body.password, phoneNumber: phone }),
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!registration.ok) return reply(400, { error: 'Registration failed. Your username may be unavailable. Go back to edit your details, then try again.' });
+    await session.delete('signupPhone');
+    return reply(200, { registered: true });
+  } catch (error) {
+    return reply(503, { error: error instanceof Error && error.message === 'SMS_UNAVAILABLE'
+      ? 'SMS verification is not configured. Please try again later.'
+      : 'The service could not be reached. Please try again.' });
+  }
+};
