+++ b/tests/signup.test.ts
@@ -0,0 +1,112 @@
+import assert from 'node:assert/strict';
+import { test, afterEach } from 'node:test';
+import { handleSignup } from '../src/utils/signup-handler';
+import { normalizePhone } from '../src/utils/phone';
+
+const originalFetch = globalThis.fetch;
+const variables = ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_VERIFY_SERVICE_SID', 'TWILIO_VERIFY_TEMPLATE_SID'];
+const originalEnv = variables.map((key) => process.env[key]);
+afterEach(() => {
+  globalThis.fetch = originalFetch;
+  variables.forEach((key, i) => {
+    if (originalEnv[i] === undefined) delete process.env[key];
+    else process.env[key] = originalEnv[i];
+  });
+});
+const phone = '+14155552671';
+const details = { action: 'register', phone, code: '012345', username: 'reader', password: 'password1' };
+function session() {
+  const values = new Map<string, unknown>();
+  return { values, get: async (key: string) => structuredClone(values.get(key)), set: (key: string, value: unknown) => values.set(key, structuredClone(value)), delete: (key: string) => values.delete(key) };
+}
+function pending(state: ReturnType<typeof session>, overrides = {}) {
+  state.set('signupPhone', { phone, sid: 'VEtest', expiresAt: Date.now() + 600000, attempts: 0, approved: false, ...overrides });
+}
+async function call(body: unknown, state = session(), origin = 'https://example.com') {
+  const request = new Request('https://example.com/devtools-times/api/signup', {
+    method: 'POST', headers: { Origin: origin, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
+  });
+  return handleSignup({ request, session: state, url: new URL(request.url), clientAddress: '127.0.0.1' } as never);
+}
+function configured() { variables.forEach((key) => { process.env[key] = 'test-only'; }); }
+function mockFetch(replies: Array<{ status?: number; body: object }>) {
+  const calls: Array<{ url: string; init?: RequestInit }> = [];
+  globalThis.fetch = (async (url, init) => {
+    calls.push({ url: String(url), init });
+    const next = replies.shift();
+    assert.ok(next, 'unexpected outbound request');
+    return Response.json(next.body, { status: next.status ?? 200 });
+  }) as typeof fetch;
+  return calls;
+}
+
+test('phone normalization keeps country codes and rejects ambiguous numbers', () => {
+  assert.equal(normalizePhone('+1 (415) 555-2671'), phone);
+  for (const value of ['4155552671', '+0123456789', '+12', '+1415abc2671']) assert.equal(normalizePhone(value), null);
+});
+test('rejects cross-origin signup and missing challenge without outbound requests', async () => {
+  const calls = mockFetch([]);
+  assert.equal((await call(details, session(), 'https://other.example')).status, 403);
+  assert.equal((await call(details)).status, 400);
+  assert.equal(calls.length, 0);
+});
+test('fails closed when SMS provider is unconfigured', async () => {
+  variables.forEach((key) => delete process.env[key]);
+  const calls = mockFetch([]);
+  assert.equal((await call({ action: 'send', phone })).status, 503);
+  assert.equal(calls.length, 0);
+});
+test('sending uses an origin-bound template, provider rate limits, and a session cooldown', async () => {
+  configured();
+  const state = session();
+  const calls = mockFetch([{ body: { status: 'pending', sid: 'VEtest' } }]);
+  assert.equal((await call({ action: 'send', phone }, state)).status, 200);
+  const fields = calls[0].init!.body as URLSearchParams;
+  assert.equal(fields.get('TemplateSid'), 'test-only');
+  assert.deepEqual(JSON.parse(fields.get('RateLimits')!), { signup_phone: phone, signup_ip: '127.0.0.1' });
+  assert.equal((await call({ action: 'send', phone: '+442079460123' }, state)).status, 429);
+  assert.equal(calls.length, 1);
+});
+test('expired, mismatched, and exhausted challenges cannot reach the registration service', async () => {
+  const state = session();
+  const calls = mockFetch([]);
+  pending(state, { expiresAt: Date.now() - 1 });
+  assert.equal((await call(details, state)).status, 400);
+  pending(state, { phone: '+442079460123' });
+  assert.equal((await call(details, state)).status, 400);
+  pending(state, { attempts: 5 });
+  assert.equal((await call(details, state)).status, 429);
+  assert.equal(calls.length, 0);
+});
+test('an incorrect OTP never registers an account', async () => {
+  configured();
+  const state = session();
+  pending(state);
+  const calls = mockFetch([{ body: { status: 'pending' } }]);
+  assert.equal((await call(details, state)).status, 400);
+  assert.equal(calls.length, 1);
+  assert.equal((await state.get('signupPhone') as { attempts: number }).attempts, 1);
+});
+test('leading zero OTP is checked server-side before registration and challenge is consumed', async () => {
+  configured();
+  const state = session();
+  pending(state);
+  const calls = mockFetch([{ body: { status: 'approved' } }, { body: {} }]);
+  assert.equal((await call(details, state)).status, 200);
+  assert.equal((calls[0].init!.body as URLSearchParams).get('Code'), '012345');
+  assert.equal((calls[0].init!.body as URLSearchParams).get('VerificationSid'), 'VEtest');
+  assert.deepEqual(JSON.parse(calls[1].init!.body as string), { username: 'reader', password: 'password1', phoneNumber: phone });
+  assert.equal(await state.get('signupPhone'), undefined);
+  assert.equal((await call(details, state)).status, 400);
+  assert.equal(calls.length, 2);
+});
+test('registration can retry after upstream failure without reusing a consumed provider code', async () => {
+  configured();
+  const state = session();
+  pending(state);
+  const calls = mockFetch([{ body: { status: 'approved' } }, { status: 503, body: {} }, { body: {} }]);
+  assert.equal((await call(details, state)).status, 400);
+  assert.equal((await call(details, state)).status, 200);
+  assert.equal(calls.length, 3);
+  assert.ok(calls[2].url.endsWith('/api/register'));
+});

