@@ -0,0 +1,94 @@
+import type { APIRoute } from 'astro';
+
+const json = (body: Record<string, unknown>, status = 200) =>
+  new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+
+export const POST: APIRoute = async ({ request }) => {
+  if (request.headers.get('origin') !== new URL(request.url).origin) {
+    return json({ error: 'Please submit this form from the sign-up page.' }, 403);
+  }
+
+  const account = process.env.TWILIO_ACCOUNT_SID;
+  const token = process.env.TWILIO_AUTH_TOKEN;
+  const service = process.env.TWILIO_VERIFY_SERVICE_SID;
+  if (!account || !token || !service) {
+    return json({ error: 'SMS verification is temporarily unavailable. Please try again later.' }, 503);
+  }
+
+  try {
+    const body = await request.json();
+    if (!body || typeof body !== 'object') return json({ error: 'Invalid request.' }, 400);
+    const { action, phoneNumber, verificationSid, code, username, password } = body;
+    let resource: string;
+    let params: URLSearchParams;
+
+    if (action === 'send') {
+      if (typeof phoneNumber !== 'string' || !/^\+[1-9]\d{7,14}$/.test(phoneNumber)) {
+        return json({ error: 'Enter a phone number with its country code, such as +1 202 555 0123.' }, 400);
+      }
+      resource = 'Verifications';
+      params = new URLSearchParams({ To: phoneNumber, Channel: 'sms' });
+    } else if (action === 'register') {
+      if (typeof verificationSid !== 'string' || !/^VE[0-9a-fA-F]{32}$/.test(verificationSid) ||
+          typeof code !== 'string' || !/^\d{6}$/.test(code) ||
+          typeof username !== 'string' || !username.trim() || username.length > 100 ||
+          typeof password !== 'string' || password.length < 8 || password.length > 256 || !/\d/.test(password)) {
+        return json({ error: 'Check your username, password, and six-digit verification code.' }, 400);
+      }
+      resource = 'VerificationCheck';
+      params = new URLSearchParams({ VerificationSid: verificationSid, Code: code });
+    } else {
+      return json({ error: 'Invalid request.' }, 400);
+    }
+
+    const verification = await fetch(`https://verify.twilio.com/v2/Services/${service}/${resource}`, {
+      method: 'POST',
+      headers: {
+        Authorization: `Basic ${Buffer.from(`${account}:${token}`).toString('base64')}`,
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: params,
+      signal: AbortSignal.timeout(15000),
+    });
+    const result = await verification.json();
+    if (!verification.ok) {
+      if (verification.status === 429 || result.code === 60202 || result.code === 60203) {
+        return json({ error: 'Too many attempts. Please wait a few minutes before trying again.' }, 429);
+      }
+      if (action === 'register' && verification.status === 404) {
+        return json({ error: 'This code has expired or was already used. Request a new code.', restart: true }, 400);
+      }
+      return json({ error: action === 'send'
+        ? 'We could not send a code. Check your phone number and try again.'
+        : 'We could not verify this code. Check the code and try again.' }, 400);
+    }
+
+    if (action === 'send') {
+      return json({ verificationSid: result.sid });
+    }
+    if (result.status !== 'approved') {
+      return json({ error: 'That code is incorrect. Check your text message and try again.' }, 400);
+    }
+
+    // Only the phone number confirmed by the SMS provider reaches registration.
+    try {
+      const registration = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ username: username.trim(), password, phoneNumber: result.to }),
+        signal: AbortSignal.timeout(15000),
+      });
+      if (!registration.ok) {
+        return json({ error: 'Your account could not be created. Check your details and request a new code to try again.', restart: true }, 400);
+      }
+      return json({ success: true });
+    } catch {
+      return json({ error: 'Registration could not be completed. Request a new code before trying again.', restart: true }, 502);
+    }
+  } catch {
+    return json({ error: 'We could not complete your request. Please try again.' }, 400);
+  }
+};

