@@ -0,0 +1,79 @@
+const directions = {
+  ArrowRight: { near: 'left', far: 'right', start: 'top', end: 'bottom', sign: 1 },
+  ArrowLeft: { near: 'right', far: 'left', start: 'top', end: 'bottom', sign: -1 },
+  ArrowDown: { near: 'top', far: 'bottom', start: 'left', end: 'right', sign: 1 },
+  ArrowUp: { near: 'bottom', far: 'top', start: 'left', end: 'right', sign: -1 },
+};
+
+// Read geometry for every keypress: DOM order and column counts can diverge
+// from the rendered layout after wrapping, resizing, or CSS reordering.
+export function findSpatialTarget(current, candidates, key) {
+  const direction = directions[key];
+  if (!direction) return null;
+  const origin = current.getBoundingClientRect();
+  const { near, far, start, end, sign } = direction;
+  const originCenter = (origin[start] + origin[end]) / 2;
+  const ranked = candidates.filter(item => item !== current).map(item => {
+    const rect = item.getBoundingClientRect();
+    const gap = (rect[near] - origin[far]) * sign;
+    const offset = Math.abs((rect[start] + rect[end]) / 2 - originCenter);
+    const aligned = Math.min(rect[end], origin[end]) > Math.max(rect[start], origin[start]);
+    return { item, gap, offset, aligned };
+  }).filter(candidate => candidate.gap >= -1);
+
+  const aligned = ranked.filter(candidate => candidate.aligned);
+  const pool = aligned.length ? aligned : ranked;
+  pool.sort((a, b) => aligned.length
+    ? a.gap - b.gap || a.offset - b.offset
+    : (a.gap + 2 * a.offset) - (b.gap + 2 * b.offset));
+  return pool[0]?.item ?? null;
+}
+
+function isAvailable(item) {
+  if (item.closest('[hidden], [inert], [aria-hidden="true"], [aria-disabled="true"]') ||
+      item.matches(':disabled')) return false;
+  if (typeof item.checkVisibility === 'function' &&
+      !item.checkVisibility({ visibilityProperty: true, opacityProperty: true })) return false;
+  const rect = item.getBoundingClientRect();
+  return rect.width > 0 && rect.height > 0 && getComputedStyle(item).visibility === 'visible';
+}
+
+export function initSpatialNavigation(grid) {
+  const items = () => [...grid.querySelectorAll('[data-spatial-item]')];
+  const activate = active => {
+    for (const item of items()) item.tabIndex = item === active ? 0 : -1;
+  };
+  activate(items().find(isAvailable));
+
+  // Pointer and programmatic focus must also update the next Tab entry point.
+  grid.addEventListener('focusin', event => {
+    const target = event.composedPath()[0];
+    if (items().includes(target) && isAvailable(target)) activate(target);
+  });
+
+  grid.addEventListener('keydown', event => {
+    if (!Object.hasOwn(directions, event.key) || event.defaultPrevented ||
+        event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || event.isComposing) return;
+    const current = event.composedPath()[0];
+    if (!(current instanceof Element) || current.matches(
+      ':read-write, select, input, textarea, [role="slider"], [role="spinbutton"], [role="combobox"]'
+    )) return;
+    const candidates = items().filter(isAvailable);
+    // Leave nested controls alone; only the card links participate.
+    if (!candidates.includes(current)) return;
+    const next = findSpatialTarget(current, candidates, event.key);
+    if (!next) return; // Preserve native scrolling at the widget's boundaries.
+    activate(next);
+    next.focus({ preventScroll: true });
+    if (next.getRootNode().activeElement !== next) {
+      activate(current);
+      return;
+    }
+    event.preventDefault();
+    next.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
+  });
+}
+
+if (typeof document !== 'undefined') {
+  document.querySelectorAll('[data-spatial-grid]').forEach(initSpatialNavigation);
+}
