@@ -0,0 +1,130 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { findSpatialTarget, initSpatialNavigation } from './spatial-navigation.js';
+
+class Item {
+  constructor(x, y, width = 100, height = 100) {
+    this.rect = { left: x, top: y, right: x + width, bottom: y + height, width, height };
+    this.tabIndex = 0;
+    this.visible = true;
+  }
+  getBoundingClientRect() { return this.rect; }
+  checkVisibility() { return this.visible; }
+  closest() { return this.unavailable; }
+  matches() { return this.control; }
+  focus() { this.root.activeElement = this; }
+  getRootNode() { return this.root; }
+  scrollIntoView(options) { this.scrolled = options; }
+}
+
+test('moves in all four physical directions independent of DOM order', () => {
+  const center = new Item(120, 120);
+  const left = new Item(0, 120);
+  const right = new Item(240, 120);
+  const up = new Item(120, 0);
+  const down = new Item(120, 240);
+  const items = [down, right, center, left, up];
+  for (const [key, expected] of Object.entries({ ArrowLeft: left, ArrowRight: right, ArrowUp: up, ArrowDown: down })) {
+    assert.equal(findSpatialTarget(center, items, key), expected);
+  }
+});
+
+test('handles wrapping, incomplete rows, stacking, and changed layout geometry', () => {
+  const first = new Item(0, 0);
+  const second = new Item(120, 0);
+  const third = new Item(0, 120);
+  const items = [first, second, third];
+  assert.equal(findSpatialTarget(second, items, 'ArrowDown'), third);
+  assert.equal(findSpatialTarget(second, items, 'ArrowRight'), null);
+  second.rect = new Item(0, 120).rect;
+  third.rect = new Item(0, 240).rect;
+  assert.equal(findSpatialTarget(first, items, 'ArrowDown'), second);
+  assert.equal(findSpatialTarget(first, items, 'ArrowRight'), null);
+  assert.equal(findSpatialTarget(third, items, 'ArrowDown'), null);
+});
+
+test('uses edges and prioritizes overlapping candidates before diagonal scoring', () => {
+  const current = new Item(0, 0);
+  const overlapping = new Item(90, 0, 200);
+  const diagonal = new Item(110, 110);
+  const aligned = new Item(300, 0);
+  assert.equal(findSpatialTarget(current, [current, overlapping], 'ArrowRight'), null);
+  assert.equal(findSpatialTarget(current, [diagonal, aligned], 'ArrowRight'), aligned);
+  const nearbyDiagonal = new Item(120, 110);
+  assert.equal(findSpatialTarget(current, [new Item(110, 400), nearbyDiagonal], 'ArrowRight'), nearbyDiagonal);
+});
+
+test('breaks aligned ties by perpendicular offset and tolerates fractional edges', () => {
+  const current = new Item(0, 0);
+  const offset = new Item(120, 80);
+  const aligned = new Item(120, 0);
+  assert.equal(findSpatialTarget(current, [offset, aligned], 'ArrowRight'), aligned);
+  const rounded = new Item(99.75, 0);
+  assert.equal(findSpatialTarget(current, [rounded], 'ArrowRight'), rounded);
+  assert.equal(findSpatialTarget(current, [rounded], 'Tab'), null);
+});
+
+function fixture() {
+  const items = [new Item(0, 0), new Item(120, 0), new Item(240, 0)];
+  const handlers = {};
+  const root = { activeElement: items[0] };
+  items.forEach(item => { item.root = root; });
+  initSpatialNavigation({
+    querySelectorAll: () => items,
+    addEventListener: (name, callback) => { handlers[name] = callback; },
+  });
+  const press = (key, target = root.activeElement, overrides = {}) => {
+    const event = {
+      key, composedPath: () => [target], defaultPrevented: false,
+      preventDefault() { this.defaultPrevented = true; }, ...overrides,
+    };
+    handlers.keydown(event);
+    return event;
+  };
+  return { items, handlers, root, press };
+}
+
+test('keyboard integration preserves native behavior and manages roving focus', () => {
+  const originalElement = globalThis.Element;
+  const originalStyle = globalThis.getComputedStyle;
+  globalThis.Element = Item;
+  globalThis.getComputedStyle = () => ({ visibility: 'visible' });
+  try {
+    const { items, handlers, root, press } = fixture();
+    assert.deepEqual(items.map(item => item.tabIndex), [0, -1, -1]);
+    assert.equal(press('ArrowLeft').defaultPrevented, false);
+    assert.equal(press('ArrowRight').defaultPrevented, true);
+    assert.equal(root.activeElement, items[1]);
+    assert.deepEqual(items.map(item => item.tabIndex), [-1, 0, -1]);
+    assert.deepEqual(items[1].scrolled, { block: 'nearest', inline: 'nearest', behavior: 'instant' });
+    for (const modifier of ['altKey', 'ctrlKey', 'metaKey', 'shiftKey', 'isComposing']) {
+      assert.equal(press('ArrowRight', items[1], { [modifier]: true }).defaultPrevented, false);
+      assert.equal(root.activeElement, items[1]);
+    }
+    press('ArrowRight', items[1], { defaultPrevented: true });
+    assert.equal(root.activeElement, items[1]);
+    for (const key of ['Tab', 'Enter', ' ', 'Escape']) {
+      assert.equal(press(key).defaultPrevented, false);
+    }
+    items[2].visible = false;
+    assert.equal(press('ArrowRight').defaultPrevented, false);
+    items[2].visible = true;
+    items[2].unavailable = true;
+    assert.equal(press('ArrowRight').defaultPrevented, false);
+    items[2].unavailable = false;
+    const nestedControl = new Item(130, 20);
+    nestedControl.control = true;
+    assert.equal(press('ArrowRight', nestedControl).defaultPrevented, false);
+    assert.equal(press('ArrowRight', new Item(130, 20)).defaultPrevented, false);
+    handlers.focusin({ composedPath: () => [items[2]] });
+    assert.deepEqual(items.map(item => item.tabIndex), [-1, -1, 0]);
+    items[0].focus = () => {}; // A failed focus move must not cancel native scrolling.
+    items[1].unavailable = true;
+    root.activeElement = items[2];
+    assert.equal(press('ArrowLeft').defaultPrevented, false);
+    assert.deepEqual(items.map(item => item.tabIndex), [-1, -1, 0]);
+  } finally {
+    globalThis.Element = originalElement;
+    globalThis.getComputedStyle = originalStyle;
+  }
+});

