new file mode 100644
index 0000000..292f77b
--- /dev/null
+++ b/spatial-navigation.mjs
@@ -0,0 +1,65 @@
+const directions = {
+  ArrowLeft: { axis: 'x', sign: -1 },
+  ArrowRight: { axis: 'x', sign: 1 },
+  ArrowUp: { axis: 'y', sign: -1 },
+  ArrowDown: { axis: 'y', sign: 1 },
+};
+
+// Work from current geometry, so resizing, reordering and RTL need no cached
+// column count. Horizontal movement stays in its row; vertical movement picks
+// the closest card in the next row, including an incomplete final row.
+export function findSpatialNeighbor(rects, currentIndex, key) {
+  const direction = directions[key];
+  const current = rects[currentIndex];
+  if (!direction || !current) return -1;
+
+  const horizontal = direction.axis === 'x';
+  const start = horizontal ? 'left' : 'top';
+  const end = horizontal ? 'right' : 'bottom';
+  const crossStart = horizontal ? 'top' : 'left';
+  const crossEnd = horizontal ? 'bottom' : 'right';
+  const center = rect => (rect[start] + rect[end]) / 2;
+  const crossCenter = rect => (rect[crossStart] + rect[crossEnd]) / 2;
+  let best = -1;
+  let bestDistance = Infinity;
+  let bestAlignment = Infinity;
+
+  rects.forEach((rect, index) => {
+    if (index === currentIndex || direction.sign * (center(rect) - center(current)) <= 0) return;
+    const crossOverlap = Math.min(current[crossEnd], rect[crossEnd])
+      - Math.max(current[crossStart], rect[crossStart]);
+    if (horizontal && crossOverlap <= 0) return;
+    if (!horizontal && (direction.sign > 0
+      ? rect.top < current.bottom
+      : rect.bottom > current.top)) return;
+
+    const distance = Math.max(0, direction.sign > 0
+      ? rect[start] - current[end]
+      : current[start] - rect[end]);
+    const alignment = Math.abs(crossCenter(rect) - crossCenter(current));
+    if (distance < bestDistance || (distance === bestDistance && alignment < bestAlignment)) {
+      best = index;
+      bestDistance = distance;
+      bestAlignment = alignment;
+    }
+  });
+  return best;
+}
+
+export function enableSpatialNavigation(grid) {
+  grid.addEventListener('keydown', event => {
+    if (!directions[event.key] || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
+
+    // Only handle the card's main link; leave inputs and other controls alone.
+    const links = [...grid.querySelectorAll('.card > a.btn')].filter(link =>
+      !link.closest('[hidden], [inert], [aria-hidden="true"]') && link.getClientRects().length > 0);
+    const currentIndex = links.indexOf(event.target);
+    if (currentIndex === -1) return;
+
+    const rects = links.map(link => link.closest('.card').getBoundingClientRect());
+    const nextIndex = findSpatialNeighbor(rects, currentIndex, event.key);
+    // At an edge, keep focus in place without scrolling the page or wrapping.
+    event.preventDefault();
+    if (nextIndex !== -1) links[nextIndex].focus();
+  });
+}
diff --git a/spatial-navigation.test.mjs b/spatial-navigation.test.mjs
new file mode 100644
index 0000000..5ca9524
--- /dev/null
+++ b/spatial-navigation.test.mjs
@@ -0,0 +1,98 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { findSpatialNeighbor, enableSpatialNavigation } from './spatial-navigation.mjs';
+
+const rect = (left, top, width = 100, height = 100) => ({
+  left, top, right: left + width, bottom: top + height,
+});
+
+test('three-column layout follows physical directions and stops at edges', () => {
+  const cards = [rect(0, 0), rect(120, 0), rect(240, 0)];
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowLeft'), 0);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowRight'), 2);
+  assert.equal(findSpatialNeighbor(cards, 2, 'ArrowRight'), -1);
+  assert.equal(findSpatialNeighbor(cards, 0, 'ArrowLeft'), -1);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowDown'), -1);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowUp'), -1);
+});
+
+test('two-column layout handles an incomplete last row without horizontal wrapping', () => {
+  const cards = [rect(0, 0), rect(120, 0), rect(0, 120)];
+  assert.equal(findSpatialNeighbor(cards, 0, 'ArrowDown'), 2);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowDown'), 2);
+  assert.equal(findSpatialNeighbor(cards, 2, 'ArrowUp'), 0);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowRight'), -1);
+  assert.equal(findSpatialNeighbor(cards, 2, 'ArrowLeft'), -1);
+});
+
+test('single-column layout only moves vertically', () => {
+  const cards = [rect(0, 0), rect(0, 120), rect(0, 240)];
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowDown'), 2);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowUp'), 0);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowRight'), -1);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowLeft'), -1);
+});
+
+test('RTL and reordered cards follow visual positions instead of DOM order', () => {
+  const cards = [rect(240, 0), rect(120, 0), rect(0, 0)];
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowLeft'), 2);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowRight'), 0);
+});
+
+test('vertical movement selects the nearest column in the next row', () => {
+  const cards = [rect(0, 0), rect(120, 0), rect(0, 120), rect(120, 120), rect(120, 240)];
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowDown'), 3);
+  assert.equal(findSpatialNeighbor(cards, 2, 'ArrowUp'), 0);
+});
+
+test('different card heights do not cause vertical movement within a row', () => {
+  const cards = [rect(0, 0, 100, 80), rect(120, 0, 100, 100), rect(0, 120)];
+  assert.equal(findSpatialNeighbor(cards, 0, 'ArrowDown'), 2);
+  assert.equal(findSpatialNeighbor(cards, 1, 'ArrowUp'), -1);
+});
+
+test('empty collections and unsupported keys have no destination', () => {
+  assert.equal(findSpatialNeighbor([], 0, 'ArrowDown'), -1);
+  assert.equal(findSpatialNeighbor([rect(0, 0)], 0, 'Tab'), -1);
+});
+
+test('keyboard handler uses fresh geometry, ignores hidden cards, and preserves native keys', () => {
+  let handler;
+  let focused = -1;
+  let geometry = [rect(0, 0), rect(120, 0), rect(240, 0)];
+  const hidden = new Set();
+  const links = geometry.map((_, index) => ({
+    closest(selector) {
+      return selector === '.card'
+        ? { getBoundingClientRect: () => geometry[index] }
+        : hidden.has(index) ? {} : null;
+    },
+    getClientRects: () => [geometry[index]],
+    focus: () => { focused = index; },
+  }));
+  enableSpatialNavigation({
+    addEventListener: (name, callback) => { assert.equal(name, 'keydown'); handler = callback; },
+    querySelectorAll: () => links,
+  });
+  const press = (key, options = {}) => {
+    let prevented = false;
+    handler({ key, target: links[0], preventDefault: () => { prevented = true; }, ...options });
+    return prevented;
+  };
+  assert.equal(press('ArrowRight'), true);
+  assert.equal(focused, 1);
+  hidden.add(1);
+  press('ArrowRight');
+  assert.equal(focused, 2);
+  geometry = [rect(0, 0), rect(0, 120), rect(0, 240)];
+  press('ArrowDown');
+  assert.equal(focused, 2);
+  focused = -1;
+  assert.equal(press('ArrowLeft'), true);
+  assert.equal(focused, -1);
+  for (const key of ['Tab', 'Enter', ' ', 'Escape']) assert.equal(press(key), false);
+  for (const modifier of ['ctrlKey', 'altKey', 'metaKey', 'shiftKey']) {
+    assert.equal(press('ArrowDown', { [modifier]: true }), false);
+  }
+  assert.equal(press('ArrowDown', { target: {} }), false);
+});

