+        if (availability === 'unavailable') {
+          journalStatus.textContent = 'Browser AI summaries aren’t available on this device. You can still read the full journal above.';
+          return;
+        }
+        journalStatus.textContent = availability === 'available'
+          ? 'Create a few key points with AI on your device.'
+          : 'Your browser needs to download an AI model first. Select Summarize to begin; this may take a few minutes.';
+        summarizeButton.disabled = false;
