+    (() => {
+      const menu = document.querySelector('#coffee-menu');
+      const tablist = menu.querySelector('[role="tablist"]');
+      const tabs = [...tablist.querySelectorAll('[role="tab"]')];
+      const panels = [...menu.querySelectorAll('[role="tabpanel"]')];
+      const shell = menu.querySelector('.menu-tabs-shell');
+      const controls = [...menu.querySelectorAll('.tab-scroll')];
+      const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
+      const scrollBehavior = () => motion.matches ? 'auto' : 'smooth';
+
+      function updateScrollControls() {
+        const maxScroll = tablist.scrollWidth - tablist.clientWidth;
+        const overflowing = maxScroll > 1;
+        controls.forEach(control => {
+          control.hidden = !overflowing;
+          control.disabled = control.dataset.direction === '-1'
+            ? tablist.scrollLeft <= 1
+            : tablist.scrollLeft >= maxScroll - 1;
+        });
+        shell.classList.toggle('can-scroll-left', overflowing && tablist.scrollLeft > 1);
+        shell.classList.toggle('can-scroll-right', overflowing && tablist.scrollLeft < maxScroll - 1);
+      }
+
+      function revealTab(tab) {
+        const viewport = tablist.getBoundingClientRect();
+        const bounds = tab.getBoundingClientRect();
+        const inset = 8;
+        if (bounds.left < viewport.left + inset) {
+          tablist.scrollBy({ left: bounds.left - viewport.left - inset, behavior: scrollBehavior() });
+        } else if (bounds.right > viewport.right - inset) {
+          tablist.scrollBy({ left: bounds.right - viewport.right + inset, behavior: scrollBehavior() });
+        }
+      }
