+(() => {
+  const selector = document.querySelector('#menu-language');
+  const button = document.querySelector('#translate-button');
+  const status = document.querySelector('#translation-status');
+  const nodes = Array.from(document.querySelectorAll('[data-translate]'));
+  const originals = nodes.map(node => node.textContent);
+  const cache = new Map([['en', originals]]);
+  let displayedLanguage = 'en';
+  let selectionVersion = 0;
+
+  if (!('Translator' in window)) {
+    status.textContent = 'On-device translation is not supported in this browser. The original English text is shown. Try a supported desktop browser such as Chrome.';
+    return;
+  }
+
+  selector.disabled = false;
+  status.textContent = 'Choose a language to translate the coffee descriptions and our story.';
+
+  selector.addEventListener('change', async () => {
+    const version = ++selectionVersion;
+    const targetLanguage = selector.value;
+    button.disabled = true;
+    button.textContent = targetLanguage === 'en' ? 'Show English' : 'Translate';
+    if (targetLanguage === displayedLanguage) {
+      status.textContent = 'This language is already shown.';
+      return;
+    }
+    if (cache.has(targetLanguage)) {
+      button.disabled = false;
+      status.textContent = 'Ready. Select the button to change the text.';
+      return;
+    }
+    status.textContent = 'Checking on-device language availability…';
+    try {
+      const availability = await window.Translator.availability({ sourceLanguage: 'en', targetLanguage });
+      if (version !== selectionVersion) return;
+      if (availability === 'unavailable') {
+        status.textContent = 'This language is unavailable on your device. Choose another language. The current text has been kept.';
+        return;
+      }
+      button.disabled = false;
+      status.textContent = availability === 'available'
+        ? 'Ready to translate on your device.'
+        : 'Select Translate to download the language pack and translate on your device.';
+    } catch {
+      if (version === selectionVersion) {
+        status.textContent = 'Could not check language availability. Choose a language again to retry. The current text has been kept.';
+      }
+    }
+  });
+
+  button.addEventListener('click', async () => {
+    const targetLanguage = selector.value;
+    let translator;
+    button.disabled = true;
+    selector.disabled = true;
+    status.textContent = 'Preparing on-device translation…';
+    try {
+      let translated = cache.get(targetLanguage);
+      if (!translated) {
+        // Availability was checked on selection; create runs directly in this user gesture.
+        translator = await window.Translator.create({
+          sourceLanguage: 'en',
+          targetLanguage,
+          monitor(monitor) {
+            monitor.addEventListener('downloadprogress', event => {
+              status.textContent = `Downloading language pack… ${Math.round(event.loaded * 100)}%`;
+            });
+          },
+        });
+        status.textContent = 'Translating the menu descriptions and story on your device…';
+        translated = [];
+        for (const original of originals) {
+          translated.push(await translator.translate(original));
+        }
+        cache.set(targetLanguage, translated);
+      }
+      // Commit together so a failure never leaves a partially translated page.
+      nodes.forEach((node, index) => {
+        node.textContent = translated[index];
+        node.lang = targetLanguage;
+      });
+      displayedLanguage = targetLanguage;
+      const name = selector.selectedOptions[0].textContent;
+      status.textContent = targetLanguage === 'en'
+        ? 'Original English text restored.'
+        : `Coffee descriptions and story are now in ${name}. Translations are automatic.`;
+    } catch {
+      status.textContent = 'Translation could not finish. Your current text has been kept. Select Translate to retry, or choose another language.';
+    } finally {
+      if (translator) translator.destroy();
+      selector.disabled = false;
+      button.disabled = displayedLanguage === targetLanguage;
+    }
+  });
+})();

