+++ b/src/scripts/article-translation.ts
@@ -0,0 +1,179 @@
+type LanguagePair = { sourceLanguage: string; targetLanguage: string };
+type Availability = 'available' | 'downloadable' | 'downloading' | 'unavailable';
+type LocalTranslator = {
+  translate(text: string, options: { signal: AbortSignal }): Promise<string>;
+  destroy(): void;
+};
+type TranslatorAPI = {
+  availability(options: LanguagePair): Promise<Availability>;
+  create(options: LanguagePair & {
+    signal: AbortSignal;
+    monitor: (monitor: { addEventListener(type: 'downloadprogress', listener: (event: { loaded: number }) => void): void }) => void;
+  }): Promise<LocalTranslator>;
+};
+
+class ArticleTranslation extends HTMLElement {
+  private language!: HTMLSelectElement;
+  private button!: HTMLButtonElement;
+  private restoreButton!: HTMLButtonElement;
+  private status!: HTMLElement;
+  private api?: TranslatorAPI;
+  private pair: LanguagePair = { sourceLanguage: 'en', targetLanguage: 'es' };
+  private originals = new Map<Text, string>();
+  private attributes = new Map<HTMLElement, { lang: string | null; dir: string | null }>();
+  private operation?: AbortController;
+  private checkVersion = 0;
+  private activeLanguage = 'en';
+
+  connectedCallback() {
+    // Only show this control on pages containing news content.
+    if (!document.querySelector('[data-translatable]')) return;
+    this.hidden = false;
+    this.language = this.querySelector('[data-language]')!;
+    this.button = this.querySelector('[data-translate]')!;
+    this.restoreButton = this.querySelector('[data-restore]')!;
+    this.status = this.querySelector('[role="status"]')!;
+    this.api = (window as Window & { Translator?: TranslatorAPI }).Translator;
+    this.language.onchange = () => void this.checkAvailability();
+    this.button.onclick = () => void this.translate();
+    this.restoreButton.onclick = () => this.restore();
+    void this.checkAvailability();
+  }
+
+  disconnectedCallback() {
+    this.checkVersion++;
+    this.operation?.abort();
+  }
+
+  private async checkAvailability() {
+    const version = ++this.checkVersion;
+    this.button.disabled = true;
+    this.pair = { sourceLanguage: 'en', targetLanguage: this.language.value };
+    if (!this.api) {
+      this.language.disabled = true;
+      this.status.textContent = 'On-device translation is unavailable in this browser. Try a supported desktop Chrome or Edge browser. You can still read the original English articles.';
+      return;
+    }
+    if (this.language.value === 'en') {
+      this.button.disabled = this.activeLanguage === 'en';
+      this.status.textContent = 'English is the original language. Select Translate to return to the original.';
+      return;
+    }
+    this.status.textContent = 'Checking language availability…';
+    try {
+      const availability = await this.api.availability(this.pair);
+      if (version !== this.checkVersion || !this.isConnected) return;
+      this.button.disabled = availability === 'unavailable' || this.language.value === this.activeLanguage;
+      this.status.textContent = availability === 'unavailable'
+        ? 'This language is unavailable on your device. Choose another language.'
+        : availability === 'available'
+          ? 'Ready to translate on your device. Machine translations may contain errors.'
+          : 'A language pack is needed. Select Translate to download it; translation then runs on your device.';
+    } catch {
+      if (version === this.checkVersion && this.isConnected) {
+        this.status.textContent = 'Could not check language availability. Choose a language to try again.';
+      }
+    }
+  }
+
+  private restore() {
+    this.operation?.abort();
+    this.operation = undefined;
+    for (const [node, text] of this.originals) node.data = text;
+    for (const [element, attributes] of this.attributes) {
+      for (const name of ['lang', 'dir'] as const) {
+        const value = attributes[name];
+        if (value === null) element.removeAttribute(name);
+        else element.setAttribute(name, value);
+      }
+    }
+    this.activeLanguage = 'en';
+    this.language.disabled = !this.api;
+    this.restoreButton.disabled = true;
+    this.button.textContent = 'Translate';
+    void this.checkAvailability();
+  }
+
+  private async translate() {
+    if (this.language.value === 'en') {
+      this.restore();
+      return;
+    }
+    if (!this.api || this.operation) return;
+    const controller = new AbortController();
+    this.operation = controller;
+    const pair = { ...this.pair };
+    this.language.disabled = true;
+    this.button.disabled = true;
+    this.button.textContent = 'Translating…';
+    this.restoreButton.disabled = false;
+    this.status.textContent = 'Preparing on-device translation…';
+    let translator: LocalTranslator | undefined;
+    try {
+      // Availability is checked before the click, so create retains user activation.
+      translator = await this.api.create({
+        ...pair,
+        signal: controller.signal,
+        monitor: monitor => monitor.addEventListener('downloadprogress', event => {
+          if (!controller.signal.aborted) {
+            this.status.textContent = `Downloading language pack: ${Math.round(event.loaded * 100)}%. Translation stays on your device.`;
+          }
+        }),
+      });
+      const roots = [...document.querySelectorAll<HTMLElement>('[data-translatable]')];
+      const nodes = new Set<Text>();
+      for (const root of roots) {
+        if (!this.attributes.has(root)) {
+          this.attributes.set(root, { lang: root.getAttribute('lang'), dir: root.getAttribute('dir') });
+        }
+        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+          acceptNode: node => node.textContent?.trim() && !node.parentElement?.closest('script, style, code, pre, [translate="no"], button, select')
+            ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT,
+        });
+        while (walker.nextNode()) nodes.add(walker.currentNode as Text);
+      }
+      const results = new Map<Text, string>();
+      const cache = new Map<string, string>();
+      for (const node of nodes) {
+        if (!this.originals.has(node)) this.originals.set(node, node.data);
+        const original = this.originals.get(node)!;
+        const text = original.trim();
+        this.status.textContent = `Translating article text: ${results.size + 1} of ${nodes.size}…`;
+        let result = cache.get(text);
+        if (result === undefined) {
+          result = await translator.translate(text, { signal: controller.signal });
+          cache.set(text, result);
+        }
+        // Preserve spacing and inline elements; never insert model output as HTML.
+        results.set(node, original.replace(/\S[\s\S]*\S|\S/, () => result!));
+      }
+      if (controller.signal.aborted || !this.isConnected) return;
+      // Commit together so errors leave the previous language intact.
+      for (const [node, result] of results) node.data = result;
+      for (const root of roots) {
+        root.lang = pair.targetLanguage;
+        root.dir = pair.targetLanguage === 'ar' ? 'rtl' : 'ltr';
+      }
+      this.activeLanguage = pair.targetLanguage;
+      const name = this.language.selectedOptions[0].textContent;
+      this.status.textContent = `Showing ${name}. Translated on your device. Machine translations may contain errors.`;
+    } catch {
+      if (!controller.signal.aborted && this.isConnected) {
+        this.status.textContent = 'Translation failed. Your current article text is unchanged. Try again, or choose another language. Language pack downloads need an internet connection.';
+      }
+    } finally {
+      translator?.destroy();
+      if (this.operation === controller) {
+        this.operation = undefined;
+        this.language.disabled = false;
+        this.button.textContent = 'Translate';
+        this.button.disabled = this.activeLanguage === this.language.value;
