diff --git a/src/utils/articleTranslation.ts b/src/utils/articleTranslation.ts
new file mode 100644
index 0000000..2ac2626
--- /dev/null
+++ b/src/utils/articleTranslation.ts
@@ -0,0 +1,183 @@
+type Availability = 'unavailable' | 'downloadable' | 'downloading' | 'available';
+type Translator = { translate(text: string): Promise<string>; destroy(): void };
+type TranslatorAPI = {
+  availability(options: { sourceLanguage: string; targetLanguage: string }): Promise<Availability>;
+  create(options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal: AbortSignal;
+    monitor(monitor: { addEventListener(type: 'downloadprogress', listener: (event: { loaded: number }) => void): void }): void;
+  }): Promise<Translator>;
+};
+
+// Only explicitly marked editorial content is translated. Text nodes preserve links,
+// emphasis and other markup without injecting model output as HTML.
+export function collectText(roots: HTMLElement[]): Map<Text, string> {
+  const originals = new Map<Text, string>();
+  for (const root of roots) {
+    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
+    let node: Node | null;
+    while ((node = walker.nextNode())) {
+      if (node.textContent?.trim() && !node.parentElement?.closest('script, style, code, pre, [translate="no"]')) {
+        originals.set(node as Text, node.textContent);
+      }
+    }
+  }
+  return originals;
+}
+
+export class ArticleTranslator extends HTMLElement {
+  private originals = new Map<Text, string>();
+  private roots: HTMLElement[] = [];
+  private cache = new Map<string, string[]>();
+  private run = 0;
+  private check = 0;
+  private abort?: AbortController;
+  private translator?: Translator;
+  private listeners?: AbortController;
+  private select!: HTMLSelectElement;
+  private apply!: HTMLButtonElement;
+  private original!: HTMLButtonElement;
+  private status!: HTMLElement;
+  private api?: TranslatorAPI;
+  private busy = false;
+
+  connectedCallback() {
+    // Astro's router inserts a complete document before upgrading this element.
+    this.roots = Array.from(document.querySelectorAll<HTMLElement>('[data-translate]'));
+    if (!this.roots.length) return;
+    this.hidden = false;
+    this.originals = collectText(this.roots);
+    this.select = this.querySelector('select')!;
+    this.apply = this.querySelector('[data-apply]')!;
+    this.original = this.querySelector('[data-original]')!;
+    this.status = this.querySelector('[role="status"]')!;
+    this.api = (window as Window & { Translator?: TranslatorAPI }).Translator;
+    this.listeners = new AbortController();
+    const options = { signal: this.listeners.signal };
+    this.select.addEventListener('change', () => void this.checkAvailability(), options);
+    this.apply.addEventListener('click', () => void this.translate(), options);
+    this.original.addEventListener('click', () => this.restore(), options);
+    void this.checkAvailability();
+  }
+
+  disconnectedCallback() {
+    this.stop();
+    this.check++;
+    this.listeners?.abort();
+  }
+
+  private async checkAvailability() {
+    const check = ++this.check;
+    this.apply.disabled = true;
+    if (this.select.value === 'en') {
+      this.status.textContent = 'Restore the original English text.';
+      this.apply.disabled = false;
+      return;
+    }
+    if (!this.api) {
+      this.status.textContent = 'On-device translation isn’t available in this browser. Try a supported desktop browser such as Chrome.';
+      return;
+    }
+    this.status.textContent = 'Checking language support…';
+    try {
+      const availability = await this.api.availability({ sourceLanguage: 'en', targetLanguage: this.select.value });
+      if (check !== this.check || !this.isConnected) return;
+      this.apply.disabled = availability === 'unavailable' || this.busy;
+      this.status.textContent = availability === 'unavailable'
+        ? 'This language isn’t supported on your device. Choose another language.'
+        : availability === 'available'
+          ? 'Ready to translate articles and teasers on this page.'
+          : 'A language pack is needed. Translate will download it to your device; an internet connection may be required.';
+    } catch {
+      if (check === this.check) this.status.textContent = 'Couldn’t check language support. Select a language to try again.';
+    }
+  }
+
+  private stop() {
+    this.run++;
+    this.abort?.abort();
+    this.translator?.destroy();
+    this.translator = undefined;
+    this.busy = false;
+  }
+
+  private restore() {
+    this.stop();
+    this.check++;
+    for (const [node, text] of this.originals) node.textContent = text;
+    for (const root of this.roots) {
+      root.removeAttribute('lang');
+      root.removeAttribute('dir');
+    }
+    this.select.disabled = false;
+    this.select.value = 'en';
+    this.apply.disabled = false;
+    this.apply.textContent = 'Translate';
+    this.original.hidden = true;
+    this.status.textContent = 'Showing original English articles and teasers.';
+  }
+
+  private async translate() {
+    const language = this.select.value;
+    if (language === 'en') return this.restore();
+    if (!this.api || this.busy) return;
+    const run = ++this.run;
+    this.check++;
+    this.abort = new AbortController();
+    this.busy = true;
+    this.select.disabled = true;
+    this.apply.disabled = true;
+    this.apply.textContent = 'Translating…';
+    this.original.hidden = false;
+    this.status.textContent = 'Preparing on-device translation…';
+    let translator: Translator | undefined;
+    try {
+      let translated = this.cache.get(language);
+      if (!translated) {
+        // Call create directly from the click, before any await, to retain activation.
+        translator = await this.api.create({
+          sourceLanguage: 'en', targetLanguage: language, signal: this.abort.signal,
+          monitor: monitor => monitor.addEventListener('downloadprogress', event => {
+            if (run === this.run) this.status.textContent = `Downloading language pack… ${Math.round(event.loaded * 100)}%`;
+          }),
+        });
+        if (run !== this.run) return;
+        this.translator = translator;
+        translated = [];
+        const texts = Array.from(this.originals.values());
+        const repeated = new Map<string, string>();
+        for (const [index, text] of texts.entries()) {
+          const clean = text.trim();
+          const result = repeated.get(clean) ?? await translator.translate(clean);
+          if (run !== this.run) return;
+          repeated.set(clean, result);
+          translated.push(text.replace(clean, () => result));
+          this.status.textContent = `Translating articles and teasers… ${index + 1} of ${texts.length}`;
+        }
+        this.cache.set(language, translated);
+      }
+      if (run !== this.run) return;
+      // Commit together so a failed or cancelled request never leaves a mixed page.
+      const results = translated;
+      Array.from(this.originals.keys()).forEach((node, index) => { node.textContent = results[index]; });
+      for (const root of this.roots) {
+        root.lang = language;
+        root.dir = language === 'ar' ? 'rtl' : 'ltr';
+      }
+      const label = this.select.selectedOptions[0].textContent;
+      this.status.textContent = `Showing ${label}. Machine translated on your device; translations may contain errors.`;
+    } catch {
+      if (run === this.run) this.status.textContent = 'Translation couldn’t finish. The displayed text was kept. Check your connection or choose another language and try again.';
+    } finally {
+      translator?.destroy();
+      if (run === this.run) {
+        this.translator = undefined;
+        this.busy = false;
+        this.select.disabled = false;
+        this.apply.disabled = false;
+        this.apply.textContent = 'Translate';
+      }
+    }
+  }
+}
diff --git a/tests/articleTranslation.test.mjs b/tests/articleTranslation.test.mjs
new file mode 100644
index 0000000..7d9d6f4
--- /dev/null
+++ b/tests/articleTranslation.test.mjs
@@ -0,0 +1,112 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+
+class Element extends EventTarget {
+  hidden = false;
+  disabled = false;
+  textContent = '';
+  value = 'es';
+  isConnected = true;
+  selectedOptions = [{ textContent: 'Español — Spanish' }];
+  removeAttribute(name) { delete this[name]; }
+  querySelector(selector) { return this.elements[selector]; }
+}
+globalThis.HTMLElement = Element;
+globalThis.NodeFilter = { SHOW_TEXT: 4 };
+let roots = [];
+globalThis.document = {
+  querySelectorAll: () => roots,
+  createTreeWalker(root) {
+    let index = 0;
+    return { nextNode: () => root.nodes[index++] ?? null };
+  },
+};
+globalThis.window = {};
+const { ArticleTranslator, collectText } = await import('../src/utils/articleTranslation.ts');
+
+function setup(api) {
+  const node = { textContent: '  Original article  ', parentElement: { closest: () => null } };
+  const root = new Element();
+  root.nodes = [node];
+  roots = [root];
+  window.Translator = api;
+  const control = new ArticleTranslator();
+  control.elements = Object.fromEntries(['select', '[data-apply]', '[data-original]', '[role="status"]'].map(key => [key, new Element()]));
+  control.connectedCallback();
+  return { control, node, root, status: control.elements['[role="status"]'], apply: control.elements['[data-apply]'] };
+}
+const tick = () => new Promise(resolve => setImmediate(resolve));
+
+test('collects editorial text while excluding code and whitespace', () => {
+  const included = { textContent: 'Headline', parentElement: { closest: () => null } };
+  const code = { textContent: 'const x = 1', parentElement: { closest: () => ({}) } };
+  assert.deepEqual([...collectText([{ nodes: [included, code, { textContent: ' ' }] }]).values()], ['Headline']);
+});
+
+test('unsupported browsers keep original text and disable translation', () => {
+  const { node, status, apply } = setup(undefined);
+  assert.equal(apply.disabled, true);
+  assert.match(status.textContent, /isn’t available/);
+  assert.equal(node.textContent, '  Original article  ');
+});
+
+test('unsupported language pairs cannot be applied', async () => {
+  const { apply, status } = setup({ availability: async () => 'unavailable' });
+  await tick();
+  assert.equal(apply.disabled, true);
+  assert.match(status.textContent, /isn’t supported/);
+});
+
+test('translation preserves whitespace, sets language, caches and restores originals', async () => {
+  let created = 0;
+  let destroyed = 0;
+  const { control, node, root } = setup({
+    availability: async () => 'available',
+    create: async () => {
+      created++;
+      return { translate: async text => `<${text}>`, destroy: () => destroyed++ };
+    },
+  });
+  await tick();
+  await control.translate();
+  assert.equal(node.textContent, '  <Original article>  ');
+  assert.equal(root.lang, 'es');
+  control.restore();
+  assert.equal(node.textContent, '  Original article  ');
+  assert.equal(root.lang, undefined);
+  control.elements.select.value = 'es';
+  await control.translate();
+  assert.equal(created, 1);
+  assert.equal(destroyed, 1);
+});
+
+test('failed translations leave all displayed text intact and allow retry', async () => {
+  const { control, node, status, apply } = setup({
+    availability: async () => 'available',
+    create: async () => ({ translate: async () => { throw new Error('failure'); }, destroy() {} }),
+  });
+  await tick();
+  await control.translate();
+  assert.equal(node.textContent, '  Original article  ');
+  assert.match(status.textContent, /couldn’t finish/);
+  assert.equal(apply.disabled, false);
+});
+
+test('restoring during a download prevents stale results being applied', async () => {
+  let finish;
+  let signal;
+  const { control, node } = setup({
+    availability: async () => 'downloadable',
+    create: options => {
+      signal = options.signal;
+      return new Promise(resolve => { finish = resolve; });
+    },
+  });
+  await tick();
+  const pending = control.translate();
