new file mode 100644
index 0000000..b6fe0fa
--- /dev/null
+++ b/safe-html.mjs
@@ -0,0 +1,33 @@
+const elements = ['div', 'h3', 'p', 'a'];
+const attributes = ['class', 'href'];
+
+// Cache per window so the fallback also works in isolated documents/tests.
+const purifiers = new WeakMap();
+
+export async function safeSetHTML(element, html) {
+  if ('setHTML' in element) {
+    element.setHTML(html, { sanitizer: { elements, attributes } });
+    return;
+  }
+
+  const window = element.ownerDocument.defaultView;
+  if (!purifiers.has(window)) {
+    purifiers.set(window, import('./vendor/purify.es.mjs').then(({ default: createDOMPurify }) => {
+      const purifier = createDOMPurify(window);
+      if (!purifier.isSupported) throw new Error('HTML sanitization is unavailable.');
+      return purifier;
+    }));
+  }
+
+  const purifier = await purifiers.get(window);
+  // DOMPurify returns TrustedHTML when Trusted Types is available, and a
+  // sanitized string otherwise. Never retry a rejected write with raw HTML.
+  element.innerHTML = purifier.sanitize(html, {
+    ALLOWED_TAGS: [...elements, '#text'],
+    ALLOWED_ATTR: attributes,
+    ALLOW_ARIA_ATTR: false,
+    ALLOW_DATA_ATTR: false,
+    KEEP_CONTENT: false,
+    RETURN_TRUSTED_TYPE: true,
+  });
+}
