+++ b/seasonal-favorites.mjs
@@ -0,0 +1,28 @@
+import { safeSetHTML } from './safe-html.mjs';
+
+const cards = [
+  `<div class="card">
+    <h3>Maple Oat Latte</h3>
+    <p>Creamy oat milk with a hint of Vermont maple syrup.</p>
+    <a href="/menu/seasonal" class="btn">View Details</a>
+  </div>`,
+  `<div class="card">
+    <h3>Dark Roast Espresso</h3>
+    <p>Bold, smokey, and perfect for a morning boost.</p>
+    <a href="/menu/espresso" class="btn">View Details</a>
+  </div>`,
+  `<div class="card">
+    <h3>Cold Brew</h3>
+    <p>Steeped for 18 hours for maximum smoothness.</p>
+    <a href="/menu/cold-brew" class="btn">View Details</a>
+  </div>`,
+];
+
+const container = document.getElementById('seasonal-favorites');
+try {
+  await safeSetHTML(container, cards.join(''));
+} catch (error) {
+  // Fail closed if sanitization or policy creation fails.
+  container.textContent = 'Seasonal favorites are unavailable. Please visit our menu.';
+  console.error('Unable to render seasonal favorites.', error);
+}
diff --git a/tests/safe-html.test.mjs b/tests/safe-html.test.mjs
new file mode 100644
index 0000000..c314691
--- /dev/null
+++ b/tests/safe-html.test.mjs
@@ -0,0 +1,131 @@
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import test from 'node:test';
+import { JSDOM } from 'jsdom';
+import { safeSetHTML } from '../safe-html.mjs';
+
+test('fallback preserves cards and removes executable markup and unsafe URLs', async () => {
+  const dom = new JSDOM('<main></main>');
+  const container = dom.window.document.querySelector('main');
+  const attacks = [
+    '<script>alert(1)</script><img src=x onerror=alert(1)>',
+    '<svg><a xlink:href="javascript:alert(1)">attack</a></svg>',
+    '<a href="jav&#x61;script:alert(1)" onclick="alert(1)">attack</a>',
+    '<a href="java\tscript:alert(1)">attack</a>',
+    '<a href="data:text/html,<script>alert(1)</script>">attack</a>',
+    '<iframe srcdoc="<script>alert(1)</script>"></iframe>',
+    '<div id="seasonal-favorites" name="innerHTML" style="color:red" data-x="1" aria-label="bad">text</div>',
+    '<math><mtext><table><mglyph><style><!--</style><img title="--><img src=x onerror=alert(1)>">',
+  ];
+  for (const attack of attacks) {
+    await safeSetHTML(container, `<div class="card"><h3>Coffee</h3><p>Warm &amp; cozy.</p><a class="btn" href="/menu/seasonal">View Details</a></div>${attack}`);
+    assert.equal(container.querySelector('.card h3').textContent, 'Coffee');
+    assert.equal(container.querySelector('.card p').textContent, 'Warm & cozy.');
+    assert.equal(container.querySelector('.btn').getAttribute('href'), '/menu/seasonal');
+    for (const element of container.querySelectorAll('*')) {
+      assert.ok(['DIV', 'H3', 'P', 'A'].includes(element.tagName));
+      for (const attr of element.attributes) {
+        assert.ok(['class', 'href'].includes(attr.name));
+        if (attr.name === 'href') assert.doesNotMatch(attr.value, /^(?:javascript|data):/i);
+      }
+    }
+  }
+  await safeSetHTML(container, '<p>Replacement</p>');
+  assert.equal(container.children.length, 1);
+  assert.equal(container.textContent, 'Replacement');
+  dom.window.close();
+});
+
+test('native path uses safe setHTML with a restrictive sanitizer', async () => {
+  let received;
+  const element = {
+    setHTML(html, options) { received = { html, options }; },
+    set innerHTML(value) { assert.fail('Native path must not use innerHTML'); },
+  };
+  await safeSetHTML(element, '<p>Native path</p>');
+  assert.deepEqual(received, {
+    html: '<p>Native path</p>',
+    options: { sanitizer: { elements: ['div', 'h3', 'p', 'a'], attributes: ['class', 'href'] } },
+  });
+});
+
+test('fallback supplies TrustedHTML to an enforcing sink', async () => {
+  const dom = new JSDOM('<main></main>');
+  const window = dom.window;
+  class TrustedHTML {
+    constructor(value) { this.value = value; }
+    toString() { return this.value; }
+  }
+  const policyNames = [];
+  window.trustedTypes = {
+    createPolicy(name, rules) {
+      assert.equal(name, 'dompurify');
+      policyNames.push(name);
+      return {
+        createHTML: input => new TrustedHTML(rules.createHTML(input)),
+        createScriptURL: input => rules.createScriptURL(input),
+      };
+    },
+    isHTML: input => input instanceof TrustedHTML,
+  };
+  const descriptor = Object.getOwnPropertyDescriptor(window.Element.prototype, 'innerHTML');
+  Object.defineProperty(window.Element.prototype, 'innerHTML', {
+    ...descriptor,
+    set(value) {
+      if (!(value instanceof TrustedHTML)) throw new TypeError('TrustedHTML required');
+      descriptor.set.call(this, String(value));
+    },
+  });
+  const container = window.document.querySelector('main');
+  assert.throws(() => { container.innerHTML = '<p>raw</p>'; }, TypeError);
+  await safeSetHTML(container, '<p onclick="alert(1)">Sanitized</p>');
+  assert.equal(container.textContent, 'Sanitized');
+  assert.equal(container.querySelector('p').attributes.length, 0);
+  assert.deepEqual(policyNames, ['dompurify']);
+  dom.window.close();
+});
+
+test('homepage renders all original favorites and enforces a policy allowlist', async () => {
+  const html = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+  const dom = new JSDOM(html);
+  const document = dom.window.document;
+  const csp = document.querySelector('meta[http-equiv="Content-Security-Policy"]');
+  assert.match(csp.content, /require-trusted-types-for 'script'/);
+  assert.match(csp.content, /trusted-types dompurify;/);
+  assert.ok(csp.compareDocumentPosition(document.querySelector('script')) & dom.window.Node.DOCUMENT_POSITION_FOLLOWING);
+  assert.equal(document.querySelectorAll('.card').length, 0);
+  globalThis.document = document;
+  try {
+    await import('../seasonal-favorites.mjs');
+    assert.deepEqual([...document.querySelectorAll('.card h3')].map(el => el.textContent), [
+      'Maple Oat Latte', 'Dark Roast Espresso', 'Cold Brew',
+    ]);
+    assert.deepEqual([...document.querySelectorAll('.card a')].map(el => el.getAttribute('href')), [
+      '/menu/seasonal', '/menu/espresso', '/menu/cold-brew',
+    ]);
+  } finally {
+    delete globalThis.document;
+    dom.window.close();
+  }
+});
+
+test('homepage fails closed when safe insertion is rejected', async () => {
+  const dom = new JSDOM('<div id="seasonal-favorites"></div>');
+  const container = dom.window.document.getElementById('seasonal-favorites');
+  container.setHTML = () => { throw new Error('Sanitization rejected'); };
+  Object.defineProperty(container, 'innerHTML', {
+    set() { assert.fail('Failure must never retry with raw HTML'); },
+  });
+  const originalError = console.error;
+  console.error = () => {};
+  globalThis.document = dom.window.document;
+  try {
+    await import('../seasonal-favorites.mjs?failure');
+    assert.equal(container.textContent, 'Seasonal favorites are unavailable. Please visit our menu.');
+    assert.equal(container.children.length, 0);
+  } finally {
+    console.error = originalError;
+    delete globalThis.document;
+    dom.window.close();
+  }
+});
