+import {
+  allowedRedirect, createWidgetValidator, isSameSiteUrl,
+  isTrustedOrderingMessage, parseWebUrl,
+} from './validation.mjs';
+
+const widget = document.querySelector('#coffee-widget');
+const acceptWidgetMessage = createWidgetValidator(widget.contentWindow);
+const baseUrl = window.location.href;
+
+window.addEventListener('message', (event) => {
+  const data = event.data;
+  if (!data || typeof data !== 'object') return;
+
+  if (acceptWidgetMessage(event)) {
+    if (data.type === 'coffee-tip' && typeof data.text === 'string' && data.text.length <= 500) {
+      document.querySelector('#coffee-tip').textContent = data.text;
+    }
+    return;
+  }
+
+  if (!isTrustedOrderingMessage(event)) return;
+  if (data.type === 'order-status' && typeof data.text === 'string' && data.text.length <= 500) {
+    document.querySelector('#order-status').textContent = data.text;
+  } else if (data.type === 'redirect' && typeof data.url === 'string') {
+    const target = allowedRedirect(data.url, baseUrl);
+    if (target) window.location.assign(target);
+  }
+});
+
+function validateLink(link) {
+  const url = parseWebUrl(link, baseUrl);
+  if (!url) return false;
+  if (!isSameSiteUrl(url, baseUrl)) link.relList.add('external', 'noopener', 'noreferrer');
+  else link.relList.remove('external');
+  return true;
+}
+
+document.querySelectorAll('a[href]').forEach(validateLink);
+// Validate at activation too, including dynamically inserted links and middle clicks.
+for (const type of ['click', 'auxclick']) {
+  document.addEventListener(type, (event) => {
+    const link = event.target.closest?.('a[href]');
+    if (link && !validateLink(link)) event.preventDefault();
+  });
+}
+
+// Install the listener before loading the sandbox so its init cannot be missed.
+widget.src = '/coffee-widget.html';
