--- /dev/null
+++ b/validation.mjs
@@ -0,0 +1,91 @@
+// Deployment configuration: this is an exact origin, not a site-wide allowlist.
+export const ORDERING_ORIGIN = 'https://orders.dailygrind.coffee';
+// Only this explicitly controlled registrable domain gets cross-subdomain
+// fallback support. Other deployments fail closed to the current hostname.
+const SITE_DOMAIN = 'dailygrind.coffee';
+
+function extractOrigin(candidate) {
+  try {
+    return Origin.from(candidate);
+  } catch (error) {
+    // Synthetic MessageEvents lack the browser's internal origin. Never use
+    // this fallback for opaque widget identities, where "null" loses identity.
+    if (typeof MessageEvent !== 'undefined' && candidate instanceof MessageEvent) {
+      return Origin.from(candidate.origin);
+    }
+    throw error;
+  }
+}
+
+export function isTrustedOrderingMessage(event) {
+  try {
+    if ('Origin' in globalThis) {
+      return extractOrigin(event).isSameOrigin(Origin.from(ORDERING_ORIGIN));
+    }
+    const sender = new URL(event.origin);
+    return sender.origin !== 'null' && sender.origin === new URL(ORDERING_ORIGIN).origin;
+  } catch {
+    return false;
+  }
+}
+
+export function parseWebUrl(candidate, baseUrl) {
+  try {
+    const value = typeof candidate === 'string' ? candidate : candidate?.href;
+    if (typeof value !== 'string' || !value.trim()) return null;
+    const url = new URL(value, baseUrl);
+    if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
+    return url;
+  } catch {
+    return null;
+  }
+}
+
+export function isSameSiteUrl(candidate, baseUrl) {
+  try {
+    const url = parseWebUrl(candidate, baseUrl);
+    const base = parseWebUrl(baseUrl);
+    if (!url || !base) return false;
+    if ('Origin' in globalThis) {
+      return Origin.from(url).isSameSite(Origin.from(base));
+    }
+    // URL parsing handles credentials, default ports, backslashes and IDNs.
+    // Do not infer registrable domains by splitting arbitrary hostnames.
+    const inOwnedSite = (hostname) => hostname === SITE_DOMAIN || hostname.endsWith(`.${SITE_DOMAIN}`);
+    return url.protocol === base.protocol && (
+      url.hostname === base.hostname || (inOwnedSite(base.hostname) && inOwnedSite(url.hostname))
+    );
+  } catch {
+    return false;
+  }
+}
+
+export function allowedRedirect(candidate, baseUrl) {
+  const url = parseWebUrl(candidate, baseUrl);
+  return url && isSameSiteUrl(url, baseUrl) ? url.href : null;
+}
+
+export function createWidgetValidator(expectedWindow) {
+  const hasOrigin = 'Origin' in globalThis;
+  let pinnedOrigin = hasOrigin ? new Origin() : null;
+  let pinned = false;
+
+  return (event) => {
+    // Check source on every message, including init. Another null-origin
+    // iframe must never win a race to initialize this widget.
+    if (!expectedWindow || event.source !== expectedWindow) return false;
+    try {
+      const sender = hasOrigin ? Origin.from(event) : null;
+      if (hasOrigin ? !sender.opaque : event.origin !== 'null') return false;
+      if (!pinned) {
+        if (event.data?.type !== 'init') return false;
+        pinnedOrigin = sender;
+        pinned = true;
+      }
+      // Never repin, even if the same WindowProxy navigates to a new origin.
+      return hasOrigin ? sender.isSameOrigin(pinnedOrigin) : true;
+    } catch {
+      return false;
+    }
+  };
+}
