+++ b/validation.test.mjs
@@ -0,0 +1,109 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import {
+  ORDERING_ORIGIN, allowedRedirect, createWidgetValidator,
+  isSameSiteUrl, isTrustedOrderingMessage, parseWebUrl,
+} from './validation.mjs';
+
+test('ordering origin requires the exact normalized tuple', () => {
+  for (const origin of [ORDERING_ORIGIN, `${ORDERING_ORIGIN}:443`]) {
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin })), true);
+  }
+  for (const origin of [
+    'null', '', 'invalid', 'http://orders.dailygrind.coffee',
+    'https://orders.dailygrind.coffee:8443', 'https://dailygrind.coffee',
+    'https://orders.dailygrind.coffee.evil.example',
+    'https://orders.dailygrind.coffee@evil.example',
+  ]) {
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin })), false, origin);
+  }
+});
+
+test('redirects parse relative URLs and enforce schemeful same-site rules', () => {
+  const base = 'https://www.dailygrind.coffee/account';
+  assert.equal(allowedRedirect('/menu?coffee=1#latte', base), 'https://www.dailygrind.coffee/menu?coffee=1#latte');
+  assert.equal(allowedRedirect('https://orders.dailygrind.coffee:8443/done', base), 'https://orders.dailygrind.coffee:8443/done');
+  for (const target of [
+    'http://www.dailygrind.coffee/menu', '//evil.example',
+    'https://dailygrind.coffee.evil.example', 'https://evildailygrind.coffee',
+    'https://dailygrind.coffee@evil.example', 'https://user:password@www.dailygrind.coffee',
+    'https://www.dailygrind.coffee\\@evil.example',
+    'javascript:alert(1)', 'data:text/html,test', 'blob:https://www.dailygrind.coffee/id',
+    'null', 'https://[', '', null, {},
+  ]) {
+    // A backslash before @ becomes a path separator: URL parsing retains the
+    // safe host, rather than mistaking path text for URL credentials.
+    if (target === 'https://www.dailygrind.coffee\\@evil.example') {
+      assert.equal(allowedRedirect(target, base), 'https://www.dailygrind.coffee/@evil.example');
+    } else if (target === 'null') {
+      assert.equal(allowedRedirect(target, base), 'https://www.dailygrind.coffee/null');
+    } else assert.equal(allowedRedirect(target, base), null, String(target));
+  }
+});
+
+test('fallback never guesses registrable domains on other deployments', () => {
+  assert.equal(isSameSiteUrl('https://b.co.uk', 'https://a.co.uk'), false);
+  assert.equal(isSameSiteUrl('https://b.github.io', 'https://a.github.io'), false);
+  assert.equal(isSameSiteUrl('/menu', 'http://localhost:11222'), true);
+  assert.equal(isSameSiteUrl('https://evil.example', 'https://localhost'), false);
+  assert.equal(isSameSiteUrl('http://localhost', 'https://localhost'), false);
+  assert.equal(isSameSiteUrl({ href: 'https://orders.dailygrind.coffee/menu' }, 'https://dailygrind.coffee'), true);
+  assert.equal(parseWebUrl('mailto:hello@example.com', 'https://dailygrind.coffee'), null);
+});
+
+test('widget fallback pins only init from the expected opaque window', () => {
+  const widget = {};
+  const otherWidget = {};
+  const accept = createWidgetValidator(widget);
+  const message = (source, type, origin = 'null') => ({ source, origin, data: { type } });
+  assert.equal(accept(message(otherWidget, 'init')), false);
+  assert.equal(accept(message(widget, 'coffee-tip')), false);
+  assert.equal(accept(message(widget, 'init', ORDERING_ORIGIN)), false);
+  assert.equal(accept(message(widget, 'init')), true);
+  assert.equal(accept(message(widget, 'coffee-tip')), true);
+  assert.equal(accept(message(otherWidget, 'coffee-tip')), false);
+  assert.equal(accept(message(otherWidget, 'init')), false);
+  assert.equal(accept(message(widget, 'coffee-tip', ORDERING_ORIGIN)), false);
+  assert.equal(createWidgetValidator(null)(message(null, 'init')), false);
+});
+
+test('Origin API path preserves opaque identity and rejects repinning after navigation', () => {
+  // Node has no browser-dispatched opaque MessageEvents. Model only the
+  // origin-extraction boundary to verify our pinning logic independently.
+  const internalOrigins = new WeakMap();
+  class TestOrigin {
+    opaque = true;
+    static from(value) {
+      const result = internalOrigins.get(value);
+      if (!result) throw new TypeError('No browser origin');
+      return result;
+    }
+    isSameOrigin(other) { return this === other; }
+  }
+  const previous = Object.getOwnPropertyDescriptor(globalThis, 'Origin');
+  globalThis.Origin = TestOrigin;
+  try {
+    const widget = {};
+    const otherWidget = {};
+    const original = new TestOrigin();
+    const navigated = new TestOrigin();
+    const accept = createWidgetValidator(widget);
+    const message = (source, type, origin) => {
+      const event = { source, origin: 'null', data: { type } };
+      if (origin) internalOrigins.set(event, origin);
+      return event;
+    };
+    assert.equal(accept(message(otherWidget, 'init', navigated)), false);
+    assert.equal(accept(message(widget, 'coffee-tip', original)), false);
+    assert.equal(accept(message(widget, 'init', original)), true);
+    assert.equal(accept(message(widget, 'coffee-tip', original)), true);
+    assert.equal(accept(message(otherWidget, 'coffee-tip', navigated)), false);
+    assert.equal(accept(message(widget, 'init', navigated)), false);
+    assert.equal(accept(message(widget, 'coffee-tip', navigated)), false);
+    assert.equal(accept(message(widget, 'init')), false);
+    assert.equal(accept(message(widget, 'coffee-tip', original)), true);
+  } finally {
+    if (previous) Object.defineProperty(globalThis, 'Origin', previous);
+    else delete globalThis.Origin;
+  }
+});

