+(() => {
+  'use strict';
+
+  // Deployment configuration: the ordering service must use this exact origin.
+  const ORDERING_ORIGIN = 'https://orders.thedailygrind.com';
+  const SITE_ORIGIN = window.location.origin;
+  const widget = document.getElementById('ordering-widget');
+  const status = document.getElementById('order-status');
+  let widgetSender = null;
+
+  function parseWebURL(value) {
+    if (typeof value !== 'string' || !value.trim()) return null;
+    try {
+      const url = new URL(value, window.location.href);
+      if (!['https:', 'http:'].includes(url.protocol)) return null;
+      if (url.username || url.password) return null;
+      return url;
+    } catch {
+      return null;
+    }
+  }
+
+  function redirect(value) {
+    const url = parseWebURL(value);
+    // Use the stricter same-origin policy, including scheme and port. Never
+    // infer a registrable domain by splitting on dots (e.g. co.uk).
+    if (url && url.origin === SITE_ORIGIN) window.location.assign(url.href);
+  }
+
+  function updateStatus(value) {
+    if (typeof value === 'string' && value.length <= 1000) {
+      status.textContent = value;
+    }
+  }
+
+  window.addEventListener('message', (event) => {
+    const data = event.data;
+    if (!data || typeof data !== 'object' || Array.isArray(data)) return;
+
+    // Opaque sandbox origins all serialize as "null". Authenticate the
+    // expected WindowProxy before pinning it; origin alone is insufficient.
+    if (event.origin === 'null') {
+      if (!widget || !event.source || event.source !== widget.contentWindow) return;
+      if (data.type === 'widget:init' && widgetSender === null) {
+        widgetSender = event.source;
+        return;
+      }
+      if (event.source !== widgetSender) return;
+      if (data.type === 'widget:status') updateStatus(data.message);
+      return;
+    }
+
+    if (event.origin !== ORDERING_ORIGIN) return;
+    if (data.type === 'order:status') updateStatus(data.message);
+    if (data.type === 'order:redirect') redirect(data.url);
+  });
+
+  // Start only after the listener is installed. This bootstrap sends no secrets;
+  // the parent verifies its source before accepting initialization.
+  if (widget) {
+    widget.srcdoc = "<!doctype html><script>parent.postMessage({type: 'widget:init'}, '*');</script>";
+  }
+
+  function validateLink(link) {
+    const url = parseWebURL(link.getAttribute('href'));
+    if (!url) return false;
+    if (url.origin !== SITE_ORIGIN) {
+      if (url.protocol !== 'https:') return false;
+      link.relList.add('noopener', 'noreferrer');
+    }
+    return true;
+  }
+
+  document.querySelectorAll('a[href]').forEach((link) => {
+    if (!validateLink(link)) link.removeAttribute('href');
+  });
+  // Also cover links added or changed after initialization, including nested
+  // click targets and middle-click navigation.
+  function guardLink(event) {
+    const link = event.target.closest?.('a[href]');
+    if (link && !validateLink(link)) event.preventDefault();
+  }
+  document.addEventListener('click', guardLink, true);
+  document.addEventListener('auxclick', guardLink, true);
+})();
