@@ -0,0 +1,110 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+function link(href) {
+  return {
+    href,
+    rel: new Set(),
+    getAttribute() { return this.href; },
+    removeAttribute() { this.href = null; },
+    get relList() { return { add: (...values) => values.forEach(v => this.rel.add(v)) }; },
+  };
+}
+
+function setup(links = []) {
+  const listeners = {};
+  const navigations = [];
+  const widget = { contentWindow: {} };
+  const status = { textContent: '' };
+  const location = {
+    origin: 'https://www.dailygrind.co.uk',
+    href: 'https://www.dailygrind.co.uk/menu',
+    assign: url => navigations.push(url),
+  };
+  runInNewContext(readFileSync(`${__dirname}/security.js`, 'utf8'), {
+    URL,
+    window: { location, addEventListener: (name, fn) => { listeners[name] = fn; } },
+    document: {
+      getElementById: id => id === 'ordering-widget' ? widget : status,
+      querySelectorAll: () => links,
+      addEventListener: (name, fn) => { listeners[name] = fn; },
+    },
+  });
+  return {
+    widget, status, navigations,
+    message: (origin, data, source = {}) => listeners.message({ origin, data, source }),
+    click: (href, kind = 'click') => {
+      const target = link(href);
+      let blocked = false;
+      listeners[kind]({ target: { closest: () => target }, preventDefault: () => { blocked = true; } });
+      return { blocked, target };
+    },
+  };
+}
+
+const trusted = 'https://orders.thedailygrind.com';
+
+test('ordering messages require an exact origin and safe payload', () => {
+  const app = setup();
+  for (const origin of ['null', 'http://orders.thedailygrind.com', `${trusted}.evil.test`, `${trusted}:444`, 'https://evil.test']) {
+    app.message(origin, { type: 'order:status', message: 'forged' });
+  }
+  for (const data of [null, 'bad', [], { type: 'order:status', message: {} }]) app.message(trusted, data);
+  assert.equal(app.status.textContent, '');
+  app.message(trusted, { type: 'order:status', message: '<b>Ready</b>' });
+  assert.equal(app.status.textContent, '<b>Ready</b>');
+});
+
+test('redirects use parsed origins, including multi-label suffixes and ports', () => {
+  const app = setup();
+  for (const url of [
+    '//evil.co.uk/path', 'https://www.dailygrind.co.uk.evil.test',
+    'https://www.dailygrind.co.uk@evil.test', 'https://other.dailygrind.co.uk',
+    'https://www.dailygrind.co.uk:444', 'http://www.dailygrind.co.uk',
+    'javascript:alert(1)', 'data:text/html,bad', 'https://[', {}, '',
+    'https://user:pass@www.dailygrind.co.uk', '/\\evil.test/path',
+  ]) app.message(trusted, { type: 'order:redirect', url });
+  assert.deepEqual(app.navigations, []);
+  for (const url of ['/checkout?order=1', 'https://www.dailygrind.co.uk:443/done']) {
+    app.message(trusted, { type: 'order:redirect', url });
+  }
+  assert.deepEqual(app.navigations, ['https://www.dailygrind.co.uk/checkout?order=1', 'https://www.dailygrind.co.uk/done']);
+});
+
+test('sandbox initialization pins the known widget, never the first opaque sender', () => {
+  const app = setup();
+  const otherFrame = {};
+  const send = (type, source) => app.message('null', { type, message: 'accepted' }, source);
+  send('widget:init', otherFrame);
+  send('widget:status', app.widget.contentWindow);
+  assert.equal(app.status.textContent, '');
+  send('widget:init', null);
+  send('widget:init', app.widget.contentWindow);
+  send('widget:status', otherFrame);
+  assert.equal(app.status.textContent, '');
+  send('widget:status', app.widget.contentWindow);
+  assert.equal(app.status.textContent, 'accepted');
+  app.message('null', { type: 'order:redirect', url: '/checkout' }, app.widget.contentWindow);
+  assert.deepEqual(app.navigations, []);
+  app.status.textContent = '';
+  send('widget:init', otherFrame);
+  send('widget:status', otherFrame);
+  assert.equal(app.status.textContent, '');
+});
+
+test('initial and dynamic links reject unsafe URLs and protect external navigation', () => {
+  const links = [link('javascript:alert(1)'), link('/menu'), link('https://coffee.example/menu')];
+  const app = setup(links);
+  assert.equal(links[0].href, null);
+  assert.equal(links[1].href, '/menu');
+  assert.deepEqual([...links[2].rel], ['noopener', 'noreferrer']);
+  for (const href of ['data:text/html,bad', 'http://external.test', 'https://user:pass@external.test', 'https://[']) {
+    assert.equal(app.click(href).blocked, true);
+    assert.equal(app.click(href, 'auxclick').blocked, true);
+  }
+  assert.equal(app.click('/menu').blocked, false);
+  assert.equal(app.click('https://external.test').blocked, false);
+  assert.deepEqual([...app.click('//external.test').target.rel], ['noopener', 'noreferrer']);
+});

