@@ -0,0 +1,38 @@
+import { randomBytes, randomUUID } from 'node:crypto';
+import { verifyEmailVerificationToken } from './verification.mjs';
+
+export function createRegistration(db, verify = verifyEmailVerificationToken) {
+  db.exec(`CREATE TABLE IF NOT EXISTS challenges (
+    session TEXT PRIMARY KEY, nonce TEXT NOT NULL, expires INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS rewards_accounts (
+    id TEXT PRIMARY KEY, email TEXT NOT NULL, email_key TEXT UNIQUE NOT NULL,
+    name TEXT NOT NULL, email_verified_at TEXT NOT NULL);`);
+  return {
+    challenge() {
+      db.prepare('DELETE FROM challenges WHERE expires < ?').run(Date.now());
+      const session = randomBytes(32).toString('base64url');
+      const nonce = randomBytes(32).toString('base64url');
+      db.prepare('INSERT INTO challenges VALUES (?, ?, ?)').run(session, nonce, Date.now() + 600000);
+      return { session, nonce };
+    },
+    async submit({ session, nonce, name, email, token, origin }) {
+      // DELETE RETURNING consumes the nonce atomically, before any asynchronous verification.
+      const challenge = db.prepare('DELETE FROM challenges WHERE session = ? RETURNING nonce, expires').get(session);
+      if (!challenge || challenge.expires < Date.now() || nonce !== challenge.nonce) {
+        return { status: 403, message: 'This sign-up session has expired. Please try again below.' };
+      }
+      if (!name || name.length > 100 || email.length > 254 || !/^[^\s@]+@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/i.test(email)) {
+        return { status: 400, message: 'Please enter your name and a valid email address.' };
+      }
+      if (!token) return { status: 422, message: 'Your browser could not confirm this email. Sign in to your email provider in a supported browser, then try again. No verification email was sent.' };
+      try {
+        await verify({ rawToken: token, submittedEmail: email, expectedNonce: challenge.nonce, expectedAudience: origin });
+      } catch {
+        return { status: 422, message: 'We could not verify your email securely. Please try again with your email provider signed in. No verification email was sent.' };
+      }
+      db.prepare(`INSERT INTO rewards_accounts VALUES (?, ?, ?, ?, ?)
+        ON CONFLICT(email_key) DO NOTHING`).run(randomUUID(), email, email.toLowerCase(), name, new Date().toISOString());
+      return { status: 200, verified: true, message: 'Your email is verified and your rewards account is ready. Welcome to the Daily Grind community!' };
+    },
+  };
+}
