@@ -0,0 +1,115 @@
+import { createHash } from 'node:crypto';
+import { lookup, resolveTxt } from 'node:dns/promises';
+import { request } from 'node:https';
+import ipaddr from 'ipaddr.js';
+import { SdJwtInstance, decodeSdJwtSync } from '@sd-jwt/core';
+import { createLocalJWKSet, importJWK, jwtVerify } from 'jose';
+
+const ALGORITHMS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => alg === 'Ed25519' ? 'EdDSA' : alg;
+export const hasher = (data, alg) => {
+  if (!['sha-256', 'sha-384', 'sha-512'].includes(alg)) throw new Error('Unsupported hash');
+  return createHash(alg.replace('-', '')).update(data).digest();
+};
+
+// Pin the connection to a checked public address; reject redirects and private networks.
+export async function fetchPublicJson(value) {
+  const url = new URL(value);
+  if (url.protocol !== 'https:' || url.username || url.password || (url.port && url.port !== '443')) {
+    throw new Error('Public HTTPS URL required');
+  }
+  const addresses = await lookup(url.hostname, { all: true });
+  if (!addresses.length || addresses.some(({ address }) => ipaddr.process(address).range() !== 'unicast')) {
+    throw new Error('Non-public destination');
+  }
+  const address = addresses[0];
+  return new Promise((resolve, reject) => {
+    const req = request(url, {
+      headers: { Accept: 'application/json' },
+      lookup: (_host, options, callback) => options.all
+        ? callback(null, [address]) : callback(null, address.address, address.family),
+    }, (res) => {
+      if (res.statusCode !== 200) {
+        res.resume();
+        reject(new Error('Provider request failed'));
+        return;
+      }
+      const chunks = [];
+      let size = 0;
+      res.on('data', (chunk) => {
+        size += chunk.length;
+        if (size > 65536) req.destroy(new Error('Provider response too large'));
+        else chunks.push(chunk);
+      });
+      res.on('error', reject);
+      res.on('end', () => {
+        try { resolve(JSON.parse(Buffer.concat(chunks).toString())); }
+        catch (error) { reject(error); }
+      });
+    });
+    const timer = setTimeout(() => req.destroy(new Error('Provider timeout')), 5000);
+    req.on('close', () => clearTimeout(timer));
+    req.on('error', reject);
+    req.end();
+  });
+}
+
+export async function verifyEmailVerificationToken({ rawToken, submittedEmail, expectedNonce, expectedAudience }, dependencies = {}) {
+  if (!expectedNonce || !rawToken || rawToken.length > 24000) throw new Error('Missing verification');
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evt = decoded.jwt.payload;
+  const issuer = evt.iss;
+  if (!decoded.kbJwt || typeof issuer !== 'string') throw new Error('Missing key binding or issuer');
+  const issuerUrl = new URL(issuer);
+  if (issuerUrl.origin !== issuer || issuerUrl.protocol !== 'https:' || issuerUrl.port || issuerUrl.username || issuerUrl.password) {
+    throw new Error('Invalid issuer origin');
+  }
+  const domain = submittedEmail.slice(submittedEmail.lastIndexOf('@') + 1).toLowerCase();
+  const records = await (dependencies.resolveTxt ?? resolveTxt)(`_email-verification.${domain}`);
+  if (!records.some((parts) => `iss=${issuerUrl.hostname}` === parts.join('').trim())) {
+    throw new Error('Issuer not delegated by email domain');
+  }
+  const getJson = dependencies.fetchJson ?? fetchPublicJson;
+  const metadata = await getJson(`${issuer}/.well-known/email-verification`);
+  if (metadata.issuer !== issuer || typeof metadata.jwks_uri !== 'string') throw new Error('Invalid issuer metadata');
+  const jwks = createLocalJWKSet(await getJson(metadata.jwks_uri));
+  const evtOptions = {
+    typ: 'ev+sd-jwt', issuer, algorithms: ALGORITHMS,
+    requiredClaims: ['iat', 'exp'], maxTokenAge: '5m', clockTolerance: 60,
+  };
+  const sdJwt = new SdJwtInstance({
+    hasher,
+    verifier: async (data, signature) => {
+      const token = `${data}.${signature}`;
+      try { await jwtVerify(token, jwks, evtOptions); }
+      catch (error) {
+        if (error.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw error;
+        let matched = false;
+        for await (const key of error) {
+          try { await jwtVerify(token, key, evtOptions); matched = true; break; }
+          catch { /* Try the next authorized issuer key when kid is absent. */ }
+        }
+        if (!matched) throw error;
+      }
+      return true;
+    },
+    kbVerifier: async (data, signature, payload) => {
+      const jwk = payload.cnf?.jwk;
+      const alg = decoded.kbJwt.header.alg;
+      if (!jwk || jwk.d || jwk.k || !ALGORITHMS.includes(jwk.alg) || !ALGORITHMS.includes(alg)
+        || normalizeAlg(jwk.alg) !== normalizeAlg(alg)) throw new Error('Invalid holder key');
+      await jwtVerify(`${data}.${signature}`, await importJWK(jwk, alg), {
+        typ: 'kb+jwt', audience: expectedAudience, algorithms: [alg],
+        requiredClaims: ['iat', 'aud', 'nonce'], maxTokenAge: '5m', clockTolerance: 60,
+      });
+      return true;
+    },
+  });
+  const { payload } = await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'], keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience, keyBindingMaxAgeSeconds: 300, skewSeconds: 60,
+  });
+  if (payload.email_verified !== true || typeof payload.email !== 'string'
+    || payload.email.toLowerCase() !== submittedEmail.toLowerCase()) throw new Error('Email mismatch');
+  return payload;
+}
