--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,59 @@
+import { createServer } from 'node:http';
+import { readFile, mkdir } from 'node:fs/promises';
+import { DatabaseSync } from 'node:sqlite';
+import { createRegistration } from './lib/registration.mjs';
+
+const origin = new URL(process.env.PUBLIC_ORIGIN || 'http://localhost:11222').origin;
+const secure = origin.startsWith('https:');
+if (process.env.NODE_ENV === 'production' && !secure) throw new Error('PUBLIC_ORIGIN must use HTTPS in production');
+const dataDirectory = new URL('./data/', import.meta.url);
+await mkdir(dataDirectory, { recursive: true, mode: 0o700 });
+const db = new DatabaseSync(process.env.DATABASE_PATH || new URL('rewards.sqlite', dataDirectory).pathname);
+db.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;');
+const registration = createRegistration(db);
+const template = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
+const cookieName = secure ? '__Host-dg-signup' : 'dg-signup';
+
+function render(res, result = {}, values = {}) {
+  const { session, nonce } = registration.challenge();
+  res.writeHead(result.status || 200, {
+    'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store',
+    'Set-Cookie': `${cookieName}=${session}; Path=/; HttpOnly; SameSite=Lax; Max-Age=600${secure ? '; Secure' : ''}`,
+    'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin',
+    'Content-Security-Policy': "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https://images.unsplash.com; form-action 'self'; frame-ancestors 'none'; base-uri 'none'",
+    ...(process.env.EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN ? { 'Origin-Trial': process.env.EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN } : {}),
+  });
+  const replacements = {
+    NONCE: nonce, NAME: values.name || '', EMAIL: values.email || '',
+    STATUS: result.message || '', STATUS_CLASS: result.message ? (result.verified ? 'success' : 'error') : 'empty',
+    FORM_HIDDEN: result.verified ? 'hidden' : '',
+  };
+  res.end(template.replace(/__DG_([A-Z_]+)__/g, (_, key) => escapeHtml(replacements[key] ?? '')));
+}
+
+createServer(async (req, res) => {
+  try {
+    const path = new URL(req.url, origin).pathname;
+    if (req.method === 'GET' && path === '/') return render(res);
+    if (req.method === 'POST' && path === '/api/verify-email') {
+      if (req.headers.origin !== origin || !req.headers['content-type']?.startsWith('application/x-www-form-urlencoded')) {
+        res.writeHead(403); res.end('Invalid form origin or content type.'); return;
+      }
+      let body = '';
+      for await (const chunk of req) {
+        body += chunk.toString();
+        if (Buffer.byteLength(body) > 32768) { res.writeHead(413); res.end('Form too large.'); return; }
+      }
+      const form = new URLSearchParams(body);
+      const values = { name: (form.get('name') || '').trim(), email: (form.get('email') || '').trim() };
+      const session = req.headers.cookie?.split(';').map((part) => part.trim()).find((part) => part.startsWith(`${cookieName}=`))?.slice(cookieName.length + 1) || '';
+      const result = await registration.submit({ ...values, session, nonce: form.get('csrf_nonce'), token: form.get('token') || '', origin });
+      return render(res, result, result.verified ? {} : values);
+    }
+    res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Page not found.');
+  } catch {
+    res.writeHead(500, { 'Content-Type': 'text/plain', 'Cache-Control': 'no-store' });
+    res.end('We could not finish your request. Please return to the homepage and try again.');
+  }
+}).listen(Number(process.env.PORT || 11222), '0.0.0.0');
diff --git a/test/verification.test.mjs b/test/verification.test.mjs
new file mode 100644
index 0000000..fb00ea9
--- /dev/null
+++ b/test/verification.test.mjs
@@ -0,0 +1,107 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { randomBytes } from 'node:crypto';
+import { DatabaseSync } from 'node:sqlite';
+import { SdJwtInstance } from '@sd-jwt/core';
+import { CompactSign, exportJWK, generateKeyPair } from 'jose';
+import { hasher, verifyEmailVerificationToken, fetchPublicJson } from '../lib/verification.mjs';
+import { createRegistration } from '../lib/registration.mjs';
+
+const origin = 'https://coffee.example';
+const nonce = 'server-generated-single-use-nonce';
+const issuer = 'https://issuer.example';
+const email = 'Customer@example.com';
+const issuerKeys = await generateKeyPair('ES256');
+const holderKeys = await generateKeyPair('ES256');
+const otherIssuer = await generateKeyPair('ES256');
+const issuerJwk = { ...await exportJWK(issuerKeys.publicKey), alg: 'ES256' };
+const holderJwk = { ...await exportJWK(holderKeys.publicKey), alg: 'ES256' };
+const sign = (key) => async (data) => (await new CompactSign(Buffer.from(data.split('.')[1], 'base64url'))
+  .setProtectedHeader(JSON.parse(Buffer.from(data.split('.')[0], 'base64url'))).sign(key)).split('.')[2];
+
+async function fixture({ claims = {}, kb = {}, signingKey = issuerKeys.privateKey, holderKey = holderKeys.privateKey } = {}) {
+  const sd = new SdJwtInstance({
+    hasher, hashAlg: 'sha-256', saltGenerator: () => randomBytes(16).toString('base64url'),
+    signAlg: 'ES256', signer: sign(signingKey), kbSignAlg: 'ES256', kbSigner: sign(holderKey),
+  });
+  const now = Math.floor(Date.now() / 1000);
+  const evt = await sd.issue({
+    iss: issuer, iat: now, exp: now + 300, email, email_verified: true,
+    cnf: { jwk: holderJwk }, ...claims,
+  }, undefined, { header: { typ: 'ev+sd-jwt' } });
+  return sd.present(evt, undefined, { kb: { payload: { iat: now, aud: origin, nonce, ...kb } } });
+}
+const dependencies = {
+  resolveTxt: async () => [['iss=issuer.example']],
+  fetchJson: async (url) => url.endsWith('/.well-known/email-verification')
+    ? { issuer, jwks_uri: `${issuer}/keys` }
+    : { keys: [await exportJWK(otherIssuer.publicKey), issuerJwk] },
+};
+const verify = (rawToken, overrides = {}, deps = dependencies) => verifyEmailVerificationToken({
+  rawToken, submittedEmail: email.toLowerCase(), expectedNonce: nonce, expectedAudience: origin, ...overrides,
+}, deps);
+
+test('accepts signed presentation, case-insensitive email, and multiple issuer keys without kid', async () => {
+  const result = await verify(await fixture());
+  assert.equal(result.email_verified, true);
+});
+
+test('rejects invalid claims and forged issuer or holder signatures', async (t) => {
+  for (const [label, options] of Object.entries({
+    'unverified address': { claims: { email_verified: false } },
+    'different address': { claims: { email: 'attacker@example.com' } },
+    'expired token': { claims: { exp: Math.floor(Date.now() / 1000) - 120 } },
+    'missing expiration': { claims: { exp: undefined } },
+    'wrong nonce': { kb: { nonce: 'other-session' } },
+    'wrong audience': { kb: { aud: 'https://attacker.example' } },
+    'stale key binding': { kb: { iat: Math.floor(Date.now() / 1000) - 1000 } },
+    'forged issuer': { signingKey: otherIssuer.privateKey },
+    'forged holder': { holderKey: otherIssuer.privateKey },
+  })) {
+    await t.test(label, async () => {
+      // The alternate issuer must not be in the trusted set for the forgery test.
+      const deps = { ...dependencies, fetchJson: async (url) => url.endsWith('/keys')
+        ? { keys: [issuerJwk] } : { issuer, jwks_uri: `${issuer}/keys` } };
+      await assert.rejects(verify(await fixture(options), {}, deps));
+    });
+  }
+});
+
+test('rejects missing binding, untrusted DNS issuer, and invalid discovery', async () => {
+  const token = await fixture();
+  await assert.rejects(verify(token.slice(0, token.lastIndexOf('~') + 1)));
+  await assert.rejects(verify(token, { expectedNonce: '' }));
+  await assert.rejects(verify(token, {}, { ...dependencies, resolveTxt: async () => [['iss=attacker.example']] }));
+  await assert.rejects(verify(token, {}, { ...dependencies, fetchJson: async () => ({ issuer: 'https://attacker.example' }) }));
+  // Swap the EVT under a valid holder-signed binding: sd_hash must reject it.
+  const different = await fixture({ claims: { exp: Math.floor(Date.now() / 1000) + 240 } });
+  await assert.rejects(verify(`${different.slice(0, different.lastIndexOf('~') + 1)}${token.slice(token.lastIndexOf('~') + 1)}`));
+});
+
+test('provider fetching rejects private networks and non-HTTPS destinations', async () => {
+  for (const url of ['https://127.0.0.1/keys', 'https://169.254.169.254/keys', 'http://issuer.example/keys', 'https://user:pass@issuer.example/keys']) {
+    await assert.rejects(fetchPublicJson(url));
+  }
+});
+
+test('registration persists only verified accounts and consumes challenges on every attempt', async () => {
+  const db = new DatabaseSync(':memory:');
+  const registration = createRegistration(db, (args) => verifyEmailVerificationToken(args, dependencies));
+  const input = { email, name: 'Coffee Customer', origin };
+  const first = registration.challenge();
+  const token = await fixture({ kb: { nonce: first.nonce } });
+  const valid = { ...input, ...first, token };
+  assert.equal((await registration.submit(valid)).verified, true);
+  assert.equal((await registration.submit(valid)).status, 403);
+  const missing = registration.challenge();
+  assert.equal((await registration.submit({ ...input, ...missing, token: '' })).status, 422);
+  assert.equal((await registration.submit({ ...input, ...missing, token })).status, 403);
+  const bad = registration.challenge();
+  assert.equal((await registration.submit({ ...input, ...bad, token: 'forged' })).status, 422);
+  const csrf = registration.challenge();
+  assert.equal((await registration.submit({ ...input, ...csrf, nonce: 'wrong', token })).status, 403);
+  const duplicate = registration.challenge();
+  assert.equal((await registration.submit({ ...input, email: email.toUpperCase(), ...duplicate, token: await fixture({ kb: { nonce: duplicate.nonce } }) })).verified, true);
+  assert.equal(db.prepare('SELECT count(*) AS count FROM rewards_accounts').get().count, 1);
+  db.close();
+});

