diff --git a/lib/store.mjs b/lib/store.mjs
new file mode 100644
index 0000000..69c535f
--- /dev/null
+++ b/lib/store.mjs
@@ -0,0 +1,27 @@
+import { DatabaseSync } from 'node:sqlite';
+import { randomBytes } from 'node:crypto';
+export function createStore(filename) {
+  const db = new DatabaseSync(filename);
+  db.exec(`PRAGMA journal_mode=WAL;
+    CREATE TABLE IF NOT EXISTS challenges (session TEXT PRIMARY KEY, nonce TEXT NOT NULL, expires INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, verified_at INTEGER NOT NULL);`);
+  return {
+    issue() {
+      db.prepare('DELETE FROM challenges WHERE expires < ?').run(Date.now());
+      const session = randomBytes(32).toString('base64url');
+      const nonce = randomBytes(32).toString('base64url');
+      db.prepare('INSERT INTO challenges VALUES (?, ?, ?)').run(session, nonce, Date.now() + 600000);
+      return { session, nonce };
+    },
+    consume(session) {
+      const row = db.prepare('DELETE FROM challenges WHERE session = ? RETURNING nonce, expires').get(session || '');
+      return row && row.expires > Date.now() ? row.nonce : null;
+    },
+    register({ email, name, passwordHash }) {
+      const id = randomBytes(16).toString('hex');
+      db.prepare('INSERT INTO accounts VALUES (?, ?, ?, ?, ?) ON CONFLICT(email) DO NOTHING').run(id, email.toLowerCase(), name, passwordHash, Date.now());
+      return id;
+    },
+    close: () => db.close(),
+  };
+}
diff --git a/lib/verify-email.mjs b/lib/verify-email.mjs
new file mode 100644
index 0000000..a2c1553
--- /dev/null
+++ b/lib/verify-email.mjs
@@ -0,0 +1,64 @@
+import { createHash } from 'node:crypto';
+import { resolveTxt } from 'node:dns/promises';
+import { SdJwtInstance, decodeSdJwtSync } from '@sd-jwt/core';
+import { importJWK, jwtVerify } from 'jose';
+
+const algorithms = ['Ed25519', 'EdDSA', 'ES256'];
+const hasher = (data, alg) => {
+  if (alg !== 'sha-256') throw new Error('Unsupported digest');
+  return createHash('sha256').update(data).digest();
+};
+// Explicit network allowlist prevents token-controlled discovery URLs causing SSRF.
+const providers = {
+  'https://accounts.google.com': ['https://verifiablecredentials-pa.googleapis.com/.well-known/vc-public-jwks'],
+};
+async function fetchJSON(url) {
+  const response = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(5000) });
+  if (!response.ok) throw new Error('Provider unavailable');
+  const data = await response.text();
+  if (data.length > 100000) throw new Error('Provider response too large');
+  return JSON.parse(data);
+}
+export async function verifyEmailToken({ token, email, nonce, audience }, dependencies = {}) {
+  if (!token || token.length > 20000 || !nonce) throw new Error('Missing verification');
+  const decoded = decodeSdJwtSync(token, hasher);
+  const evt = decoded.jwt.payload;
+  const kb = decoded.kbJwt;
+  if (!kb || !providers[evt.iss] || !algorithms.includes(decoded.jwt.header.alg) || !algorithms.includes(kb.header.alg)) throw new Error('Unsupported token');
+  if (!['ev+sd-jwt', 'evt+jwt'].includes(decoded.jwt.header.typ)) throw new Error('Invalid token type');
+  if (evt.email_verified !== true || typeof evt.email !== 'string' || evt.email.toLowerCase() !== email.toLowerCase()) throw new Error('Email mismatch');
+  if (!Number.isFinite(evt.exp) || !Number.isFinite(evt.iat) || evt.exp <= Date.now() / 1000 || evt.exp <= evt.iat) throw new Error('Expired token');
+  const records = await (dependencies.resolveTxt || resolveTxt)(`_email-verification.${email.split('@')[1].toLowerCase()}`);
+  if (!records.some(parts => parts.join('').trim() === `iss=${new URL(evt.iss).hostname}`)) throw new Error('Issuer not delegated');
+  const getJSON = dependencies.fetchJSON || fetchJSON;
+  const metadata = await getJSON(`${evt.iss}/.well-known/email-verification`);
+  if ((metadata.issuer && metadata.issuer !== evt.iss) || !providers[evt.iss].includes(metadata.jwks_uri)) throw new Error('Untrusted provider metadata');
+  const jwks = await getJSON(metadata.jwks_uri);
+  if (!Array.isArray(jwks.keys) || jwks.keys.length > 30) throw new Error('Invalid keys');
+  const holder = evt.cnf?.jwk;
+  if (!holder || holder.d || holder.k || !['OKP', 'EC'].includes(holder.kty)) throw new Error('Invalid holder key');
+  const normalize = alg => alg === 'Ed25519' ? 'EdDSA' : alg;
+  if (holder.alg && normalize(holder.alg) !== normalize(kb.header.alg)) throw new Error('Holder algorithm mismatch');
+  const sdJwt = new SdJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      for (const jwk of jwks.keys.filter(key => !decoded.jwt.header.kid || key.kid === decoded.jwt.header.kid)) {
+        try {
+          if (jwk.d || jwk.k) continue;
+          const key = await importJWK(jwk, decoded.jwt.header.alg);
+          await jwtVerify(`${data}.${sig}`, key, { issuer: evt.iss, algorithms, maxTokenAge: '5m', clockTolerance: 30 });
+          return true;
+        } catch { /* Providers may omit kid; try each public key. */ }
+      }
+      return false;
+    },
+    kbVerifier: async (data, sig) => {
+      const key = await importJWK(holder, kb.header.alg);
+      await jwtVerify(`${data}.${sig}`, key, { typ: 'kb+jwt', audience, algorithms, maxTokenAge: '5m', clockTolerance: 30 });
+      return true;
+    },
+  });
+  const verified = await sdJwt.verify(token, { requiredClaimKeys: ['email', 'email_verified'], keyBindingNonce: nonce, expectedKeyBindingAudience: audience, keyBindingMaxAgeSeconds: 300, skewSeconds: 30 });
+  if (verified.payload.email_verified !== true || verified.payload.email?.toLowerCase() !== email.toLowerCase()) throw new Error('Email mismatch');
+  return { email, issuer: evt.iss };
+}
