diff --git a/server.mjs b/server.mjs
new file mode 100644
index 0000000..ccf2b9c
--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,62 @@
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { randomBytes, scrypt as scryptCallback } from 'node:crypto';
+import { promisify } from 'node:util';
+import { createStore } from './lib/store.mjs';
+import { verifyEmailToken } from './lib/verify-email.mjs';
+
+const scrypt = promisify(scryptCallback);
+const origin = new URL(process.env.PUBLIC_ORIGIN || `http://localhost:${process.env.PORT || 11222}`).origin;
+const secure = origin.startsWith('https:');
+if (process.env.NODE_ENV === 'production' && !secure) throw new Error('PUBLIC_ORIGIN must use HTTPS in production');
+const store = createStore(process.env.DATABASE_PATH || './rewards.sqlite');
+const template = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+const css = await readFile(new URL('./styles.css', import.meta.url));
+const escape = text => String(text).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+function render(res, { status = 200, message = '', success = false } = {}) {
+  const challenge = store.issue();
+  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Set-Cookie': `${secure ? '__Host-' : ''}grind_signup=${challenge.session}; HttpOnly; SameSite=Lax; Path=/; Max-Age=600${secure ? '; Secure' : ''}`, ...(process.env.ORIGIN_TRIAL_TOKEN ? { 'Origin-Trial': process.env.ORIGIN_TRIAL_TOKEN } : {}) });
+  res.end(template.replace('nonce="SERVER_NONCE"', `nonce="${challenge.nonce}"`).replace('<!-- SERVER_STATUS -->', message ? `<div class="form-status ${success ? 'success' : 'error'}" role="${success ? 'status' : 'alert'}" tabindex="-1">${escape(message)}</div>` : '').replace('data-success="false"', `data-success="${success}"`));
+}
+createServer(async (req, res) => {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'same-origin');
+  try {
+    const path = new URL(req.url, origin).pathname;
+    if (req.method === 'GET' && path === '/') return render(res);
+    if (req.method === 'GET' && path === '/styles.css') {
+      res.writeHead(200, { 'Content-Type': 'text/css' }); return res.end(css);
+    }
+    if (req.method === 'POST' && path === '/api/verify-email') {
+      if (req.headers.origin !== origin) { res.writeHead(403); return res.end('Please submit from the Daily Grind homepage.'); }
+      const cookieName = `${secure ? '__Host-' : ''}grind_signup=`;
+      const session = req.headers.cookie?.split(';').map(x => x.trim()).find(x => x.startsWith(cookieName))?.slice(cookieName.length);
+      // DELETE RETURNING atomically consumes the challenge before any asynchronous work.
+      const nonce = store.consume(session);
+      let body = '';
+      for await (const chunk of req) {
+        body += chunk;
+        if (Buffer.byteLength(body) > 30000) return render(res, { status: 413, message: 'That submission was too large. Please try again.' });
+      }
+      if (!req.headers['content-type']?.startsWith('application/x-www-form-urlencoded')) return render(res, { status: 415, message: 'Please use the sign-up form below.' });
+      const form = new URLSearchParams(body);
+      const email = (form.get('email') || '').trim();
+      const name = (form.get('name') || '').trim();
+      const password = form.get('password') || '';
+      if (!nonce) return render(res, { status: 400, message: 'Your sign-up session expired or was already used. Please try again below.' });
+      if (!/^[^\s@]+@(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/.test(email) || email.length > 254 || !name || name.length > 80 || password.length < 12 || password.length > 128 || form.get('terms') !== 'yes') return render(res, { status: 400, message: 'Please complete all fields, use a password of 12–128 characters, and accept the rewards terms.' });
+      if (!form.get('token')) return render(res, { status: 422, message: 'Your browser couldn’t verify your email. Try a supported Chrome browser, signed in to a participating email provider. No account was created and no email was sent.' });
+      try { await verifyEmailToken({ token: form.get('token'), email, nonce, audience: origin }); }
+      catch { return render(res, { status: 422, message: 'We couldn’t confirm your email. Please try again while signed in to your email provider. No account was created and no email was sent.' }); }
+      const salt = randomBytes(16).toString('hex');
+      const hash = await scrypt(password, salt, 64);
+      store.register({ email, name, passwordHash: `scrypt:${salt}:${hash.toString('hex')}` });
+      // Generic response also covers duplicate addresses without disclosing account existence.
+      return render(res, { success: true, message: 'Email confirmed. You’re all set! If you’re already a member, your existing rewards account is ready to use.' });
+    }
+    res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Page not found');
+  } catch {
+    if (!res.headersSent) render(res, { status: 503, message: 'We couldn’t complete sign-up right now. Please try again in a moment.' });
+    else res.end();
+  }
+}).listen(Number(process.env.PORT || 11222), '0.0.0.0');
