index 0000000..76d1295
--- /dev/null
+++ b/test/verification.test.mjs
@@ -0,0 +1,75 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createHash } from 'node:crypto';
+import { generateKeyPair, exportJWK, SignJWT } from 'jose';
+import { verifyEmailToken } from '../lib/verify-email.mjs';
+import { createStore } from '../lib/store.mjs';
+
+const issuer = await generateKeyPair('ES256');
+const holder = await generateKeyPair('ES256');
+const unrelated = await generateKeyPair('ES256');
+const publicIssuer = await exportJWK(issuer.publicKey);
+const publicHolder = await exportJWK(holder.publicKey);
+const now = Math.floor(Date.now() / 1000);
+const email = 'coffee@gmail.com';
+const nonce = 'a-single-use-server-challenge';
+const audience = 'https://dailygrind.example';
+async function presentation(evtOverrides = {}, kbOverrides = {}, badSignature = false) {
+  const evt = await new SignJWT({ iss: 'https://accounts.google.com', email, email_verified: true, iat: now, exp: now + 240, cnf: { jwk: publicHolder }, _sd_alg: 'sha-256', ...evtOverrides }).setProtectedHeader({ alg: 'ES256', typ: 'ev+sd-jwt' }).sign(badSignature ? unrelated.privateKey : issuer.privateKey);
+  const sd_hash = createHash('sha256').update(`${evt}~`).digest('base64url');
+  const kb = await new SignJWT({ iat: now, aud: audience, nonce, sd_hash, ...kbOverrides }).setProtectedHeader({ alg: 'ES256', typ: 'kb+jwt' }).sign(holder.privateKey);
+  return `${evt}~${kb}`;
+}
+const dependencies = {
+  resolveTxt: async () => [['iss=accounts.google.com']],
+  fetchJSON: async url => url.endsWith('/email-verification') ? { issuer: 'https://accounts.google.com', jwks_uri: 'https://verifiablecredentials-pa.googleapis.com/.well-known/vc-public-jwks' } : { keys: [publicHolder, publicIssuer] },
+};
+const verify = (token, overrides = {}, deps = dependencies) => verifyEmailToken({ token, email, nonce, audience, ...overrides }, deps);
+
+test('accepts signed, delegated token with key binding and no kid among multiple keys', async () => {
+  assert.equal((await verify(await presentation())).email, email);
+});
+test('rejects missing token or nonce', async () => {
+  await assert.rejects(verify(''));
+  await assert.rejects(verify(await presentation(), { nonce: '' }));
+});
+test('rejects email mismatch, false verified claim, expiry and stale issuer', async () => {
+  for (const claims of [{ email: 'other@gmail.com' }, { email_verified: false }, { exp: now - 1 }, { iat: now - 600 }, { iss: 'https://evil.example' }]) {
+    await assert.rejects(verify(await presentation(claims)));
+  }
+});
+test('rejects forged issuer signature', async () => { await assert.rejects(verify(await presentation({}, {}, true))); });
+test('rejects wrong audience, nonce, digest and stale holder', async () => {
+  for (const claims of [{ aud: 'https://evil.example' }, { nonce: 'replayed' }, { sd_hash: 'tampered' }, { iat: now - 600 }, { iat: now + 600 }]) {
+    await assert.rejects(verify(await presentation({}, claims)));
+  }
+});
+test('rejects missing key binding', async () => { await assert.rejects(verify((await presentation()).split('~')[0] + '~')); });
+test('rejects absent DNS delegation before fetching metadata', async () => {
+  let fetched = false;
+  await assert.rejects(verify(await presentation(), {}, { resolveTxt: async () => [['iss=evil.example']], fetchJSON: async () => { fetched = true; } }));
+  assert.equal(fetched, false);
+});
+test('rejects untrusted discovery and JWKS locations', async () => {
+  for (const metadata of [{ issuer: 'https://evil.example' }, { issuer: 'https://accounts.google.com', jwks_uri: 'http://127.0.0.1/keys' }]) {
+    await assert.rejects(verify(await presentation(), {}, { ...dependencies, fetchJSON: async () => metadata }));
+  }
+});
+test('server challenges are unique and can only be consumed once', () => {
+  const store = createStore(':memory:');
+  const first = store.issue();
+  const second = store.issue();
+  assert.notEqual(first.nonce, second.nonce);
+  assert.notEqual(first.session, first.nonce);
+  assert.equal(store.consume('invented'), null);
+  assert.equal(store.consume(first.session), first.nonce);
+  assert.equal(store.consume(first.session), null);
+  assert.equal(store.consume(second.session), second.nonce);
+  store.close();
+});
+test('registration persists a unique account without overwriting existing credentials', () => {
+  const store = createStore(':memory:');
+  assert.ok(store.register({ email, name: 'Coffee', passwordHash: 'test-hash' }));
+  assert.doesNotThrow(() => store.register({ email: email.toUpperCase(), name: 'Duplicate', passwordHash: 'other-hash' }));
+  store.close();
+});

