+.toggle-label { display:flex; align-items:center; gap:9px; color:#465440; cursor:pointer; } .switch { appearance:none; width:29px; height:17px; background:#c8cec5; border-radius:20px; margin:0; position:relative; cursor:pointer; } .switch:checked { background:var(--green); } .switch::after { content:""; width:11px; height:11px; background:white; border-radius:50%; position:absolute; left:3px; top:3px; transition:transform .15s; } .switch:checked::after { transform:translateX(12px); }
+.size-control { display:flex; align-items:center; gap:10px; } input[type="range"] { width:75px; accent-color:var(--green); cursor:pointer; } output { min-width:28px; color:#52604d; font-family:monospace; }
+.metric { font-family:monospace; color:#536649; background:#eaf0e3; border-radius:4px; padding:3px 7px; }
+.code-card { margin-top:22px; } .code-header { padding:15px 23px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid #edf0eb; }
+.file { font-family:monospace; font-size:.7rem; color:#6d7867; display:flex; align-items:center; gap:9px; } .file-icon { color:#8b9882; font-size:.8rem; }
+.copy { background:white; border:1px solid var(--border); color:#63705b; padding:5px 10px; border-radius:5px; font-size:.65rem; display:flex; align-items:center; gap:6px; }
+.code-grid { display:grid; grid-template-columns:1fr 1fr; padding:23px 26px; gap:25px; background:#fdfefb; }
