+.insight { display:flex; gap:12px; padding:19px 0; color:#7a8373; font-size:.75rem; } .info-icon { border:1px solid #9da993; border-radius:50%; width:15px; height:15px; line-height:14px; text-align:center; font-family:Georgia,serif; font-size:.65rem; flex-shrink:0; margin-top:2px; } .insight p { margin:0; max-width:95ch; } .insight strong { color:#59674f; font-weight:500; }
+footer { display:flex; justify-content:space-between; gap:20px; color:#92998d; border-top:1px solid var(--border); padding:20px 0 0; margin-top:18px; font-size:.65rem; } footer span:last-child { display:flex; align-items:center; gap:7px; } .footer-mark { color:#768b6c; }
+.reference { padding:30px; } .reference h2 { font-weight:500; margin:0 0 12px; font-size:1.3rem; } .reference p { max-width:75ch; color:#75806d; } .reference code { color:#45613a; } [hidden] { display:none!important; }
