+// Templates are parsed once per component type and cloned for each instance.
+export function createTemplate(markup, styles) {
+  const template = document.createElement('template');
+  template.innerHTML = `<style>${styles}</style>${markup}`;
+  return template;
+}
+
+export function mount(element, template) {
+  const root = element.attachShadow({ mode: 'open', delegatesFocus: true });
+  root.append(template.content.cloneNode(true));
+  return root;
+}
+
+export const baseStyles = `
+  :host { display: block; }
+  *, *::before, *::after { box-sizing: border-box; }
+  ::slotted(*) { box-sizing: border-box; }
+  ::slotted(a:focus-visible), button:focus-visible {
+    outline: 3px solid currentColor;
+    outline-offset: 4px;
+  }
+`;
+
+export const actionStyles = `
+  ::slotted(a) {
+    display: inline-block;
+    background: var(--primary, #4e342e);
+    color: white;
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    margin-top: 15px;
+  }
+  ::slotted(a:hover) { background: #3e2723; }
+`;
