+            result = { error: 'Choose a seasonal coffee and a whole-number quantity from 1 to 10.' };
+            status.textContent = result.error;
+            form.reportValidity();
+          } else {
+            order.set(drink, (order.get(drink) || 0) + quantity);
+            renderOrder();
+            const message = `Added ${quantity} × ${menu.get(drink)} to your order.`;
+            status.textContent = message;
+            result = {
