+++ b/src/utils/articleUtilities.ts
@@ -0,0 +1,39 @@
+export const articleUtilities = {
+  'coffee-alchemy': { name: 'brew-coffee', endpoint: 'coffee-brew', description: 'Fetch the coffee brewing statistics for this article.' },
+  'coastal-pulse': { name: 'get-tide-levels', endpoint: 'tide-levels', description: 'Fetch current tide levels for the coastal article.' },
+  'silent-architects': { name: 'get-plant-stats', endpoint: 'plant-stats', description: 'Fetch plant statistics using the article’s plant cache cookies.' },
+  'super-bowl-lx': { name: 'get-article-popularity', endpoint: 'article-popularity', description: 'Fetch popularity statistics for an article.' },
+} as const;
+
+export type UtilitySlug = keyof typeof articleUtilities;
+
+export async function runArticleUtility(slug: UtilitySlug, signal: AbortSignal, id?: string) {
+  const utility = articleUtilities[slug];
+  const url = new URL(`${import.meta.env.BASE_URL}api/${utility.endpoint}`, location.origin);
+  if (id) url.searchParams.set('id', id);
+  if (slug === 'silent-architects') {
+    // Preserve this DevTools example's intentionally oversized request headers.
+    const value = 'A'.repeat(2000);
+    for (let index = 1; index <= 3; index++) {
+      document.cookie = `plant_stats_cache_${index}=${value}; path=${url.pathname}`;
+    }
+  }
+  try {
+    const response = await fetch(url, { signal });
+    const text = await response.text();
+    let data: unknown = text;
+    if (response.headers.get('content-type')?.includes('application/json') && text) {
+      data = JSON.parse(text);
+    }
+    return {
+      ...(response.ok ? {} : { error: `Request failed: ${response.status} ${response.statusText}` }),
+      status: response.status,
+      redirected: response.redirected,
+      url: response.url,
+      data,
+    };
+  } catch (error) {
+    if (signal.aborted) throw error;
+    return { error: error instanceof Error ? error.message : 'Network request failed. Please retry.' };
+  }
+}
diff --git a/src/utils/browserTools.ts b/src/utils/browserTools.ts
new file mode 100644
index 0000000..f6e6717
--- /dev/null
+++ b/src/utils/browserTools.ts
@@ -0,0 +1,118 @@
+import type { WebMCP } from 'webmcp-types';
+import { articleUtilities, runArticleUtility, type UtilitySlug } from './articleUtilities';
+
+let pageController: AbortController | undefined;
+
+// Wait for the React island and its data before reporting that a form is ready.
+function openForm(kind: 'search' | 'reading-list', signal: AbortSignal) {
+  return new Promise<{ ready: boolean }>((resolve, reject) => {
+    let opened = false;
+    const observer = new MutationObserver(check);
+    const timer = window.setTimeout(() => finish(new Error('The form is still loading. Please retry.')), 15000);
+    function finish(error?: unknown) {
+      observer.disconnect();
+      clearTimeout(timer);
+      signal.removeEventListener('abort', abort);
+      if (error) reject(error);
+      else resolve({ ready: true });
+    }
+    function abort() { finish(signal.reason); }
+    function check() {
+      const button = document.querySelector<HTMLButtonElement>(`[data-open-${kind}]`);
+      // Astro removes ssr after the island has hydrated and attached listeners.
+      if (!button || button.disabled || button.closest('astro-island[ssr]')) return;
+      const name = kind === 'search' ? 'search-articles' : 'manage-reading-list';
+      if (document.querySelector(`form[toolname="${name}"]`)) {
+        finish();
+      } else if (!opened) {
+        opened = true;
+        button.click();
+      }
+    }
+    observer.observe(document.body, { childList: true, subtree: true, attributes: true });
+    signal.addEventListener('abort', abort, { once: true });
+    if (signal.aborted) abort();
+    else check();
+  });
+}
+
+async function setupTools() {
+  pageController?.abort();
+  const controller = new AbortController();
+  pageController = controller;
+  const slug = document.querySelector<HTMLElement>('[data-article-slug]')?.dataset.articleSlug;
+  const utilitySlug = slug && Object.hasOwn(articleUtilities, slug) ? slug as UtilitySlug : undefined;
+
+  // These requests are intentional DevTools network examples, also used by tools.
+  if (utilitySlug) {
+    void runArticleUtility(utilitySlug, controller.signal).then(result => {
+      if ('error' in result) console.error(result.error);
+    }).catch(error => { if (!controller.signal.aborted) console.error(error); });
+  }
+
+  const context = document.modelContext;
+  if (!context || !window.isSecureContext) return;
+  const tools: WebMCP.ModelContextTool[] = (['search', 'reading-list'] as const).map(kind => ({
+    name: `open-${kind}`,
+    description: kind === 'search'
+      ? 'Open the article search form so you can search The DevTools Times.'
+      : 'Open the reading list form so you can view and manage saved articles.',
+    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
+    async execute(_input, { signal }) {
+      try {
+        return await openForm(kind, AbortSignal.any([signal, controller.signal]));
+      } catch (error) {
+        if (signal.aborted || controller.signal.aborted) throw error;
+        return { error: error instanceof Error ? error.message : 'Could not open form. Please retry.' };
+      }
+    },
+  }));
+
+  if (utilitySlug) {
+    const utility = articleUtilities[utilitySlug];
+    const popularity = utilitySlug === 'super-bowl-lx';
+    tools.push({
+      name: utility.name,
+      description: utility.description,
+      inputSchema: {
+        type: 'object',
+        properties: popularity ? { id: { type: 'string', minLength: 1, description: 'The article identifier to look up.' } } : {},
+        required: popularity ? ['id'] : [],
+        additionalProperties: false,
+      },
+      outputSchema: {
+        type: 'object',
+        properties: {
+          status: { type: 'integer' },
+          redirected: { type: 'boolean' },
+          url: { type: 'string' },
+          data: {},
+          error: { type: 'string' },
+        },
+      },
+      execute(input, { signal }) {
+        if (popularity && (typeof input.id !== 'string' || !input.id.trim())) {
+          return { error: 'Provide a non-empty article id.' };
+        }
+        return runArticleUtility(utilitySlug, AbortSignal.any([signal, controller.signal]),
+          popularity ? (input.id as string).trim() : undefined);
+      },
+      annotations: { readOnlyHint: utilitySlug !== 'silent-architects' },
+    });
+  }
+
+  for (const tool of tools) {
+    if (controller.signal.aborted) break;
+    try {
+      await context.registerTool(tool, { signal: controller.signal });
+    } catch (error) {
+      if (!controller.signal.aborted) console.error(`Could not register ${tool.name}:`, error);
+    }
+  }
+}
+
+// Astro keeps this module alive across client navigations.
+document.addEventListener('astro:page-load', () => void setupTools());
+document.addEventListener('astro:before-swap', () => pageController?.abort());
+window.addEventListener('pagehide', () => pageController?.abort());
+window.addEventListener('pageshow', event => { if (event.persisted) void setupTools(); });
diff --git a/tests/browser-tools.test.mjs b/tests/browser-tools.test.mjs
new file mode 100644
index 0000000..3e2e3e7
--- /dev/null
+++ b/tests/browser-tools.test.mjs
@@ -0,0 +1,169 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { execFileSync } from 'node:child_process';
+import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { runInNewContext } from 'node:vm';
+
+const directory = mkdtempSync(join(tmpdir(), 'devtools-tools-test-'));
+let source;
+try {
+  const file = join(directory, 'browser-tools.js');
+  execFileSync('pnpm', ['exec', 'esbuild', 'src/utils/browserTools.ts', '--bundle', '--format=iife',
+    '--define:import.meta.env.BASE_URL="/news/"', `--outfile=${file}`], { stdio: 'pipe' });
+  source = readFileSync(file, 'utf8');
+} finally {
+  rmSync(directory, { recursive: true, force: true });
+}
+
+const settle = () => new Promise(resolve => setImmediate(resolve));
+function environment({ slug, supported = true, response } = {}) {
+  const registrations = [];
+  const requests = [];
+  const listeners = new Map();
+  const errors = [];
+  const observers = [];
+  const document = {
+    cookie: '',
+    body: {},
+    querySelector: selector => selector === '[data-article-slug]' && slug ? { dataset: { articleSlug: slug } } : null,
+    addEventListener(name, handler) { listeners.set(name, handler); },
+    modelContext: supported ? {
+      async registerTool(tool, options) { registrations.push({ tool, signal: options.signal }); },
+    } : undefined,
+  };
+  runInNewContext(source, {
+    document, location: { origin: 'https://example.com' }, URL, AbortController, AbortSignal,
+    window: { isSecureContext: true, addEventListener() {}, setTimeout },
+    clearTimeout,
+    MutationObserver: class {
+      constructor(callback) { this.callback = callback; observers.push(this); }
+      observe() {}
+      disconnect() { this.disconnected = true; }
+    },
+    console: { error: (...args) => errors.push(args) },
+    fetch: async (url, options) => {
+      requests.push({ url: String(url), signal: options.signal });
+      return response ? response(url, options) : new Response(JSON.stringify({ trending: true }), {
+        headers: { 'content-type': 'application/json' },
+      });
+    },
+  });
+  return { registrations, requests, listeners, errors, observers, document, setSlug: value => { slug = value; } };
+}
+
+const cases = [
+  ['coffee-alchemy', 'brew-coffee', '/news/api/coffee-brew'],
+  ['coastal-pulse', 'get-tide-levels', '/news/api/tide-levels'],
+  ['silent-architects', 'get-plant-stats', '/news/api/plant-stats'],
+  ['super-bowl-lx', 'get-article-popularity', '/news/api/article-popularity'],
+];
+for (const [slug, name, path] of cases) {
+  test(`${slug} registers only its utility and both form openers`, async () => {
+    const env = environment({ slug });
+    env.listeners.get('astro:page-load')();
+    await settle();
+    assert.deepEqual(env.registrations.map(({ tool }) => tool.name), ['open-search', 'open-reading-list', name]);
+    const { tool } = env.registrations.at(-1);
+    const result = await tool.execute(name === 'get-article-popularity' ? { id: 'story & one' } : {}, { signal: new AbortController().signal });
+    assert.equal(result.status, 200);
+    assert.equal(new URL(env.requests.at(-1).url).pathname, path);
+    if (name === 'get-article-popularity') {
+      assert.equal(new URL(env.requests.at(-1).url).searchParams.get('id'), 'story & one');
+      const count = env.requests.length;
+      assert.match((await tool.execute({ id: ' ' }, { signal: new AbortController().signal })).error, /non-empty/);
+      assert.equal(env.requests.length, count);
+    }
+    if (name === 'get-plant-stats') {
+      assert.match(env.document.cookie, /path=\/news\/api\/plant-stats/);
+      assert.equal(tool.annotations.readOnlyHint, false);
+    }
+  });
+}
+
+test('unsupported browsers retain automatic requests without registering tools', async () => {
+  const env = environment({ slug: 'coffee-alchemy', supported: false });
+  env.listeners.get('astro:page-load')();
+  await settle();
+  assert.equal(env.requests.length, 1);
+  assert.equal(env.registrations.length, 0);
+});
+
+test('network failures return actionable HTTP status and body', async () => {
+  const env = environment({ slug: 'coffee-alchemy', response: () => new Response('{"message":"Machine broken"}', {
+    status: 500, headers: { 'content-type': 'application/json' },
+  }) });
+  env.listeners.get('astro:page-load')();
+  await settle();
+  const result = await env.registrations.at(-1).tool.execute({}, { signal: new AbortController().signal });
+  assert.equal(result.status, 500);
+  assert.match(result.error, /500/);
+  assert.equal(result.data.message, 'Machine broken');
+});
+
+test('navigation unregisters tools and cancels requests before registering the next page', async () => {
+  const env = environment({ slug: 'coffee-alchemy' });
+  env.listeners.get('astro:page-load')();
+  await settle();
+  env.listeners.get('astro:before-swap')();
+  assert.ok(env.registrations.every(({ signal }) => signal.aborted));
+  assert.ok(env.requests.every(({ signal }) => signal.aborted));
+  env.setSlug(undefined);
+  env.listeners.get('astro:page-load')();
+  await settle();
+  assert.deepEqual(env.registrations.slice(3).map(({ tool }) => tool.name), ['open-search', 'open-reading-list']);
+});
+
+test('execution cancellation aborts the fetch and propagates cancellation', async () => {
+  const env = environment({ slug: 'coastal-pulse', response: (_url, { signal }) => {
+    signal.throwIfAborted();
+    return new Response('tides');
+  } });
+  env.listeners.get('astro:page-load')();
+  await settle();
+  const execution = new AbortController();
+  execution.abort();
+  await assert.rejects(env.registrations.at(-1).tool.execute({}, { signal: execution.signal }), { name: 'AbortError' });
+  assert.ok(env.requests.at(-1).signal.aborted);
+});
+
+
+test('open-search waits for hydration and loading before returning a ready form', async () => {
+  const env = environment();
+  env.listeners.get('astro:page-load')();
+  await settle();
+  let hydrated = false;
+  let form = false;
+  let clicks = 0;
+  const button = {
+    disabled: false,
+    closest: () => hydrated ? null : {},
+    click() { clicks++; form = true; this.disabled = true; },
+  };
+  env.document.querySelector = selector => selector.startsWith('[data-open-') ? button : form ? {} : null;
+  let complete = false;
+  const result = env.registrations[0].tool.execute({}, { signal: new AbortController().signal }).then(value => { complete = true; return value; });
+  assert.equal(clicks, 0);
+  hydrated = true;
+  env.observers[0].callback();
+  assert.equal(clicks, 1);
+  env.observers[0].callback();
+  await settle();
+  assert.equal(complete, false);
+  button.disabled = false;
+  env.observers[0].callback();
+  assert.equal((await result).ready, true);
+  assert.equal(env.observers[0].disconnected, true);
+});
+
+test('cancelling a form opener disconnects its observer', async () => {
+  const env = environment();
+  env.listeners.get('astro:page-load')();
+  await settle();
+  const controller = new AbortController();
+  const result = env.registrations[1].tool.execute({}, { signal: controller.signal });
+  controller.abort();
+  await assert.rejects(result, { name: 'AbortError' });
+  assert.equal(env.observers[0].disconnected, true);
+});
