new file mode 100644
index 0000000..065e279
--- /dev/null
+++ b/src/scripts/browser-tools.ts
@@ -0,0 +1,88 @@
+import { getArticles, requestArticleUtility } from '../utils/browser-actions';
+import type { BrowserTool, ModelContext } from '../types/webmcp';
+
+// Current WebMCP uses document; retain compatibility with early navigator builds.
+const context = () => (document as Document & { modelContext?: ModelContext }).modelContext
+  ?? (navigator as Navigator & { modelContext?: ModelContext }).modelContext;
+const emptyInput = { type: 'object', properties: {}, additionalProperties: false };
+const tools: BrowserTool[] = [
+  {
+    name: 'get_articles', description: 'List DevTools Times article slugs, titles and summaries.', inputSchema: emptyInput,
+    execute: async () => getArticles(),
+  },
+  ...(['search', 'reading-list'] as const).map(kind => ({
+    name: `open_${kind.replace('-', '_')}`,
+    description: `Open the ${kind} form so its browser tool can be discovered and submitted.`,
+    inputSchema: emptyInput,
+    execute: async () => {
+      const button = document.querySelector<HTMLButtonElement>(`[data-open-tool="${kind}"]`);
+      if (!button || button.disabled) throw new Error('The form is not ready. Retry after the page finishes loading.');
+      button.click();
+      // Wait for the React island to mount the declarative form before returning.
+      await new Promise<void>((resolve, reject) => {
+        const selector = `[data-tool-form="${kind}"]`;
+        if (document.querySelector(selector)) return resolve();
+        const observer = new MutationObserver(() => {
+          if (document.querySelector(selector)) { clearTimeout(timeout); observer.disconnect(); resolve(); }
+        });
+        const timeout = setTimeout(() => { observer.disconnect(); reject(new Error('The form did not open.')); }, 5000);
+        observer.observe(document.body, { childList: true, subtree: true });
+      });
+      return { opened: kind };
+    },
+  })),
+  {
+    name: 'brew_coffee', description: 'Request the coffee article utility. The demo may return an intentional server error.',
+    inputSchema: emptyInput, execute: async () => requestArticleUtility('coffee-brew'),
+  },
+  {
+    name: 'get_plant_stats', description: 'Request plant statistics. The demo may fail when plant cache cookies exceed the header limit.',
+    inputSchema: emptyInput, execute: async () => requestArticleUtility('plant-stats'),
+  },
+  {
+    name: 'get_tide_levels', description: 'Request tide levels and report the final status and URL after any redirect.',
+    inputSchema: emptyInput, execute: async () => requestArticleUtility('tide-levels'),
+  },
+  {
+    name: 'get_article_popularity', description: 'Get popularity statistics for an article ID.',
+    inputSchema: { type: 'object', properties: { id: { type: 'string', minLength: 1, description: 'Article slug from get_articles.' } }, required: ['id'], additionalProperties: false },
+    execute: async ({ id }) => {
+      if (typeof id !== 'string' || !id.trim()) throw new Error('An article ID is required.');
+      return requestArticleUtility('article-popularity', { id });
+    },
+  },
+];
+
+const registered = new Set<string>();
+let generation = 0;
+async function registerTools() {
+  const currentGeneration = generation;
+  const modelContext = context();
+  if (!modelContext) return;
+  for (const tool of tools) {
+    if (registered.has(tool.name)) continue;
+    try {
+      await modelContext.registerTool(tool);
+      if (currentGeneration !== generation) {
+        modelContext.unregisterTool(tool.name);
+        return;
+      }
+      registered.add(tool.name);
+    } catch (error) { console.warn(`Could not register ${tool.name}`, error); }
+  }
+}
+
+// Astro's client router preserves this module across page changes.
+// Unregister only our own tools before a swap, then register on the new page.
+document.addEventListener('astro:before-swap', () => {
+  generation++;
+  const modelContext = context();
+  for (const name of registered) modelContext?.unregisterTool(name);
+  registered.clear();
+});
+let registration = Promise.resolve();
+function scheduleRegistration() {
+  registration = registration.then(registerTools);
+}
+document.addEventListener('astro:page-load', scheduleRegistration);
+scheduleRegistration();
