+import type { HTMLAttributes, FormHTMLAttributes } from 'react';
+
+declare module 'react' {
+  interface FormHTMLAttributes<T> {
+    toolname?: string;
+    tooldescription?: string;
+    toolautosubmit?: string;
+  }
+  interface HTMLAttributes<T> {
+    toolparamdescription?: string;
+  }
+}
+
+export interface BrowserTool {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  execute: (input: Record<string, unknown>) => Promise<unknown>;
+}
+
+export interface ModelContext {
+  registerTool(tool: BrowserTool): void | Promise<void>;
+  unregisterTool(name: string): void;
+}
+
+export interface ToolSubmitEvent extends SubmitEvent {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+}
diff --git a/src/utils/browser-actions.ts b/src/utils/browser-actions.ts
new file mode 100644
index 0000000..7e27720
--- /dev/null
+++ b/src/utils/browser-actions.ts
@@ -0,0 +1,64 @@
+import type { FormEvent } from 'react';
+import type { ToolSubmitEvent } from '../types/webmcp';
+
+export interface Article {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+const api = (path: string) => `${import.meta.env.BASE_URL}api/${path}`;
+
+export async function getArticles(): Promise<Article[]> {
+  const response = await fetch(api('articles.json'));
+  if (!response.ok) throw new Error(`Could not load articles (${response.status}).`);
+  return response.json();
+}
+
+export function searchArticles(articles: Article[], query: string) {
+  const term = query.trim().toLowerCase();
+  return term ? articles.filter(article =>
+    article.title.toLowerCase().includes(term) || article.summary.toLowerCase().includes(term)
+  ) : [];
+}
+
+export async function getReadingList(): Promise<string[]> {
+  const response = await fetch(api('reading-list.json'));
+  if (!response.ok) throw new Error(`Could not load reading list (${response.status}).`);
+  return (await response.json()).readingList;
+}
+
+export async function updateReadingList(slug: string, action: 'add' | 'remove' | 'toggle') {
+  const current = await getReadingList();
+  if ((action === 'add' && current.includes(slug)) || (action === 'remove' && !current.includes(slug))) return current;
+  const response = await fetch(api('reading-list.json'), {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  if (!response.ok) throw new Error(`Could not update reading list (${response.status}).`);
+  const { readingList } = await response.json();
+  window.dispatchEvent(new CustomEvent('reading-list-updated', { detail: readingList }));
+  return readingList as string[];
+}
+
+// Read form fields directly: browser agents need not fire React change events.
+// respondWith must be called synchronously during the native submit event.
+export function submitToolForm(event: FormEvent<HTMLFormElement>, action: (data: FormData) => Promise<unknown>) {
+  event.preventDefault();
+  const result = action(new FormData(event.currentTarget));
+  const nativeEvent = event.nativeEvent as ToolSubmitEvent;
+  if (nativeEvent.agentInvoked && nativeEvent.respondWith) nativeEvent.respondWith(result);
+  else void result.catch(() => {}); // The action also displays errors in the form.
+}
+
+export async function requestArticleUtility(path: string, params?: Record<string, string>) {
+  const url = new URL(api(path), window.location.origin);
+  for (const [key, value] of Object.entries(params ?? {})) url.searchParams.set(key, value);
+  const response = await fetch(url);
+  const body = await response.text();
+  let data: unknown = body;
+  try { data = JSON.parse(body); } catch { /* Error and redirect targets may return HTML. */ }
+  return { ok: response.ok, status: response.status, redirected: response.redirected, url: response.url, data };
+}
