+
+test('search matches title and summary, trims whitespace, and handles no results', () => {
+  const { searchArticles } = actions();
+  const articles = [{ slug: 'coffee', title: 'Coffee', summary: 'A morning ritual' }];
+  assert.equal(searchArticles(articles, ' COFFEE ')[0].slug, 'coffee');
+  assert.equal(searchArticles(articles, 'morning')[0].slug, 'coffee');
+  assert.equal(searchArticles(articles, 'missing').length, 0);
+  assert.equal(searchArticles(articles, '   ').length, 0);
+});
+
+test('reading-list add/remove are idempotent and use the configured base path', async () => {
+  let saved = ['coffee'];
+  let posts = 0;
+  const { updateReadingList } = actions(async (url, options) => {
+    assert.equal(url, '/devtools-times/api/reading-list.json');
+    if (options?.method === 'POST') {
+      posts++;
+      const { slug } = JSON.parse(options.body);
+      saved = saved.includes(slug) ? saved.filter(item => item !== slug) : [...saved, slug];
+    }
+    return Response.json({ readingList: saved });
+  });
+  await updateReadingList('coffee', 'add');
+  await updateReadingList('absent', 'remove');
+  assert.equal(posts, 0);
+  await updateReadingList('coffee', 'remove');
+  await updateReadingList('coffee', 'remove');
+  assert.equal(posts, 1);
+  assert.equal(saved.length, 0);
+});
