+test('HTTP utility failures and redirects remain inspectable; network failures reject', async () => {
+  const { requestArticleUtility } = actions(async url => {
+    assert.equal(url.pathname, '/devtools-times/api/article-popularity');
+    assert.equal(url.searchParams.get('id'), 'a & b');
+    return { ok: false, status: 500, redirected: true, url: 'https://example.test/final', text: async () => '{"error":"demo"}' };
+  });
