+test('agent submission responds synchronously and reads submitted form fields', async () => {
+  let prevented = false;
+  let response;
+  const data = new FormData();
+  data.set('query', 'coffee');
+  const sandbox = { module: { exports: {} }, exports: {}, FormData: class { constructor(form) { return form; } } };
+  runInNewContext(actionsCode, sandbox);
+  sandbox.module.exports.submitToolForm({
+    preventDefault() { prevented = true; }, currentTarget: data,
+    nativeEvent: { agentInvoked: true, respondWith(promise) { response = promise; } },
+  }, async fields => ({ query: fields.get('query') }));
