+function registry(modelContext, useNavigator = false) {
+  const listeners = new Map();
+  const document = {
+    addEventListener(name, callback) { listeners.set(name, callback); },
+    querySelector() { return null; },
+  };
+  if (!useNavigator) document.modelContext = modelContext;
+  runInNewContext(registryCode, { document, navigator: useNavigator ? { modelContext } : {}, console, setTimeout, clearTimeout });
+  return listeners;
+}
+
+test('registration is feature-detected, deduplicated, and restored after navigation', async () => {
+  registry(undefined);
+  const tools = new Map();
+  let registrations = 0;
+  const listeners = registry({
+    registerTool(tool) {
+      assert.equal(tools.has(tool.name), false);
+      registrations++;
+      tools.set(tool.name, tool);
+    },
+    unregisterTool(name) { tools.delete(name); },
+  });
+  await tick();
+  assert.equal(tools.size, 7);
+  listeners.get('astro:page-load')();
+  listeners.get('astro:page-load')();
+  await tick();
+  assert.equal(registrations, 7);
+  await assert.rejects(tools.get('get_article_popularity').execute({ id: '' }), /required/);
+  await assert.rejects(tools.get('open_search').execute({}), /not ready/);
+  listeners.get('astro:before-swap')();
+  assert.equal(tools.size, 0);
+  listeners.get('astro:page-load')();
+  await tick();
+  assert.equal(tools.size, 7);
+  assert.equal(registrations, 14);
+});
+
+test('early navigator.modelContext builds can register tools', async () => {
